window.QUESTIONS = [{"id":1,"type":"single","cat":"操纵与飞行技术","stem":"以下哪一种情景容易引起飞行员产生飞机比实际位置偏高的错觉（）。","A":"向上带斜坡的地形","B":"向下带斜坡的地形","C":"常规跑道","D":"以上均不正确","answer":"A"},{"id":2,"type":"single","cat":"操纵与飞行技术","stem":"X型四轴逆时针偏航时，其1、2号电机的动作应该是（）。","A":"减速、加速","B":"减速、减速","C":"加速、减速","D":"加速、加速","answer":"A"},{"id":3,"type":"single","cat":"基础概念","stem":"固定翼无人机的副翼负责完成无人机的（）动作。","A":"横滚","B":"俯仰","C":"偏航","D":"以上均不正确","answer":"A"},{"id":4,"type":"single","cat":"操纵与飞行技术","stem":"X模式4轴飞行器从悬停转换到前进，那两个轴需要加速（）。","A":"右侧两轴","B":"左侧两轴","C":"后方两轴","D":"以上均不正确","answer":"C"},{"id":5,"type":"single","cat":"电力巡检","stem":"输电线路状态巡视，对防护区内人口稠密区、交跨公路等易受外力损伤、破坏的区段巡视周期为（）至少一次。","A":"每月","B":"每季度","C":"每半年","D":"每年","answer":"A"},{"id":6,"type":"single","cat":"领航与任务规划","stem":"信号线和电源线分开走线，飞机中信号线有电子调速器（电调）控制线、接收机线、全球导航卫星系统（GNSS）线、（）、无线图像传输（无线图传）系统线。","A":"无线数据传输（无线数传）系统线","B":"电流计线","C":"电池平衡充线","D":"电机线","answer":"A"},{"id":7,"type":"single","cat":"电力巡检","stem":"故障巡检、特殊巡检等非计划巡检也应办理（）。","A":"工作票","B":"工作任务单","C":"工作许可手续","D":"作业控制卡","answer":"C"},{"id":8,"type":"single","cat":"基础概念","stem":"低空无人机任务高度一般在（）之间。","A":"0～100m","B":"100～1000m","C":"1000～7000m","D":"以上均不正确","answer":"B"},{"id":9,"type":"single","cat":"领航与任务规划","stem":"空速明显大于地速的原因是（）。","A":"逆风","B":"顺风","C":"无风","D":"以上均不正确","answer":"A"},{"id":10,"type":"single","cat":"基础概念","stem":"固定翼无人机航程的提升措施，下列选项正确的是（）。","A":"增大电池容量","B":"增加飞机起飞重量","C":"减小迎角","D":"逆风飞行","answer":"A"},{"id":11,"type":"single","cat":"设备与维护","stem":"关于遥控器天线，下面描述错误的是？（）","A":"每次飞行时，都应展开天线","B":"远离摇杆的天线尖端朝向，不应指向飞行器","C":"天线展开后应平行于飞行器","D":"远离摇杆的天线尖端朝向，应指向飞行器","answer":"D"},{"id":12,"type":"single","cat":"航空气象","stem":"无人机链路影响因素有自由空间损耗、大气衰减、雨雾衰减以及（）等。","A":"地形地貌衰减","B":"距离衰减","C":"多径效应","D":"以上均不正确","answer":"C"},{"id":13,"type":"single","cat":"领航与任务规划","stem":"无人机地面控制站是整个无人机系统非常重要的组成部分，它包括任务规划，任务回放，实时监测，数字地图，通信数据链在内的集控制，通信，数据处理于一体的综合能力，是整个无人机系统的（）。","A":"指挥终端","B":"指挥控制中心","C":"数据统计中心","D":"显示服务端","answer":"B"},{"id":14,"type":"single","cat":"领航与任务规划","stem":"直线变高菱形航线飞行训练科目中，由H点起飞，控制好油门，操控无人机匀速垂直上升至（）m高度。","A":"1","B":"1.5","C":"3","D":"7","answer":"B"},{"id":15,"type":"single","cat":"领航与任务规划","stem":"在多轴飞行任务中，触发失控返航时，应如何打断飞控当前任务，取回手动控制权（）。","A":"云台状态切换","B":"航向锁定切换","C":"GPS手动模式切换","D":"以上均不正确","answer":"C"},{"id":16,"type":"single","cat":"设备与维护","stem":"以大疆产品为例，假设飞行器处于操作员正上方，当前飞行高度为250米，距离为5米，DJIGO提示“遥控器信号微弱”时，操作员应如何处理（）。","A":"无需理会，飞行器可自行修复信号","B":"继续上升飞行器，高度越高信号越好","C":"原地悬停飞行器，重启遥控器","D":"操作员将遥控器天线摆放至平行于地面","answer":"D"},{"id":17,"type":"single","cat":"操纵与飞行技术","stem":"六轴飞行器安装有（）。","A":"6个顺时针旋转螺旋桨","B":"3个顺时针旋转螺旋桨，3个逆时针旋转螺旋桨","C":"4个顺时针旋转螺旋桨，2个逆时针旋转螺旋桨","D":"以上均不正确","answer":"B"},{"id":18,"type":"single","cat":"领航与任务规划","stem":"起落航线的重要组成部分应急航线相关内容不包括（）。","A":"检查飞行平台、发动机、机上设备的故障状态、油量、电量","B":"决定着陆场或迫降场","C":"任务执行情况","D":"以上均不正确","answer":"C"},{"id":19,"type":"single","cat":"基础概念","stem":"多旋翼飞行器上的电信号传播顺序一般为（）。","A":"飞控——机载遥控接收机——电机——电调","B":"机载遥控接收机——飞控——电调——电机","C":"飞控——电调——机载遥控接收机——电机","D":"以上均不正确","answer":"B"},{"id":20,"type":"single","cat":"设备与维护","stem":"垂起固定翼无人机零部件的定期维护保养，下列选项错误的是（）。","A":"检查电池有无破损，鼓包胀气","B":"保持机身框架完好无裂纹","C":"检查电机安装是否紧固，有无松动等现象","D":"及时清理油污、碎屑，保持各部位清洁","answer":"D"},{"id":21,"type":"single","cat":"基础概念","stem":"飞机纵向阻尼力矩的产生主要（）。","A":"由后掠机翼产生的","B":"由垂直尾翼产生的","C":"由水平尾翼产生的","D":"以上均不正确","answer":"C"},{"id":22,"type":"single","cat":"设备与维护","stem":"电机在焊接插头时，应该先对线头和插头分别（），然后再焊接。","A":"上锡","B":"清洗","C":"预热","D":"上助焊剂","answer":"A"},{"id":23,"type":"single","cat":"领航与任务规划","stem":"航迹规划需要充分考虑（）的选取、标绘，航线预先规划以及在线调整时机。","A":"电子地图","B":"飞行航迹","C":"地理位置","D":"以上均不正确","answer":"A"},{"id":24,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机平飞转弯后段（）。","A":"当飞机轨迹方向离目标方向10度-15度时，注视地平仪，根据接近目标方向的快慢，逐渐回杆","B":"当飞机轨迹方向到达目标方向时，注视地平仪，逐渐回杆","C":"当飞机轨迹方向超过目标方向10度-15度时，注视地平仪，逐渐回杆","D":"以上均不正确","answer":"A"},{"id":25,"type":"single","cat":"电力巡检","stem":"相同巡检作业时，航线规划应优先调用已经实际飞行的（）。","A":"历史航线","B":"起落航线","C":"安全航线","D":"应急航线","answer":"A"},{"id":26,"type":"single","cat":"设备与维护","stem":"以大疆产品为例，操作员打开遥控器时，遥控器发出警告提示音及指示灯为红灯慢闪时，提示的是？（）","A":"遥控器天线未打开","B":"飞行器未于飞行器连接","C":"遥控器需进行摇杆校准","D":"遥控未开启","answer":"C"},{"id":27,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，如果飞机处于顺侧风时（）。","A":"地速增大，收油门下滑和四转弯时机均应适当提前","B":"地速减小，收油门下滑和四转弯时机均应适当延后","C":"地速增大，收油门下滑和四转弯时机均应适当延后","D":"以上均不正确","answer":"A"},{"id":28,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，下列哪种情况，收油门的时机应适当提前，收油门的动作适当加快？（）","A":"实际下滑点与预定下滑点吻合","B":"实际下滑点在预定下滑点后面","C":"实际下滑点在预定下滑点前面","D":"以上均不正确","answer":"C"},{"id":29,"type":"single","cat":"操纵与飞行技术","stem":"姿态遥控模式下操纵无人机爬升，俯仰角偏高时，下列正确的操纵是（）。","A":"应柔和地向右扭舵","B":"应柔和地向后带杆","C":"应柔和地向前顶杆","D":"以上均不正确","answer":"C"},{"id":30,"type":"single","cat":"电力巡检","stem":"小型无人直升机巡检飞行速度不宜大于（）。","A":"10m/s","B":"15m/s","C":"20m/s","D":"25m/s","answer":"A"},{"id":31,"type":"single","cat":"设备与维护","stem":"位置传感器用于感受无人机的位置，是飞行轨迹控制的必要前提（）是典型的位置传感器。","A":"角速率传感器","B":"加速度传感器","C":"GPS卫星导航接收机","D":"以上均不正确","answer":"C"},{"id":32,"type":"single","cat":"基础概念","stem":"（）升降舵、方向舵的舵量标准没有绝对的规定，在调整过程中应注意不能一次调整到位，而是每次调整一个小数量，一般要经过几次调整后才能达到理想状态。","A":"电子调速器（电调）","B":"遥控器","C":"舵机","D":"副翼","answer":"D"},{"id":33,"type":"single","cat":"操纵与飞行技术","stem":"姿态遥控模式下操纵无人机爬升，飞机带右坡度时，下列正确的操纵是（）。","A":"应柔和地向右压杆","B":"应柔和地回杆或向左压杆","C":"应柔和地向前顶杆","D":"以上均不正确","answer":"B"},{"id":34,"type":"single","cat":"设备与维护","stem":"需要灵活操控性能的飞机，选用（）电机。","A":"高直径","B":"高转速","C":"高扭矩","D":"以上均不正确","answer":"B"},{"id":35,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机要求实现悬停中向右偏航，不同螺旋桨应如何变化？（）","A":"逆时针桨减速，顺时针桨加速","B":"机体轴左边螺旋桨加速，右边螺旋桨减速","C":"逆时针桨加速，顺时针桨减速","D":"以上均不正确","answer":"C"},{"id":36,"type":"single","cat":"操纵与飞行技术","stem":"X型四轴前进时，其1、3号电机的动作应该是（）。","A":"加速、加速","B":"减速、减速","C":"加速、减速","D":"减速、加速","answer":"D"},{"id":37,"type":"single","cat":"基础概念","stem":"以下操作符合安全规范的是（）。","A":"在无人机旋转的旋翼下方吹风乘凉","B":"初次飞行时，在空旷地区操作无人机，并且保持安全距离","C":"用手触摸高速旋转中的螺旋桨","D":"在密集人群上方飞行","answer":"B"},{"id":38,"type":"single","cat":"基础概念","stem":"可能需要执行的应急程序不包括（）。","A":"动力装置重启操作","B":"备份系统切换操作","C":"导航系统重启操作","D":"以上均不正确","answer":"C"},{"id":39,"type":"single","cat":"操纵与飞行技术","stem":"无人机定速遥控飞行时收起襟翼，驾驶员需（）。","A":"增加油门以保持空速","B":"针对此情况，无需做相关动作","C":"减小油门以保持空速","D":"以上均不正确","answer":"C"},{"id":40,"type":"single","cat":"设备与维护","stem":"下面属于使用遥控器时日常维护保养要素的是（）。","A":"保证电源工作正常","B":"定期打磨天线避免生锈","C":"对摇杆灵敏度进行检查","D":"定期拆解遥控器进行除尘","answer":"A"},{"id":41,"type":"single","cat":"基础概念","stem":"飞行器在执行兴趣点环绕最低高度是？（）","A":"5米","B":"10米","C":"15米","D":"20米","answer":"A"},{"id":42,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，下列哪种情况需要复飞（）。","A":"飞机油料不足","B":"跑道上有飞机或其它障碍物影响着陆安全时","C":"飞机稍稍偏离期望下滑线","D":"以上均不正确","answer":"B"},{"id":43,"type":"single","cat":"基础概念","stem":"未按照国家有关规定经特别批准，（）航空器不得飞入空中禁区和临时空中禁区。","A":"军用","B":"民用","C":"临时","D":"任何","answer":"D"},{"id":44,"type":"single","cat":"基础概念","stem":"第一人称视角（FPV）穿越机在穿越障碍时发生剧烈碰撞，此时第一人称视角（FPV）眼镜再也无法看清影像，此时应首先检修（）。","A":"摄像头","B":"电机","C":"电子调速器（电调）","D":"螺旋桨","answer":"A"},{"id":45,"type":"single","cat":"基础概念","stem":"下列正确的是（）。","A":"飞机的升阻比越大，飞机的空气动力特性越差","B":"飞机的升阻比越小，飞机的空气动力特性越好","C":"飞机的升阻比越大，飞机的空气动力特性越好","D":"以上均不正确","answer":"C"},{"id":46,"type":"single","cat":"操纵与飞行技术","stem":"撞网回收系统是常用的无人机起飞着陆系统，当该起飞着陆系统出现故障时，我们可能需要维修下面这些装置：拦阻网装置、吸能缓冲装置和（）。","A":"末端引导装置","B":"遥控装置","C":"发射装置","D":"飞行控制系统（自驾仪）装置","answer":"A"},{"id":47,"type":"single","cat":"基础概念","stem":"多旋翼无人机的特点是（）。","A":"机动灵活","B":"使用成本低","C":"结构简单","D":"其他全是","answer":"D"},{"id":48,"type":"single","cat":"基础概念","stem":"在对无人机电动系统组装时，参照电路的稳定电流，并根据整机的重量要求选择合适的（）。","A":"电池","B":"电动机","C":"电调","D":"飞控","answer":"A"},{"id":49,"type":"single","cat":"领航与任务规划","stem":"（）是在无人机执行任务前，由地面控制站制定的，主要是综合任务要求、地理环境和无人机任务载荷等因素进行规划，其特点是约束和飞行环境给定，规划的主要目的是通过选用合适的算法谋求（）飞行航迹。","A":"预先规划，全局最优","B":"实时规划，航程最短","C":"航迹规划，航时最短","D":"以上均不正确","answer":"A"},{"id":50,"type":"single","cat":"操纵与飞行技术","stem":"无人机驾驶员操纵无人机定高平飞时，下列操纵正确的是（）。","A":"如航迹方向偏离目标超过5°，应协调地压杆扭舵，使飞机对正目标，然后改平坡度","B":"如航迹方向偏离目标超过5°，应柔和地向偏转的方向适当扭舵杆","C":"如航迹方向偏离目标超过5°，应缓慢地向偏转的反方向适当扭舵杆","D":"以上均不正确","answer":"A"},{"id":51,"type":"single","cat":"设备与维护","stem":"BEC电子调速器（电调）有分流供电能力，可将动力电池电压变为（）电压给飞行控制系统（自驾仪）供电，多旋翼无人机的多个电子调速器（电调）都给飞行控制系统（自驾仪）供电，就容易混乱，所以我们一般只会保留一个电子调速器（电调）供电。","A":"24V","B":"12V","C":"5V","D":"36V","answer":"C"},{"id":52,"type":"single","cat":"基础概念","stem":"遥控直升机在动力停滞状态，靠旋翼与空气相互作用维持直升机保持飞行的过程，称为（）飞行。","A":"维持","B":"自旋","C":"滑行","D":"以上均不正确","answer":"B"},{"id":53,"type":"single","cat":"领航与任务规划","stem":"GPS的3个主要功能是（）。","A":"高度速度经纬度","B":"高度速度（地速）位置","C":"高度速度（空速）位置","D":"以上均不正确","answer":"B"},{"id":54,"type":"single","cat":"电力巡检","stem":"使用固定翼无人机巡检系统巡检作业时，使用（）方式时，应防止橡皮筋断裂伤人。","A":"滑翔起飞","B":"弹射起飞","C":"增稳起飞","D":"垂直起飞","answer":"B"},{"id":55,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，关于大逆风着陆描述正确的是（）。","A":"第三转弯后，适当提前下滑时机，进入第四转弯的高度应比正常风速时略低","B":"第三转弯后，适当延迟下滑时机，进入第四转弯的高度应比正常风速时略高","C":"第三转弯后，适当提前下滑时机，进入第四转弯的高度应比正常风速时略高","D":"以上均不正确","answer":"B"},{"id":56,"type":"single","cat":"法规与空域","stem":"空域是航空器运行的环境，也是宝贵的国家资源国务院中央军委十分重视我国民用航空交通管制的建设工作，目前正在推进空城管理改革预计划分三类空城为（）。","A":"管制空域、监视空城和报告空域","B":"管制空城、非管制空域和特殊空域","C":"营制空域、非管制空域和报告空域","D":"监视空域、非监视空域和报告空域","answer":"A"},{"id":57,"type":"single","cat":"领航与任务规划","stem":"无人机物理限制对飞行航迹有以下限制（），最小航迹段较长度，最低安全飞行高度。","A":"最大转弯半径，最小俯仰角","B":"最小转弯半径，最小俯仰角","C":"最小转弯半径，最大俯仰角","D":"以上均不正确","answer":"C"},{"id":58,"type":"single","cat":"操纵与飞行技术","stem":"无人机的发射方式可归纳为手抛发射、零长发射、弹射发射、起落架滑跑起飞、母机、空中发射、容器式发射装置发射和垂直起飞等类型下列说法正确的是（）。","A":"在地面发射时，无人机使用较为广泛的发射方式是母机空中发射与零长发射","B":"无人机安装在轨道式发射装置上，在压缩空气、橡筋或液压等弹射装置作用下起飞，无人机飞离发射装置后，在辅助发动机作用下完成飞行任务","C":"容器式发射装置是一种封闭式发射装置，兼备发射与贮存无人机功能它有单室式和多室式两种类型","D":"以上均不正确","answer":"C"},{"id":59,"type":"single","cat":"操纵与飞行技术","stem":"以大疆精灵4飞行器为例，起飞前未移除云台扣会造成什么后果（）。","A":"损坏云台电机","B":"画面清晰无影响","C":"云台正常自检","D":"飞行器进入FPV模式","answer":"A"},{"id":60,"type":"single","cat":"操纵与飞行技术","stem":"固定翼无人机机动飞行时平飞速度的提升措施，下列选项正确的是（）。","A":"减小飞机载重量","B":"增大迎角","C":"增大机翼面积","D":"减小翼型厚度","answer":"D"},{"id":61,"type":"single","cat":"操纵与飞行技术","stem":"多轴飞行器悬停时的平衡不包括（）。","A":"方向平衡","B":"俯仰平衡","C":"前飞废阻力平衡","D":"以上均不正确","answer":"C"},{"id":62,"type":"single","cat":"基础概念","stem":"垂直起降固定翼无人机尾翼由安定面和（）构成。","A":"舵面","B":"外翼段","C":"中翼段","D":"尾翼","answer":"A"},{"id":63,"type":"single","cat":"设备与维护","stem":"遥控器、图传、地面站与飞行器之间数据链路分别是（）。","A":"上行链路、下行链路、上行链路","B":"上行链路、下行链路、上下行链路并存","C":"下行链路、下行链路、上行链路","D":"以上均不正确","answer":"B"},{"id":64,"type":"single","cat":"基础概念","stem":"在管制机场附近的所有航空器，以及在地面的航空器都应服从（）的指令。","A":"管制员","B":"机务人员","C":"机长","D":"副机长","answer":"A"},{"id":65,"type":"single","cat":"操纵与飞行技术","stem":"无人机重新起飞测试时，出现某台或多台电动机起动微调级时起动不一致的情况，此时首先需要（），直到所有电动机能够同步起动和停止。","A":"更换飞控","B":"重新校准油门行程","C":"更换接收机","D":"拆卸螺旋桨","answer":"B"},{"id":66,"type":"single","cat":"设备与维护","stem":"小型多旋翼无人机续航时间测试步骤，第一步是将多旋翼无人机放置在环境气候实验室中；第二步是调节所述环境气候实验室室内的压强P.温度T.（），模拟真实环境；第三步，启动电池电量饱和的多旋翼无人机，开始记录时间。","A":"湿度φ","B":"密度ρ","C":"高度H","D":"风速V","answer":"D"},{"id":67,"type":"single","cat":"法规与空域","stem":"起飞前，操作人员应逐项开展设备检查、系统自检、（）确保无人机处于适航状态。","A":"天气检查","B":"航线检查","C":"地面检查","D":"空域检查","answer":"B"},{"id":68,"type":"single","cat":"操纵与飞行技术","stem":"以大疆产品为例，飞行器姿态数据中，“V.S”代表什么？","A":"飞行器与起飞点之间的相对高度","B":"飞行器与起飞点之间的水平距离","C":"飞行器沿垂直方向的上升、下降速度","D":"飞行器沿水平运动的飞行速度","answer":"C"},{"id":69,"type":"single","cat":"领航与任务规划","stem":"就任务规划系统具备的功能而言，任务规划可包含航迹规划、任务分配规划、数据链路规划和系统保障与应急预案规划等，其中（）是任务规划的主体和核心。","A":"数据链路规划","B":"任务分配规划","C":"航迹规划","D":"以上均不正确","answer":"C"},{"id":70,"type":"single","cat":"操纵与飞行技术","stem":"旋翼无人机最主要的操纵面是（）。","A":"尾桨","B":"副翼","C":"方向舵","D":"旋翼","answer":"D"},{"id":71,"type":"single","cat":"操纵与飞行技术","stem":"姿态遥控模式下操纵无人机爬升，飞机爬升率过小时，下列正确的操纵是（）。","A":"柔和减小俯仰角","B":"柔和增大俯仰角","C":"迅速停止爬升","D":"以上均不正确","answer":"B"},{"id":72,"type":"single","cat":"基础概念","stem":"下列属于多旋翼无人机性能优化主要措施的是（）。","A":"功能改造，如任务载荷系统改造","B":"检修维保，如故障检修、维护保养等","C":"美观改造，如颜色、LOG等改造","D":"结构改造，如机体结构、减振、减噪等改造","answer":"D"},{"id":73,"type":"single","cat":"设备与维护","stem":"固定翼无人机方向舵和升降舵并排安装在舵机层板架上舵机配有减震用的橡胶垫，内有一个空心铆钉用螺钉固定时，空心铆钉起（）的作用。","A":"减小振幅","B":"平衡重心","C":"限制高度","D":"确定安装位置","answer":"C"},{"id":74,"type":"single","cat":"领航与任务规划","stem":"一般常见的组合导航系统以（）为主。","A":"天文导航和惯性导航","B":"图像匹配导航和卫星导航","C":"卫星导航和天文导航","D":"多卫星","answer":"D"},{"id":75,"type":"single","cat":"电力巡检","stem":"无人机巡检作业人员应具有（）年以上高压输电线路运行维护经验。","A":"1","B":"2","C":"3","D":"4","answer":"B"},{"id":76,"type":"single","cat":"航空气象","stem":"气温的变化，会严重影响电动无人机的哪项性能？","A":"速度性能","B":"续航性能","C":"载荷性能","D":"以上均不正确","answer":"B"},{"id":77,"type":"single","cat":"操纵与飞行技术","stem":"四轴飞行器为什么相邻的桨旋转方向不同？（）","A":"增加升力","B":"抵消反扭矩","C":"更加灵活","D":"以上均不正确","answer":"B"},{"id":78,"type":"single","cat":"操纵与飞行技术","stem":"无人机定速遥控飞行时收起起落架，驾驶员需（）。","A":"增加油门以保持空速","B":"减小油门以保持空速","C":"针对此情况，无需做相关动作","D":"以上均不正确","answer":"B"},{"id":79,"type":"single","cat":"飞行原理","stem":"实际升力和洗流方向是（）。","A":"平行的","B":"交叉的","C":"垂直的","D":"根据迎角变化","answer":"C"},{"id":80,"type":"single","cat":"设备与维护","stem":"一般电源适配器的最大输出功率要比充电器的最大最出功率大（）倍。","A":"1.2-1.5","B":"2-3","C":"2.5-3","D":"3-5","answer":"A"},{"id":81,"type":"single","cat":"领航与任务规划","stem":"下面哪项功能与GPS指南针模块无关（）。","A":"精准定位悬停","B":"定高","C":"保持飞行稳定","D":"失控返航","answer":"B"},{"id":82,"type":"single","cat":"操纵与飞行技术","stem":"是否装有（）也是无人驾驶航空器区别于普通航空模型的重要标志。","A":"定位系统","B":"飞控系统","C":"电力系统","D":"动力系统","answer":"B"},{"id":83,"type":"single","cat":"操纵与飞行技术","stem":"固定翼无人机动力装置安装时，对于油动发动机，油箱出油口与发动机连接，油箱进气管与消声器、增压嘴连接利用（）给油箱增压、加压，保证无人机在任何飞行姿态供油压力稳定。","A":"飞行惯性产生的压力","B":"空气流动产生的压力","C":"油料挥发产生的压力","D":"发动机的排气压力","answer":"D"},{"id":84,"type":"single","cat":"设备与维护","stem":"电调是多旋翼无人机最重要的部件之一，不属于飞行器电调功能的是（）。","A":"变压供电","B":"电机调速","C":"实时电机反转","D":"以上均不正确","answer":"C"},{"id":85,"type":"single","cat":"设备与维护","stem":"翼载荷（），飞行速度（），无人机的机动性较差，但飞行阻力小，抗风性和穿透性较好。","A":"小，慢","B":"小，快","C":"大，慢","D":"大，快","answer":"D"},{"id":86,"type":"single","cat":"操纵与飞行技术","stem":"无人机装配报告中桨叶安装复检包括（）、正反桨位置检查、螺旋桨安装牢固、垂起桨和平飞桨区分安装。","A":"桨叶动平衡检查","B":"桨叶静平衡检查","C":"桨叶效率检查","D":"桨叶无损检查","answer":"D"},{"id":87,"type":"single","cat":"领航与任务规划","stem":"以大疆产品为例，关于飞行器返航点描述正确的是？（）","A":"返航点可在飞行中刷新","B":"返航点不可在飞行中刷新","C":"室内飞行时可刷新返航点","D":"GPS信号弱时可刷新返航点","answer":"A"},{"id":88,"type":"single","cat":"基础概念","stem":"新出厂或组装后首次投入飞行的旋翼飞机，应在正式飞行之前进行（）。","A":"有桨调试","B":"无桨调试","C":"充电","D":"放电","answer":"B"},{"id":89,"type":"single","cat":"基础概念","stem":"现场禁止使用可能对无人机造成干扰的（）。","A":"遥控系统","B":"图传系统","C":"任务设备","D":"电子设备","answer":"D"},{"id":90,"type":"single","cat":"基础概念","stem":"以下那一项是无人飞行器的英文缩写（）。","A":"UAU","B":"ATC","C":"AUV","D":"UAV","answer":"D"},{"id":91,"type":"single","cat":"设备与维护","stem":"无刷电机动平衡性能对飞行器性能的影响，下面不包括的是（）。","A":"降低电调寿命","B":"影响飞行器飞行性能","C":"飞机振动","D":"影响电机寿命","answer":"A"},{"id":92,"type":"single","cat":"领航与任务规划","stem":"起落航线（五边航线）组成内容不包括（）。","A":"着陆目测、着陆","B":"任务飞行","C":"起飞、建立航线","D":"以上均不正确","answer":"B"},{"id":93,"type":"single","cat":"操纵与飞行技术","stem":"擦地着陆回收是通过无人机与地面摩擦阻力实现速度缓冲与能量吸收的着陆方式，擦地着陆不受地形条件和机型大小限制，成功着陆率高，但容易造成（）损伤，需要更换与维修。","A":"机体","B":"全球定位系统（GPS）模块","C":"电机","D":"接收机","answer":"A"},{"id":94,"type":"single","cat":"基础概念","stem":"如果多轴飞行器安装的螺旋桨与电动机不匹配，桨尺寸过大，会带来的坏处不包括（）。","A":"飞控电流过大，造成损坏","B":"电机电流过大，造成损坏","C":"电调电流过大，造成损坏","D":"以上均不正确","answer":"A"},{"id":95,"type":"single","cat":"设备与维护","stem":"电调是通过改变什么来控制电机转速的？（）","A":"电流","B":"电压","C":"功率","D":"以上均不正确","answer":"B"},{"id":96,"type":"single","cat":"设备与维护","stem":"下面那一部分不属于电调的组成部分（）。","A":"插头","B":"漆包线","C":"硅胶线","D":"信号线","answer":"B"},{"id":97,"type":"single","cat":"电力巡检","stem":"设备运维单位提前建立各型无人机巡检系统正常以及备选起飞和（），由工作许可人在地图上进行标注，并及时更新。","A":"线路资料信息","B":"设备信息","C":"起飞区档案","D":"降落区档案","answer":"D"},{"id":98,"type":"single","cat":"操纵与飞行技术","stem":"以大疆产品为例，飞行器飞行过程中，红色三角形位于姿态球左上方，三角形尖端朝向姿态球中心，请问飞行器处于操作者哪个位置，机头朝向如何？","A":"飞行器处于操作者左前方，机头朝向操作者自己","B":"飞行器处于操作者左后方，机头朝向操作者自己","C":"飞行器处于操作者右后方，机头朝向操作者前方","D":"飞行器处于操作者右前方，机头朝向操作者后方","answer":"A"},{"id":99,"type":"single","cat":"设备与维护","stem":"多轴飞行器飞控板上一般会安装（）。","A":"6个角速率陀螺","B":"1个角速率陀螺","C":"3个角速率陀螺","D":"以上均不正确","answer":"A"},{"id":100,"type":"single","cat":"领航与任务规划","stem":"无人机任务规划需要考虑的因素有（）、无人机物理限制、实时性要求。","A":"飞行任务范围，飞行安全限制","B":"飞行安全限制，飞行任务要求","C":"飞行环境限制，飞行任务要求","D":"以上均不正确","answer":"C"},{"id":101,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，为加强架空输电线路无人机巡检现场管理，规范各类工作人员的行为，保证（）安全，应遵循国家有关法律、法规，并结合电力生产的实际，开展架空输电线路无人机巡检作业。","A":"人身","B":"电网","C":"设备","D":"设施","answer":"ABC"},{"id":102,"type":"multi","cat":"电力巡检","stem":"无人直升机巡检系统应按要求定期（），确保状态良好。","A":"检查","B":"保养","C":"维修","D":"试验","answer":"BCD"},{"id":103,"type":"multi","cat":"基础概念","stem":"固定翼无人机性能升级的主要目标（）。","A":"提升航时","B":"改变焦点位置","C":"提高抗风性","D":"提高抗雨性","answer":"ACD"},{"id":104,"type":"multi","cat":"电力巡检","stem":"使用小型无人直升机巡检系统的巡检作业，操控手应在巡检作业前一个工作日（）。","A":"完成所用无人直升机巡检系统的检查","B":"确认状态正常","C":"准备好现场作业工器具","D":"备品备件等物资","answer":"ABCD"},{"id":105,"type":"multi","cat":"操纵与飞行技术","stem":"旋翼无人机按起飞重量可分为以下几种类型（）。","A":"微型旋翼无人机","B":"轻型旋翼无人机","C":"小型无人旋翼机","D":"大旋无人旋翼机","answer":"ABCD"},{"id":106,"type":"multi","cat":"基础概念","stem":"图元标注主要包括以下三个方面信息（）。","A":"航迹标注","B":"场地标注","C":"警示标注","D":"任务区域标注","answer":"BCD"},{"id":107,"type":"multi","cat":"领航与任务规划","stem":"（）时，作业人员应与无人直升机始终保持足够安全距离，避开起降航线。","A":"起飞","B":"巡视","C":"拍照","D":"降落","answer":"AD"},{"id":108,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，民用无人机可以分为（）。","A":"巡查/监视无人机","B":"农用无人机","C":"通信中继无人机","D":"勘探无人机","answer":"ABD"},{"id":109,"type":"single","cat":"基础概念","stem":"下列（）属于电动无人机的缺点。","A":"续航能力差","B":"系统稳定性差","C":"环境适应能力差","D":"震动大","answer":"A"},{"id":110,"type":"single","cat":"设备与维护","stem":"飞机飞行时感受到气流的冲击力量，即动压，与空气静止时的压力相比，从而转换出飞机空速需要用到的传感器是（）。","A":"姿态传感器","B":"高度传感器","C":"空速传感器","D":"位置传感器","answer":"C"},{"id":111,"type":"single","cat":"设备与维护","stem":"关于多轴飞行器机桨与电机匹配描述错误的是（）。","A":"2S电池下，KV1300-1500左右用9050浆","B":"3S电池下，KV900-1000的电机配1060或1047桨","C":"3S电池下，KV1200-1400配3寸桨","D":"以上均不正确","answer":"C"},{"id":112,"type":"single","cat":"基础概念","stem":"抵达现场，应报告（），履行飞行许可手续，获得许可后方可开展作业。","A":"机长","B":"空管部门","C":"工作负责人","D":"工作许可人","answer":"B"},{"id":113,"type":"single","cat":"基础概念","stem":"在目视范围内，操控手应密切观察无人直升机（）及周围环境变化，异常情况下，操控手可手动接管控制无人直升机。","A":"机架","B":"脚架","C":"光电吊舱","D":"飞行姿态","answer":"D"},{"id":114,"type":"single","cat":"设备与维护","stem":"属于无人机飞控子系统的是（）。","A":"无人机姿态稳定与控制","B":"无人机任务设备管理与控制","C":"信息收集与传递","D":"以上均不正确","answer":"A"},{"id":115,"type":"single","cat":"操纵与飞行技术","stem":"以大疆产品为例，DJIGO界面中，姿态球上绿色范围表示的是。","A":"飞行器云台朝向","B":"遥控器朝向","C":"移动设备朝向","D":"操作员朝向","answer":"A"},{"id":116,"type":"single","cat":"飞行原理","stem":"下列属于无人驾驶航空器产生升力的主要部件是（）。","A":"机翼","B":"尾翼","C":"燃料系统","D":"动力装置","answer":"A"},{"id":117,"type":"single","cat":"基础概念","stem":"无人机配平的主要考虑是重心沿（）的前后位置。","A":"纵轴","B":"横轴","C":"立轴","D":"以上均不正确","answer":"A"},{"id":118,"type":"single","cat":"基础概念","stem":"固定翼无人机配平主要考虑的是（）沿纵轴的前后位置。","A":"气动焦点","B":"发动机","C":"重心","D":"以上均不正确","answer":"C"},{"id":119,"type":"single","cat":"基础概念","stem":"多旋翼无人机以下哪个下降速度较为合理（）。","A":"2m/s","B":"5m/s","C":"8m/s","D":"以上均不正确","answer":"A"},{"id":120,"type":"single","cat":"基础概念","stem":"无识别标志的航空器因特殊情况需要飞行的（）。","A":"必须经相关管制单位批准","B":"必须经中国人民解放军空军批准","C":"必须经由国务院﹑中央军委空中交通管制委员会批准","D":"必须经民航局批准","answer":"B"},{"id":121,"type":"single","cat":"基础概念","stem":"民用无人机在条件允许的情况下，一般要（）。","A":"顺风起飞","B":"左侧风起飞","C":"逆风起飞","D":"以上均不正确","answer":"C"},{"id":122,"type":"single","cat":"基础概念","stem":"要想飞机飞行更稳定，负载应（）。","A":"靠近重心安装","B":"尽量向下远离重心位置安装","C":"尽量向上远离重心位置安装","D":"以上均不正确","answer":"A"},{"id":123,"type":"single","cat":"操纵与飞行技术","stem":"地面控制站功能主要包括以下几个方面：飞行状态的监测与控制、（）、飞行数据的记录与回放、模拟飞行。","A":"地图导航","B":"任务规划","C":"飞行控制","D":"地图导航与任务规划","answer":"D"},{"id":124,"type":"single","cat":"基础概念","stem":"固定翼无人机练习启动时，可用（）的螺旋桨，既容易启动，又不易反转和打手。","A":"直径较大和较重","B":"直径较小和较重","C":"直径较小和较轻","D":"直径较大和较轻","answer":"A"},{"id":125,"type":"single","cat":"航空气象","stem":"飞控系统主要由陀螺仪、加速度计、角速度计、气压计、GPS模块、指南针和控制电路等组成，主要功能是计算并调试无人机（）。","A":"飞行时间","B":"飞行姿态","C":"飞行距离","D":"飞行系统","answer":"B"},{"id":126,"type":"single","cat":"操纵与飞行技术","stem":"飞机起飞时后缘襟翼放下的角度小于着陆时放下的角度是因为（）。","A":"后缘襟翼放下角度比较小时，机翼的升力系数增加，阻力系数不增加","B":"后缘襟翼放下角度比较大时，机翼的阻力系数增加，升力系数不增加","C":"后缘襟翼放下角度比较小时，机翼的升力系数增加的效果大于阻力系数增加的效果","D":"以上均不正确","answer":"C"},{"id":127,"type":"single","cat":"操纵与飞行技术","stem":"无人机在遥控下降中，速度过大时，驾驶员应（）。","A":"适当减小带杆量，增大下滑角","B":"适当增加带杆量，减小下滑角","C":"顺其自然，让其自动恢复状态","D":"以上均不正确","answer":"B"},{"id":128,"type":"single","cat":"飞行原理","stem":"根据机翼产生升力的特性，飞行速度越快机翼产生的升力越大，为了保持无人机运动的水平，发动机还会有一定的（）。","A":"左拉角度","B":"右拉角度","C":"上拉角度","D":"下拉角度","answer":"D"},{"id":129,"type":"single","cat":"操纵与飞行技术","stem":"多轴飞行器悬停转向和以10km/h速度前飞转向中（）。","A":"横滚角不同","B":"横滚角不确定","C":"横滚角相同","D":"以上均不正确","answer":"A"},{"id":130,"type":"single","cat":"基础概念","stem":"多旋翼无人机螺旋桨静平衡测试中，有孔位分配法削、减法和（）。","A":"增重法","B":"剪切法","C":"更换法","D":"打磨法","answer":"A"},{"id":131,"type":"single","cat":"设备与维护","stem":"多旋翼在测试电机转动方向最重要的安全措施是（）。","A":"拆卸螺旋桨","B":"拆卸机臂","C":"拆卸电机","D":"以上均不正确","answer":"A"},{"id":132,"type":"single","cat":"操纵与飞行技术","stem":"无人机驾驶员舵面遥控操纵飞机时（）。","A":"拉杆飞机转入下降","B":"推油门飞机转入下降","C":"推杆飞机转入下降","D":"以上均不正确","answer":"C"},{"id":133,"type":"single","cat":"基础概念","stem":"高压线路的电线覆冰首先在（）生长，如风向不发生大的变化，迎风面上覆冰厚度会继续增加。","A":"导线两端","B":"导线下方","C":"迎风面上","D":"背风面上","answer":"C"},{"id":134,"type":"single","cat":"基础概念","stem":"4轴飞行器飞行运动中有（）。","A":"6个自由度，沿3轴移动，绕3轴转动","B":"4个自由度，绕4个轴转动","C":"4个自由度，沿3个轴移动","D":"以上均不正确","answer":"A"},{"id":135,"type":"single","cat":"基础概念","stem":"（）是指无人机发动机推力/拉力与无人机飞行重力之比该参数是衡量动力系统乃至整机性能的重要参数，很大程度上影响飞行性能。","A":"展弦比","B":"冗余度","C":"推重比","D":"以上均不正确","answer":"C"},{"id":136,"type":"single","cat":"操纵与飞行技术","stem":"固定翼常规无人机飞行主操纵面有（）。","A":"副翼、升降舵、方向舵、调整片","B":"副翼、升降舵(或全动平尾)、方向舵","C":"副翼","D":"以上均不正确","answer":"B"},{"id":137,"type":"single","cat":"操纵与飞行技术","stem":"下面关于悬停操纵说法错误的是（）。","A":"悬停时的姿态是各气动力和力矩以及重量、重心配平的结果，是唯一的","B":"在悬停中，要保持直升机没有前后移位，必须使纵向力和俯仰力矩平衡","C":"悬停时气动力自动保持平衡，无需频繁操纵","D":"以上均不正确","answer":"C"},{"id":138,"type":"single","cat":"操纵与飞行技术","stem":"X模式4轴飞行器从悬停转换到向右平移，哪两个轴需要减速（）。","A":"横轴右侧","B":"横轴左侧","C":"纵轴右侧","D":"以上均不正确","answer":"C"},{"id":139,"type":"single","cat":"操纵与飞行技术","stem":"（）的主要功能是监控无人驾驶航空器的飞行过程以及任务执行情况，它是一个实时采集并分析遥测数据、不定时发送控制指令、显示飞行状态等功能结合于一体的综合监控系统。","A":"地面控制站","B":"飞控系统","C":"动力系统","D":"电力系统","answer":"A"},{"id":140,"type":"single","cat":"航空气象","stem":"同一架无人机于某日中午和傍晚进行两次GPS高度200米的飞行，地面基准气压相同的前提下（）。","A":"中午的气压高度高","B":"傍晚的气压高度高","C":"中午和傍晚的气压高度一样高","D":"以上均不正确","answer":"A"},{"id":141,"type":"single","cat":"航空气象","stem":"下列选项中，关于气温影响飞机滑跑距离说法正确的是（）。","A":"气温高时，空气密度小，飞机增速慢，飞机的离地速度增大，起飞滑跑距离要长","B":"气温低时，空气密度小，飞机增速快，飞机升力减小，起飞滑跑距离要长","C":"气温高时，空气密度大，飞机增速快，飞机升力增大，起飞滑跑距离要短","D":"气温低时，空气密度大，飞机升力减小，起飞滑跑距离增加。","answer":"A"},{"id":142,"type":"single","cat":"基础概念","stem":"以下哪个不是在系统菜单设置里的功能？（）","A":"Sound","B":"UserName","C":"function","D":"以上均不正确","answer":"C"},{"id":143,"type":"single","cat":"操纵与飞行技术","stem":"四轴飞行器和八轴飞行器的区别是（）。","A":"四轴飞行时间短，效率高八轴更稳","B":"四轴飞行时间久，效率高八轴更稳","C":"八轴飞行时间久，效率高四轴更稳","D":"以上均不正确","answer":"B"},{"id":144,"type":"single","cat":"领航与任务规划","stem":"共轴式无人机的航向操纵多是如何实现的（）。","A":"通过操纵上下旋翼的自动倾斜器","B":"通过分别改变上下的旋翼的总距","C":"通过自动倾斜器和总距的联合操纵","D":"以上均不正确","answer":"B"},{"id":145,"type":"single","cat":"基础概念","stem":"无人直升机飞行过程中应避免进行超出其（）的飞行。","A":"飞行高度","B":"飞行距离","C":"性能指标","D":"遥控信号","answer":"C"},{"id":146,"type":"single","cat":"操纵与飞行技术","stem":"飞行驾驶员姿态遥控模式下操纵无人机下降时，下列正确的操纵是（）。","A":"如俯角过小，应柔和地向后带杆","B":"如俯角过小，应柔和地向左压杆","C":"如俯角过小，应柔和地向前顶杆","D":"以上均不正确","answer":"C"},{"id":147,"type":"single","cat":"操纵与飞行技术","stem":"无人机驾驶员操纵无人机地面滑行时，下列描述正确的是（）。","A":"主要通过控制方向舵杆量操纵","B":"主要通过控制副翼杆量操纵","C":"主要通过控制升降舵杆量操纵","D":"以上均不正确","answer":"A"},{"id":148,"type":"single","cat":"设备与维护","stem":"下列关于使用遥控器注意事项错误的是（）。","A":"电源检査及充电","B":"做好日常保养","C":"拉距离试验","D":"有桨开机试验","answer":"D"},{"id":149,"type":"single","cat":"操纵与飞行技术","stem":"垂直起降固定翼无人机外翼段主要为无人机提供（），外翼段上装有副翼，控制无人机的滚转运动。","A":"起降动力","B":"升力","C":"重力","D":"推力","answer":"B"},{"id":150,"type":"single","cat":"设备与维护","stem":"电池、电子调速器（电调）和电机三者之前的关系（）。","A":"电池输出电流≥电子调速器（电调）最大电流≥电动机最高承载电流","B":"电池输出电流≥电子调速器（电调）最高大电流≤电动机最高随载电流","C":"电池输出电流≤电子调速器（电调）最大电流≤电动机最高承载电流","D":"电池输出电流≤电子调速器（电调）最大电流≥电动机最高承载电流","answer":"A"},{"id":151,"type":"single","cat":"操纵与飞行技术","stem":"固定翼90度转弯风力对飞机影响（）。","A":"顺风大","B":"逆风大","C":"一样","D":"以上均不正确","answer":"C"},{"id":152,"type":"single","cat":"设备与维护","stem":"巡航阶段地面站上显示的重要飞行信息不包括（）。","A":"电池电压","B":"飞行速度","C":"飞行控制系统状态","D":"位置","answer":"C"},{"id":153,"type":"single","cat":"电力巡检","stem":"设备运维单位提前建立各型无人机巡检系统正常以及备选起飞和降落区档案，由（）在地图上进行标注，并及时更新。","A":"工作负责人","B":"工作许可人","C":"程控手","D":"操控手","answer":"B"},{"id":154,"type":"single","cat":"基础概念","stem":"机场上空高度较低的云会直接影响飞机的起降其中，危害最大的云是（）。","A":"对流云","B":"卷状云","C":"层状云","D":"层积云","answer":"A"},{"id":155,"type":"single","cat":"操纵与飞行技术","stem":"用下滑有利速度下滑，飞机的（）。","A":"升阻比最大","B":"升力最大","C":"下滑角最大","D":"以上均不正确","answer":"A"},{"id":156,"type":"single","cat":"设备与维护","stem":"一般民用无人机所使用遥控器的频率是（）。","A":"2.4ZHZ","B":"2.4GHZ","C":"2.4WHZ","D":"以上均不正确","answer":"B"},{"id":157,"type":"single","cat":"领航与任务规划","stem":"（）与任务规划是无人机地面站的主要功能。","A":"指挥控制","B":"导航","C":"飞行视角显示","D":"以上均不正确","answer":"A"},{"id":158,"type":"single","cat":"基础概念","stem":"活塞式发动机是将燃料在发动机气缸内部燃烧，将燃烧的化学能转变（）。","A":"动能","B":"热能","C":"机械能","D":"势能","answer":"B"},{"id":159,"type":"single","cat":"基础概念","stem":"据统计，无人机系统事故60%以上发生在（）。","A":"滑跑阶段","B":"起降阶段","C":"巡航阶段","D":"以上均不正确","answer":"B"},{"id":160,"type":"single","cat":"操纵与飞行技术","stem":"飞行驾驶员操纵无人转弯时，下列描述正确的操纵方式是（）。","A":"机头过低时，应向转弯一侧的斜后方适当拉杆并稍回舵","B":"机头过低时，应向转弯一侧的斜前方适当推杆并稍扭舵","C":"机头过低时，应向转弯一侧的斜前方适当拉杆并稍扭舵","D":"以上均不正确","answer":"A"},{"id":161,"type":"single","cat":"基础概念","stem":"以下哪种闪灯情况，可判定为指南针异常（）。","A":"飞行器LED紫黄灯交替快闪","B":"飞行器LED黄红灯交替慢闪","C":"飞行器LED黄灯快闪","D":"飞行器LED红灯常亮","answer":"B"},{"id":162,"type":"single","cat":"基础概念","stem":"在温暖的天气飞行中，在较低高度有时会遇上湍流空气，以下描述正确的是（）。","A":"很可能在路面和荒地上空发生上升气流","B":"在类似成片树林的广阔植被区域发生上升气流","C":"在大片水体区域发生上升气流","D":"在路面和荒地遇到下沉气流","answer":"A"},{"id":163,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机转弯时产生偏差的主要原因不包括（）。","A":"进入和退出转弯时，动作不协调，产生侧滑","B":"天气状况不佳","C":"转弯中，未保持好机头与天地线的关系位置，以致速度增大或减小","D":"以上均不正确","answer":"B"},{"id":164,"type":"single","cat":"设备与维护","stem":"关于无刷电机下列说法正确的是（）。","A":"定子是线圈，转子是磁极","B":"用直流电直接可以驱动","C":"有碳刷","D":"寿命较短","answer":"A"},{"id":165,"type":"single","cat":"领航与任务规划","stem":"（）主要指执行任务过程中实现动作的时间点、方式和方法，设定航点的时间节点，飞行高度、航速、飞行姿态以及配合载荷设备的工作状态和模式，当无人机到达该航点时实施航拍、盘旋等飞行任务。","A":"任务分配","B":"载荷规划","C":"目标分配","D":"以上均不正确","answer":"C"},{"id":166,"type":"single","cat":"基础概念","stem":"六旋翼无人机，其六个螺旋桨旋转方向分别为（）。","A":"全部顺时针或逆时针","B":"三个顺时针三个逆时针","C":"两个顺时针两个逆时针，另外两个方向无所谓","D":"螺旋桨旋转方向可随意设置","answer":"B"},{"id":167,"type":"single","cat":"设备与维护","stem":"（）主要是制定无人机飞行任务、完成无人机载荷数据的处理和应用，指挥中心/数据处理中心一般都是通过无人机控制站等间接地实现对无人机的控制和数据接收。","A":"无人机控制站","B":"指挥处理中心","C":"载荷控制站","D":"以上均不正确","answer":"B"},{"id":168,"type":"single","cat":"基础概念","stem":"以下不属于航空器的是（）。","A":"直升机","B":"飞艇","C":"卫星","D":"以上均不正确","answer":"C"},{"id":169,"type":"single","cat":"电力巡检","stem":"用计算机生成或打印的工作票应使用统一的票面格式由（）审核无误，手工或电子签名后方可执行。","A":"工作票签发人","B":"工作许可人","C":"工作负责人","D":"专责监护人","answer":"A"},{"id":170,"type":"single","cat":"设备与维护","stem":"无人机航时长短除了与电池性能有关以外，还有一些外在的因素也会对无人机的续航能力有影响，比如天气原因、飞行的方式、（）。","A":"信号距离","B":"飞机的重量","C":"飞行模式","D":"驾驶员操作技术","answer":"B"},{"id":171,"type":"single","cat":"设备与维护","stem":"djipc地面站实时建图最大的优点是什么（）。","A":"可以实时建图","B":"能编辑航线","C":"能添加航点","D":"能控制云台","answer":"A"},{"id":172,"type":"single","cat":"航空气象","stem":"气压传感器测的是以下哪个高度？（）","A":"相对高度","B":"海拔高度","C":"无线电高度","D":"以上均不正确","answer":"B"},{"id":173,"type":"single","cat":"设备与维护","stem":"锂聚合物电池的标称电压是（）。","A":"1.2V","B":"4.2V","C":"3.7V","D":"以上均不正确","answer":"C"},{"id":174,"type":"single","cat":"基础概念","stem":"旋翼机可以用（）的飞行代替滑行。","A":"1米至5米高度","B":"1米至10米高度","C":"1米至15米高度","D":"以上均不正确","answer":"B"},{"id":175,"type":"single","cat":"航空气象","stem":"影响飞行的三大气象要素为（）。","A":"气温、气压和空气湿度","B":"气温、风和云","C":"风、云和降水","D":"气温、风向、降水","answer":"A"},{"id":176,"type":"single","cat":"设备与维护","stem":"飞行控制系统（自驾仪）安装水平面应与（）。","A":"机翼平面平行","B":"水平尾翼平面平行","C":"机身水平面平行","D":"随意安装","answer":"C"},{"id":177,"type":"single","cat":"设备与维护","stem":"线圈匝数越多的电机，kv值（）。","A":"越高","B":"无关","C":"越低","D":"以上均不正确","answer":"C"},{"id":178,"type":"single","cat":"设备与维护","stem":"安装无人机的惯性测量单元（IMU）时要求靠近飞行器的（），并有一定的减震和指向要求。","A":"中心","B":"压力中心","C":"焦点","D":"重心","answer":"D"},{"id":179,"type":"single","cat":"操纵与飞行技术","stem":"相当于无人驾驶航空器大脑的是（）。","A":"定位系统","B":"飞控系统","C":"电力系统","D":"动力系统","answer":"B"},{"id":180,"type":"single","cat":"设备与维护","stem":"聚合物锂电池单体充满电后的电压一般为（）。","A":"3.7V","B":"4.2V","C":"3.3V","D":"以上均不正确","answer":"B"},{"id":181,"type":"single","cat":"基础概念","stem":"（）与无人机控制站的功能类似，但只能控制无人机的机载任务设备，不能进行无人机的飞行控制。","A":"指挥处理中心","B":"无人机控制站","C":"载荷控制站","D":"飞控子系统","answer":"C"},{"id":182,"type":"single","cat":"设备与维护","stem":"维护保养人员应按要求（）按时开展日常维护、零件维修更换、大修保养和试验等工作。","A":"使用经验","B":"使用说明书","C":"飞行手册","D":"维护保养手册","answer":"D"},{"id":183,"type":"single","cat":"电力巡检","stem":"设备运维单位应建立（），包括：线路走向和走势、交叉跨越情况、杆塔坐标、周边地形地貌等，并核实无误。","A":"线路资料信息","B":"设备信息","C":"起飞区档案","D":"降落区档案","answer":"A"},{"id":184,"type":"single","cat":"基础概念","stem":"多旋翼无人机飞行后的检查，下列选项错误的是（）。","A":"检查电子罗盘、IMU等的指向是否和多旋翼无人机机头指向一致","B":"飞行结束后按清单清点设备、材料和工具","C":"飞行结束后及时检查无人机完好情况，发现有缺陷的要及时更换修复","D":"飞行结束后，及时检查飞行附属设备，如云台、工具、材料、电脑等使用状况","answer":"A"},{"id":185,"type":"single","cat":"基础概念","stem":"多旋翼飞行器通常装有（）具以上旋翼。","A":"四","B":"三","C":"二","D":"一","answer":"B"},{"id":186,"type":"single","cat":"基础概念","stem":"（）航空器平台结构通常包括机翼、机身、尾翼和起落架等。","A":"单旋翼","B":"多旋翼","C":"固定翼","D":"以上均不正确","answer":"C"},{"id":187,"type":"single","cat":"基础概念","stem":"下列说法错误的是（没有提到的条件则为相同）（）。","A":"旋翼直径越大则拉力越大","B":"旋翼直径越大则悬停诱导速度越大","C":"旋翼直接越大则桨盘载荷越小标准","D":"以上均不正确","answer":"B"},{"id":188,"type":"single","cat":"操纵与飞行技术","stem":"无人机系统中，起降驾驶员一般不参与哪个阶段控制（）。","A":"降落阶段","B":"巡航阶段","C":"起飞阶段","D":"以上均不正确","answer":"B"},{"id":189,"type":"single","cat":"飞行原理","stem":"利用增大机翼弯度来提高机翼的升力系数，会导致（）。","A":"机翼上表面最低压力点前移，减小临界迎角","B":"机翼上表面最低压力点后移，减小临界迎角","C":"机翼上表面最低压力点前移，加大临界迎角","D":"以上均不正确","answer":"A"},{"id":190,"type":"single","cat":"基础概念","stem":"下列哪一项是飞行重规划要考虑的内容（）。","A":"已知威胁区域","B":"未知威胁区域","C":"无人机自身约束条件","D":"以上均不正确","answer":"B"},{"id":191,"type":"single","cat":"操纵与飞行技术","stem":"多轴左右平移时，飞机姿态是绕哪根轴发生变化？（）","A":"纵轴","B":"横轴","C":"立轴","D":"以上均不正确","answer":"A"},{"id":192,"type":"single","cat":"基础概念","stem":"在中华人民共和国境内飞行的航空器必须遵守统一的飞行规则，该飞行规则应当由（）制定。","A":"中国民用航空局和中共中央军事委员会","B":"中共中央军事委员会 \"","C":"中华人民共和国国务院和中共中央军事委员会\"","D":"中华人民共和国民用航空局","answer":"C"},{"id":193,"type":"single","cat":"操纵与飞行技术","stem":"视距内飞行定义中的高度，一般是指人、机相对高度不超过起飞点（）米。","A":"100米","B":"120米","C":"500米","D":"1000米","answer":"B"},{"id":194,"type":"single","cat":"设备与维护","stem":"关于部分多轴飞行器，机臂上反角设计描述正确的是（）。","A":"提高稳定性","B":"提高机动性","C":"减少电力损耗","D":"以上均不正确","answer":"A"},{"id":195,"type":"single","cat":"领航与任务规划","stem":"姿态遥控模式下操纵无人机爬升，飞机航向向左偏离时，下列正确的操纵是（）。","A":"应柔和地向右扭舵","B":"应柔和地向左扭舵","C":"应柔和地向前顶杆","D":"以上均不正确","answer":"A"},{"id":196,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检系统配置导则》中：小型无人直升机巡检和固定翼无人机巡检工作班成员至少应包括（）。","A":"指挥手","B":"操控手","C":"程控手","D":"任务手","answer":"BC"},{"id":197,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中：以下对中型无人机的巡线效果说法正确的是（）。","A":"飞行准备时间长。","B":"可定点悬停","C":"机动灵活率高","D":"发现隐蔽缺陷能力强","answer":"BCD"},{"id":198,"type":"multi","cat":"基础概念","stem":"在《输变电工程无人机航空摄影测量技术应用导则》中，输变电工程中应积极稳妥地采用无人机航空摄影测量技术，辅助优化输变电工程的（）和（）。","A":"可行性研究报告","B":"施工方案","C":"初步设计","D":"施工图设计","answer":"CD"},{"id":199,"type":"multi","cat":"基础概念","stem":"一般白平衡的模式包括（）。","A":"自动模式","B":"RAW模式","C":"阴天模式","D":"自定义模式","answer":"ACD"},{"id":200,"type":"multi","cat":"设备与维护","stem":"动力系统维护，做法正确的是（）。","A":"定时用手旋转电机，看是否顺畅","B":"桨叶有缺口继续使用","C":"作业期间定期清理电机农药残留","D":"桨叶上下表面应定时清理农药残留","answer":"ACD"},{"id":201,"type":"multi","cat":"基础概念","stem":"无人机平台外观质量需满足以下技术要求（）。","A":"外观结构。整机外观美观整洁、结构坚固、无裸露导线。","B":"外壳材料。外壳为绝缘复合材料，外壳包覆完全。","C":"连接紧固性。部件间连接紧固，紧固件、连接件有防松措施。","D":"设备表面。","answer":"ABCD"},{"id":202,"type":"multi","cat":"电力巡检","stem":"操控手是利用遥控器以（）或（）模式控制无人机巡检系统飞行的工作人员。","A":"手动","B":"增稳","C":"全自主","D":"半自主","answer":"AB"},{"id":203,"type":"single","cat":"法规与空域","stem":"根据中国民航局分类标准，重量为2.5kg的无人机属于（）。","A":"微型无人机","B":"轻型无人机","C":"小型无人机","D":"大型无人机","answer":"B","exp":"注：微型≤0.25kg，轻型0.254kg，小型420kg，大型＞20kg"},{"id":204,"type":"single","cat":"基础概念","stem":"无人机视距内飞行的最大高度限制（真高）为（）。","A":"50米","B":"120米","C":"300米","D":"500米","answer":"B","exp":"依据《无人驾驶航空器飞行管理暂行条例》，视距内真高不超过120米"},{"id":205,"type":"single","cat":"飞行原理","stem":"多旋翼无人机悬停时，升力主要由（）提供。","A":"机翼","B":"螺旋桨旋转产生的反作用力","C":"尾翼","D":"空气浮力","answer":"B","exp":"多旋翼依靠螺旋桨旋转产生升力"},{"id":206,"type":"single","cat":"设备与维护","stem":"无人机遥控器常用的2.4GHz频段属于（）。","A":"长波","B":"中波","C":"短波","D":"微波","answer":"D","exp":"2.4GHz为微波频段，用于短距离无线通信"},{"id":207,"type":"single","cat":"领航与任务规划","stem":"GPS模式下，无人机的定位精度通常为（）。","A":"0.10.5米","B":"15米","C":"1020米","D":"50100米","answer":"B","exp":"民用GPS定位精度一般为25米，RTK差分可提升至厘米级"},{"id":208,"type":"single","cat":"设备与维护","stem":"锂聚合物电池（LiPo）的标称电压为（）。","A":"3.7V/节","B":"1.2V/节","C":"1.5V/节","D":"4.2V/节","answer":"A","exp":"LiPo单节标称电压3.7V，满电4.2V"},{"id":209,"type":"single","cat":"基础概念","stem":"无人机避障系统中，激光雷达（LiDAR）的主要优势是（）。","A":"成本低","B":"抗干扰性强","C":"探测精度高","D":"适应雨雾环境","answer":"C","exp":"激光雷达通过激光测距，精度可达厘米级"},{"id":210,"type":"single","cat":"操纵与飞行技术","stem":"当飞行环境风速超过（）时，多旋翼无人机需谨慎起飞。","A":"3m/s","B":"6m/s","C":"10m/s","D":"15m/s","answer":"B","exp":"多旋翼抗风能力一般为56级风，即813.8m/s，但6m/s为安全临界值"},{"id":211,"type":"single","cat":"法规与空域","stem":"我国管制空域分为（）类。","A":"3","B":"5","C":"7","D":"9","answer":"C","exp":"A、B、C、D、E、F、G七类，其中G类为非管制空域"},{"id":212,"type":"single","cat":"操纵与飞行技术","stem":"起飞前检查中，无需确认的项目是（）。","A":"电池电量","B":"飞控校准状态","C":"周边电磁环境","D":"无人机颜色","answer":"D","exp":"颜色不影响飞行安全"},{"id":213,"type":"single","cat":"领航与任务规划","stem":"无人机飞行日志中，GPS卫星数显示为4颗时，通常（）。","A":"可正常定位","B":"仅能2D定位","C":"无法定位","D":"进入姿态模式","answer":"B","exp":"3颗卫星2D定位，4颗及以上3D定位"},{"id":214,"type":"single","cat":"基础概念","stem":"农业植保无人机的喷头流量调节主要影响（）。","A":"飞行速度","B":"药液覆盖密度","C":"电池续航","D":"避障精度","answer":"B","exp":"流量越大，单位面积药液量越多"},{"id":215,"type":"single","cat":"基础概念","stem":"无人机在海拔1000米以上高原飞行时，需调整的参数是（）。","A":"最大速度","B":"起飞重量","C":"气压计校准","D":"图传频率","answer":"C","exp":"高原气压低，需重新校准气压计以确保高度计准确"},{"id":216,"type":"single","cat":"基础概念","stem":"反制无人机的电子围栏技术主要通过（）实现。","A":"物理拦截","B":"信号干扰","C":"激光摧毁","D":"网捕","answer":"B","exp":"电子围栏通过发射同频干扰信号限制无人机进入"},{"id":217,"type":"single","cat":"基础概念","stem":"无人机飞行中出现磁罗盘干扰警告时，正确操作是（）。","A":"继续飞行并记录数据","B":"立即降落并重新校准","C":"加速飞离当前区域","D":"切换至手动模式","answer":"B","exp":"磁罗盘干扰会导致航向错误，需降落校准"},{"id":218,"type":"single","cat":"基础概念","stem":"多旋翼无人机的轴距指（）。","A":"螺旋桨直径","B":"电机中心到中心的对角线距离","C":"机身长度","D":"桨叶尖端间距","answer":"B","exp":"轴距是多旋翼电机安装位置的对角线距离"},{"id":219,"type":"single","cat":"设备与维护","stem":"无人机图传系统的延迟应控制在（）以内以保证操作安全。","A":"50ms","B":"200ms","C":"500ms","D":"1000ms","answer":"B","exp":"延迟超过200ms可能导致操作滞后，影响避障"},{"id":220,"type":"single","cat":"航空气象","stem":"以下气象条件中，最适合无人机飞行的是（）。","A":"小雨，能见度5km","B":"晴，风速4m/s，湿度60%","C":"雾，能见度1km","D":"雷暴，风速12m/s","answer":"B","exp":"晴、低风速、适宜湿度为理想条件"},{"id":221,"type":"single","cat":"领航与任务规划","stem":"无人机失控返航功能的触发条件不包括（）。","A":"遥控器信号丢失","B":"电池电量低于阈值","C":"GPS信号丢失","D":"飞手主动触发","answer":"C","exp":"GPS丢失时可能切换至姿态模式，不一定触发返航"},{"id":222,"type":"single","cat":"基础概念","stem":"物流无人机的最大载重通常指（）。","A":"电池重量","B":"机身重量+载重","C":"除去机身重量的有效载重","D":"起飞总重量","answer":"C","exp":"最大载重为有效载荷，不包括机身和电池"},{"id":223,"type":"single","cat":"设备与维护","stem":"无人机桨叶动平衡不良会导致（）。","A":"续航增加","B":"电机发热异常","C":"图传信号增强","D":"飞控校准成功","answer":"B","exp":"动平衡差会导致电机负载不均，发热加剧"},{"id":224,"type":"single","cat":"法规与空域","stem":"以下属于特殊空域的是（）。","A":"居民区上空","B":"机场净空区","C":"农田上方","D":"公园广场","answer":"B","exp":"机场净空区、军事管理区等为特殊空域，需专项申请"},{"id":225,"type":"single","cat":"基础概念","stem":"无人机飞行高度的参考基准通常是（）。","A":"平均海平面","B":"起飞点地面","C":"最近建筑物顶部","D":"当地海拔","answer":"B","exp":"无人机高度一般指相对于起飞点的相对高度，或真高"},{"id":226,"type":"single","cat":"基础概念","stem":"农业植保无人机的喷幅指（）。","A":"单次飞行覆盖的宽度","B":"喷头数量","C":"药液容量","D":"飞行速度","answer":"A","exp":"喷幅是药液喷洒的横向覆盖宽度"},{"id":227,"type":"single","cat":"设备与维护","stem":"无人机电池循环寿命指（）。","A":"充满电的次数","B":"放电至0%的次数","C":"充放电至80%容量的次数","D":"存放时间","answer":"C","exp":"循环寿命一般定义为容量降至初始80%时的充放电次数"},{"id":228,"type":"single","cat":"操纵与飞行技术","stem":"无人机手动模式下，飞手需完全控制（）。","A":"油门、俯仰、横滚、航向","B":"仅油门","C":"自动返航","D":"避障","answer":"A","exp":"手动模式无飞控辅助，需手动控制所有动作"},{"id":229,"type":"single","cat":"基础概念","stem":"以下不属于黑飞行为的是（）。","A":"在机场5km内飞行","B":"未申请空域飞行","C":"按计划在非管制空域飞行","D":"超过高度限制飞行","answer":"C","exp":"合法申请并在批准范围内飞行不属于黑飞"},{"id":230,"type":"single","cat":"基础概念","stem":"无人机视觉定位系统在（）环境下失效。","A":"室内无GPS","B":"纯色地面（如雪地）","C":"光照充足","D":"纹理丰富地面","answer":"B","exp":"视觉定位依赖地面纹理，纯色地面无法识别"},{"id":231,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机悬停功耗主要受（）影响最大。","A":"螺旋桨直径","B":"电池容量","C":"飞控型号","D":"环境温度","answer":"A","exp":"桨径越大，产生相同升力所需转速越低，功耗越小"},{"id":232,"type":"single","cat":"设备与维护","stem":"无人机抗风等级标注为6级，对应的风速范围是（）。","A":"3.4~5.4m/s","B":"5.5~7.9m/s","C":"8.0~10.7m/s","D":"10.8~13.8m/s","answer":"C","exp":"6级风为8.0~10.7m/s，对应强风"},{"id":233,"type":"multi","cat":"操纵与飞行技术","stem":"无人机起飞前需检查的项目包括（）。","A":"电池电量是否达标","B":"螺旋桨安装是否牢固","C":"飞控IMU校准状态","D":"周边是否有电磁干扰源","answer":"ABCD","exp":"所有选项均为安全飞行必要检查"},{"id":234,"type":"multi","cat":"法规与空域","stem":"以下属于无人机禁飞区的有（）。","A":"军事管理区上空","B":"核电站周边5km","C":"大型运动会场馆","D":"普通居民小区","answer":"ABC","exp":"居民区非禁飞区，但需遵守高度限制"},{"id":235,"type":"multi","cat":"基础概念","stem":"多旋翼无人机的系统组成包括（）。","A":"飞控系统","B":"动力系统","C":"图传系统","D":"导航系统","answer":"ABCD","exp":"多旋翼由飞控、动力、图传、导航等子系统组成"},{"id":236,"type":"multi","cat":"基础概念","stem":"影响无人机续航时间的因素有（）。","A":"飞行速度","B":"环境温度","C":"载重重量","D":"电池老化程度","answer":"ABCD","exp":"速度越快、温度越低、载重越大、电池老化，续航越短"},{"id":237,"type":"multi","cat":"设备与维护","stem":"无人机飞行中出现电机异常发热可能的原因是（）。","A":"桨叶动平衡差","B":"电机进水","C":"飞控参数错误","D":"电池电压过高","answer":"ABC","exp":"电池电压过高会导致过流，但正常电压下发热多因机械或参数问题"},{"id":238,"type":"multi","cat":"基础概念","stem":"视距内飞行（VLOS）的要求包括（）。","A":"驾驶员肉眼可见无人机","B":"飞行高度≤120米","C":"无需额外通信设备","D":"需持有驾驶员执照","answer":"ABC","exp":"视距内飞行对执照的要求根据无人机重量而定，微型无人机可无执照"},{"id":239,"type":"multi","cat":"基础概念","stem":"无人机电磁干扰的可能来源有（）。","A":"高压输电线","B":"手机信号塔","C":"汽车火花塞","D":"无人机自身电机","answer":"ABCD","exp":"强电磁源及设备内部电磁辐射均可能干扰"},{"id":240,"type":"multi","cat":"设备与维护","stem":"锂聚合物电池的安全操作包括（）。","A":"充电电流不超过1C","B":"存放电压3.8~3.9V/节","C":"避免过放（＜3.0V/节）","D":"高温环境下充电","answer":"ABC","exp":"高温充电易引发电池膨胀甚至起火"},{"id":241,"type":"multi","cat":"领航与任务规划","stem":"无人机航线规划的原则包括（）。","A":"避开禁飞区","B":"预留安全高度","C":"减少急转动作","D":"优先逆风飞行","answer":"ABC","exp":"逆风飞行会增加功耗，通常优先顺风或侧风"},{"id":242,"type":"multi","cat":"设备与维护","stem":"无人机飞行日志中需记录的关键数据有（）。","A":"GPS坐标","B":"电池电压/电流","C":"飞控温度","D":"遥控器信号强度","answer":"ABCD","exp":"所有选项均为故障分析的关键数据"},{"id":243,"type":"single","cat":"法规与空域","stem":"民用无人机系统的机长是指（）。","A":"操控无人机的人","B":"负责整个飞行任务安全和运行的人","C":"协助操控无人机的人","D":"仅负责地面监控的人员","answer":"B"},{"id":244,"type":"single","cat":"设备与维护","stem":"无人机飞行前，检查电池时不需要检查的是（）。","A":"电池电量","B":"电池外观有无破损","C":"电池品牌","D":"电池连接是否牢固","answer":"C"},{"id":245,"type":"single","cat":"基础概念","stem":"以下哪种天气条件最不适合无人机飞行（）。","A":"晴天微风","B":"小雨","C":"阴天少云","D":"风速2~3米/秒","answer":"B"},{"id":246,"type":"single","cat":"基础概念","stem":"无人机在海拔较高地区飞行时，空气密度降低，会导致（）。","A":"升力增加","B":"升力减小","C":"飞行速度加快","D":"电机效率提高","answer":"B"},{"id":247,"type":"single","cat":"领航与任务规划","stem":"无人机的GPS定位模式下，通常能实现（）。","A":"自主悬停","B":"高速飞行","C":"倒飞","D":"自动避障","answer":"A"},{"id":248,"type":"single","cat":"设备与维护","stem":"无人机飞行中，出现炸机现象通常是指（）。","A":"无人机正常降落","B":"无人机在空中平稳飞行","C":"无人机坠毁","D":"无人机失去信号","answer":"C"},{"id":249,"type":"single","cat":"操纵与飞行技术","stem":"无人机的最大起飞重量是指（）。","A":"无人机自身重量","B":"无人机可携带的最大载荷重量","C":"无人机自身重量与最大载荷重量之和","D":"无人机空机重量","answer":"C"},{"id":250,"type":"single","cat":"设备与维护","stem":"多旋翼无人机的桨叶通常采用（）设计。","A":"对称翼型","B":"非对称翼型","C":"平板翼型","D":"三角翼型","answer":"B"},{"id":251,"type":"single","cat":"设备与维护","stem":"无人机飞行中，若遥控器信号丢失，以下做法正确的是（）。","A":"立即切断电源","B":"等待信号自动恢复","C":"打开无人机的自动返航功能","D":"尝试手动操作返回","answer":"C"},{"id":252,"type":"single","cat":"法规与空域","stem":"以下关于无人机保险的说法，错误的是（）。","A":"可以保障无人机在飞行中因意外事故造成的损失","B":"购买保险后可以随意飞行","C":"不同的保险条款保障范围不同","D":"保险可以降低飞行风险带来的经济损失","answer":"B"},{"id":253,"type":"single","cat":"基础概念","stem":"无人机飞行高度一般以（）为基准进行测量。","A":"当地地面","B":"海平面","C":"建筑物顶部","D":"树木顶部","answer":"B"},{"id":254,"type":"single","cat":"操纵与飞行技术","stem":"无人机的飞行姿态主要由（）传感器测量。","A":"气压计","B":"陀螺仪","C":"加速度计","D":"以上都是","answer":"D"},{"id":255,"type":"single","cat":"基础概念","stem":"无人机飞行时，遇到强风，应该（）。","A":"继续保持原高度飞行","B":"降低飞行高度","C":"增加飞行高度","D":"加速飞行","answer":"B"},{"id":256,"type":"single","cat":"基础概念","stem":"无人机的飞行限制区域不包括（）。","A":"机场净空保护区","B":"军事管理区","C":"人口密集区","D":"空旷农田","answer":"D"},{"id":257,"type":"single","cat":"设备与维护","stem":"以下哪种电池适合用于无人机（）。","A":"碱性电池","B":"镍氢电池","C":"锂电池","D":"铅酸电池","answer":"C"},{"id":258,"type":"single","cat":"基础概念","stem":"无人机在飞行中突然出现抖动，可能的原因是（）。","A":"电池电量充足","B":"桨叶安装不平衡","C":"飞行高度过低","D":"遥控器信号强","answer":"B"},{"id":259,"type":"single","cat":"基础概念","stem":"无人机的飞行记录可以帮助（）。","A":"分析飞行问题和改进飞行技术","B":"增加飞行速度","C":"提高电池续航能力","D":"改变无人机外观","answer":"A"},{"id":260,"type":"single","cat":"设备与维护","stem":"多旋翼无人机的电机转速增加时，（）。","A":"升力减小","B":"升力增加","C":"飞行速度降低","D":"电池消耗减慢","answer":"B"},{"id":261,"type":"single","cat":"设备与维护","stem":"无人机飞行前，对遥控器的检查不包括（）。","A":"遥控器电量","B":"遥控器天线是否完好","C":"遥控器的颜色","D":"遥控器的功能按键是否正常","answer":"C"},{"id":262,"type":"single","cat":"法规与空域","stem":"以下关于无人机实名登记的说法，正确的是（）。","A":"不需要进行实名登记","B":"只有大型无人机需要实名登记","C":"所有民用无人机都需要实名登记","D":"只有商业用途的无人机需要实名登记","answer":"C"},{"id":263,"type":"single","cat":"基础概念","stem":"无人机在夜间飞行时，需要（）。","A":"关闭灯光","B":"打开警示灯","C":"仅依靠GPS定位","D":"高速飞行","answer":"B"},{"id":264,"type":"single","cat":"基础概念","stem":"无人机的飞行范围受到（）限制。","A":"电池续航能力","B":"遥控器信号范围","C":"法律法规","D":"以上都是","answer":"D"},{"id":265,"type":"single","cat":"基础概念","stem":"无人机的水平尾翼主要作用是（）。","A":"增加飞行速度","B":"控制俯仰姿态","C":"增加升力","D":"减少阻力","answer":"B"},{"id":266,"type":"single","cat":"基础概念","stem":"无人机飞行中，若遇到电磁干扰，可能会导致（）。","A":"飞行速度加快","B":"飞行姿态失控","C":"电池电量增加","D":"桨叶转速加快","answer":"B"},{"id":267,"type":"single","cat":"领航与任务规划","stem":"以下关于无人机航点规划的说法，错误的是（）。","A":"可以实现无人机的自动飞行","B":"航点规划需要考虑地形和障碍物","C":"航点规划完成后不能修改","D":"合理的航点规划可以提高飞行效率","answer":"C"},{"id":268,"type":"single","cat":"基础概念","stem":"无人机的动力系统不包括（）。","A":"电机","B":"桨叶","C":"电池","D":"飞控系统","answer":"D"},{"id":269,"type":"single","cat":"设备与维护","stem":"无人机在飞行中，若出现电机过热，应该（）。","A":"继续飞行","B":"立即增加电机转速","C":"降低飞行高度","D":"降落检查","answer":"D"},{"id":270,"type":"single","cat":"基础概念","stem":"以下关于无人机避障系统的说法，正确的是（）。","A":"所有无人机都有避障系统","B":"避障系统能完全避免碰撞","C":"避障系统可以检测前方和下方障碍物","D":"避障系统不需要维护","answer":"C"},{"id":271,"type":"single","cat":"基础概念","stem":"无人机飞行时，若遇到大雨，应该（）。","A":"继续飞行完成任务","B":"降低飞行速度","C":"尽快降落","D":"升高飞行高度","answer":"C"},{"id":272,"type":"single","cat":"法规与空域","stem":"无人机的飞行执照分为（）。","A":"一种","B":"两种","C":"三种","D":"四种","answer":"C"},{"id":273,"type":"multi","cat":"基础概念","stem":"以下属于无人机飞行前准备工作的有（）。","A":"检查无人机外观","B":"校准飞控系统","C":"规划飞行路线","D":"检查电池电量","answer":"ABCD"},{"id":274,"type":"multi","cat":"基础概念","stem":"影响无人机飞行安全的因素有（）。","A":"天气条件","B":"飞行环境","C":"操作人员技能","D":"无人机设备状况","answer":"ABCD"},{"id":275,"type":"multi","cat":"基础概念","stem":"无人机的飞行模式通常有（）。","A":"GPS定位模式","B":"手动模式","C":"姿态模式","D":"自动返航模式","answer":"ABCD"},{"id":276,"type":"multi","cat":"基础概念","stem":"多旋翼无人机的优点有（）。","A":"垂直起降","B":"空中悬停","C":"结构简单","D":"续航时间长","answer":"ABC"},{"id":277,"type":"multi","cat":"设备与维护","stem":"无人机的飞控系统可以（）。","A":"控制飞行姿态","B":"记录飞行数据","C":"实现自动飞行","D":"调节电机转速","answer":"ABCD"},{"id":278,"type":"multi","cat":"基础概念","stem":"以下哪些地方不适合无人机飞行（）。","A":"核电站附近","B":"野生动物保护区","C":"体育赛事现场","D":"公园开阔草地","answer":"ABC"},{"id":279,"type":"multi","cat":"设备与维护","stem":"无人机电池使用时的注意事项有（）。","A":"避免过充","B":"避免过放","C":"定期检查电池外观","D":"存放时保持适当电量","answer":"ABCD"},{"id":280,"type":"multi","cat":"领航与任务规划","stem":"无人机的导航方式有（）。","A":"GPS导航","B":"视觉导航","C":"惯性导航","D":"磁力导航","answer":"ABCD"},{"id":281,"type":"multi","cat":"基础概念","stem":"无人机在飞行中出现异常情况，应该（）。","A":"保持冷静","B":"尝试判断原因","C":"采取相应措施","D":"立即切断电源","answer":"ABC"},{"id":282,"type":"multi","cat":"法规与空域","stem":"以下关于无人机的法律法规，说法正确的有（）。","A":"需要遵守当地的飞行规定","B":"飞行前可能需要申请飞行许可","C":"不得在禁飞区飞行","D":"可以随意拍摄他人隐私","answer":"ABC"},{"id":283,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机平飞转弯时（）。","A":"转弯中，如果坡度过大，应协调地适当回杆回舵","B":"转弯中，如果坡度过小，应协调地适当回杆回舵","C":"转弯中，如果坡度过大，应协调地适当增加压杆扭舵量","D":"以上均不正确","answer":"A"},{"id":284,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆拉平时，对拉平操作描述不恰当的是（）。","A":"主动地、有预见地、机动灵活地去操纵飞机","B":"严格按高度值执行动作","C":"正确的拉平动作，必须按照实际情况","D":"以上均不正确","answer":"B"},{"id":285,"type":"single","cat":"飞行原理","stem":"翼载荷是无人机（）升力面所承受的气动力载荷翼载荷可衡量飞行中机翼的受载状况，直接影响到无人机的飞行性能。","A":"单位体积","B":"单位长度","C":"单位面积","D":"单位高度","answer":"C"},{"id":286,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，如果拉平前飞机的俯角较大、下降快，应（）。","A":"拉杆稍早些","B":"拉杆稍晚些","C":"还按正常时机拉杆","D":"以上均不正确","answer":"A"},{"id":287,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，下列哪种情况，收油门的时机应适当延迟，收油门的动作适当减慢？（）","A":"当时的高度与预定高度吻合","B":"当时的高度高于预定高度","C":"当时的高度低于预定高度","D":"以上均不正确","answer":"C"},{"id":288,"type":"single","cat":"设备与维护","stem":"电调、电机和螺旋桨是旋翼飞机的（）。","A":"控制系统","B":"电力系统","C":"动力系统","D":"稳定系统","answer":"C"},{"id":289,"type":"single","cat":"操纵与飞行技术","stem":"下列属于无人驾驶航空器核心控制装置的是（）。","A":"定位系统","B":"飞控系统","C":"电力系统","D":"动力系统","answer":"B"},{"id":290,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机平飞转弯前（）。","A":"根据转弯坡度大小，减油门5%-10%，保持好平飞状态","B":"根据转弯坡度大小，加油门5%-10%，保持好平飞状态","C":"保持当前平飞状态","D":"以上均不正确","answer":"B"},{"id":291,"type":"single","cat":"基础概念","stem":"机翼1/4弦线与垂直机身中心线的直线之间的夹角称为机翼的（）。","A":"安装角","B":"上反角","C":"后掠角","D":"以上均不正确","answer":"C"},{"id":292,"type":"single","cat":"电力巡检","stem":"（）是根据故障情况选择适用机型开展故障查找，巡检图像质量应满足故障分析需要。","A":"正常巡检","B":"故障巡检","C":"特殊巡检","D":"灾后特巡","answer":"B"},{"id":293,"type":"single","cat":"设备与维护","stem":"无人机装配报告中任务载荷系统复检项包括任务载荷系统安装方向正确且牢固、任务载荷系统活动部分手动推动阻尼正常、任务载荷系统信号线插接正确且牢固、（）、任务载荷系统电源线插接正确且牢固。","A":"任务载荷系统完好无损","B":"任务载荷系统自检通过","C":"任务载荷系统完成校验","D":"任务载荷系统指示灯运行正常","answer":"A"},{"id":294,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，关于收油门描述正确的是（）。","A":"收油门的过程要拉长一些，拉长了可以柔和，使速度减小均匀，有利于做好着陆","B":"收油门的过程要尽量短，短了可以柔和，使速度减小均匀，有利于做好着陆","C":"收油门的过程可以随意些，跟着感觉就好","D":"以上均不正确","answer":"A"},{"id":295,"type":"single","cat":"领航与任务规划","stem":"典型的无人机是由飞行器平台、动力系统、控制站与飞行控制系统、通信导航系统、任务载荷系统以及（）系统组成。","A":"发射/回收系统","B":"燃油系统","C":"制导系统","D":"飞行系统","answer":"A"},{"id":296,"type":"single","cat":"设备与维护","stem":"一款四旋翼其1号电机通电后发现旋转方向为顺时针，这时应（）。","A":"飞行器电调故障，更换电调","B":"将1号电机的螺旋桨更换为CW桨叶即可","C":"将1号电机引出线2根线与电调线2根线进行对调即可","D":"飞行器严重错误，禁止飞行","answer":"C"},{"id":297,"type":"single","cat":"飞行原理","stem":"螺旋桨的螺距是什么？（）","A":"螺距是指螺旋桨旋转一周所上升或前进的距离","B":"螺距是指螺旋桨旋转一周所上升的距离","C":"螺距是指螺旋桨旋转一周所前进的距离","D":"以上均不正确","answer":"A"},{"id":298,"type":"single","cat":"基础概念","stem":"（）不属于垂直起降固定翼无人机主要组成部分。","A":"外翼段","B":"中翼段","C":"尾翼","D":"上翼段","answer":"D"},{"id":299,"type":"single","cat":"设备与维护","stem":"遥控器开机按钮操作顺序（）。","A":"长按","B":"短按再长按","C":"短按一下","D":"长按再短按","answer":"B"},{"id":300,"type":"single","cat":"设备与维护","stem":"无人机装配报告中动力系统复检项包括电机安装、（）、电池安装和桨叶安装。","A":"飞行控制系统（自驾仪）安装","B":"无线图像传输（无线图传）系统安装","C":"电子调速器（电调）安装","D":"无线数据传输（无线数传）系统安装","answer":"C"},{"id":301,"type":"single","cat":"基础概念","stem":"无人机系统中，起降操作手一般不参与哪个阶段控制（）。","A":"起飞阶段","B":"降落阶段","C":"巡航阶段","D":"以上均不正确","answer":"C"},{"id":302,"type":"single","cat":"基础概念","stem":"四旋翼飞行器支架中间的空间中安放（）和外部设备。","A":"定位装置","B":"摄像头","C":"飞行控制计算机","D":"机载设备","answer":"C"},{"id":303,"type":"single","cat":"领航与任务规划","stem":"360°圆周航线飞行训练科目中，操作无人机在姿态模式下，完成360°圆周航线飞行，在飞行过程中与地面标识物的水平误差不得大于±（）cm。","A":"10","B":"30","C":"50","D":"100","answer":"C"},{"id":304,"type":"single","cat":"基础概念","stem":"固定翼无人机电子调速器的标称电流应（）电动机的最大额定电流。","A":"大于或等于","B":"小于或等于","C":"大于","D":"小于","answer":"A"},{"id":305,"type":"single","cat":"基础概念","stem":"关于四旋翼飞行器的描述，以下错误的是？（）","A":"桨叶分为正反桨","B":"需按照说明书将桨叶装在正确的位置上","C":"飞行器启动前需检查桨叶是否有旋紧","D":"桨叶有严重破损无需更换","answer":"D"},{"id":306,"type":"single","cat":"基础概念","stem":"多轴飞行器重心过高于或过低于桨平面会（）。","A":"增加稳定性","B":"降低机动性","C":"显著影响电力消耗","D":"以上均不正确","answer":"B"},{"id":307,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，收油门过早、过粗，速度减小快，使拉平时的速度小，飞机下沉快（）。","A":"容易拉平低或者进入平飘时仰角较大","B":"对飞机无影响","C":"容易拉平高或者进入平飘时仰角较小","D":"以上均不正确","answer":"A"},{"id":308,"type":"single","cat":"设备与维护","stem":"如果数据链路上行中断，会发生（）的后果。","A":"无人机退出地面站控制模式","B":"不能获取无人机状态信息","C":"无法在线重规划航线航点及发送任务指令","D":"以上均不正确","answer":"C"},{"id":309,"type":"single","cat":"基础概念","stem":"飞行高度层应当根据（）配备。","A":"航线或航路走向、航空器性能、飞行区域以及航线的地形、天气和飞行情况等","B":"飞行任务的性质、航空器等级、飞行区域以及航线的地形、天气和飞行情况等","C":"飞行任务的性质、航空器性能、飞行区域以及航线的地形、天气和飞行情况等","D":"航线或航路走向、航空器等级、飞行区域以及航线的地形、天气和飞行情况等","answer":"C"},{"id":310,"type":"single","cat":"设备与维护","stem":"以下种类的电池，具有记忆效应的是（）。","A":"铅酸电池","B":"聚合物锂电池","C":"镍镉电池","D":"以上均不正确","answer":"C"},{"id":311,"type":"single","cat":"操纵与飞行技术","stem":"在修改完毕摇杆模式后，在起飞前应轻压低油门，轻微晃动俯仰与横滚，因为（）。","A":"确认舵量","B":"确认摇杆模式修改是否成功","C":"确认油门","D":"激活机器","answer":"B"},{"id":312,"type":"single","cat":"飞行原理","stem":"起飞时，可操纵变距螺旋桨的桨叶角到什么状态（）。","A":"小桨叶角及低转速","B":"大桨叶角及高转速","C":"小桨叶角及高转速","D":"以上均不正确","answer":"C"},{"id":313,"type":"single","cat":"领航与任务规划","stem":"菱形航线平移训练科目中，由H点起飞，控制好油门，操控无人机匀速垂直上升至（）m高度，保持无人机姿态平稳，悬停1-3秒。","A":"1","B":"1.5","C":"3","D":"7","answer":"C"},{"id":314,"type":"single","cat":"领航与任务规划","stem":"众所周知，物体运动的速度是一个矢量，关于飞行过程中空速与地速的关系，下列正确的是（）。","A":"正侧风时，空速=地速","B":"无论何时，空速+风速=地速","C":"逆风时，空速＜地速","D":"以上均不正确","answer":"B"},{"id":315,"type":"single","cat":"领航与任务规划","stem":"以下不是导航飞控系统组成部分的是（）。","A":"传感器","B":"电台","C":"执行机构","D":"以上均不正确","answer":"B"},{"id":316,"type":"single","cat":"设备与维护","stem":"无人机数据链的关键能力不包括（）。","A":"抗干扰能力","B":"安全性","C":"抗欺骗性","D":"高速传输","answer":"D"},{"id":317,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机起飞降落的特点是（）。","A":"安全性高","B":"受场地限制小","C":"稳定性高","D":"其他全是","answer":"D"},{"id":318,"type":"multi","cat":"电力巡检","stem":"航线规划根据（）等信息，规划巡检飞行航线，满足工作任务要求。","A":"气象条件","B":"空域情况","C":"线路通道环境","D":"无人直升机性能","answer":"BCD"},{"id":319,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，作业人员应具备必要的（）等巡检飞行知识和相关业务技能，熟悉在《电力安全工作规程（线路部分）》（Q/GDW1799.2）和本标准，并经考试合格。","A":"电气","B":"机械","C":"气象","D":"航线规划","answer":"ABCD"},{"id":320,"type":"multi","cat":"电力巡检","stem":"小型无人直升机巡检工作班成员至少应包括（）。","A":"操控手","B":"程控手","C":"任务手","D":"安全监护员","answer":"AB"},{"id":321,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人直升机巡检系统》中，无人直升机巡检系统的地面站系统包括（）。","A":"硬件设备","B":"飞行控制软件","C":"检测软件","D":"地面通信系统","answer":"ABC"},{"id":322,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，按照维修保养等级可分为（）。","A":"日常维护","B":"一级技术保养维护","C":"二级技术保养维护","D":"三级技术保养维护","answer":"ABC"},{"id":323,"type":"multi","cat":"基础概念","stem":"安全保护功能自检项目包括（）、（）、（）和（）等。","A":"飞行控制模块","B":"电池电压值","C":"发动机（电机）工况","D":"遥控遥测信号","answer":"ABCD"},{"id":324,"type":"single","cat":"操纵与飞行技术","stem":"无人机驾驶员操纵无人机下降到10米以下时，应重点关注的信息是（）。","A":"飞机航行灯开闭状态","B":"飞机下降速度、姿态和空速","C":"飞机剩余油量","D":"以上均不正确","answer":"B"},{"id":325,"type":"single","cat":"基础概念","stem":"多旋翼无人机机体一般不使用材料（）。","A":"碳纤维材料","B":"高强度工程塑料","C":"玻纤维材料","D":"以上均不正确","answer":"C"},{"id":326,"type":"single","cat":"基础概念","stem":"下列哪个属于对冲击流？（）","A":"风沿迎风坡上升","B":"背风坡下降","C":"雷雨气流上升下降","D":"以上均不正确","answer":"C"},{"id":327,"type":"single","cat":"操纵与飞行技术","stem":"电调是连接（）与电机的部件，主要功能是接收飞控发出的信号，再将控制信号转换为电流的大小，调节电机转速，从而影响和控制飞行器的飞行状态。","A":"飞控","B":"信号接收器","C":"姿态感知器","D":"GPS","answer":"A"},{"id":328,"type":"single","cat":"基础概念","stem":"小型固定翼飞机的主要部件包括（）起落装置和动力裝置。","A":"机体","B":"机翼","C":"机械臂","D":"云端","answer":"A"},{"id":329,"type":"single","cat":"飞行原理","stem":"小型固定翼飞机的结构系统主要包括机身、机翼、尾翼、起降装置，（）是无人机产生升力的主要部件。","A":"机身","B":"机翼","C":"尾翼","D":"起降装置","answer":"B"},{"id":330,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆到平飘阶段（）。","A":"平飘前段，速度较大，下沉较慢，拉杆量应小一些","B":"平飘前段，速度较大，下沉较慢，拉杆量应大一些","C":"平飘后段，速度较小，下沉较快，拉杆量应适当减小","D":"以上均不正确","answer":"A"},{"id":331,"type":"single","cat":"设备与维护","stem":"固定翼无人机航程的测试受电池电量、（）的影响。","A":"距离对信号","B":"GPS","C":"电机输出马力","D":"桨叶尺寸","answer":"A"},{"id":332,"type":"single","cat":"基础概念","stem":"可能需要处置的危急情况不包括：（）。","A":"任务设备故障","B":"舵面故障","C":"动力装置故障","D":"以上均不正确","answer":"A"},{"id":333,"type":"single","cat":"设备与维护","stem":"飞控子系统可以不具备如下功能：（）。","A":"姿态稳定与控制","B":"增稳与姿态解算","C":"任务分配与航迹规划","D":"以上均不正确","answer":"C"},{"id":334,"type":"single","cat":"设备与维护","stem":"无人机装配中机翼、电机、机臂和（）需要用到水平尺。","A":"电池","B":"电子调速器（电调）","C":"飞行控制系统（自驾仪）","D":"分电板","answer":"C"},{"id":335,"type":"single","cat":"领航与任务规划","stem":"下列哪种规划是任务规划的主体核心（）。","A":"任务分配规划","B":"航迹规划","C":"应急预案规划","D":"以上均不正确","answer":"B"},{"id":336,"type":"single","cat":"设备与维护","stem":"以下哪种动力电池放电电流最大（）。","A":"20000mAh，5C","B":"8000mAh，20C","C":"2000mAh，30C","D":"以上均不正确","answer":"B"},{"id":337,"type":"single","cat":"飞行原理","stem":"关于失速，下面哪个说法是不正确的？（）","A":"机翼迎角超过临界角，导致升力急剧降低的飞行状态称为失速","B":"直升机飞速度过快，可能导致后行旋翼出现失速","C":"失速会导致升力急剧减小，阻力系数缓慢减小","D":"以上均不正确","answer":"C"},{"id":338,"type":"single","cat":"操纵与飞行技术","stem":"在固定翼无人机中，无人机的飞行姿态是通过调节各个（）来实现的。","A":"固定翼","B":"电机","C":"电调","D":"舵面","answer":"D"},{"id":339,"type":"single","cat":"操纵与飞行技术","stem":"无人机飞行员操纵方向舵时，飞行器将绕（）。","A":"横轴运动","B":"纵轴运动","C":"立轴运动","D":"以上均不正确","answer":"C"},{"id":340,"type":"single","cat":"基础概念","stem":"旋翼水平铰的作用（）。","A":"自动调节桨叶升力变化，消除侧倾力矩","B":"使桨叶拉力发生周期性变化，也会使桨叶根部受到的弯矩发生周期性变化","C":"产生自下而上的挥舞相对气流，这会使桨叶迎角减小，拉力减小","D":"以上均不正确","answer":"A"},{"id":341,"type":"single","cat":"操纵与飞行技术","stem":"着陆目测是驾驶员驾驶员对飞机飞行高度和降落点进行目视判断，对于目测质量的评判为（）。","A":"飞机没有达到目测接地范围就接地的，叫目测低","B":"飞机没有达到目测接地范围就接地的，叫目测高","C":"飞机超过目测接地范围才接地的，叫目测低","D":"以上均不正确","answer":"A"},{"id":342,"type":"single","cat":"电力巡检","stem":"巡检作业前，根据相应（）和巡检任务编制无人直升机巡检作业指导书。","A":"性能","B":"机型","C":"航程","D":"载荷","answer":"B"},{"id":343,"type":"single","cat":"设备与维护","stem":"遥控器开机以后检查哪几项？（）","A":"电压、模型名称、混控","B":"电压、模型类型、发射制式、中立微调","C":"电压、混控、大小舵","D":"以上均不正确","answer":"B"},{"id":344,"type":"single","cat":"基础概念","stem":"现有脉冲宽度调制（PWM）信号波的周期为10ms，高电平的持续时间为4ms，其占空比为（）。","A":"0.2","B":"0.4","C":"0.6","D":"0.8","answer":"B"},{"id":345,"type":"single","cat":"设备与维护","stem":"发射机的天线是可调整的，飞行过程中若天线直接对着无人机，这可能会（）接收机信号强度。","A":"增强","B":"过滤","C":"屏蔽","D":"减弱","answer":"D"},{"id":346,"type":"single","cat":"设备与维护","stem":"长时间不用时应把电池放在阴凉且干燥的地方保存，电池每隔大约3个月或经过约（）次充放电后，需进行一次完整的充电和放电过程再保存，以保证电池的最佳工作状态。","A":"50","B":"20","C":"40","D":"30","answer":"D"},{"id":347,"type":"single","cat":"设备与维护","stem":"多轴飞行器飞控计算机的功能不包括（）。","A":"稳定飞行器姿态","B":"接收地面控制信号","C":"导航","D":"以上均不正确","answer":"B"},{"id":348,"type":"single","cat":"基础概念","stem":"以下（）不属于固定翼无人机的机电系统。","A":"螺旋桨","B":"电调","C":"伺服机构","D":"配电系统","answer":"C"},{"id":349,"type":"single","cat":"设备与维护","stem":"飞控系统的核心是（）。","A":"主控制模块","B":"信号调理及接口模块","C":"数据采集模块","D":"舵机驱动模块","answer":"A"},{"id":350,"type":"single","cat":"操纵与飞行技术","stem":"任务分配提供可用的无人机资源和着陆点的显示，辅助操作人员进行（）。","A":"载荷规划、通信规划和目标分配","B":"链路规划、返航规划和载荷分配","C":"任务规划、返航规划和载荷分配","D":"以上均不正确","answer":"A"},{"id":351,"type":"single","cat":"电力巡检","stem":"无人直升机巡检系统应定置存放，并由（）管理。","A":"无人机班组","B":"输电运检部门","C":"专人","D":"仓库管理员","answer":"C"},{"id":352,"type":"single","cat":"操纵与飞行技术","stem":"已知一款多旋翼为四旋翼设计，推重比为2，单电机最大推力为3kg，其标准起飞重量是多少kg（）。","A":"8","B":"7","C":"6","D":"4","answer":"C"},{"id":353,"type":"single","cat":"操纵与飞行技术","stem":"微型无人机，是指空机重量小于（）千克，设计性能同时满足飞行真高不超过（）米、最大飞行速度不超过（）千米/小时、无线电发射设备符合微功率短距离无线电发射设备技术要求的遥控驾驶航空器。","A":"4，20，40","B":"0.25，50，40","C":"0.25，20，40","D":"4，50，40","answer":"B"},{"id":354,"type":"single","cat":"基础概念","stem":"开展无人机作业，风力应不大于（）级。","A":"4","B":"5","C":"6","D":"7","answer":"B"},{"id":355,"type":"single","cat":"基础概念","stem":"关于温度对多旋翼飞行器的影响，以下错误的是？（）","A":"低温环境下电池需要保温","B":"低温环境下飞行器IMU需要预热","C":"温环境会导致电池、电机发热加剧，从降低飞行效率","D":"温对飞行器没有任何影响","answer":"D"},{"id":356,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，收油门的基本要领是（）。","A":"跟着感觉操作","B":"适时、柔和","C":"适时、快速","D":"以上均不正确","answer":"B"},{"id":357,"type":"single","cat":"基础概念","stem":"6045R螺旋桨，45什么意思，是CW桨还是CCW桨？（）","A":"螺距、正桨","B":"螺距、反桨","C":"直径、反桨","D":"以上均不正确","answer":"B"},{"id":358,"type":"single","cat":"基础概念","stem":"随着飞行控制系统能力的不断提升，（）的作用越来越小。","A":"电气系统","B":"遥控系统","C":"飞行控制系统","D":"动力系统","answer":"B"},{"id":359,"type":"single","cat":"飞行原理","stem":"某多轴螺旋型号为1045，那么他的桨长（）毫米，螺距（）毫米。","A":"254,114","B":"10，45","C":"25，11","D":"11，25","answer":"A"},{"id":360,"type":"single","cat":"设备与维护","stem":"长期不使用电池需在多少V电压下存放？（）","A":"3.75","B":"3.65","C":"3.95","D":"3.85","answer":"D"},{"id":361,"type":"single","cat":"设备与维护","stem":"固定翼无人机地面控制站包括地面站电脑、（）、数据链地面终端等通讯设备，用以辅助完成路线规划任务和飞行过程的监控。","A":"服务器","B":"平板终端","C":"手机","D":"操纵手柄","answer":"D"},{"id":362,"type":"single","cat":"法规与空域","stem":"（）是为保护航空器起飞、飞行和降落安全，根据民用机场净空障碍物限制图要求划定的空间范围。","A":"机场净空区","B":"航空限制区","C":"机场限制区","D":"航空净空区","answer":"A"},{"id":363,"type":"single","cat":"设备与维护","stem":"以下哪一项不属于调试飞控是的校准内容（）。","A":"磁罗盘","B":"加速度计","C":"空速计","D":"陀螺仪","answer":"C"},{"id":364,"type":"single","cat":"飞行原理","stem":"增大飞机机翼的展弦比，目的是减小飞机的（）。","A":"摩擦阻力","B":"压差阻力","C":"诱导阻力","D":"以上均不正确","answer":"C"},{"id":365,"type":"single","cat":"设备与维护","stem":"无刷电机如果遇到旋转方向相反，正确的处理方法是（）。","A":"电调与电源的连线进行对换","B":"电调与电机的连线3根中任意对换2根","C":"电调与飞控的连线进行对换","D":"以上均不正确","answer":"B"},{"id":366,"type":"single","cat":"航空气象","stem":"实际飞行时，使用有飞控的飞机，以起降场或视界内的某一点为（），飞机升空绕原点爬高探测云底的高度。","A":"中心","B":"参照物","C":"原点","D":"终点","answer":"C"},{"id":367,"type":"single","cat":"设备与维护","stem":"IMU方向选择，即飞控安装方向选择，需要根据飞控实际的安装位置，选择正确的安装方向，错误的选择将会导致（）。","A":"起飞后向后飞","B":"起飞后向左飞","C":"起飞后向右飞","D":"严重的飞行事故","answer":"D"},{"id":368,"type":"single","cat":"领航与任务规划","stem":"无人机航迹规划需要综合应用（），以获得全面详细的无人机飞行现状以及环境信息，结合无人机自身技术指标特点，按照一定的航迹规划方法，制定最优或次优路径。","A":"导航技术、地理信息技术以及远程感知技术","B":"导航技术、航迹优化算法以及地理信息技术","C":"飞控技术、导航技术以及地理信息技术","D":"以上均不正确","answer":"A"},{"id":369,"type":"single","cat":"基础概念","stem":"固定翼无人机飞行时，出现机体晃动，此时应检查（）。","A":"电机安装角度是否有偏差","B":"螺旋桨是否完好","C":"机翼是否平衡","D":"上述部件都可能有故障，都要检查","answer":"D"},{"id":370,"type":"single","cat":"飞行原理","stem":"固定翼无人机提高供升阻比的措施下列说法正确的是（）。","A":"选择平凸形翼型","B":"减小飞行速度","C":"减小展弦比","D":"设置翼梢小翼","answer":"D"},{"id":371,"type":"single","cat":"飞行原理","stem":"螺旋桨叶本身是扭转的，因此桨叶角从毂轴到叶尖是变化的最大安装角或者最大桨距在（）。","A":"叶尖处","B":"桨叶中部","C":"毂轴处","D":"以上均不正确","answer":"C"},{"id":372,"type":"single","cat":"操纵与飞行技术","stem":"四轴如何实现左转90°？（）","A":"逆时针旋转的桨加速","B":"顺时针旋转的桨减速","C":"顺时针旋转的桨加速","D":"以上均不正确","answer":"C"},{"id":373,"type":"single","cat":"基础概念","stem":"无人直升机或多旋翼飞行器飞行时间的含义是指（）。","A":"自旋翼机起飞离地到着陆接地的瞬间","B":"自旋翼机起飞滑跑至着陆滑跑终止的瞬间","C":"自旋翼机旋翼开始转动至旋翼停止转动的瞬间","D":"以上均不正确","answer":"C"},{"id":374,"type":"single","cat":"基础概念","stem":"围绕多轴飞行器立轴的是什么运动（）。","A":"滚转运动","B":"俯仰运动","C":"偏航运动","D":"以上均不正确","answer":"C"},{"id":375,"type":"single","cat":"领航与任务规划","stem":"“卫星接收信号强度符合要求，确认任务规划正确无误，数据上传和下传工作正常”是（）的工作内容之一。","A":"飞行器整体目视检查","B":"遥控器检査","C":"地面站检査","D":"环境与飞行场地检査","answer":"C"},{"id":376,"type":"single","cat":"领航与任务规划","stem":"机场的起落航线通常为（）航线，起落航线的飞行高度通常为（）。","A":"左，300至600米","B":"右，300至500米","C":"左，300至500米","D":"以上均不正确","answer":"C"},{"id":377,"type":"single","cat":"基础概念","stem":"以下不是多轴飞行器优点的是（）。","A":"气动效率高","B":"结构简单","C":"成本低廉","D":"以上均不正确","answer":"A"},{"id":378,"type":"single","cat":"基础概念","stem":"多旋翼无人机机体平台起装载和承力的作用，加强对机体平台的检查并及时发现、正确处理裂纹，消除飞行中因机体平台振动所导致的机体平台（）风险。","A":"故障","B":"断裂","C":"变形","D":"事故","answer":"B"},{"id":379,"type":"single","cat":"操纵与飞行技术","stem":"电调是连接飞控与电机的部件，主要功能是接收飞控发出的信号，再将控制信号转换为（），调节电机转速，从而影响和控制飞行器的飞行状态。","A":"电压的大小","B":"电流的大小","C":"脉冲信号","D":"光波信号","answer":"B"},{"id":380,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼飞行器悬停时的平衡不包括（）。","A":"俯仰平衡","B":"升力平衡","C":"诱导阻力平衡","D":"以上均不正确","answer":"C"},{"id":381,"type":"single","cat":"基础概念","stem":"测试多旋翼无人机的载重量是否正常，需测出多旋翼无人机的（）、基本重量。","A":"最大起飞重量","B":"负载重量","C":"任务载荷系统重量","D":"电池重量","answer":"A"},{"id":382,"type":"single","cat":"基础概念","stem":"固定翼无人机的方向舵负责完成无人机的（）动作。","A":"横滚","B":"俯仰","C":"偏航","D":"以上均不正确","answer":"C"},{"id":383,"type":"single","cat":"航空气象","stem":"（）包括携带的传感器类型、摄像机类型和专用任务设备类型等，规划设备工作时间及工作模式，同时需要考虑气象情况对设备的影响程度。","A":"任务规划","B":"载荷规划","C":"任务分配","D":"以上均不正确","answer":"B"},{"id":384,"type":"single","cat":"基础概念","stem":"短程无人机活动半径在（）以内。","A":"15km","B":"15-50km","C":"50-200km","D":"以上均不正确","answer":"C"},{"id":385,"type":"single","cat":"基础概念","stem":"活塞发动机混合气过富油燃烧将引起（）的问题。","A":"发动机过热","B":"电嘴积碳","C":"发动机工作平稳，但燃油消耗量变大","D":"以上均不正确","answer":"B"},{"id":386,"type":"single","cat":"操纵与飞行技术","stem":"当飞机飞行时所需功率小，留空时间长的平飞速度又称为（）。","A":"直线速度","B":"经济速度","C":"续航速度","D":"最大速度","answer":"B"},{"id":387,"type":"single","cat":"操纵与飞行技术","stem":"无人机着陆目测须重点决断着陆方向和（）。","A":"三四转弯位置","B":"一转弯位置","C":"二转弯位置","D":"以上均不正确","answer":"A"},{"id":388,"type":"single","cat":"基础概念","stem":"（）包括在执行任务的过程中，需要根据环境情况的变化制定一些通信任务，调整与任务控制站之间的通信方式等。","A":"目标分配","B":"链路规划","C":"通信规划","D":"以上均不正确","answer":"C"},{"id":389,"type":"single","cat":"基础概念","stem":"对装备定距螺旋桨的活塞发动机，通常用来反映功率的仪表的是（）。","A":"进气压力表","B":"转速表","C":"燃油流量表","D":"以上均不正确","answer":"B"},{"id":390,"type":"single","cat":"领航与任务规划","stem":"无人机任务规划需要实现的功能包括（）。","A":"自主导航功能，应急处理功能，航迹规划功能","B":"任务分配功能，航迹规划功能，仿真演示功能","C":"自主导航功能，自主起降功能，航迹规划功能","D":"以上均不正确","answer":"B"},{"id":391,"type":"single","cat":"领航与任务规划","stem":"360°圆周航线飞行训练科目中，操作无人机在姿态模式下，完成360°圆周航线飞行，在飞行过程中每两个航点之间的垂直误差不大于±（）cm。","A":"10","B":"30","C":"50","D":"100","answer":"B"},{"id":392,"type":"single","cat":"设备与维护","stem":"以下地面链路天线哪一种是定向天线（）。","A":"八木天线","B":"鞭状天线","C":"三叶草天线","D":"以上均不正确","answer":"A"},{"id":393,"type":"single","cat":"法规与空域","stem":"无人机系统（），由运营人指派对无人机的运行负有必不可少责任并在飞行期间适时操纵无人机的人。","A":"安全员","B":"驾驶员","C":"机长","D":"观测员","answer":"B"},{"id":394,"type":"single","cat":"航空气象","stem":"气压计是反映无人机的什么物理量？（）","A":"速度","B":"高度","C":"温度","D":"以上均不正确","answer":"B"},{"id":395,"type":"single","cat":"领航与任务规划","stem":"以下正确的任务规划流程是（）。","A":"接受任务-任务理解-环境评估-任务分配-航迹规划-航迹优化-生产计划","B":"接受任务-任务理解-任务分配-环境评估-航迹规划-航迹优化-生产计划","C":"接受任务-任务理解-任务分配-航迹规划-环境评估-航迹优化-生产计划","D":"以上均不正确","answer":"A"},{"id":396,"type":"single","cat":"设备与维护","stem":"无人机在正常条件下使用，每飞行（）小时进行一次简易维护，包括清理机体异物（如灰尘、油泥等）。","A":"10","B":"20","C":"30","D":"40","answer":"B"},{"id":397,"type":"single","cat":"飞行原理","stem":"机翼的安装角是（）。","A":"翼弦与相对气流速度的夹角","B":"翼弦与机身纵轴之间所夹锐角","C":"翼弦与水平面之间所夹的锐角","D":"以上均不正确","answer":"B"},{"id":398,"type":"single","cat":"基础概念","stem":"下列关于操作人员要求，描述错误的是（）。","A":"不可将植保无人机操作到人员正上方，不可接近飞行中的无人机","B":"植保无人机提示需磁罗盘校准时，第一时间进行校准","C":"飞行前8小时禁止饮酒","D":"作业区域有农户在拔草，依然继续作业","answer":"D"},{"id":399,"type":"multi","cat":"基础概念","stem":"空速管安装位置一定要选在无人机外面气流受影响较小的位置，一般选择在（）。","A":"机身正上方","B":"机头正前方","C":"垂尾","D":"翼尖方向","answer":"BCD"},{"id":400,"type":"multi","cat":"基础概念","stem":"目前国内天气获取途径有（）。","A":"口述天气","B":"民航机场预报","C":"军用气象台站","D":"通过互联网查询气象信息","answer":"BCD"},{"id":401,"type":"multi","cat":"领航与任务规划","stem":"从实施时间上分，任务规划可以分为（）。","A":"预先规划","B":"航迹规划","C":"载荷规划","D":"实时规划","answer":"AD"},{"id":402,"type":"multi","cat":"基础概念","stem":"无人机遥感系统可完成对水土流失的（）等的实时动态监测。","A":"成因","B":"强度","C":"影响范围","D":"防治成效","answer":"ABCD"},{"id":403,"type":"multi","cat":"基础概念","stem":"对流层的主要特征（）。","A":"气温随高度升高而升高","B":"气温、湿度的水平分布很不均匀","C":"空气具有强烈的垂直混合","D":"气流混乱","answer":"BC"},{"id":404,"type":"multi","cat":"设备与维护","stem":"无人直升机电池不应（）等，电源正负极标识清晰正确，接头有防松措施，宜使用防误插接头","A":"变形","B":"表面有针眼","C":"碰磕","D":"裂纹","answer":"ABCD"},{"id":405,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人直升机巡检系统》中，中型无人直升机巡检系统应装有（）的航行灯。","A":"左红","B":"右绿","C":"尾白","D":"左绿","answer":"ABC"},{"id":406,"type":"multi","cat":"基础概念","stem":"（）是常规布局的飞机主要舵面。","A":"升降舵","B":"襟翼","C":"方向舵","D":"副翼","answer":"ACD"},{"id":407,"type":"multi","cat":"操纵与飞行技术","stem":"无人机着陆分为哪几个阶段？（）","A":"下滑","B":"拉平","C":"平飘接地","D":"着陆滑跑","answer":"ABCD"},{"id":408,"type":"single","cat":"电力巡检","stem":"巡检作业区域出现雷雨、（）等突变天气或空域许可情况发生变化时，应采取措施控制无人直升机返航或就近降落。","A":"低温","B":"大雾","C":"高温","D":"大风","answer":"D"},{"id":409,"type":"single","cat":"基础概念","stem":"螺旋桨安装在电动机上，多旋翼无人机安装的都是（）的螺旋桨。","A":"不可变","B":"可变","C":"可变总距","D":"不可变总距","answer":"D"},{"id":410,"type":"single","cat":"法规与空域","stem":"空域管理的具体办法由（）制定。","A":"中国民用航空局","B":"中共中央军事委员","C":"中华人民共和国国务院和中共中央军事委员会","D":"机场塔台","answer":"C"},{"id":411,"type":"single","cat":"领航与任务规划","stem":"已经实际飞行的航线应及时存档，并标注（）信息。","A":"区域坐标","B":"任务区域","C":"特殊区段","D":"警示区域","answer":"C"},{"id":412,"type":"single","cat":"基础概念","stem":"（）无人机侦察监测区域应预先标注，主要包括任务区域范围，侦察监测范围对象等。","A":"场地标注","B":"任务区域标注","C":"警示标注","D":"以上均不正确","answer":"B"},{"id":413,"type":"single","cat":"领航与任务规划","stem":"航向角是飞行器（）在水平面的投影与指北线之间的夹角。","A":"纵轴","B":"横轴","C":"立轴","D":"经线","answer":"A"},{"id":414,"type":"single","cat":"飞行原理","stem":"固定翼型无人机机体主要由机身及机翼、起落架、（）、螺旋桨、油箱、机上飞行控制系统等组成。","A":"发动机","B":"操作手柄","C":"备件","D":"飞控计算机","answer":"A"},{"id":415,"type":"single","cat":"操纵与飞行技术","stem":"维修无人机飞行控制系统（自驾仪）系统时，飞行控制系统（自驾仪）尽可能安装在固定翼无人机的重心，确保自动驾驶仪上的箭头的方向（）。","A":"向上","B":"向下","C":"无人机朝前的方向相同","D":"无人机朝前的方向相反","answer":"C"},{"id":416,"type":"single","cat":"操纵与飞行技术","stem":"（）的主要功用是支持飞机在地面停放，并用于飞机的起飞和降落。","A":"起落装置","B":"螺旋桨","C":"机臂","D":"动力系统","answer":"A"},{"id":417,"type":"single","cat":"航空气象","stem":"垂起固定翼无人机电子电气部件中的飞行控制系统（自驾仪），测试内容为（）、气压计、空速计，下列选项错误的是。","A":"飞控仪本体","B":"遥控器、接收机对频","C":"相关飞控组件","D":"惯性测量单元","answer":"B"},{"id":418,"type":"single","cat":"设备与维护","stem":"多旋翼无人机的飞控（自驾仪）的理想安装位置是无人机重心，若飞控（自驾仪）远离重心，将会产生（），引起加速度的测量误差，即杆臂效应。","A":"离心加速度","B":"切向加速度","C":"离心加速度和切向加速度","D":"向心加速度","answer":"C"},{"id":419,"type":"single","cat":"电力巡检","stem":"无人直升机在巡检过程中，通讯链路保持畅通的范围称（）。","A":"操控范围","B":"视距内范围","C":"无人直升机数据链范围","D":"巡检范围","answer":"C"},{"id":420,"type":"single","cat":"基础概念","stem":"多旋翼设计上反角的作用是（）。","A":"机动","B":"稳定","C":"省电","D":"以上均不正确","answer":"B"},{"id":421,"type":"single","cat":"飞行原理","stem":"固定翼型无人机通过（）和机翼的滑行实现起降和飞行，遥控飞行和程控飞行均容易实现。","A":"电气系统","B":"动力系统","C":"机身","D":"飞控","answer":"B"},{"id":422,"type":"single","cat":"基础概念","stem":"小型无人机，是指空机质量小于等于（）千克的无人机，微型和轻型无人机除外。","A":"116","B":"5700","C":"1260","D":"以上均不正确","answer":"B"},{"id":423,"type":"single","cat":"操纵与飞行技术","stem":"启动发动机时，遥控器的油门杆应置于（）。","A":"高速位置","B":"怠速位置","C":"中速位置","D":"以上均不正确","answer":"B"},{"id":424,"type":"single","cat":"领航与任务规划","stem":"无人机任务规划是实现（）的有效途径，它在很大程度上决定了无人机执行任务的效率。","A":"自主导航与飞行控制","B":"飞行任务与载荷匹配","C":"航迹规划与自主导航","D":"以上均不正确","answer":"A"},{"id":425,"type":"single","cat":"基础概念","stem":"无人机怎么飞最省油或最省电？（）","A":"匀速","B":"高速","C":"底速","D":"以上均不正确","answer":"A"},{"id":426,"type":"single","cat":"基础概念","stem":"地面与通信车之间的交流电压为220V，经整流、滤波等一系列处理之后成为近（）的高压直流电，通过系留电缆输送至无人机。","A":"600V","B":"400V","C":"500V","D":"450V","answer":"B"},{"id":427,"type":"single","cat":"基础概念","stem":"多旋翼飞行器在运输过程中的注意事项是（）。","A":"做好减震措施，固定云台并安装云台固定支架，装箱运输","B":"可随意拆装运输","C":"装箱运输，也可行李箱运输","D":"以上均不正确","answer":"A"},{"id":428,"type":"single","cat":"基础概念","stem":"下面哪个单位领导全国的飞行管制工作（）。","A":"国务院","B":"民航局","C":"国务院﹑中央军委空中交通管制委员会","D":"中央军委","answer":"C"},{"id":429,"type":"single","cat":"设备与维护","stem":"铰接式旋翼在吹风挥舞时，旋翼每转一周，桨叶挥舞速度和挥舞角分别出现一次周期性变化下面正确的是（）。","A":"挥舞角的变化比挥舞速度的变化滞后90°","B":"桨叶在90°方位下挥速度最大，在270°方位上挥速度最大","C":"桨叶在180°方位挥舞最低，在360°方位挥舞最高","D":"以上均不正确","answer":"A"},{"id":430,"type":"single","cat":"操纵与飞行技术","stem":"姿态传感器应安装在无人机（）附近，振动要尽可能的小，有较高的安装精度要求。","A":"中心","B":"重心","C":"焦点","D":"以上均不正确","answer":"B"},{"id":431,"type":"single","cat":"领航与任务规划","stem":"应急航线的主要目的是确保飞机安全返航，规划一条安全返航通道和（），以及（）。","A":"应急迫降点，安全返航策略","B":"应急迫降点，航线转移策略","C":"安全着陆点，安全着陆策略","D":"以上均不正确","answer":"B"},{"id":432,"type":"single","cat":"操纵与飞行技术","stem":"以大疆产品为例，飞行器姿态数据中，“H.S”代表什么？（）","A":"飞行器与起飞点之间的相对度","B":"飞行器与起飞点之间的水平距离","C":"飞行器沿垂直方向的上升、下降速度","D":"飞行器沿水平方向的飞行速度","answer":"D"},{"id":433,"type":"single","cat":"领航与任务规划","stem":"（）在无人机任务规划中的作用是显示无人机的飞行位置、画出飞行航迹、标识规划点以及显示规划航迹等。","A":"电子地图","B":"飞行航迹","C":"地理位置","D":"以上均不正确","answer":"A"},{"id":434,"type":"single","cat":"飞行原理","stem":"无人直升机的基本结构一般包括：机身、主旋翼、尾桨、操作系统、传动系统、电动机或发动机和（）。","A":"起落架","B":"起落台","C":"遥控器","D":"赛道","answer":"A"},{"id":435,"type":"single","cat":"设备与维护","stem":"多旋翼无人机的动力电机调速不采用（）的方法调速。","A":"电枢供电电压","B":"改变电机主磁通","C":"改变电枢回路总电阻","D":"改变外接电阻","answer":"D"},{"id":436,"type":"single","cat":"设备与维护","stem":"遥控接收机连接在飞行控制器上，没有输出遥控信号，此时应检查（）。","A":"飞控电源电压是否为5V","B":"飞控电源电压是否为9V","C":"飞控电源电压是否为11.3V","D":"飞控电源电压是否为14.8V","answer":"A"},{"id":437,"type":"single","cat":"操纵与飞行技术","stem":"电动无人驾驶航空器的动力系统主要有（）、电池组、电子调速器和螺旋桨组成。","A":"减震器","B":"电池电压检测器","C":"电动机","D":"飞控系统","answer":"C"},{"id":438,"type":"single","cat":"基础概念","stem":"高原地区16*8两叶、17*6两叶、15*5三叶，灵活性最好的是哪一个，最省电是哪一个？（）","A":"灵活：15*5三叶；最省：17*6两叶","B":"灵活：16*8两叶；最省：17*6两叶","C":"灵活：15*5三叶；最省：16*8两叶","D":"以上均不正确","answer":"A"},{"id":439,"type":"single","cat":"航空气象","stem":"飞机上产生的摩擦阻力与大气的哪种物理性质有关（）。","A":"可压缩性","B":"粘性","C":"温度","D":"以上均不正确","answer":"B"},{"id":440,"type":"single","cat":"基础概念","stem":"无人机分类的方法多种多样，其中通常所说的固定翼无人机、多旋翼无人机、无人直升机是按照（）的方法来分类的。","A":"动力及能源","B":"控制方式","C":"平台结构","D":"续航时间","answer":"C"},{"id":441,"type":"single","cat":"领航与任务规划","stem":"航迹优化是指航迹规划完成后，系统根据无人机飞行的（）对航迹进行优化处理，制定出适合无人机飞行的航迹。","A":"最大转弯半径和最大俯仰角","B":"最小转弯半径和最大俯仰角","C":"最大转弯半径和最小俯仰角","D":"以上均不正确","answer":"B"},{"id":442,"type":"single","cat":"基础概念","stem":"起降点四周（）条件应良好，满足安全起降要求。","A":"起降","B":"作业","C":"飞行","D":"净空","answer":"D"},{"id":443,"type":"single","cat":"基础概念","stem":"模型飞机使用的双向对称线性热收缩聚酯薄膜，通常称为（），是轻型高强度、高收缩性双向拉伸聚酯薄膜。","A":"热缩薄膜","B":"双向薄膜","C":"线性薄膜","D":"聚酯薄膜","answer":"A"},{"id":444,"type":"single","cat":"基础概念","stem":"远程无人机活动半径在（）。","A":"50-200km","B":"200-800km","C":"＞800km","D":"以上均不正确","answer":"C"},{"id":445,"type":"single","cat":"操纵与飞行技术","stem":"影响飞机俯仰平衡的力矩主要是（）。","A":"机身力矩和机翼力矩","B":"机翼力矩和垂尾力矩","C":"机翼力矩和水平尾翼力矩","D":"以上均不正确","answer":"C"},{"id":446,"type":"single","cat":"基础概念","stem":"以机械结构复杂性来对比，三种飞行器结构从简单到复杂排列正确的是（）。","A":"直升机、固定翼、多旋翼","B":"直升机、多旋翼、固定翼","C":"多旋翼、固定翼、直升机","D":"固定翼、直升机、多旋翼","answer":"C"},{"id":447,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，接地后跳跃的修正方法是（）。","A":"飞机跳离地面时，应稳住杆，迅速判明离地的高度和飞机状态","B":"飞机跳离地面时，应迅速拉杆，避免再次坠落弹起","C":"飞机跳离地面时，应迅速推杆，压住飞机状态","D":"以上均不正确","answer":"A"},{"id":448,"type":"single","cat":"电力巡检","stem":"灾情检查主要是对受灾区域内的输电线路设备状态和（）进行检查和评估。","A":"设备受损情况","B":"通道环境","C":"弧垂状态","D":"树木情况","answer":"A"},{"id":449,"type":"single","cat":"法规与空域","stem":"无人机系统的机长是指（）。","A":"协作操控无人机的人","B":"负责整个无人机系统运行和安全的驾驶员","C":"操控无人机的人","D":"以上均不正确","answer":"B"},{"id":450,"type":"single","cat":"领航与任务规划","stem":"无人机RTK模式需要良好的卫星可见性和接收能力，维修完后不要在室内或者建筑物附近测试设备，以下哪种情况不适合测试：接收天线附近有阻挡天空视图（）。","A":"高于地平线5°的障碍物","B":"高于地平线10°的障碍物","C":"高于地平线25°的障碍物","D":"高于地平线40°的障碍物","answer":"D"},{"id":451,"type":"single","cat":"电力巡检","stem":"使用无人机巡检系统进行的架空线路巡检作业，作业人员包括（）和工作班成员。","A":"工作负责人","B":"监护人","C":"工作许可人","D":"无人机超控员","answer":"A"},{"id":452,"type":"single","cat":"设备与维护","stem":"下面关于M600所使用电池的参数准确的是（）。","A":"6S4600MAH20CLIPO","B":"6S5700MAH20CLIPO","C":"6S6000MAH20CLIPO","D":"12S12000MAH20CLIPO","answer":"B"},{"id":453,"type":"single","cat":"领航与任务规划","stem":"（）功能通常包括指挥调度、任务规划、操作控制、显示记录等功能。","A":"数据链路分系统","B":"无人机地面站系统","C":"飞控与导航系统","D":"以上均不正确","answer":"B"},{"id":454,"type":"single","cat":"操纵与飞行技术","stem":"着陆后检查内容不包括（）。","A":"飞行器外观检查","B":"燃油动力飞行器需要称重检查","C":"气象检查","D":"以上均不正确","answer":"C"},{"id":455,"type":"single","cat":"基础概念","stem":"存储无人机的所有设备应装箱存放在室内，保持干燥，存储温度为（）。","A":"-40℃～50℃","B":"-50℃～60℃","C":"-30℃～60℃","D":"-40℃～60℃","answer":"D"},{"id":456,"type":"single","cat":"基础概念","stem":"长期存放的飞行器，至少（）进行一次通电试车检査。","A":"每季度","B":"每月","C":"每周","D":"每年","answer":"B"},{"id":457,"type":"single","cat":"基础概念","stem":"中程无人机活动半径为（）。","A":"50～200km","B":"＞800km","C":"200～800km","D":"以上均不正确","answer":"C"},{"id":458,"type":"single","cat":"设备与维护","stem":"3508/2835两个电机（）。","A":"带动的桨宽大","B":"带动的速度快","C":"2835外观上的更细更高","D":"以上均不正确","answer":"C"},{"id":459,"type":"single","cat":"设备与维护","stem":"一款电机参数为3S最大电流23A，下面哪一款电调搭配最为适合（）。","A":"2-3S20A","B":"2-6S40A","C":"2S30A","D":"2-3S30A","answer":"D"},{"id":460,"type":"single","cat":"设备与维护","stem":"以下属于闭源飞行控制系统（自驾仪）的是（）。","A":"A3","B":"APM","C":"PX4","D":"CCD3","answer":"A"},{"id":461,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机复飞时，正确的操纵方式是（）。","A":"迅速推满油门，同时快速拉杆转入爬升","B":"保持油门，快速拉杆转入爬升","C":"柔和地加满油门，保持好方向，同时柔和拉杆使飞机逐渐转入爬升，保持好爬升状态","D":"以上均不正确","answer":"C"},{"id":462,"type":"single","cat":"基础概念","stem":"飞机重心位置的表示方法是（）。","A":"用重心到平均几何弦后缘的距离和平均几何弦长之比的百分数来表示","B":"用重心到机体基准面的距离和平均气动力弦长之比的百分数来表示","C":"用重心到平均气动力弦前缘的距离和平均气动力弦长之比的百分数来表示","D":"以上均不正确","answer":"C"},{"id":463,"type":"single","cat":"设备与维护","stem":"飞行控制系统通过加速度传感器和角速度传感器融合测量无人机的（）。","A":"飞行速度","B":"飞行姿态","C":"飞行高度","D":"飞行温度","answer":"B"},{"id":464,"type":"single","cat":"设备与维护","stem":"无刷电机轴承损坏造成的现象，不包括的是（）。","A":"通电后无任何动作","B":"动平衡破坏","C":"空载电流增大","D":"旋转内部杂音","answer":"A"},{"id":465,"type":"single","cat":"操纵与飞行技术","stem":"关于固定翼无人机起飞类型，下列说法正确的是（）。","A":"在地面发射时，无人机使用较为广泛的发射方式是母机空中发射与零长发射","B":"垂直起降的固定翼无人机均安装有专用的辅助动力系统","C":"容器式发射装置是一种封闭发射装置，兼备发射与贮存无人机功能","D":"所有特种固定翼无人机也可采用垂直方式发射和回收","answer":"C"},{"id":466,"type":"single","cat":"基础概念","stem":"一般固定翼无人机螺旋桨旋转时距地面最近点的高度至少要大于其直径的（）。","A":"1/2","B":"1/5","C":"1/10","D":"1/20","answer":"C"},{"id":467,"type":"single","cat":"基础概念","stem":"活塞发动机中，CDI系统属于（）的一部分。","A":"排气系统","B":"进气系统","C":"点火系统","D":"以上均不正确","answer":"C"},{"id":468,"type":"single","cat":"操纵与飞行技术","stem":"起飞前，应确认现场的（）符合该机型的作业范围。","A":"湿度","B":"温度","C":"风速","D":"气压","answer":"C"},{"id":469,"type":"multi","cat":"电力巡检","stem":"巡检前，作业人员应了解巡检线路情况（）、所需空域等。","A":"海拔高度","B":"地形地貌","C":"气象环境","D":"植被分布","answer":"ABCD"},{"id":470,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，巡检作业点是指中小型无人直升机巡检作业时，无人直升机巡检系统停留进行（）等作业的位置。","A":"拍照","B":"摄像","C":"查找","D":"分析","answer":"AB"},{"id":471,"type":"multi","cat":"操纵与飞行技术","stem":"无人机着陆时观察地面关系的目的是（），以便准确地操纵飞机着陆。","A":"判断高度、下沉情况、飞行状态和运动的方向","B":"判断下降率","C":"了解速度","D":"目测的情况","answer":"ABCD"},{"id":472,"type":"multi","cat":"电力巡检","stem":"输电线路在线监测系统需要实现系统主站和系统终端之间高速、可靠和透明的数据传输，远程通信可采用（）等多种通信方式。","A":"局域网","B":"光纤专网","C":"无线专网","D":"无线公网","answer":"BCD"},{"id":473,"type":"multi","cat":"电力巡检","stem":"中型无人直升机巡检和固定翼无人机巡检工作班成员至少应包括（）。","A":"操控手","B":"程控手","C":"任务手","D":"安全监护员","answer":"ABC"},{"id":474,"type":"multi","cat":"领航与任务规划","stem":"应急航线的主要目的是确保飞机安全返航，规划（）。","A":"安全着陆点","B":"应急迫降点","C":"航线转移策略","D":"安全返航通道","answer":"BCD"},{"id":475,"type":"multi","cat":"电力巡检","stem":"固定翼无人机巡检系统包括（）","A":"固定翼无人机系统","B":"任务载荷","C":"发射回收系统","D":"综合保障系统","answer":"ABCD"},{"id":476,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机是指具有（）个及以上旋翼，能垂直起降、自由悬停的无人驾驶航空器。","A":"二","B":"三","C":"四","D":"五","answer":"B"},{"id":477,"type":"single","cat":"设备与维护","stem":"关于无人机飞行控制系统（自驾仪）调参时电压保护设置叙述正确的是（）。","A":"有两级低电压报警设置，第一级报警出现红灯闪烁，表示电量较低，可以继续飞行","B":"第一级报警出现红灯闪烁，表示电量极低，飞行控制系统（自驾仪）恒定设置为自动下降，可更改","C":"设置低电压报警值无需注意测算线损电压，提高精度","D":"出现低电压报警时最好及时降落，避免出现危险","answer":"B"},{"id":478,"type":"single","cat":"操纵与飞行技术","stem":"无人机的回收方式可归纳为伞降回收，空中回收，起落架轮式着陆，拦阻网回收，气垫着陆和垂直着陆等类型，下列说法错误的是（）。","A":"空中回收，在飞机上必须有空中回收系统，在无人机上除了有阻力伞和主伞之外，还需要有钩挂伞，吊索和旋转的脱离机构","B":"起落架轮式着陆，多数无人机的起落架局部被设计成坚固，局部较脆弱","C":"用拦截网系统回收无人机是目前世界上小型无人机采用的回收方式之一","D":"以上均不正确","answer":"B"},{"id":479,"type":"single","cat":"基础概念","stem":"为防止民用无人机飞入或者飞出特定区域，在相应电子地理范围中画出其区域边界，保障区域安全的软硬件系统叫（）。","A":"净空系统","B":"融合空域","C":"电子围栏","D":"隔离系统","answer":"C"},{"id":480,"type":"single","cat":"基础概念","stem":"对频在多旋翼飞行器当中，是指哪个动作（）。","A":"将飞行器与遥控器进行唯一性的连接","B":"将飞行器进行数据下载","C":"将遥控器射频信号进行校对","D":"将遥控器与飞行器进行图传传输","answer":"A"},{"id":481,"type":"single","cat":"领航与任务规划","stem":"航线库应根据（）及时更新。","A":"飞行航迹","B":"作业实际情况","C":"现场气象条件","D":"电子地图","answer":"B"},{"id":482,"type":"single","cat":"设备与维护","stem":"“在与地面站保持不少于2米的距离测试各指令通道工作正常”是（）的工作内容之一。","A":"飞行器整体目视检查","B":"遥控器检査","C":"地面站检査","D":"环境与飞行场地检査","answer":"B"},{"id":483,"type":"single","cat":"基础概念","stem":"无人机的基本感度是什么感度？（）","A":"磁罗盘的感度","B":"姿态角的感度","C":"陀螺仪的感度","D":"以上均不正确","answer":"C"},{"id":484,"type":"single","cat":"基础概念","stem":"地球自转产生的地球自转偏向力对风向产生影响，下列哪个是正确的？","A":"北半球，地球自转偏向力使得气流向左偏转","B":"北半球，地球自转偏向力使得气流向右偏转","C":"北半球，地球自转偏向力使得气流先向右再向左偏转","D":"以上均不正确","answer":"B"},{"id":485,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机在姿态遥控状态下，如出现动力失效则正确的处理方法是？（）","A":"遥控器油门保持中间略上位置","B":"接地瞬间将油门收至最小","C":"始终保持油门最大位置试图恢复动力","D":"以上均不正确","answer":"B"},{"id":486,"type":"single","cat":"基础概念","stem":"无人机平台包括无人机本体和（）。","A":"图像传输系统","B":"飞行控制系统","C":"地面站系统","D":"动力系统","answer":"B"},{"id":487,"type":"single","cat":"基础概念","stem":"下列关于飞行过程中出现指南针受到干扰的处理方式正确的是（）。","A":"迅速将飞行模式切换到手动模式，并尽快操作飞行器降落，若操作困难可采取就近降落","B":"迅速将飞行模式切换到姿态模式，并尽快操作飞行器降落，若操作困难可采取就近降落","C":"立即采取一键返航操作","D":"拉高飞行器等待干扰消失后继续作业","answer":"B"},{"id":488,"type":"single","cat":"法规与空域","stem":"航空器使用航路和航线，进入空域或者脱离空域，应当经（）同意。","A":"负责该航路和航线的飞行管制部门","B":"空中交通管理局下属的区域管制部门","C":"中国人民解放军空军","D":"中国民用航空总局或中国人民解放军空军","answer":"A"},{"id":489,"type":"single","cat":"领航与任务规划","stem":"GPS传感器测得的是以下下那一高度（）。","A":"真实高度","B":"相对高度","C":"海拔高度","D":"补偿高度","answer":"C"},{"id":490,"type":"single","cat":"设备与维护","stem":"遥控器接收机和发射机对频调试中，对码完成后ID编码存储在（）内。","A":"发射机","B":"接收机","C":"遥控器","D":"舵机","answer":"B"},{"id":491,"type":"single","cat":"设备与维护","stem":"IMU与磁罗盘之间的关系是怎样的（）。","A":"磁罗盘对IMU的方位数据进行校正","B":"IMU对磁罗盘的方位数据进行校正","C":"IMU与磁罗盘之间的数据是平行的","D":"IMU与磁罗盘各种负责角速度和经纬度","answer":"A"},{"id":492,"type":"single","cat":"操纵与飞行技术","stem":"姿态遥控模式下操纵无人机爬升，飞机带左坡度时，下列正确的操纵是（）。","A":"应柔和地向左压杆","B":"应柔和地回杆或向右压杆","C":"应柔和地向前顶杆","D":"以上均不正确","answer":"B"},{"id":493,"type":"single","cat":"基础概念","stem":"旋翼无人机在空中飞行时具有（）个自由度。","A":"3","B":"6","C":"9","D":"以上均不正确","answer":"B"},{"id":494,"type":"single","cat":"飞行原理","stem":"某多轴螺旋型号为15×5，那么他的桨长（）毫米，螺距（）毫米。","A":"381,127","B":"150，50","C":"15，50","D":"38，12","answer":"A"},{"id":495,"type":"single","cat":"设备与维护","stem":"运动相机ISO调试中，调高的ISO使（），调低的ISO使影像画面细腻。","A":"画面抖动","B":"画面粗糙","C":"影像颗粒感很强","D":"画面不稳定","answer":"C"},{"id":496,"type":"single","cat":"基础概念","stem":"舵面操控是什么控制量？（）","A":"模拟控制量","B":"开关控制量","C":"模拟控制量也叫比例控制量","D":"以上均不正确","answer":"C"},{"id":497,"type":"single","cat":"领航与任务规划","stem":"侧风中着陆，为了修正偏流，可以采用既修正了偏流，又使飞机的升阻比不减小的（）。","A":"改变航向法","B":"改变航向法和侧滑法相结合","C":"侧滑法","D":"以上均不正确","answer":"A"},{"id":498,"type":"single","cat":"基础概念","stem":"物体的运动是各式各样的，车辆行驶、鸟类飞翔、机器运转等，从表面上看，运动方式千差万别，但实质上都离不开两种基本的运动：（）和转动。","A":"平移","B":"平行","C":"平动","D":"直行","answer":"C"},{"id":499,"type":"single","cat":"基础概念","stem":"关于固定翼无人机重心位置的调整及配平，下列说法错误的是（）。","A":"重心的位置影响飞机的纵向稳定性","B":"焦点位置是固定的","C":"重心在后，焦点在前稳定性好","D":"重心位置可以通过移动零部件摆放位置改变","answer":"C"},{"id":500,"type":"single","cat":"航空气象","stem":"无人机定高系统中气压计定高，高度每升高（）米，气压下降1000Pa。","A":"1000","B":"100","C":"10","D":"1","answer":"B"},{"id":501,"type":"single","cat":"操纵与飞行技术","stem":"以大疆产品为例，飞行器姿态数据中，“D”代表什么？","A":"飞行器与起飞点之间的相对度距离","B":"飞行器与起飞点之间的相对水平距离","C":"飞行器沿垂直方向的上升、下降速度","D":"飞行器沿水平运动的飞行速度","answer":"B"},{"id":502,"type":"single","cat":"设备与维护","stem":"垂起固定翼机体结构件的日常维护保养，下列选项错误的是（）。","A":"检查电池有无破损，鼓包胀气，漏液等现象","B":"检查机身、机翼是否在搬运中有破损并及时维修","C":"检查机身、机翼连接处是否还连接牢固并及时维修","D":"对机身、机翼擦拭，保持干净","answer":"A"},{"id":503,"type":"single","cat":"设备与维护","stem":"无人机的舵机损坏后，按要求需更换指针型摇臂，这配件适合方向舵和（）使用。","A":"机身","B":"升降舵","C":"尾翼","D":"副翼","answer":"B"},{"id":504,"type":"single","cat":"基础概念","stem":"无人机的多机协同方式主要分为两类（）。","A":"一站多机模式、长僚机编队模式","B":"多站多机模式、长僚机编队模式","C":"多站多机模式、长机编队模式","D":"一站多机模式、僚机编队模式","answer":"A"},{"id":505,"type":"single","cat":"设备与维护","stem":"飞机中常见大功率电源线有电池电源线、电机相线和（），其他低功率细电源线可和信号线一起布线。","A":"无线数据传输（无线数传）系统线","B":"电子调速器（电调）控制线","C":"电子调速器（电调）电源线","D":"无线图像传输（无线图传）系统线","answer":"C"},{"id":506,"type":"single","cat":"基础概念","stem":"飞行器在执行兴趣点环绕最低度是？（）","A":"5米","B":"10米","C":"15米","D":"20米","answer":"A"},{"id":507,"type":"single","cat":"设备与维护","stem":"固定翼无人机电动机KV电池电压等于（）。","A":"电动机负载转速","B":"电动机最大转速","C":"电动机最小转速","D":"电动机空载转速","answer":"C"},{"id":508,"type":"single","cat":"操纵与飞行技术","stem":"在起飞过程中，地面站操作员通常每隔（）向飞行操作员通报无人机当前飞行高度、速度等数据。","A":"5~10s","B":"1~5s","C":"10~15s","D":"15~20s","answer":"A"},{"id":509,"type":"single","cat":"电力巡检","stem":"使用的无人机巡检系统应通过（）。","A":"试验检测","B":"型号检测","C":"厂家检测","D":"系统检查","answer":"A"},{"id":510,"type":"single","cat":"操纵与飞行技术","stem":"以下哪种方式不属于无人机的起飞方式（）。","A":"空中投放","B":"火箭助飞","C":"手抛起飞","D":"垂直起飞","answer":"A"},{"id":511,"type":"single","cat":"设备与维护","stem":"在整个飞行器系统中，电调信号线最终插入哪个部分（）。","A":"主控","B":"IMU","C":"PMU","D":"IOSD","answer":"A"},{"id":512,"type":"single","cat":"飞行原理","stem":"如果无人机没有前进速度，那么桨叶角就（）桨叶迎角。","A":"大于","B":"等于","C":"小于","D":"以上均不正确","answer":"B"},{"id":513,"type":"single","cat":"领航与任务规划","stem":"下列关于RTK的特性，描述错误的是（）。","A":"RTK定位可达厘米级别，偏差较小","B":"RTK定向功能，具备抗电磁干扰能力","C":"执行航线作业时，RTK在同源情况下，无需纠正偏移","D":"网络RTK在无网络情况下也可正常使用","answer":"D"},{"id":514,"type":"single","cat":"设备与维护","stem":"关于固定翼无人机载荷能力提升改造，下列说法正确的是（）。","A":"减小机翼展弦比","B":"减小机翼面积","C":"采用对称型机翼","D":"增大机翼展弦比","answer":"D"},{"id":515,"type":"single","cat":"操纵与飞行技术","stem":"起飞前有围观群众近距离观看，我们应当采取以下什么方式起飞（）。","A":"飞手站在飞行器机头前，直接解锁起飞","B":"周围人员不会干扰到无人机信号，无需理会，直接解锁起飞","C":"未等地勤将围观人员疏散至安全区域，直接解锁起飞","D":"疏散人群至安全距离后，飞手站在飞行器尾部6米处，解锁起飞","answer":"D"},{"id":516,"type":"single","cat":"设备与维护","stem":"无线图像传输（无线图传）系统接收端通常直接和（）连接。","A":"无线无线数据传输（无线数传）系统","B":"显示器","C":"飞行控制系统（自驾仪）","D":"监视器","answer":"B"},{"id":517,"type":"single","cat":"领航与任务规划","stem":"动力系统工作恒定的情况下（）限制了航迹在垂直平面内上升和下滑的最大角度。","A":"最大俯仰角","B":"最大转弯半径","C":"最小转弯半径","D":"以上均不正确","answer":"A"},{"id":518,"type":"single","cat":"操纵与飞行技术","stem":"固定翼无人机舵机如果不处于中立位置时，则可能在无人机起飞后产生（），而中立微调则是修改舵机中立位置的设置。","A":"加速","B":"减速","C":"偏移","D":"无法起飞","answer":"C"},{"id":519,"type":"single","cat":"法规与空域","stem":"关于为什么人机要远离国家边境线，描述最准确的是？（）","A":"从电磁安全方考虑","B":"从象安全方考虑","C":"从避免出现边境纠纷方考虑","D":"因为边境线飞行环境不好","answer":"C"},{"id":520,"type":"single","cat":"设备与维护","stem":"以下电池类型中，记忆效应最强的是（）。","A":"锂电池","B":"镍氢电池","C":"镍镉电池","D":"以上均不正确","answer":"C"},{"id":521,"type":"single","cat":"设备与维护","stem":"指挥控制与（）是无人机地面站的主要功能。","A":"飞行状态监控","B":"任务规划","C":"飞行视角显示","D":"以上均不正确","answer":"B"},{"id":522,"type":"single","cat":"基础概念","stem":"下面哪种连接是对的？（）","A":"电池—电调—电机","B":"电机—电调—电池—IMU","C":"电机—电调—IMU—电池","D":"以上均不正确","answer":"A"},{"id":523,"type":"single","cat":"飞行原理","stem":"操纵无人机时，若迎角超过临界迎角，升力系数将会（）。","A":"迅速增大","B":"迅速减小","C":"缓慢增大","D":"以上均不正确","answer":"B"},{"id":524,"type":"single","cat":"基础概念","stem":"在机翼表面附面层由层流状态转变为紊流状态的转捩点的位置。","A":"在飞行M数小于一定值时保持不变","B":"将随着飞行速度的提高而前移","C":"将随着飞行速度的提高而后移","D":"以上均不正确","answer":"B"},{"id":525,"type":"single","cat":"操纵与飞行技术","stem":"（）是指最大起飞重量超过25千克不超过150千克，且空机重量超过15千克的无人机。","A":"小型无人机","B":"中型无人机","C":"大型无人机","D":"轻型无人机","answer":"B"},{"id":526,"type":"single","cat":"基础概念","stem":"磁罗盘所主要感应的参数是（）。","A":"经纬度","B":"角度方位","C":"角速度","D":"加速度","answer":"B"},{"id":527,"type":"single","cat":"基础概念","stem":"直升机、固定翼、多旋翼三种飞行器，其续航性能从高到低排列正确的是（）。","A":"直升机、固定翼、多旋翼","B":"直升机、多旋翼、固定翼","C":"多旋翼、直升机、固定翼","D":"固定翼、直升机、多旋翼","answer":"D"},{"id":528,"type":"single","cat":"设备与维护","stem":"无人机系统通讯链路主要包括：指挥与控制、感知和规避、（）三种。","A":"空中交通管制","B":"视频通信","C":"通信中继","D":"以上均不正确","answer":"A"},{"id":529,"type":"single","cat":"基础概念","stem":"下列关于操作无人机禁止行为描述错误的是（）。","A":"禁止任何形式的载人操作","B":"禁止靠近及抓握飞行当中的无人机","C":"禁止操作无人机飞行至密集人群上空","D":"飞行中的无人机失控时可手接飞行器","answer":"D"},{"id":530,"type":"single","cat":"设备与维护","stem":"多旋翼无人机抗风性测试结果表明，无人机抗风性与无人机的（）有关，下列选项错误的是。","A":"电池容量","B":"飞行控制系统（自驾仪）算法的精确度","C":"PID算法的协调性","D":"重量体积","answer":"A"},{"id":531,"type":"single","cat":"操纵与飞行技术","stem":"姿态遥控模式下操纵无人机爬升，飞机速度减小太多时，下列正确的操纵是（）。","A":"迅速关闭发动机","B":"迅速增大俯仰角","C":"迅速减小俯仰角","D":"以上均不正确","answer":"C"},{"id":532,"type":"single","cat":"飞行原理","stem":"直升机在前飞时桨叶在什么方位迎角最小？（）","A":"180°方位","B":"90°方位","C":"270°方位","D":"以上均不正确","answer":"B"},{"id":533,"type":"multi","cat":"基础概念","stem":"电动动力系统主要由（）组成。","A":"调速系统","B":"电池","C":"动力电机","D":"动力电源","answer":"ACD"},{"id":534,"type":"multi","cat":"电力巡检","stem":"使用中型无人直升机巡检系统的巡检作业，程控手应在巡检作业前一个工作日（），并交工作负责人检查无误。","A":"完成航线规划工作","B":"编辑生成飞行航线","C":"各巡检作业点作业方案","D":"安全策略","answer":"ABCD"},{"id":535,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，操控手是利用遥控器以（）或控制无人机巡检系统飞行的人员","A":"增稳模式","B":"手动","C":"自动","D":"全自动","answer":"AB"},{"id":536,"type":"multi","cat":"设备与维护","stem":"维护保养人员应按维护保养手册要求按时开展（）等工作。","A":"日常维护","B":"零件维修更换","C":"大修保养","D":"试验","answer":"ABCD"},{"id":537,"type":"multi","cat":"电力巡检","stem":"以下哪些属于小型无人直升机巡检系统出厂检验必做项目？","A":"外观及尺寸测量","B":"重量测量","C":"高低温工作试验","D":"抗风能力试验","answer":"AB"},{"id":538,"type":"multi","cat":"基础概念","stem":"下面（）直升机不是采用了无轴承旋翼。","A":"S-76直升机","B":"苏制米-8直升机","C":"UH-60","D":"直升机","answer":"BCD"},{"id":539,"type":"single","cat":"领航与任务规划","stem":"在航拍任务中，若需获得1:2000比例尺的正射影像，飞行相对航高H（单位：m）与相机像元尺寸p（单位：μm）、焦距f（单位：mm）应满足的关系是","A":"H=2000·f/p","B":"H=2000·p/f","C":"H=2000·f·p","D":"H=2000/(f·p)","answer":"A"},{"id":540,"type":"multi","cat":"基础概念","stem":"下列哪些因素会导致空三解算“分层”","A":"曝光时间差异>2档","B":"重叠度局部<30%","C":"相机主距标定误差>3%","D":"测区高差>1/3航高","answer":"ABC"},{"id":541,"type":"single","cat":"设备与维护","stem":"无人机装配报告编制主要包括括装配工序、装配标准、（）、装配工具、装配材料清单和装配安全规范。","A":"装配进度表","B":"装配复检表","C":"装配时间","D":"装配图","answer":"B"},{"id":542,"type":"single","cat":"领航与任务规划","stem":"GPS系统不能提供哪个参数（）。","A":"方位角度","B":"高度","C":"经纬度","D":"速度","answer":"A"},{"id":543,"type":"single","cat":"基础概念","stem":"物体的运动是各式各样的，车辆行驶、鸟类飞翔、机器运转等，从表面上看，运动方式千差万别，但实质上都离不开两种基本的运动：平动和（）。","A":"转动","B":"旋转","C":"下降","D":"上升","answer":"A"},{"id":544,"type":"single","cat":"航空气象","stem":"危及飞行安全和影响正常飞行的重要天气现象，包括（）、降水、地面和近地面层的凝结、凝华和冻结现象、沙尘暴和雷暴等。","A":"空气湿度","B":"大气压","C":"云","D":"雨","answer":"C"},{"id":545,"type":"single","cat":"设备与维护","stem":"（）的主要功能是根据飞控计算机的指令，按规定的静态和动态要求，通过对无人机各控制舵面和发动机节风门等的控制，实现对无人机的飞行控制。","A":"电源","B":"伺服执行机构","C":"数据链","D":"以上均不正确","answer":"B"},{"id":546,"type":"single","cat":"基础概念","stem":"以下飞行器不是多轴飞行器的是（）。","A":"Uh-60黑鹰","B":"Phantom精灵","C":"Inspire悟","D":"以上均不正确","answer":"A"},{"id":547,"type":"single","cat":"设备与维护","stem":"关于电调的主要作用，下面描述正确的是（）。","A":"驱动电机运转","B":"接收飞行信号","C":"存储飞行数据","D":"调节飞行的姿态","answer":"A"},{"id":548,"type":"single","cat":"领航与任务规划","stem":"无人机驾驶员操纵无人机定高平飞航迹偏离时，下列描述正确的是（）。","A":"如果轨迹方向偏离目标5°以内，应快速大幅度地向偏转的反方向适当扭舵杆","B":"如果轨迹方向偏离目标5°以内，应柔和地向偏转的方向适当扭舵杆","C":"如果轨迹方向偏离目标5°以内，应柔和地向偏转的反方向适当扭舵杆","D":"以上均不正确","answer":"C"},{"id":549,"type":"single","cat":"基础概念","stem":"（）的功能是向无人机各用电系统或设备提供满足预定设计要求的电能。","A":"电源","B":"配电系统","C":"供电系统","D":"以上均不正确","answer":"C"},{"id":550,"type":"single","cat":"基础概念","stem":"一般我们说的4级风，风速为（）。","A":"10.8-13.8m/s","B":"8.0-10.7m/s","C":"5.5-7.9m/s","D":"以上均不正确","answer":"C"},{"id":551,"type":"single","cat":"操纵与飞行技术","stem":"飞行驾驶员操纵无人机坡度转弯时，同时操纵方向舵作用是（）。","A":"进行协调转弯，可有效增大转弯半径并减少侧滑","B":"进行协调转弯，可有效减小转弯半径并减少侧滑","C":"进行协调转弯，可有效减小转弯半径并增大侧滑","D":"以上均不正确","answer":"B"},{"id":552,"type":"single","cat":"航空气象","stem":"遥控无人机着陆时，风速大或气温低时（）。","A":"如目测低，加油门量相应小些","B":"如目测高，收油门量相应大些","C":"如目测低，加油门量相应大些","D":"以上均不正确","answer":"C"},{"id":553,"type":"single","cat":"设备与维护","stem":"在飞行中当发动机停车时，地面站会（）(飞机安装有转速传感器)。","A":"报警","B":"失控","C":"没有影响","D":"断开连接","answer":"A"},{"id":554,"type":"single","cat":"领航与任务规划","stem":"飞行器在执行航点飞行时，相邻航点的设置应大于？（）","A":"5米","B":"10米","C":"15米","D":"20米","answer":"A"},{"id":555,"type":"single","cat":"基础概念","stem":"以下哪个英文缩写对应是错误的？（）","A":"舵机反向REV","B":"功能设置FUNC","C":"失控保护F-C","D":"以上均不正确","answer":"C"},{"id":556,"type":"single","cat":"设备与维护","stem":"（）是指通过遥控器屏幕可以查看各个通道的工作状态，也可以分辨通道的正反相。","A":"舵量显示","B":"舵机相位","C":"相位功能","D":"定向功能","answer":"A"},{"id":557,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机在预定高度由平飞转爬升时（）。","A":"注视地平仪，柔和地加油门至100%，同时稍拉杆转为爬升","B":"注视地平仪，快速加油门至100%，同时快速拉杆转为爬升","C":"注视地平仪，快速加油门至100%，同时快速顶杆","D":"以上均不正确","answer":"A"},{"id":558,"type":"single","cat":"领航与任务规划","stem":"若一架无人机在飞行中可以进行舵面遥控，但无实时图像信号，地面站有各类仪表信息，但无法编辑航点航线，请问该无人机的遥控器（）正常，图传（）故障，数据电台（）正常，（）故障。","A":"下行链路、上行链路、下行链路、上行链路","B":"上行链路、下行链路、下行链路、上行链路","C":"上行链路、上行链路、下行链路、下行链路","D":"以上均不正确","answer":"B"},{"id":559,"type":"single","cat":"领航与任务规划","stem":"在垂直矩形航线飞行训练科目中，无人机最大飞行高度为（）m。","A":"1","B":"1.5","C":"3","D":"7","answer":"D"},{"id":560,"type":"single","cat":"设备与维护","stem":"以大疆产品为例，飞行器与遥控器电源开启方法为（）。","A":"短按","B":"长按","C":"短按，再长按","D":"长按，再短按","answer":"C"},{"id":561,"type":"single","cat":"操纵与飞行技术","stem":"以大疆产品为例，姿态数据中，“H”代表什么？（）","A":"飞行器与起飞点之间的相对度距离","B":"飞行器与起飞点之间的相对水平距离","C":"飞行器沿垂直方向的上升、下降速度","D":"飞行器沿水平运动的飞行速度","answer":"A"},{"id":562,"type":"single","cat":"基础概念","stem":"微型无人机，是指空机重量小于（）千克的无人机？","A":"0.25千克","B":"0.20千克","C":"0.15千克","D":"0.35千克","answer":"A"},{"id":563,"type":"single","cat":"设备与维护","stem":"已知某锂电池铭牌标记为6S2P3C，单片锂电池容量为16000mAh，则该电池最大放电电流是（）。","A":"16A","B":"48A","C":"96A","D":"以上均不正确","answer":"C"},{"id":564,"type":"single","cat":"电力巡检","stem":"每次巡检作业结束后，（）应填写无人机巡检系统使用记录单。","A":"操控手","B":"程控手","C":"工作负责人","D":"工作许可人","answer":"C"},{"id":565,"type":"single","cat":"基础概念","stem":"关于多轴飞行器的优势描述不正确的是（）。","A":"成本低廉","B":"气动效率高","C":"结构简单便携","D":"以上均不正确","answer":"B"},{"id":566,"type":"single","cat":"基础概念","stem":"对于续航时间计算，当检测到电量剩余（）时，开始报警，提示用户应该注意剩余点亮，提前做好返航准备。","A":"30%","B":"20%","C":"40%","D":"50%","answer":"A"},{"id":567,"type":"single","cat":"操纵与飞行技术","stem":"飞机的姿态需要通过加速度计、（）等惯性传感器进行测量。","A":"陀螺仪","B":"GPS","C":"双目传感器","D":"位置传感器","answer":"A"},{"id":568,"type":"single","cat":"基础概念","stem":"下列不属于在恶劣环境中使用过的飞机，进行清洁重点的选项是（）。","A":"电机","B":"飞控","C":"机架","D":"螺旋桨","answer":"C"},{"id":569,"type":"single","cat":"领航与任务规划","stem":"无人机的GPS模块因损坏需进行替换，替换后重新安装，其位置距离螺旋桨有一定要求，下面安装位置正确的是（）。","A":"距离螺旋桨12cm","B":"距离螺旋桨8cm","C":"距离螺旋桨5cm","D":"安装在机体正下方","answer":"A"},{"id":570,"type":"single","cat":"航空气象","stem":"气压随高度按指数递减，其规律性比较明显，且飞机一般沿等压面飞行，故空气密度的变化主要由空气（）的变化所引起。","A":"压强","B":"湿度","C":"温度","D":"速度","answer":"C"},{"id":571,"type":"single","cat":"基础概念","stem":"在风中全马力飞行的固定翼民用无人机（）。","A":"顺风飞行时空速较大","B":"逆风飞行时空速较大","C":"顺风逆风空速相同","D":"以上均不正确","answer":"C"},{"id":572,"type":"single","cat":"基础概念","stem":"爬升的注意事项，正确的是（）。","A":"飞行员不应以垂直上升作为主要的飞行方式","B":"垂直上升中，保持直升机状态比较容易","C":"要进入回避区","D":"标准","answer":"A"},{"id":573,"type":"single","cat":"飞行原理","stem":"8040螺旋桨，其螺距为（）。","A":"4in","B":"40in","C":"8in","D":"10.16in","answer":"A"},{"id":574,"type":"single","cat":"设备与维护","stem":"无刷电机去除了电刷，最直接的变化就是没有了有刷电机运转时产生的电火花，这样就极大减少了电火花对（）的干扰。","A":"动力系统","B":"地面站接收设备","C":"遥控无线电设备","D":"飞控系统","answer":"C"},{"id":575,"type":"single","cat":"领航与任务规划","stem":"应根据无人直升机的（）合理规划航线。","A":"型号","B":"性能","C":"航程","D":"载荷","answer":"B"},{"id":576,"type":"single","cat":"航空气象","stem":"当在山谷、山脊或山区做低空飞行时，最容易碰到乱流造成危险的情况是（）。","A":"在山的背风面顺风飞行","B":"在山的背风面逆风飞行","C":"在山的迎风面逆风飞行","D":"在山的迎风面顺风飞行","answer":"A"},{"id":577,"type":"single","cat":"电力巡检","stem":"（）应在每次巡检作业结束后的第二个工作日内前将相关变化情况报送工作许可人。","A":"工作负责人","B":"程控手","C":"工作许可人","D":"操控手","answer":"A"},{"id":578,"type":"single","cat":"设备与维护","stem":"（）是后台指挥中心与前线地面执行人员沟通的枢纽，是最清楚整体行动方案的人，由云台手负责指挥飞行，（）主要负责飞行安全。","A":"飞手，云台手","B":"云台手，飞手","C":"飞手，飞手","D":"云台手，云台手","answer":"B"},{"id":579,"type":"single","cat":"基础概念","stem":"多旋翼无人机为保证机身稳定防止机身自旋，相对旋翼转动方向（）。","A":"相同","B":"相反","C":"垂直","D":"水平","answer":"A"},{"id":580,"type":"single","cat":"基础概念","stem":"无人机飞行摇杆常规操作方式是（）。","A":"姿态遥控和舵面遥控","B":"自主控制","C":"人工修正","D":"以上均不正确","answer":"A"},{"id":581,"type":"single","cat":"基础概念","stem":"不能在压线、信号发射塔附近进行飞行的原因不包含的是？（）","A":"有可能对飞行器磁罗盘信号造成扰","B":"会造成飞行器飞行效率下降","C":"有可能对飞行器遥控器信号造成扰","D":"有可能造成飞行器失控","answer":"B"},{"id":582,"type":"single","cat":"基础概念","stem":"应核对（）是否满足安全飞行要求。","A":"航迹规划","B":"任务规划","C":"航线规划","D":"飞行规划","answer":"C"},{"id":583,"type":"single","cat":"基础概念","stem":"一份详细的测试报告包含足够的信息，包括（），下列选项错误的是。","A":"产品质量和测试过程的评价","B":"测试报告基于测试中的数据采集","C":"测试原因","D":"对最终的测试结果分析","answer":"C"},{"id":584,"type":"single","cat":"设备与维护","stem":"电机的定子22084T1000KV是指（）。","A":"22定子直径毫米，08定子的高度毫米，1000KV每分钟每V电压1000转","B":"22定子直径英寸，08定子的高度英寸，1000KV每分钟每V电压1000转","C":"22定子直径毫米，08定子的高度毫米，1000KV每分钟1000转","D":"以上均不正确","answer":"A"},{"id":585,"type":"single","cat":"操纵与飞行技术","stem":"飞机在起飞着陆前放下襟翼的作用是（）。","A":"增加升力","B":"增加阻力","C":"增大摩擦力","D":"增大升力的同时增加阻力","answer":"D"},{"id":586,"type":"single","cat":"基础概念","stem":"下哪种情况，磁罗盘信号不会受扰？（）","A":"停车场","B":"空旷场地","C":"磁矿上方","D":"大块属四周","answer":"B"},{"id":587,"type":"single","cat":"设备与维护","stem":"测试过程中多旋翼无人机通过牵引绳对测重块施加向上提拉力，从而使测力传感器的检测数据逐渐减小，当所述测力传感器的检测数值稳定后，减小量即为多旋翼无人机的（）。","A":"载重量","B":"重量","C":"起飞重量","D":"安全重量","answer":"A"},{"id":588,"type":"multi","cat":"基础概念","stem":"操控手应始终注意观察无人机（）等信息，判断系统工作是否正常。","A":"巡检系统飞行姿态","B":"发动机或电机运转声音","C":"电池电压","D":"航向","answer":"AB"},{"id":589,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中：目前，以（）无人机为飞行平台的输电线路无人机巡检技术已取得了显著的成效。","A":"小型旋翼","B":"固定翼","C":"中型","D":"中大型","answer":"AB"},{"id":590,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，白天工作间断时，应将发动机处于（），并采取其他必要的安全措施，必要时派人看守。","A":"停运状态","B":"电机下电","C":"关闭","D":"电机运行","answer":"AB"},{"id":591,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，当无人机出现（）等故障时，应及时修正舵向，调节速度、高度，恢复通信链路，若长时间无法恢复正常，应视无人机状态由工作负责人决定是否终止巡检作业。","A":"姿态不稳","B":"航迹偏移大","C":"链路不畅","D":"速度过快","answer":"ABC"},{"id":592,"type":"multi","cat":"电力巡检","stem":"使用固定翼无人机巡检系统进行的架空输电线路巡检作业，工作班成员至少包括（）","A":"飞控手","B":"任务手","C":"程控手","D":"操控手","answer":"CD"},{"id":593,"type":"single","cat":"基础概念","stem":"无人机（）越大，爬升需用功率也越（）。","A":"质量、小","B":"质量、大","C":"体积、大","D":"体积、小","answer":"B"},{"id":594,"type":"single","cat":"基础概念","stem":"固定翼无人机机电系统由动力单元、（）、燃油、电子调速器、配电系统和机载电源组成，提供无人机飞行所需的动力和能源。","A":"机翼","B":"螺旋桨","C":"数据链机载终端","D":"地面站","answer":"B"},{"id":595,"type":"single","cat":"操纵与飞行技术","stem":"固定翼无人机机体通常由（）的模块化机体组成，既方便携带，又可以在短时间内完成组装、起飞。","A":"可重复利用","B":"可拆卸","C":"可回收","D":"可丢弃","answer":"B"},{"id":596,"type":"single","cat":"设备与维护","stem":"遥控无人机固定翼当蒙皮上结霜（）。","A":"失速速率减小","B":"失速速率增加","C":"失速速率增大或减小","D":"以上均不正确","answer":"B"},{"id":597,"type":"single","cat":"基础概念","stem":"关于多旋翼无人机抗雨性能测试，下列说法错误的是（）。","A":"静置淋雨，放置在台风淋雨箱体中间位置，启动并处于怠速状态，保持运行5分钟，多旋翼无人机在雨中能正常旋转","B":"淋雨后检验，放置在外场，检查雨后机体状态，并进行起飞、悬停、降落检查，多旋翼无人机运行正常","C":"雨中悬停，进行雨中悬停，保持5分钟，多旋翼无人机在雨中正常悬停，起降正常","D":"雨中应急返航，进行应急返航，只需返航过程中多旋翼无人机运行正常，安全降落即可","answer":"D"},{"id":598,"type":"single","cat":"飞行原理","stem":"测量机翼的翼弦是从（）。","A":"机身中心线到翼尖","B":"左翼尖到右翼尖","C":"机翼前缘到后缘","D":"以上均不正确","answer":"C"},{"id":599,"type":"single","cat":"领航与任务规划","stem":"遥控无人机着陆时，对用侧滑与改变航向相结合的方法修正侧风影响描述正确的是（）。","A":"退出第四转弯的时机应根据风向适当提前或延迟","B":"退出第四转弯的时机一律适当提前","C":"退出第四转弯的时机一律适当延迟","D":"以上均不正确","answer":"A"},{"id":600,"type":"single","cat":"基础概念","stem":"无人机越往高空飞行（飞行速度不变），飞行所获得的（）就越小。","A":"升力","B":"重力","C":"推力","D":"以上均不正确","answer":"A"},{"id":601,"type":"single","cat":"操纵与飞行技术","stem":"飞行驾驶员姿态遥控模式下操纵无人机下降，速度过大时，下列正确的操纵是（）。","A":"适当增加带杆量，减小下滑角","B":"适当减小带杆量，减小下滑角","C":"适当减小带杆量，增大下滑角","D":"以上均不正确","answer":"A"},{"id":602,"type":"single","cat":"基础概念","stem":"低高度通场是指无人机在飞行过程中从机场跑道上空飞过或是从观礼台前方上空飞过，是无人机表达敬意的一种方式一般认为（）米以下都可以视为低高度。","A":"5","B":"50","C":"100","D":"150","answer":"A"},{"id":603,"type":"single","cat":"领航与任务规划","stem":"关于航向锁定功能，下列描述正确的是（）。","A":"飞行器始终按机头为前向飞行","B":"飞行器按锁定前的机头朝向为前向飞行","C":"需将遥控器切换到S档","D":"需将遥控器切换到A档","answer":"B"},{"id":604,"type":"single","cat":"基础概念","stem":"无人机盘旋飞行时，无人机内，外机翼的线速度是不相同的内翼速度（），外翼速度（）。","A":"小，小","B":"大，大","C":"小，大","D":"大，小","answer":"C"},{"id":605,"type":"single","cat":"设备与维护","stem":"垂起固定翼无人机电子电气部件的日常维护保养，下列选项错误的是（）。","A":"检查各电线外皮是否完好，有无刮擦脱皮等现象","B":"检查飞行器的重心位置是否正确","C":"检查飞行器电池安装是否正确，电池电量是否充足","D":"检查电机安装是否紧固，有无松动等现象","answer":"B"},{"id":606,"type":"single","cat":"基础概念","stem":"无人机电气系统中，电源和（）两者组合统称为供电系统。","A":"配电系统","B":"供电线路","C":"用电设备","D":"以上均不正确","answer":"A"},{"id":607,"type":"single","cat":"基础概念","stem":"亚音速气流经过收缩管道后（）。","A":"速度增加，压强增大","B":"速度降低，压强下降","C":"速度增加，压强下降","D":"以上均不正确","answer":"C"},{"id":608,"type":"single","cat":"操纵与飞行技术","stem":"使用返航锁定时，遥控器横滚杆向左打杆，飞行器将？（）","A":"向左曲线飞行","B":"向左沿直线飞行","C":"向右曲线飞行","D":"向右沿直线飞行","answer":"A"},{"id":609,"type":"single","cat":"基础概念","stem":"以下无人机中，需要跑道起降的是（）？","A":"固定翼无人机","B":"无人直升机","C":"多旋翼无人机","D":"六轴飞行器","answer":"A"},{"id":610,"type":"single","cat":"设备与维护","stem":"用遥控器设置无人机的电调，需要（）。","A":"断开电机","B":"接上电机","C":"断开动力电源","D":"以上均不正确","answer":"B"},{"id":611,"type":"single","cat":"基础概念","stem":"多旋翼无人机磁罗盘正确校准的方法是（）。","A":"校准时需要水平和垂直","B":"校准时应靠近强磁场区域","C":"校准时可以在雷雨天气","D":"校准时机身可以任意倾斜角度","answer":"A"},{"id":612,"type":"single","cat":"设备与维护","stem":"打开遥控器前检查哪几步？（）","A":"天线、开关、油门位置","B":"电压、油门位置、中立微调","C":"发射制式、模型类型、电压","D":"以上均不正确","answer":"A"},{"id":613,"type":"single","cat":"设备与维护","stem":"经验表明无人机每飞行（）小时或者更少就需要某种类型的预防性维护，至少每（）小时进行较小的维护。","A":"30，60","B":"20，50","C":"25，40","D":"以上均不正确","answer":"B"},{"id":614,"type":"single","cat":"基础概念","stem":"飞行前检查，下列哪一项最危险（）。","A":"电池表面有轻微污渍","B":"电池电量90%","C":"遥控器表面有污渍","D":"套筒未旋紧或卡扣未卡紧","answer":"D"},{"id":615,"type":"single","cat":"操纵与飞行技术","stem":"直升机飞行中需要的操纵（）。","A":"需要六个，因为直升机空中有六个自由度","B":"需要三个操纵就可以改变俯仰、横测和航向姿态","C":"需要四个操纵才能改变与保持所需姿态","D":"以上均不正确","answer":"B"},{"id":616,"type":"single","cat":"基础概念","stem":"飞行前检查的第一项是（）。","A":"重心","B":"紧固件","C":"电压","D":"以上均不正确","answer":"B"},{"id":617,"type":"single","cat":"基础概念","stem":"多旋翼1.1米轴距代表什么意思？（）","A":"对角电机之间的直径距离为1.1米","B":"相邻电机之间的直径距离为1.1米","C":"对角电机之间的半径距离为1.1米","D":"以上均不正确","answer":"A"},{"id":618,"type":"single","cat":"操纵与飞行技术","stem":"飞行驾驶员操纵无人机无坡度转弯，正确的操纵方式是（）。","A":"向转弯方向压方向舵，副翼同方向打以保证坡度水平","B":"向转弯方向压方向舵，副翼反打以保证坡度水平","C":"向转弯方向压方向舵，副翼同方向打以形成坡度","D":"以上均不正确","answer":"B"},{"id":619,"type":"single","cat":"基础概念","stem":"多旋翼无人机机体一般由机身、（）、起落架和结构挂载件组成。","A":"电气系统","B":"任务载荷设备","C":"机臂","D":"地面站","answer":"C"},{"id":620,"type":"single","cat":"飞行原理","stem":"为了使固定翼无人机飞行中俯仰为矩平衡，电动机相对无人机纵轴一般有向下（）的下拉安装角。","A":"1～1.5°","B":"1.5～3°","C":"3～4.5°","D":"5.5～6°","answer":"B"},{"id":621,"type":"single","cat":"基础概念","stem":"多轴飞行时地面人员手里拿的“控”指的是（）。","A":"地面遥控发射机","B":"链路系统","C":"导航飞控系统","D":"以上均不正确","answer":"A"},{"id":622,"type":"single","cat":"设备与维护","stem":"多旋翼机身由上中心板、下中心板、分电板、电池挂板和（）组成。","A":"飞行控制系统（自驾仪）减震板","B":"飞行控制系统（自驾仪）主板","C":"相机挂板","D":"光流挂板","answer":"A"},{"id":623,"type":"single","cat":"领航与任务规划","stem":"飞行器与返航点超过（）米才可以启动返航锁定？（）","A":"5米","B":"10米","C":"15米","D":"20米","answer":"A"},{"id":624,"type":"single","cat":"设备与维护","stem":"检查无刷电机动平衡是否良好的方法描述正确的是（）。","A":"电机不带螺旋桨进行旋转","B":"电机带动螺旋桨进行旋转","C":"用手转动电机","D":"将飞行器起飞，感受飞行器机身振动","answer":"A"},{"id":625,"type":"single","cat":"操纵与飞行技术","stem":"民用无人驾驶航空器系统视距内运行是指航空器处于驾驶员或观测员目视视距内半径（）米，相对高度低于（）米的区域内。","A":"500、120","B":"500、100","C":"120、50","D":"250、120","answer":"A"},{"id":626,"type":"single","cat":"飞行原理","stem":"为了飞行安全，飞机飞行时的升力系数和迎角一般为（）。","A":"最大升力系数和临界迎角最大","B":"最大升力系数和小于临界迎角的迎角限定值","C":"小于最大升力系数和临界迎角的两个限定值","D":"以上均不正确","answer":"C"},{"id":627,"type":"single","cat":"飞行原理","stem":"关于旋翼的反扭矩说法正确的是（）。","A":"旋翼的反扭矩会迫使直升机向旋翼旋转的反方向偏转","B":"旋翼反扭矩的大小取决于发动机最大功率的大小","C":"发动机带动旋翼旋转时，旋翼诱导阻力力矩为发动机传递给旋翼轴的扭矩所平衡标准","D":"以上均不正确","answer":"A"},{"id":628,"type":"single","cat":"法规与空域","stem":"（）是指专门分配给无人机系统运行的空域，通过限制其他航空器的进入以规避碰撞风险。","A":"隔离空域","B":"融合空域","C":"监视空域","D":"报告空域","answer":"A"},{"id":629,"type":"single","cat":"基础概念","stem":"下面直升机旋翼的结构形式是无铰式旋翼的是（）。","A":"法国的松鼠直升机","B":"BO-105直升机","C":"直-11型直升机","D":"以上均不正确","answer":"B"},{"id":630,"type":"single","cat":"法规与空域","stem":"关于为什么无人机要远离国家边境线，描述最准确的是？（）","A":"从电磁安全方考虑","B":"从气象安全方考虑","C":"从避免出现边境纠纷方考虑","D":"因为边境线飞行环境不好","answer":"C"},{"id":631,"type":"single","cat":"基础概念","stem":"无人机更换舵角时，以下各部件中只有（）的活动面适合安装。","A":"机身","B":"副翼","C":"襟翼","D":"机臂","answer":"B"},{"id":632,"type":"single","cat":"设备与维护","stem":"下面关于遥控器闲置情况下的描述正确是（）。","A":"遥控器闲置10分钟后将发出报警，闲置15分钟将关机","B":"遥控器闲置8分钟后将发出报警，闲置15分钟将关机","C":"遥控器闲置6分钟后将发出报警，闲置12分钟将关机","D":"遥控器闲置5分钟后将发出报警，闲置10分钟将关机","answer":"D"},{"id":633,"type":"single","cat":"设备与维护","stem":"遥控器（美国手）左侧摇杆向前推飞行器会做怎样动作（）。","A":"飞行器向前飞行","B":"飞行器向左飞行","C":"飞行器向上飞行","D":"飞行器逆时针旋转","answer":"C"},{"id":634,"type":"single","cat":"操纵与飞行技术","stem":"姿态遥控模式下操纵无人机爬升，俯仰角偏低时，下列正确的操纵是（）。","A":"应柔和地向右扭舵","B":"应柔和地向前顶杆","C":"应柔和地向后带杆","D":"以上均不正确","answer":"C"},{"id":635,"type":"single","cat":"航空气象","stem":"无人机飞行员在操纵飞机平飞时，遇到强烈的垂直上升气流时，为了防止过载超规定应（）。","A":"适当减小飞行速度","B":"加大油门迅速脱离","C":"以最大上升率增大高度","D":"以上均不正确","answer":"A"},{"id":636,"type":"single","cat":"操纵与飞行技术","stem":"固定翼无人机着陆和起飞时，描述正确的是（）。","A":"固定翼无人机一般顺风起飞","B":"固定翼无人机一般顺风着陆","C":"固定翼无人机一般逆风着陆","D":"固定翼无人机起降不受风的影响","answer":"C"},{"id":637,"type":"single","cat":"基础概念","stem":"在对无人机电动系统组装时，依据所选电动机的最大额定电流选择所需（）。","A":"电池","B":"电动机","C":"电调","D":"飞控","answer":"C"},{"id":638,"type":"single","cat":"飞行原理","stem":"关于多轴飞行器的反扭矩说法不正确的是（）。","A":"多轴飞行器的俯仰运动通过改变各个旋翼的反扭矩来实现","B":"单个旋翼反扭矩的大小取决于电动机转速","C":"单个旋翼的反扭矩会迫使多轴飞行器向旋翼旋转的反方向偏转","D":"以上均不正确","answer":"A"},{"id":639,"type":"single","cat":"基础概念","stem":"无人机系统飞行器平台主要使用的是（）空气的动力驱动的航空器。","A":"等于","B":"重于","C":"轻于","D":"以上均不正确","answer":"B"},{"id":640,"type":"single","cat":"设备与维护","stem":"一块聚合物锂电池上标有25C字样，C代表（）。","A":"充电倍率","B":"容量倍率","C":"放电倍率","D":"以上均不正确","answer":"C"},{"id":641,"type":"single","cat":"领航与任务规划","stem":"同航线同重量，哪种受风力影响最小？（）","A":"速度快","B":"速度慢","C":"速度比重","D":"以上均不正确","answer":"A"},{"id":642,"type":"single","cat":"操纵与飞行技术","stem":"悬停状态的六轴飞行器如何实现向前移动（）。","A":"纵轴右侧的螺旋桨减速，纵轴左侧的螺旋桨加速","B":"横轴前侧的螺旋桨减速，横轴后侧的螺旋桨加速","C":"横轴前侧的螺旋桨加速，横轴后侧的螺旋桨减速","D":"以上均不正确","answer":"B"},{"id":643,"type":"multi","cat":"设备与维护","stem":"民用无人机系统有哪几种链路？（）","A":"数传链路","B":"图传链路","C":"卫星链路","D":"遥控器链路","answer":"ABD"},{"id":644,"type":"multi","cat":"基础概念","stem":"以下哪几项属于无人机动力装置检查与启动（）。","A":"发动机油量检查","B":"微型无人机进行不同姿态发动机稳定性检查","C":"电动机进行正反转检查","D":"动力装置启动后与其他系统的干扰检查","answer":"ABCD"},{"id":645,"type":"multi","cat":"基础概念","stem":"关于“飞行管理”正确的是（）。","A":"在一个划定的管制空域内，可由两个空中交通管制单位负责空中交通管制","B":"通常情况下，民用航空器不得飞入禁区和限制区","C":"民用航空器未经批准不得飞出中华人民共和国领空","D":"民用航空器在管制空域内飞行必须取得空中交通管制单位的许可","answer":"BCD"},{"id":646,"type":"single","cat":"操纵与飞行技术","stem":"遥控器中升降舵、副翼、方向舵、油门控制通道的英文缩写分别正确的是（）。","A":"ELE，AIL，RUD，THR","B":"ELE，THR，RUD，AIL","C":"RUD，AIL，ELE，THR","D":"以上均不正确","answer":"A"},{"id":647,"type":"single","cat":"基础概念","stem":"飞行控制是指采用（）对无人机在空中整个飞行过程的控制。","A":"遥感方式","B":"遥测方式","C":"遥控方式","D":"以上均不正确","answer":"C"},{"id":648,"type":"single","cat":"操纵与飞行技术","stem":"（）既是直流无刷电机的调制机构，也可以看作是电动无人驾驶航空器的油门执行机构。","A":"发动机","B":"电子调速器","C":"螺旋桨","D":"调压器","answer":"B"},{"id":649,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时（）。","A":"机场气温较高时，跑道上升气流明显，会导致下滑距离增长","B":"机场气温较高时，跑道下降气流明显，会导致下滑距离增长","C":"机场气温较高时，跑道下降气流明显，会导致下滑距离减小","D":"以上均不正确","answer":"A"},{"id":650,"type":"single","cat":"操纵与飞行技术","stem":"固定翼常规无人机飞行辅助操纵面有（）。","A":"副翼，升降舵，方向舵，调整片","B":"缝翼，全动平尾，襟翼，调整片","C":"缝翼，襟翼，调整片","D":"以上均不正确","answer":"C"},{"id":651,"type":"single","cat":"设备与维护","stem":"锂电池长期不用，保存电压是多少？（）","A":"3.8V","B":"3.85V","C":"3.75V","D":"以上均不正确","answer":"B"},{"id":652,"type":"single","cat":"设备与维护","stem":"经测试，某多轴飞行器稳定飞行时，动力电池的持续输出电流为10安培，该多轴可以选用（）。","A":"15A的电调","B":"10A的电调","C":"50A的电调","D":"以上均不正确","answer":"C"},{"id":653,"type":"single","cat":"设备与维护","stem":"民用无人机上的舵机一般输出行程为（）。","A":"正负120度","B":"正负45度","C":"正负20度","D":"以上均不正确","answer":"C"},{"id":654,"type":"single","cat":"电力巡检","stem":"巡检作业区域出现其他飞行器或飘浮物时，应（），在确保安全后方可继续执行巡检作业，否则应采取避让措施。","A":"迅速采取措施保证无人机巡检系统安全","B":"立即评估巡检作业安全性","C":"立即控制无人机巡检系统降落","D":"立即控制无人机巡检系统返航","answer":"B"},{"id":655,"type":"single","cat":"领航与任务规划","stem":"作业过程中，任务手如发现（）、悬停点与预设航线偏差较大，应及时告知程控手（操控手）调整飞行航线。","A":"任务目标","B":"飞行航向","C":"飞行航线","D":"飞机轨迹","answer":"C"},{"id":656,"type":"single","cat":"设备与维护","stem":"无人机（）是指根据无人机需要完成的任务、无人机的数量以及携带任务载荷的类型，对无人机制定飞行路线并进行任务分配。","A":"航迹规划","B":"任务规划","C":"飞行规划","D":"以上均不正确","answer":"B"},{"id":657,"type":"single","cat":"法规与空域","stem":"轻型无人机，是指同时满足空机重量不超过（）千克，最大起飞重量不超过（）千克，最大飞行速度不超过（）千米/小时，具备符合空域管理要求的空域保持能力和可靠被监视能力的遥控驾驶航空器，但不包括微型无人机。","A":"2，7，100","B":"3，7，100","C":"4，7，100","D":"5，7，100","answer":"C"},{"id":658,"type":"single","cat":"设备与维护","stem":"（）传感器是飞行控制系统的基本传感器之一，用以改善系统的阻尼特性、提高稳定性。","A":"迎角，侧滑角","B":"空速","C":"角速率","D":"以上均不正确","answer":"C"},{"id":659,"type":"single","cat":"基础概念","stem":"主控主要的功能是（）。","A":"接收传感器信号并实现飞行器的所有功能","B":"经纬度定位","C":"方位确定","D":"确定角速度","answer":"A"},{"id":660,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机四转弯后（）。","A":"目测过低时，应在加大油门的同时适当增加带杆量，减小下滑角，必要时可平飞一段","B":"等飞机降到较低高度时再做偏差调整","C":"目测过高时，应在加大油门的同时适当增加带杆量，减小下滑角，必要时可平飞一段","D":"以上均不正确","answer":"A"},{"id":661,"type":"single","cat":"基础概念","stem":"无人机配平的主要考虑是（）沿纵轴的前后位置。","A":"气动焦点","B":"发动机","C":"中心","D":"重心","answer":"D"},{"id":662,"type":"single","cat":"设备与维护","stem":"多轴无人机，电调上较细的白红黑3色排线，也叫杜邦线，用来连接（）。","A":"电机","B":"机载遥控接收机","C":"飞控","D":"以上均不正确","answer":"C"},{"id":663,"type":"single","cat":"基础概念","stem":"固定翼无人机起落架安装的后三点安装是指主起落架对称安装在无人机（）之前，第三个支点（尾轮）在机尾安装。","A":"中心","B":"重心","C":"焦点","D":"压力中心","answer":"A"},{"id":664,"type":"single","cat":"设备与维护","stem":"电机、电调、电池、接收机、数传电台请把他们用合格的方式连接（）。","A":"数传电台—电池—电调—电机","B":"接收机—电池—电调—电机","C":"电池—电调—电机","D":"以上均不正确","answer":"C"},{"id":665,"type":"single","cat":"基础概念","stem":"安装电动机时无人机机头方向的左上和右下为（）电动机，右上和左下为（）电动机。","A":"逆时针(CCW)，顺时针(CW)","B":"顺时针(CW)，逆时针(CCW)","C":"逆时针(CCW)，逆时针(CCW)","D":"顺时针(CW)，顺时针(CW)","answer":"B"},{"id":666,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，面对拉平高正确的操作方式是（）。","A":"拉平高时，如果飞机不下沉，应稍拉杆，使飞机下沉到预定高度","B":"拉平高时，如果飞机随即下沉，应稳住杆，待飞机下沉到一定高度时，再柔和拉杆","C":"发现有拉高的趋势，应推杆","D":"以上均不正确","answer":"B"},{"id":667,"type":"single","cat":"基础概念","stem":"固定翼无人机起落架安装的前三点安装是指主起落架对称的安置在无人机（）后面，第三个支点（前轮）位于机身前部。","A":"压力中心","B":"焦点","C":"中心","D":"重心","answer":"D"},{"id":668,"type":"single","cat":"操纵与飞行技术","stem":"无人机驾驶员关于无人机飞行速度范围不需要了解的是（）。","A":"海平面不同重量下的速度范围","B":"极限高度内的速度范围","C":"极限高度外的速度范围","D":"以上均不正确","answer":"C"},{"id":669,"type":"single","cat":"设备与维护","stem":"用遥控器设置电调，需要（）。","A":"接上电机","B":"断开动力电源","C":"断开电机","D":"以上均不正确","answer":"A"},{"id":670,"type":"single","cat":"操纵与飞行技术","stem":"以大疆产品为例，DJIGO界面中，姿态球中的飞行器状态与实际不符，可能是因为。","A":"移动设备指南针异常，需校准","B":"移动设备未连接蜂窝数据网络","C":"移动设备未登录DJIGO账户","D":"移动设备信号受到干扰","answer":"A"},{"id":671,"type":"single","cat":"操纵与飞行技术","stem":"在自主飞行过程中，遥控器油门得位置应处于（）。","A":"油门处于最上方","B":"油门处于最下方","C":"油门处于中间略上","D":"以上均不正确","answer":"C"},{"id":672,"type":"single","cat":"设备与维护","stem":"作为无人机系统的重要组成部分，链路系统的主要任务是建立一个空地（）数据传输通道。","A":"上行","B":"单向","C":"双向","D":"下行","answer":"C"},{"id":673,"type":"single","cat":"基础概念","stem":"关于固定翼无人机机体与旋翼大小改造，下列说法错误的是（）。","A":"减小旋翼大小能增大飞行速度","B":"增大垂尾面积能提高无人机纵向稳定性","C":"平尾距离重心越远能提高无人机纵向稳定性","D":"设置上反角能提高无人机横向稳定性","answer":"B"},{"id":674,"type":"single","cat":"基础概念","stem":"以下（）不属于固定翼无人机系统的地面控制站。","A":"地面站","B":"数据链地面终端","C":"操作手柄","D":"飞控计算机","answer":"D"},{"id":675,"type":"single","cat":"基础概念","stem":"部分多轴飞行器会安装垂尾（）。","A":"会减小高速前飞时的稳定性，增加悬停时的稳定性","B":"会增加高速前飞时的稳定性，减小悬停时的稳定性","C":"会增加高速前飞时的稳定性，增加悬停时的稳定性","D":"以上均不正确","answer":"B"},{"id":676,"type":"multi","cat":"领航与任务规划","stem":"航线规划应避开（）。","A":"军事禁区","B":"军事管理区","C":"空中危险区","D":"空中限制区","answer":"ABCD"},{"id":677,"type":"multi","cat":"电力巡检","stem":"应根据巡检线路的杆塔坐标、塔高、塔型等技术参数，结合线路途经区域地图和现场勘查情况（），制定（）。","A":"绘制航线","B":"巡检方式","C":"起降位置","D":"安全策略","answer":"ABCD"},{"id":678,"type":"multi","cat":"基础概念","stem":"固定翼无人机自动定高模式飞行时，持续升高或下降，可能的原因是（）。","A":"角速度计故障","B":"动力系统故障","C":"高度传感器故障","D":"加速度计故障","answer":"BC"},{"id":679,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，使用中型无人直升机巡检系统进行的架空输电线路巡检作业，作业人员包括工作负责人和工作班成员。工作班成员至少包括（）。","A":"程控手","B":"控制手","C":"操控手","D":"任务手","answer":"ACD"},{"id":680,"type":"multi","cat":"基础概念","stem":"活塞发动机在（）时，容易发生爆震。","A":"发动机处于小转速工作","B":"大进气压力状态工作","C":"发动机处于大转速工作","D":"小进气压力转台工作","answer":"AB"},{"id":681,"type":"single","cat":"领航与任务规划","stem":"多旋翼无人机功能改造需要考虑的因素通常包括起飞重量与载重比要求、续航时间要求、飞行控制与导航要求、通信传输要求、（）等。","A":"外观要求","B":"颜色要求","C":"维保要求","D":"飞行器平台与任务载荷系统的连接与联调","answer":"D"},{"id":682,"type":"single","cat":"操纵与飞行技术","stem":"操作无人机起飞前，动力装置不需要检查的是（）。","A":"发动机稳定性检查","B":"发动机生产日期","C":"发动机油路检查","D":"以上均不正确","answer":"B"},{"id":683,"type":"single","cat":"基础概念","stem":"固定翼无人机组装后，要对机翼、机身和尾翼的相互位置进行检查若发现机翼在机身上左右高低位置不一致，可将（），直到把机翼摆平为止。","A":"较高一侧机身侧板的安装机翼处削去一些","B":"较低一侧机身侧板的安装机翼处填补一些","C":"较高一侧机翼削短一些","D":"较短一侧机翼加长一些","answer":"A"},{"id":684,"type":"single","cat":"法规与空域","stem":"固定翼无人机的基本飞行性能，起飞距离指从开始滑跑到飞机越过安全高度时所经过的水平距离，影响起飞距离的因素中错误的是（）。","A":"飞机起飞重量","B":"发动机的推力","C":"减小迎角","D":"爬升角","answer":"C"},{"id":685,"type":"single","cat":"领航与任务规划","stem":"任务规划时还要考虑（），即应急航线。","A":"异常应急措施","B":"安全返航措施","C":"紧急迫降措施","D":"以上均不正确","answer":"A"},{"id":686,"type":"single","cat":"基础概念","stem":"多旋翼无人机无人机的轴距是指（）。","A":"相邻两电机轴间的距离","B":"相对电机轴间的距离","C":"电机轴距飞机立轴的距离","D":"电机轴的长度","answer":"B"},{"id":687,"type":"single","cat":"设备与维护","stem":"电调的全称是（）。","A":"电子调速器","B":"电子调压器","C":"电池调压器","D":"电机调速器","answer":"A"},{"id":688,"type":"single","cat":"基础概念","stem":"多旋翼遥控状态下动力失效的处理办法是（）。","A":"迅速收油门","B":"开伞迫降","C":"自动返航","D":"以上均不正确","answer":"B"},{"id":689,"type":"single","cat":"基础概念","stem":"在保障无人机飞行安全的基础上，为无人分配最高效的故障处置策略，例如，分配高度源故障和位置源故障的首选策略分别是（）。","A":"航迹返回和迫降","B":"定高盘旋和航向返回","C":"迫降和航向返回","D":"航迹返回和航向返回","answer":"D"},{"id":690,"type":"single","cat":"电力巡检","stem":"测绘作业一般采用（）航高，电力线路巡检采用（）作业模式。","A":"固定，变航高","B":"变航高，变航高","C":"固定，固定","D":"变航高，固定","answer":"A"},{"id":691,"type":"single","cat":"基础概念","stem":"有些无人机通过（）加速到发射速度。","A":"引力","B":"重量","C":"导轨或轨道","D":"加速度","answer":"C"},{"id":692,"type":"single","cat":"操纵与飞行技术","stem":"飞行控制系统是无人驾驶航空器的关键核心系统之一，简称（）。","A":"遥控","B":"飞控","C":"自控","D":"制控","answer":"B"},{"id":693,"type":"single","cat":"基础概念","stem":"下列错误的选项是（）。","A":"粘性阻力是由于空气和飞行器表面接触产生的","B":"形状阻力是由于空气和飞行器表面接触产生的","C":"蒙皮摩擦阻力是由于空气和飞行器表面接触产生的","D":"以上均不正确","answer":"B"},{"id":694,"type":"single","cat":"设备与维护","stem":"多旋翼无人机飞行控制系统（自驾仪）固件升级时，为保持（）稳定，应使用USB数据线连接飞行控制系统（自驾仪）进行固件升级。","A":"全球定位系统（GPS）信号","B":"动力电机","C":"飞行姿态","D":"数据传输","answer":"D"},{"id":695,"type":"single","cat":"设备与维护","stem":"关于图传信号丢失有可能是什么原因造成，以下哪项表述最全（）。","A":"遥控器天线未展开","B":"飞背对着飞行器","C":"遥控器与飞行器中间隔有障碍物","D":"其他全是","answer":"D"},{"id":696,"type":"single","cat":"设备与维护","stem":"无刷电机相对于有刷电机的优势不包括的是（）。","A":"效率更高","B":"扭矩更大","C":"寿命更长","D":"功率密度大","answer":"B"},{"id":697,"type":"single","cat":"基础概念","stem":"飞行器的失控行为不包括的是（）。","A":"返航","B":"悬停","C":"下降","D":"上升","answer":"D"},{"id":698,"type":"single","cat":"操纵与飞行技术","stem":"以大疆产品为例，飞行器飞行过程中，红三角形位于姿态球左上方，三角形尖端朝向姿态球中，请问飞行器处于操作者哪个位置，机头朝向如何？","A":"飞行器处于操作者左前方，机头朝向操作者自","B":"飞行器处于操作者左后方，机头朝向操作者自","C":"飞行器处于操作者右后方，机头朝向操作者前方","D":"飞行器处于操作者右前方，机头朝向操作者后方","answer":"A"},{"id":699,"type":"single","cat":"操纵与飞行技术","stem":"无人机定速遥控飞行时放下起落架，驾驶员需（）。","A":"增加油门以保持空速","B":"减小油门以保持空速","C":"针对此情况，无需做相关动作","D":"以上均不正确","answer":"A"},{"id":700,"type":"single","cat":"操纵与飞行技术","stem":"未来无人驾驶航空器地面控制站的发展不包括（）。","A":"友好的人机界面","B":"低成本","C":"一站多机","D":"多样性","answer":"D"},{"id":701,"type":"single","cat":"操纵与飞行技术","stem":"油门测试是以下哪一项测试的主要内容之一（）。","A":"有桨调试","B":"无桨调试","C":"主控调试","D":"油门调试","answer":"A"},{"id":702,"type":"single","cat":"操纵与飞行技术","stem":"起飞场地从北京移至拉萨，对哪类无人机的高度性能影响最严重（）。","A":"油动固定翼","B":"电动固定翼","C":"电动多轴","D":"以上均不正确","answer":"A"},{"id":703,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，拉飘的修正方法是（）。","A":"发现拉飘时，稳住并保持杆量","B":"发现拉飘时，应立即继续拉杆","C":"发现拉飘时，应立即柔和推杆制止飞机继续上飘","D":"以上均不正确","answer":"C"},{"id":704,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机进入下滑后（）。","A":"当下滑线正常时，如速度大，表明目测高，应适当收小油门","B":"当下滑线正常时，如速度大，表明目测低，应适当增加油门","C":"当下滑线正常时，如速度小，表明目测高，应适当收小油门","D":"以上均不正确","answer":"A"},{"id":705,"type":"single","cat":"领航与任务规划","stem":"导航子系统功能是向无人机提供（）信息，引导无人机沿指定航线安全、准时、准确的飞行。","A":"高度、速度和位置","B":"角速度","C":"角加速度","D":"温度、湿度","answer":"A"},{"id":706,"type":"single","cat":"飞行原理","stem":"某多轴螺旋桨长254毫米，螺距114毫米，那么他的型号可表述为（）。","A":"2511","B":"1045","C":"254114","D":"以上均不正确","answer":"B"},{"id":707,"type":"single","cat":"设备与维护","stem":"一款电机为300KV，其在3SLIPO下，最大空载转速为（）。","A":"4280RPM","B":"3000RPM","C":"3330RPM","D":"3780RPM","answer":"D"},{"id":708,"type":"single","cat":"航空气象","stem":"云还伴随出现其他一些天气现象，仍会对飞行的安定性产生影响，尤其是（），常造成飞机积冰、飞机颠簸、强烈风切变、雷击和冰暴，成为飞行障碍甚至危及飞行安全。","A":"雨层云","B":"高积云","C":"积状云","D":"层云","answer":"C"},{"id":709,"type":"single","cat":"操纵与飞行技术","stem":"组装固定翼无人机后进行试飞，如果发现飞机偏航，首先要检查的位置是（）。","A":"螺旋桨","B":"电池","C":"起落架","D":"机翼和尾翼","answer":"D"},{"id":710,"type":"single","cat":"基础概念","stem":"因照明系统发热量大，安装位置应远离（）。","A":"分电板","B":"全球导航卫星系统（GNSS）","C":"螺旋桨","D":"起落架","answer":"B"},{"id":711,"type":"multi","cat":"电力巡检","stem":"特殊巡检根据季节特点、设备状况及特殊需要，选择适用机型开展（）巡检。","A":"加强性","B":"防范性","C":"安全性","D":"针对性","answer":"ABD"},{"id":712,"type":"multi","cat":"基础概念","stem":"以下做法正确的是（）。","A":"先启动无人机飞行器，再开启遥控器","B":"更换飞行地点需重新校准指南针","C":"避免超视距飞行","D":"选择在宽阔的无人场地飞行","answer":"BCD"},{"id":713,"type":"multi","cat":"基础概念","stem":"飞行过程中可能需要处置的紧急情况包括","A":"飞控系统故障","B":"上行通讯链路故障","C":"控制站显示系统故障","D":"电池电量不足","answer":"BC"},{"id":714,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，民用航空的空中管制区包括（）、（）和（）等。","A":"塔台管制区","B":"进近管制区","C":"区域管制区","D":"管制区","answer":"ABC"},{"id":715,"type":"multi","cat":"电力巡检","stem":"在试验和推广（）时，应制定相应的安全措施，确定无人机巡检系统状态良好，并履行相关审批手续后方可执行","A":"新方法","B":"新技术","C":"新工艺","D":"新设备","answer":"BCD"},{"id":716,"type":"multi","cat":"电力巡检","stem":"无人直升机巡检系统环境适应性等级按适用环境温度进行划分，无人直升机巡检系统分为（）和特殊型","A":"普通型","B":"高温型","C":"低温型","D":"极低温型","answer":"ABCD"},{"id":717,"type":"multi","cat":"设备与维护","stem":"链路系统的本质就是两个相互通信的电台通过链路系统，无人机系统可以实现数据、图像等信息的发送和接收常用的链路系统分为（）。","A":"遥控上行链路","B":"数传链路","C":"图传下行链路","D":"数图一体的局域网链路","answer":"ABCD"},{"id":718,"type":"single","cat":"基础概念","stem":"按飞行平台构型分类，多旋翼无人机属于下列哪一类？","A":"固定翼无人机","B":"旋翼无人机","C":"扑翼无人机","D":"伞翼无人机","answer":"B"},{"id":719,"type":"single","cat":"操纵与飞行技术","stem":"某多旋翼无人机悬停时，所有电机转速突然同时下降，机体开始下降，最可能的原因是？","A":"单个电调损坏","B":"飞控参数错误","C":"电池电压过低触发低电压保护","D":"GPS信号丢失","answer":"C"},{"id":720,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机在无风条件下悬停时，增加某个电机的转速，机身会向哪个方向倾斜？","A":"向该电机所在机臂方向","B":"向该电机所在机臂相反方向","C":"绕垂直轴顺时针旋转","D":"不产生倾斜","answer":"B"},{"id":721,"type":"single","cat":"领航与任务规划","stem":"无人机飞行中，地面站显示的“地速”是指？","A":"无人机相对于空气的速度","B":"无人机相对于地面的速度","C":"风速","D":"电机转速","answer":"B"},{"id":722,"type":"single","cat":"基础概念","stem":"多旋翼无人机的“电子调速器（ESC）”主要功能是？","A":"将交流电转换为直流电","B":"将飞控输出的PWM信号转换为电机转速控制，并调节电机供电","C":"测量电池电压","D":"接收遥控器信号","answer":"B"},{"id":723,"type":"single","cat":"设备与维护","stem":"下列哪种电池最适合为中小型多旋翼无人机提供动力？","A":"铅酸电池","B":"镍镉电池","C":"锂聚合物电池（LiPo）","D":"碱性电池","answer":"C"},{"id":724,"type":"single","cat":"设备与维护","stem":"无人机上安装的“IMU”指的是什么？","A":"电子调速器","B":"惯性测量单元","C":"图像传输模块","D":"气压计","answer":"B"},{"id":725,"type":"single","cat":"法规与空域","stem":"根据我国现行法规，微型无人机空机重量范围通常为？","A":"0～500g","B":"500g～2kg","C":"2kg～7kg","D":"7kg～25kg","answer":"A"},{"id":726,"type":"single","cat":"设备与维护","stem":"多旋翼无人机桨叶安装时，正桨和反桨的区分主要依据？","A":"颜色不同","B":"桨叶旋转方向不同","C":"材质不同","D":"直径不同","answer":"B"},{"id":727,"type":"single","cat":"设备与维护","stem":"在无人机飞行中，出现“炸机”通常指的是？","A":"无人机正常降落","B":"无人机发生严重碰撞坠毁","C":"无人机失去GPS信号","D":"电池过放","answer":"B"},{"id":728,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机的偏航运动主要依靠？","A":"改变各旋翼的总升力","B":"改变各旋翼的反扭矩平衡","C":"改变机体重心位置","D":"改变机翼迎角","answer":"B"},{"id":729,"type":"single","cat":"设备与维护","stem":"飞行前检查时，发现桨叶有细小裂纹，正确的处理方式是？","A":"用胶水粘合后继续使用","B":"更换桨叶","C":"忽略，继续飞行","D":"用砂纸打磨平滑","answer":"B"},{"id":730,"type":"single","cat":"领航与任务规划","stem":"无人机飞控中的“姿态模式”相比“GPS模式”缺少的功能是？","A":"姿态稳定","B":"定高","C":"定点悬停和自动返航","D":"手动操控","answer":"C"},{"id":731,"type":"single","cat":"设备与维护","stem":"锂聚合物电池的标称电压一般为？","A":"1.2V","B":"3.7V","C":"12V","D":"24V","answer":"B"},{"id":732,"type":"single","cat":"基础概念","stem":"无人机在飞行中遭遇强风，以下哪种操作最危险？","A":"降低高度","B":"迎风飞行增加空速","C":"顺风高速飞行","D":"增大油门保持悬停","answer":"C"},{"id":733,"type":"single","cat":"飞行原理","stem":"多旋翼无人机的失速现象通常表现为？","A":"所有电机停转","B":"某一侧桨叶进入涡环状态或升力骤降","C":"GPS信号丢失","D":"电池鼓包","answer":"B"},{"id":734,"type":"single","cat":"操纵与飞行技术","stem":"无人机遥控器上“油门杆”控制的是？","A":"飞机的俯仰","B":"飞机的横滚","C":"电机的总转速（总升力）","D":"飞机的偏航","answer":"C"},{"id":735,"type":"single","cat":"设备与维护","stem":"在无人机维护中，电机轴承缺油可能导致的典型现象是？","A":"电机温度升高、噪声增大、效率下降","B":"电池电压升高","C":"GPS信号变强","D":"桨叶转速增加","answer":"A"},{"id":736,"type":"single","cat":"法规与空域","stem":"飞行计划中，通常要求无人机远离机场净空保护区，主要原因是？","A":"避免与有人机发生冲突","B":"避免电磁干扰","C":"节省电池","D":"方便降落","answer":"A"},{"id":737,"type":"single","cat":"设备与维护","stem":"某四旋翼无人机使用4S锂聚合物电池，标称电压为14.8V，容量为5000mAh，该电池的标称能量约为多少Wh？","A":"50Wh","B":"74Wh","C":"100Wh","D":"148Wh","answer":"B"},{"id":738,"type":"multi","cat":"设备与维护","stem":"多旋翼无人机飞行控制系统通常包含哪些传感器？","A":"加速度计","B":"陀螺仪","C":"气压计","D":"地磁罗盘","answer":"ABCD"},{"id":739,"type":"multi","cat":"基础概念","stem":"无人机动力系统包括哪些组成部分？","A":"电机","B":"电子调速器","C":"螺旋桨","D":"飞控计算机","answer":"ABC"},{"id":740,"type":"multi","cat":"操纵与飞行技术","stem":"下列哪些情况应禁止无人机起飞？","A":"能见度低于500m","B":"风力等级超过无人机抗风能力","C":"电池电压低于规定值","D":"空域未经批准","answer":"ABCD"},{"id":741,"type":"multi","cat":"基础概念","stem":"多旋翼无人机产生横滚运动可通过哪些方式？","A":"增加左侧电机转速，降低右侧电机转速","B":"增加右侧电机转速，降低左侧电机转速","C":"改变尾电机转速","D":"同时增加所有电机转速","answer":"AB"},{"id":742,"type":"multi","cat":"领航与任务规划","stem":"无人机飞行中GPS信号丢失后，飞控可能采取的措施包括？","A":"切换至姿态模式","B":"执行原地悬停","C":"自动返航","D":"立即断电","answer":"ABC"},{"id":743,"type":"multi","cat":"设备与维护","stem":"关于锂电池使用与保养，正确的做法有？","A":"避免过充过放","B":"存储电压保持在3.8V/cell左右","C":"鼓包电池可继续使用","D":"充电时有人看管","answer":"ABD"},{"id":744,"type":"multi","cat":"基础概念","stem":"无人机飞行中影响续航时间的主要因素有？","A":"电池容量","B":"整机重量","C":"风速风向","D":"桨叶效率","answer":"ABCD"},{"id":745,"type":"multi","cat":"设备与维护","stem":"以下哪些属于无人机日常维护内容？","A":"检查桨叶有无裂纹","B":"清洁电机","C":"校准指南针","D":"检查电池电压和内阻","answer":"ABCD"},{"id":746,"type":"multi","cat":"操纵与飞行技术","stem":"无人机在飞行中遇到“涡环状态”时，正确的改出方法有？","A":"加大油门快速爬升","B":"减小下降速度","C":"向侧前方飞行以脱离下沉气流","D":"收油门快速下降","answer":"BC"},{"id":747,"type":"multi","cat":"法规与空域","stem":"根据无人机飞行管理相关规定，下列哪些区域属于禁飞区？","A":"军用机场净空区","B":"核电站周边规定范围","C":"政府机关上空","D":"普通公园上空","answer":"ABC"},{"id":748,"type":"single","cat":"操纵与飞行技术","stem":"无人机着陆目测与有人机相比不同之处为（）。","A":"有人机是从飞机观察着陆场，无人机是从着陆场观察飞机","B":"有人机为第三视角，无人机为第一视角","C":"有人机驾驶员通过地面人员通告仪表参考值，无人机起降驾驶员可自行观察仪表参考值","D":"以上均不正确","answer":"A"},{"id":749,"type":"single","cat":"操纵与飞行技术","stem":"飞行驾驶员操作无人机定高平飞时，下列正确的是（）。","A":"不断检查空速、高度、和航向指示","B":"定高平飞结束前可以休息","C":"偶尔关注以下空速，高度和航向指示","D":"以上均不正确","answer":"A"},{"id":750,"type":"single","cat":"设备与维护","stem":"地面控制站的组成包括地面遥控设备、通讯链路硬件、计算机软硬件平台、（）。","A":"地面站软件系统","B":"飞行控制系统","C":"GPS控制系统","D":"调参系统","answer":"A"},{"id":751,"type":"single","cat":"基础概念","stem":"下列不属于飞行前检査重点的选项是（）。","A":"飞行器整体目视检查","B":"遥控器检査","C":"飞行器商标检查","D":"环境与飞行场地检査","answer":"C"},{"id":752,"type":"single","cat":"基础概念","stem":"以下通用配置中，可以不配置的是（）。","A":"飞行数据记录仪","B":"机载追踪器","C":"无人机避障系统","D":"插拔式存储设备","answer":"C"},{"id":753,"type":"single","cat":"领航与任务规划","stem":"固定翼无人机进行水平8字飞行时，要求在高度为（）米的航线上。","A":"30-50","B":"60-80","C":"90-120","D":"120-140","answer":"B"},{"id":754,"type":"single","cat":"设备与维护","stem":"电动型多旋翼无人机螺旋桨的型号必须与（）的型号相匹配。","A":"电动机","B":"电调","C":"飞控","D":"电池","answer":"A"},{"id":755,"type":"single","cat":"领航与任务规划","stem":"下列关于航线规划中障碍物测量的描述，错误的是（）。","A":"如果作业区域内存在障碍物，则建议对障碍物测量，否则有可能造成撞机","B":"障碍物区域的形状和大小，可通过调整其边界点进行微调","C":"障碍物区域测量后，应设置障碍物边距，保障飞行安全","D":"障碍物区域不受内缩距离的影响","answer":"D"},{"id":756,"type":"single","cat":"操纵与飞行技术","stem":"无人机驾驶员遥控无人机起飞滑跑描述正确的是（）。","A":"将油门迅速推至大车，等飞机速度积累到足够使其自动起飞","B":"逐渐将油门推至大车并在速度达到起飞速度时柔和拉杆起飞","C":"迅速将油门推至大车并快速拉杆起飞","D":"以上均不正确","answer":"B"},{"id":757,"type":"single","cat":"基础概念","stem":"以大疆御Mavic2变焦版为例，在DJIGO4APP中设置连拍模式，最多可连拍几张？（）","A":"3张","B":"5张","C":"7张","D":"9张","answer":"C"},{"id":758,"type":"single","cat":"基础概念","stem":"无人机燃油箱通气目的之一是（）。","A":"通气增大供油流量","B":"保证向发动机正常供油","C":"通气减小供油流量","D":"以上均不正确","answer":"B"},{"id":759,"type":"single","cat":"基础概念","stem":"旋翼的地面效应，是指飞行器在接近地面的高度工作时，被旋翼排向地面的气流受到地面阻挡，从而影响旋翼空气动力的一种现象影响地面效应的因素包括（）。","A":"温度、飞行速度和风、地表环境","B":"湿度、飞行速度和风、地表环境","C":"高度、飞行速度和风、地表环境","D":"以上均不正确","answer":"C"},{"id":760,"type":"single","cat":"设备与维护","stem":"电调的输出电流必须（）电动机的最大电流。","A":"等于","B":"大于","C":"小于","D":"不等于","answer":"B"},{"id":761,"type":"single","cat":"设备与维护","stem":"无桨调试的基本目的是进行（），检査飞控、电调和电机是否可以正常通电。","A":"断电调试","B":"强电测试","C":"弱电测试","D":"通电测试","answer":"D"},{"id":762,"type":"single","cat":"基础概念","stem":"关于天气以及作业之间的关系，以下描述错误的是（）。","A":"内吸性农药施药后应保证12小时内无降雨","B":"应在晴天以及阴天进行植保作业","C":"可在下雨后立即进行植保作业","D":"气温高于35摄氏度应停止作业","answer":"C"},{"id":763,"type":"single","cat":"基础概念","stem":"无人机发动机采用重力供油系统但装有增压泵，主要目的是为了（）。","A":"减小油箱的剩余燃油","B":"保证大速度巡航的用油","C":"保证爬升、下降及其他的特殊情况下的正常供油","D":"以上均不正确","answer":"C"},{"id":764,"type":"single","cat":"航空气象","stem":"雾霾天气对多旋翼飞行器飞行的最大影响是？（）","A":"降低电池放电性能","B":"影响飞手身体健康","C":"降低飞行效率","D":"降低能见度","answer":"D"},{"id":765,"type":"single","cat":"设备与维护","stem":"多旋翼无人机自驾仪与机架的隔振改造方法，下列说法不正确的是（）。","A":"双面泡沫胶、尼龙扣","B":"螺纹固定连接","C":"凝胶垫","D":"耳塞式或O型环悬挂安装","answer":"B"},{"id":766,"type":"single","cat":"设备与维护","stem":"两块16000MAH6S25C电池，一种方式串联，一种方式并联，哪种方式能输出电流更大？（）","A":"不联","B":"并联","C":"串联","D":"以上均不正确","answer":"B"},{"id":767,"type":"single","cat":"基础概念","stem":"同一架多旋翼飞行器，在同样做好动力匹配的前提下（）。","A":"两叶桨的效率高","B":"三叶桨的效率高","C":"两种桨效率一样高","D":"以上均不正确","answer":"A"},{"id":768,"type":"single","cat":"基础概念","stem":"移动通信模块传输模块安装前区分其类型，根据功能它可以分为图像传输型，（），数据传输型三类。","A":"遥控数据传输型","B":"电子信息传输型","C":"数图一体型","D":"全球导航卫星系统（GNSS）数据传输型","answer":"C"},{"id":769,"type":"single","cat":"基础概念","stem":"无人机飞防作业关于风的方面，描述错误的是（）。","A":"大风会引起飘移增加","B":"禁止人员处于下风向","C":"应在3级风以内作业","D":"7米/秒的风速有助于提升作业效果","answer":"D"},{"id":770,"type":"single","cat":"基础概念","stem":"（）是最佳的航空飞行层。","A":"对流层","B":"平流层","C":"高层大气","D":"底层","answer":"B"},{"id":771,"type":"single","cat":"操纵与飞行技术","stem":"自动驾驶仪中的陀螺是用来测量哪些物理量？（）","A":"飞机角速度或飞机姿态","B":"飞机角速率或飞机姿态角","C":"飞机角速度或飞机姿态角","D":"以上均不正确","answer":"C"},{"id":772,"type":"single","cat":"基础概念","stem":"在无人机协调指挥中哪个角色更适合与后方指挥人员沟通（）。","A":"飞手","B":"云台手","C":"地面人员","D":"维修员","answer":"B"},{"id":773,"type":"single","cat":"基础概念","stem":"无人机飞行时放下起落架，会使飞机（）。","A":"全机阻力减小","B":"全机阻力无明显变化","C":"全机阻力增大","D":"以上均不正确","answer":"C"},{"id":774,"type":"single","cat":"基础概念","stem":"空机重量不包含（）的重量。","A":"云台相机","B":"电机","C":"电池","D":"桨叶","answer":"A"},{"id":775,"type":"single","cat":"基础概念","stem":"请选择出哪一个功能选项，在手动遥控飞行时，可以改变各通道的操作灵敏度？（）","A":"行程比例","B":"微调比例","C":"通道速度","D":"以上均不正确","answer":"A"},{"id":776,"type":"single","cat":"操纵与飞行技术","stem":"经常在草地、碎石路面起飞、着陆的固定翼无人机，螺旋桨旋转时距地面最近点的高度至少要大于螺旋桨直径的（）。","A":"1/2","B":"1/5","C":"1/10","D":"1/20","answer":"B"},{"id":777,"type":"single","cat":"基础概念","stem":"下列不属于有桨调试主要内容是（）。","A":"油门测试","B":"动力测试","C":"俯仰测试","D":"滚转测试","answer":"B"},{"id":778,"type":"single","cat":"设备与维护","stem":"一般锂聚合物电池上都有2组线1组是输出线（粗，红黑各1根）；1组是单节锂电引出线（细，与s数有关），用以监视平衡充电时的单体电压，下面说法正确的是（）。","A":"6S电池有5根红色引出线，1根黑色引出线","B":"6S电池有7根引出线","C":"6S电池有6根引出线","D":"以上均不正确","answer":"B"},{"id":779,"type":"single","cat":"操纵与飞行技术","stem":"视距内运行航空器处于驾驶员或观测员目视视距内半径多少米？（）","A":"500米","B":"600米","C":"700米","D":"1000米","answer":"A"},{"id":780,"type":"multi","cat":"基础概念","stem":"飞行前必须检查（）是否正常。","A":"遥控设备控制距离","B":"伺服系统舵面方向","C":"动力系统运转情况","D":"模型结构完整牢固","answer":"ABCD"},{"id":781,"type":"multi","cat":"基础概念","stem":"以下（）属于警用固定翼无人机系统降落方式。","A":"起落架滑行降落","B":"垂直降落","C":"撞网/撞绳回收","D":"降落伞回收","answer":"ABCD"},{"id":782,"type":"multi","cat":"电力巡检","stem":"巡检作业区域出现雷雨、大风等可能影响作业的突变天气时，应及时评估巡检作业安全性，在确保安全后方可继续执行巡检作业，否则应采取措施控制无人机巡检系统（）。","A":"起飞","B":"避让","C":"返航","D":"就近降落","answer":"BCD"},{"id":783,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，选定的无人机巡检系统起飞和降落区应远离（），尽量避开周边军事禁区、军事管理区、森林防火区和人员活动密集区等，且满足对应机型的技术指标要求。","A":"公路","B":"铁路","C":"重要建筑","D":"重要设施","answer":"ABCD"},{"id":784,"type":"multi","cat":"设备与维护","stem":"检查无刷电机动平衡是否良好的方法描述错误的是（）。","A":"电机不带螺旋桨进行旋转","B":"电机带动螺旋桨进行旋转","C":"用手转动电机","D":"将飞行器起飞，感受飞行器机身振动","answer":"BCD"},{"id":785,"type":"multi","cat":"基础概念","stem":"大型固定翼无人机，机翼与机身常用的连接形式主要有（）。","A":"铰接接头(只传递力)","B":"固接接头(传递力和力矩)","C":"围框式接头(传递力和力矩)","D":"连动式接头（只传递力）","answer":"ABC"},{"id":786,"type":"single","cat":"法规与空域","stem":"执行紧急救护，抢险救灾或其他紧急任务，飞行计划申请最迟应在飞行前（）H提出。","A":"0.5","B":"1","C":"2","D":"3","answer":"B"},{"id":787,"type":"single","cat":"基础概念","stem":"下列关于动压的说法是正确的（）。","A":"总压与静压之和","B":"总压与静压之差","C":"动压和速度成正比","D":"以上均不正确","answer":"B"},{"id":788,"type":"single","cat":"基础概念","stem":"用万用表检测无人机黏合后防打火头和接头外壁之间的电阻值，以下哪个阻值是正常的？（）","A":"1.2Ω","B":"2.5Ω","C":"3.3Ω","D":"6.3Ω","answer":"D"},{"id":789,"type":"single","cat":"操纵与飞行技术","stem":"四轴旋翼机使用的是（），所以应当使用无刷电调。","A":"有刷电机","B":"无刷电机","C":"智控电机","D":"非智控电机","answer":"B"},{"id":790,"type":"single","cat":"设备与维护","stem":"地面站电子地图图元标注不包含下列哪种信息（）。","A":"场地标注","B":"警示标注","C":"地形标注","D":"以上均不正确","answer":"C"},{"id":791,"type":"single","cat":"操纵与飞行技术","stem":"在多旋翼无人机油门曲线调试中，关于油门表述不正确的是（）。","A":"默认的油门曲线为正比例曲线","B":"自主飞行时，油门值应处于中间略上或在中点","C":"油门曲线可以作为摇杆灵敏度设置","D":"降落过程中需要缓慢拉下油门","answer":"B"},{"id":792,"type":"single","cat":"设备与维护","stem":"地面站电子地图显示的信息分为三个方面：一是（）二是（）三是其他辅助信息。","A":"无人机地理坐标信息，无人机飞行姿态信息","B":"无人机位置和飞行航迹，无人机航迹规划信息","C":"无人机飞行姿态信息，无人机航迹规划信息","D":"以上均不正确","answer":"B"},{"id":793,"type":"single","cat":"基础概念","stem":"汽化器式活塞发动机在（）容易出现汽化器回火现象。","A":"热发动起动时","B":"油门收的过猛","C":"寒冷天气第一次起动时","D":"以上均不正确","answer":"C"},{"id":794,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机由爬升转为平飞时（）。","A":"到达预定高度时，开始改平飞","B":"上升至预定高度前10-20米时，开始改平飞","C":"超过预定高度10-20米时，开始改平飞","D":"以上均不正确","answer":"B"},{"id":795,"type":"single","cat":"操纵与飞行技术","stem":"小型无人驾驶航空器最常用的起降装置就是起落架，根据起落架的不同安装方式可分为前三点、后三点和（）起落架。","A":"平行式","B":"滑橇式","C":"交叉式","D":"车轮式","answer":"C"},{"id":796,"type":"single","cat":"操纵与飞行技术","stem":"垂直起降固定翼无人机中翼段连接（）和外翼段，悬停动力臂安装在中翼段上，无人机的悬停动力系统全部集中在悬停动力臂上，为无人机提供起降动力。","A":"外翼段","B":"尾翼","C":"机身","D":"悬停动力臂","answer":"C"},{"id":797,"type":"single","cat":"设备与维护","stem":"同样容量不同类型的电池，最轻的是（）。","A":"铅酸蓄电池","B":"聚合物锂电池","C":"碱性电池","D":"以上均不正确","answer":"B"},{"id":798,"type":"single","cat":"基础概念","stem":"拉距离试验是（）应该注意的问题。","A":"安装定位装置时","B":"测试动力系统时","C":"使用遥控器时","D":"测试地面站时","answer":"C"},{"id":799,"type":"single","cat":"基础概念","stem":"目前世界上无人机的频谱使用主要集中在（）。","A":"UHF、L和C","B":"VHF","C":"任意","D":"以上均不正确","answer":"A"},{"id":800,"type":"single","cat":"设备与维护","stem":"下列关于充电环境注意事项描述错误的是（）。","A":"避免处于阳光暴晒环境下充电","B":"应在车辆、室内等密闭空间内充电","C":"避免处于降雨条件下充电","D":"尽量处于通风常温环境下充电","answer":"B"},{"id":801,"type":"single","cat":"基础概念","stem":"（）是指军事重地、核电站和行政中心等关乎国家安全的区域及周边。","A":"安保净空区","B":"安全净空区","C":"重点地区","D":"重要地区","answer":"C"},{"id":802,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆的过程不包括（）。","A":"平飘接地和着陆滑跑","B":"下降和定高","C":"下滑和拉平","D":"以上均不正确","answer":"B"},{"id":803,"type":"single","cat":"基础概念","stem":"雷达的主要功能，不包括的是（）。","A":"避障","B":"定高","C":"提前预判障碍物","D":"照明","answer":"D"},{"id":804,"type":"single","cat":"基础概念","stem":"无人机具体执行的飞行任务主要包括到达时间和进入目标方向等，需满足如下要求：（）。","A":"航迹距离约束，固定的目标进入方向","B":"执行任务时间，进入目标位置","C":"返航时间，接近目标的飞行姿态","D":"以上均不正确","answer":"A"},{"id":805,"type":"single","cat":"操纵与飞行技术","stem":"影响直升机起飞载重量的主要因素不包括（）。","A":"机场标高，空气湿度","B":"风速和风向","C":"上反效应场地面积和周围障碍物","D":"以上均不正确","answer":"C"},{"id":806,"type":"single","cat":"基础概念","stem":"（）的内容包括出发地点、途径地点、目的地点的位置信息、飞行高度速度和需要到达的时间段。","A":"航线规划","B":"航迹规划","C":"任务规划","D":"以上均不正确","answer":"A"},{"id":807,"type":"single","cat":"基础概念","stem":"多旋翼飞行器通常至少装有（）及以上旋翼，利用空气动力克服自身重量，可自主或遥控飞行，能携带各种任务设备，并可多次回收使用。","A":"一个","B":"两个","C":"三个","D":"四个","answer":"C"},{"id":808,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，收油门过晚、过细，速度减小慢，使拉平时的速度大，飞机下沉慢（）。","A":"容易拉平高或者进入平飘时仰角较小","B":"对飞机无影响","C":"容易拉平低或者进入平飘时仰角较大","D":"以上均不正确","answer":"A"},{"id":809,"type":"single","cat":"操纵与飞行技术","stem":"无人机飞行员操纵升降舵时，飞行器将绕（）。","A":"横轴运动","B":"纵轴运动","C":"立轴运动","D":"以上均不正确","answer":"A"},{"id":810,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，无人机采用的导航技术中，多普勒导航具有（）优点","A":"自主性好","B":"反应快","C":"抗干扰性强","D":"测速精度高","answer":"ABCD"},{"id":811,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，多旋翼无人机特殊环境适应性能类检测项目包括（）。","A":"低温环境飞行性能","B":"高低温存储试验","C":"跌落试验","D":"高海拔环境飞行性能","answer":"AD"},{"id":812,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中：国家电网有限公司直升机、无人机、人工协同巡检模式试点工作收集现场应用数据，分析直升机巡检、不同类型无人机巡检、人工巡检的影响因子，采用层次分析法确定权重系数，从（）等方面构造效益评价指标。","A":"质量","B":"安全","C":"效率","D":"经济性","answer":"ABCD"},{"id":813,"type":"multi","cat":"基础概念","stem":"飞机飞行时的稳定性可分为（）。","A":"纵向稳定性","B":"航向稳定性","C":"侧向稳定性","D":"横向稳定性","answer":"ABD"},{"id":814,"type":"multi","cat":"操纵与飞行技术","stem":"无人机第四转弯点的位置是由第三转弯的（）决定的。","A":"高度","B":"角度","C":"时机","D":"风速","answer":"BC"},{"id":815,"type":"multi","cat":"领航与任务规划","stem":"随着未来体系化警务实战不断推进，以及无人机装备技术的快速发展，任务规划系统和任务规划技术需要主动适应警务实战需求和任务载荷使用特点其未来主要发展趋势有以下几点（）。","A":"多元、实时的作战信息保障","B":"通用化的软件架构","C":"智能自主规划","D":"联合协同规划","answer":"ABCD"},{"id":816,"type":"single","cat":"设备与维护","stem":"四旋翼桨叶安装必须区分正反桨、相邻位置桨叶相反、对角之间转向相反和（）。","A":"桨叶安装牢固","B":"按顺时针安装","C":"按逆时针安装","D":"安装螺丝加垫圈","answer":"A"},{"id":817,"type":"single","cat":"操纵与飞行技术","stem":"悬停状态的四轴飞行器如何实现向右移动（）。","A":"纵轴右侧的螺旋桨减速，纵轴左侧的螺旋桨加速","B":"纵轴右侧的螺旋桨加速，纵轴左侧的螺旋桨减速","C":"横轴前侧的螺旋桨加速，横轴后侧的螺旋桨减速","D":"以上均不正确","answer":"A"},{"id":818,"type":"single","cat":"航空气象","stem":"易造成飞机积冰的原因是（）。","A":"过冷雨滴","B":"雨滴","C":"雾气","D":"雾滴","answer":"A"},{"id":819,"type":"single","cat":"基础概念","stem":"在M600飞行器当中，负责显示飞行器状态的部分是（）。","A":"遥控器","B":"DJIGO","C":"遥控器显示面板","D":"手机","answer":"B"},{"id":820,"type":"single","cat":"电力巡检","stem":"若飞行航线、悬停点与杆塔坐标偏差较大，应及时修（）。","A":"航线库","B":"飞行航向","C":"飞行航迹","D":"飞行航线","answer":"A"},{"id":821,"type":"single","cat":"电力巡检","stem":"无人机技术规程适用于采用中、小型无人直升机在（）及以上电压等级架空输电线路所进行的巡检作业，35kV架空输电线路参照执行。","A":"500kV","B":"330kV","C":"220kV","D":"110kV（66kV）","answer":"D"},{"id":822,"type":"single","cat":"领航与任务规划","stem":"任务规划的主要目标是依据地形信息和执行任务环境条件信息，综合考虑无人机的性能、到达时间、耗能、威胁以及飞行区域等约束条件，为无人机规划出一条或多条自（）的（），保证无人机高效、圆满地完成飞行任务，并安全返回基地。","A":"起点到终点，最短路径","B":"起飞点到着陆点，最佳路径","C":"出发点到目标点，最优或次优航迹","D":"以上均不正确","answer":"C"},{"id":823,"type":"single","cat":"飞行原理","stem":"组装固定翼无人机后进行试飞，如果机翼和尾翼扭曲变形，则飞行时左右机翼迎角不同，会导致无人机（）。","A":"无法起飞","B":"无法转向","C":"自行俯仰","D":"偏航或横滚","answer":"D"},{"id":824,"type":"single","cat":"电力巡检","stem":"降落后，应进行（）及零部件检查，并做好无人直升机巡检系统使用记录。","A":"外观","B":"电量","C":"螺旋桨","D":"地面站","answer":"A"},{"id":825,"type":"single","cat":"基础概念","stem":"机翼空气动力受力最大的是（）。","A":"机翼上表面压力","B":"机翼下表面压力","C":"机翼上表面负压","D":"以上均不正确","answer":"C"},{"id":826,"type":"single","cat":"基础概念","stem":"关于对飞行器摇杆模式进行更改，下面描述正确的是（）。","A":"将遥控器开启，利用DJIGO的遥控器设置功能进行改手，必须接通飞行器电源","B":"将遥控器开启，利用DJIGO的遥控器设置功能进行改手，无需接通飞行器电源","C":"将遥控器开启，利用Assistant的遥控器设置功能进行改手，无需接通飞行器电源","D":"将遥控器开启，利用Assistant的遥控器设置功能进行改手，必须接通飞行器电源","answer":"B"},{"id":827,"type":"single","cat":"设备与维护","stem":"无人机飞行控制系统速率陀螺是感知飞行器平台的传感器（）。","A":"姿态角度","B":"航向角","C":"角速度","D":"以上均不正确","answer":"C"},{"id":828,"type":"single","cat":"领航与任务规划","stem":"固定翼无人机航电系统由飞控计算机、导航传感器、（）、舵机/伺服机构组成，完成飞机控制系统的需要。","A":"机翼","B":"螺旋桨","C":"数据链机载终端","D":"地面站","answer":"C"},{"id":829,"type":"single","cat":"操纵与飞行技术","stem":"为了测算多旋翼无人机姿态偏斜角度，需要借助陀螺仪，以下有关陀螺仪表述正确的是（）。","A":"陀螺仪可以改变多旋翼无人机姿态","B":"陀螺仪可以测量多旋翼无人机加速度变化","C":"陀螺仪可以稳定多旋翼无人机姿态和角速度测算","D":"陀螺仪可以测定空气的密度","answer":"C"},{"id":830,"type":"single","cat":"设备与维护","stem":"现有一块聚合物锂电池可能会长时间不使用，充放电至电量多少，电压多少储存合适？（）","A":"80%；4.7V","B":"40%至50%；3.8V","C":"20%；3.2V","D":"以上均不正确","answer":"B"},{"id":831,"type":"single","cat":"操纵与飞行技术","stem":"无人机驾驶员操纵无人机复飞时，油门状态描述正确的是（）。","A":"保持小油门","B":"逐渐收至小车状态","C":"逐渐推至大车状态","D":"以上均不正确","answer":"C"},{"id":832,"type":"single","cat":"基础概念","stem":"无人机飞行人员在执行飞行任务时，应当随身携带（）。","A":"飞行记录本","B":"飞机适航证书","C":"驾驶员执照或合格证","D":"都不需要","answer":"C"},{"id":833,"type":"single","cat":"基础概念","stem":"固定翼无人机结构组成不包括（）。","A":"机身","B":"机翼","C":"尾翼","D":"驾驶室","answer":"D"},{"id":834,"type":"single","cat":"设备与维护","stem":"地面站，遥控器，飞机的通电顺序是（）。","A":"遥控器，飞机电，地面站","B":"飞机电，地面站，遥控器","C":"地面站，遥控器，飞机电","D":"以上均不正确","answer":"C"},{"id":835,"type":"single","cat":"基础概念","stem":"飞行前检查，下列哪项不是必须检查的项目（）。","A":"周围人员是否与无人机保持安全距离","B":"药箱是否有农药沉淀","C":"遥控器表面是否有污渍","D":"套筒是否旋紧或卡扣是否卡紧","answer":"C"},{"id":836,"type":"multi","cat":"基础概念","stem":"所谓运用中的电气设备系指（）的电气设备。","A":"全部带有电压","B":"一部分带有电压","C":"一经操作即带有电压","D":"在修试所进行检修","answer":"ABC"},{"id":837,"type":"multi","cat":"电力巡检","stem":"根据所用无人机巡检系统的不同，分为（）。","A":"大型无人直升机巡检作业","B":"中型无人直升机巡检作业","C":"小型无人直升机巡检作业","D":"固定翼无人机巡检作业","answer":"BCD"},{"id":838,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，通信系统完成从控制站到无人机平台间的（）及其他数据信息的传输。","A":"控制信息","B":"任务载荷信息","C":"设备信息","D":"无人机状态信息","answer":"ABD"},{"id":839,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，无人机平台需具备（）。","A":"足够的载重能力","B":"外形设计合理","C":"控制计算能力","D":"能完成特定的任务","answer":"ABD"},{"id":840,"type":"multi","cat":"电力巡检","stem":"无人直升机巡检系统主要部件（如电机、（）等）更换或升级后，应进行检测，确保满足技术要求。","A":"飞控系统","B":"通讯链路","C":"任务设备","D":"操作系统","answer":"ABCD"},{"id":841,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，翻修是指通过对航空器或者航空器部件进行（）或者换件、重新组装和测试来恢复航空器或者航空器部件的使用寿命或者适航性状态。","A":"分解","B":"清洗","C":"检查","D":"必要的修理","answer":"ABCD"},{"id":842,"type":"multi","cat":"飞行原理","stem":"无人直升机的基本结构一般包括：机身、主旋翼、尾桨、（）、（）、电动机或发动机和（）。","A":"操作系统","B":"传动系统","C":"遥控器","D":"起落架","answer":"ABD"},{"id":843,"type":"multi","cat":"设备与维护","stem":"地面站系统包括（）等硬件设备及地面测控车辆","A":"飞行控制软件","B":"飞行数据传输系统","C":"图像接收器","D":"飞行操控器","answer":"AD"},{"id":844,"type":"single","cat":"设备与维护","stem":"X型四旋翼飞行器，其2号与3号电机搭配的螺旋桨分别是（）。","A":"CWCW","B":"CWCCW","C":"CCWCW","D":"CCWCCW","answer":"B"},{"id":845,"type":"single","cat":"设备与维护","stem":"小型固定翼无人驾驶航空器机体部分主要包括：机身、（）、尾翼。","A":"发动机","B":"云端","C":"遥控器","D":"机翼","answer":"D"},{"id":846,"type":"single","cat":"设备与维护","stem":"多轴飞行器的飞控指的是（）。","A":"机载导航飞控系统","B":"机载遥控接收机","C":"机载任务系统","D":"以上均不正确","answer":"A"},{"id":847,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机进入四转弯时（）。","A":"如飞机接近跑道延长线较快，而转弯剩余角减小较慢时，表明进入早，应立即协调地减小坡度和转弯角速度","B":"如飞机接近跑道延长线较快，而转弯剩余角减小较慢时，表明进入晚，应立即协调地增大坡度和转弯角速度","C":"如飞机接近跑道延长线较快，而转弯剩余角减小较慢时，表明进入晚，应立即协调地减小坡度和转弯角速度","D":"以上均不正确","answer":"B"},{"id":848,"type":"single","cat":"航空气象","stem":"遥控无人机着陆时，对用侧滑的方法修正侧风影响的正确描述是（）。","A":"判明偏流的方向及影响大小，适量向侧风反方向压杆形成坡度，并反扭舵抵制飞机转弯","B":"判明偏流的方向及影响大小，适量向侧风方向压杆形成坡度，并反扭舵抵制飞机转弯","C":"判明偏流的方向及影响大小，适量向侧风方向压杆形成坡度，并同向扭舵抵制飞机转弯","D":"以上均不正确","answer":"B"},{"id":849,"type":"single","cat":"基础概念","stem":"视距内运行指无人机驾驶员或无人机观测员与无人机保持直接目视视觉接触的操作方式，航空器处于驾驶员或观测员目视视距内半径（）米，相对高度低于120米的区域内。","A":"300","B":"500","C":"700","D":"1000","answer":"B"},{"id":850,"type":"single","cat":"设备与维护","stem":"两块电池6S、5000mah的电池并联，用2C充电，充电的功率是多少？（）","A":"202W","B":"504w","C":"404W","D":"以上均不正确","answer":"B"},{"id":851,"type":"single","cat":"设备与维护","stem":"（）通过调节四个电机的转速使四个旋翼间出现特定的转速差，从而实现飞行器的各种动作。","A":"定位系统","B":"动力系统","C":"电力系统","D":"飞控系统","answer":"D"},{"id":852,"type":"single","cat":"设备与维护","stem":"无刷电机的维护，以下不包括的是（）。","A":"长时间未使用，应定期通电","B":"避免进水","C":"轴承损坏及时更换","D":"注意避免轴承生锈","answer":"A"},{"id":853,"type":"single","cat":"基础概念","stem":"地面保障分系统由地面保障设备和（）组成。","A":"地面接收单元","B":"地面显控单元","C":"数据接收链路","D":"备用设备","answer":"B"},{"id":854,"type":"single","cat":"领航与任务规划","stem":"无人机系统中的GPS模块为飞控提供了哪些信息？（）","A":"传感器、姿态与加速度","B":"位置、高度与地速","C":"经纬度、高度与空速","D":"以上均不正确","answer":"B"},{"id":855,"type":"single","cat":"飞行原理","stem":"无人机定速遥控飞行时放下襟翼，驾驶员需（）。","A":"增加油门以保持空速","B":"减小油门以保持空速","C":"针对此情况，无需做相关动作","D":"以上均不正确","answer":"A"},{"id":856,"type":"single","cat":"基础概念","stem":"固定翼无人机的升降舵负责完成无人机的（）动作。","A":"横滚","B":"俯仰","C":"偏航","D":"以上均不正确","answer":"B"},{"id":857,"type":"single","cat":"基础概念","stem":"多轴旋翼飞行器通过改变（）控制飞行轨迹。","A":"总距杆","B":"尾桨","C":"转速","D":"以上均不正确","answer":"C"},{"id":858,"type":"single","cat":"操纵与飞行技术","stem":"多轴飞行器的操纵不包括（）。","A":"俯仰操纵","B":"航向操纵","C":"周期变距","D":"以上均不正确","answer":"C"},{"id":859,"type":"single","cat":"基础概念","stem":"由于加载的电子地图与实际操作时的地理位置信息有偏差，需要在使用前对地图进行（）。","A":"更新","B":"校准","C":"标注","D":"以上均不正确","answer":"B"},{"id":860,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机在预定高度由平飞转为下降时（）。","A":"注视地平仪，稍拉杆，收油门","B":"注视地平仪，稍拉杆，推油门","C":"注视地平仪，稍顶杆，收油门","D":"以上均不正确","answer":"C"},{"id":861,"type":"single","cat":"领航与任务规划","stem":"（）应具备的功能包括：标准飞行轨道生成功能，常规的飞行航线生成、管理功能。","A":"航线规划","B":"航迹规划","C":"任务规划","D":"以上均不正确","answer":"A"},{"id":862,"type":"single","cat":"操纵与飞行技术","stem":"共轴式直升机的纵横向操纵多是何处得以实现的（）。","A":"下旋翼自动倾斜器的不动环","B":"下旋翼自动倾斜器的可动环","C":"上旋翼自动倾斜器的可动环","D":"以上均不正确","answer":"A"},{"id":863,"type":"single","cat":"基础概念","stem":"在高海拔地区，多轴飞行器出现较难离地时，最有效的应对措施是（）。","A":"减重","B":"更换大桨","C":"更换大容量电池","D":"以上均不正确","answer":"A"},{"id":864,"type":"single","cat":"基础概念","stem":"民用无人机调整中的基本感度是（）。","A":"飞控PID调节中的比例项P的系数","B":"飞控PID调节中的I积分系数","C":"飞控PID调节中的D微分系数","D":"以上均不正确","answer":"A"},{"id":865,"type":"single","cat":"设备与维护","stem":"遥控器菜单中SUBTRIM代表什么意思？","A":"中立微调","B":"失控保护","C":"通道反向","D":"以上均不正确","answer":"A"},{"id":866,"type":"single","cat":"设备与维护","stem":"无人机装配报告控制系统复检中对飞行控制系统（自驾仪）信号线的检查包括电子调速器（电调）信号线、（）、接收机信号线、无线数据传输（无线数传）系统信号线、电流计信号线等。","A":"电机相线","B":"GPS天线","C":"全球导航卫星系统（GNSS）信号线","D":"电池平衡充排线","answer":"C"},{"id":867,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，应充分考虑无人机巡检系统在飞行过程中出现（）等故障的可能性，合理设置安全策略。","A":"偏离航线","B":"导航卫星颗数无法定位","C":"通讯链路中断","D":"动力失效","answer":"ABCD"},{"id":868,"type":"multi","cat":"操纵与飞行技术","stem":"无人机控制站主要是由（）等组成，可完成对无人机机载任务载荷等的操纵控制。","A":"飞行操纵","B":"任务载荷控制","C":"数据链路控制","D":"通信指挥","answer":"ABCD"},{"id":869,"type":"multi","cat":"电力巡检","stem":"无人直升机进行输电线路巡检的主要巡检内容中对基础可见光检测内容为（）。","A":"塌方","B":"护坡受损","C":"严重污秽","D":"回填土沉降","answer":"ABD"},{"id":870,"type":"multi","cat":"电力巡检","stem":"程控手是利用地面控制站以（）控制无人机巡检系统的作业人员。","A":"增稳","B":"手动","C":"监控","D":"全自主模式","answer":"AD"},{"id":871,"type":"single","cat":"法规与空域","stem":"我国民用无人驾驶航空器实名登记的主管部门是（）。","A":"国家市场监督管理总局","B":"国务院公安部门","C":"民用航空管理部门","D":"国家空中交通管理领导机构","answer":"C"},{"id":872,"type":"single","cat":"基础概念","stem":"微型无人驾驶航空器是指（）。","A":"空机重量小于0.25千克，最大飞行真高不超过50米，最大平飞速度不超过50千米/小时","B":"空机重量小于4千克，最大飞行真高不超过120米","C":"最大起飞重量不超过25千克","D":"最大起飞重量不超过150千克","answer":"A"},{"id":873,"type":"single","cat":"法规与空域","stem":"在适飞空域内飞行，下列哪种类型无人机无需提出飞行活动申请？（）","A":"小型、中型无人机","B":"微型、轻型无人机","C":"全部类型无人机","D":"中型、大型无人机","answer":"B"},{"id":874,"type":"single","cat":"法规与空域","stem":"无人机在管制空域飞行，应当（）。","A":"提前向空中交通管理机构提出飞行活动申请","B":"只需完成实名登记即可飞行","C":"起飞后向当地派出所报告","D":"只要避开民航客机即可飞行","answer":"A"},{"id":875,"type":"single","cat":"法规与空域","stem":"关于无人机飞行高度，轻型无人驾驶航空器在适飞空域内的最大真高为（）。","A":"120米","B":"150米","C":"300米","D":"500米","answer":"A"},{"id":876,"type":"single","cat":"法规与空域","stem":"操控轻型民用无人驾驶航空器在适飞空域内飞行，下列做法正确的是（）。","A":"无需取得操控员执照，但需熟悉安全操控要求","B":"必须取得民用无人机驾驶员执照","C":"必须持有机长执照并完成签注","D":"只需购买保险，无须任何资质","answer":"A"},{"id":877,"type":"single","cat":"法规与空域","stem":"民用无人驾驶航空器操控员执照由哪个机构颁发？（）","A":"中国民用航空局","B":"公安部","C":"应急管理部","D":"工业和信息化部","answer":"A"},{"id":878,"type":"single","cat":"法规与空域","stem":"国内民航局无人机执照中，多旋翼视距内驾驶员理论考试合格分数线为（）。","A":"70分","B":"80分","C":"90分","D":"60分","answer":"A"},{"id":879,"type":"single","cat":"基础概念","stem":"视距内驾驶员（VLOS）飞行的基本限制是（）。","A":"飞行半径500米以内、真高120米以内，且全程保持视距内","B":"飞行半径5千米以内","C":"真高300米以内","D":"只要天气良好可任意飞行","answer":"A"},{"id":880,"type":"single","cat":"基础概念","stem":"无人机驾驶员饮酒后是否可以操控无人机飞行？（）","A":"可以，只要飞行技术熟练","B":"可以，但只能白天飞行","C":"不可以，酒后操控存在重大安全风险","D":"司法机关统一规定，视酒量而定","answer":"C"},{"id":881,"type":"single","cat":"基础概念","stem":"无人机失联后，下列哪种行为最合理？（）","A":"原地等待，保持遥控器信号尝试重新连接，并观察飞行轨迹","B":"立即关闭遥控器","C":"不停地按遥控器油门摇杆","D":"立即驾车穿梭去寻找，不顾自身安全","answer":"A"},{"id":882,"type":"single","cat":"基础概念","stem":"多旋翼无人机实现向左飞行，通常需要（）。","A":"机体向左倾斜，升力方向向左偏转提供水平分量","B":"只改变右侧电机转速","C":"改变桨叶总距","D":"降低全部电机转速","answer":"A"},{"id":883,"type":"single","cat":"基础概念","stem":"多旋翼无人机的偏航（机头转向）主要依靠（）实现。","A":"旋翼旋转产生反扭矩的差动变化","B":"尾桨推力","C":"方向舵偏转","D":"重心移动","answer":"A"},{"id":884,"type":"single","cat":"领航与任务规划","stem":"无人机飞行过程中，若GPS信号丢失，多旋翼无人机通常会（）。","A":"自动进入姿态模式，可能发生漂移","B":"完全不受影响","C":"自动增加飞行速度","D":"立即自毁","answer":"A"},{"id":885,"type":"single","cat":"设备与维护","stem":"无人机气压计的主要作用是（）。","A":"测量相对高度","B":"测量地面速度","C":"测量水平位置","D":"测量姿态角","answer":"A"},{"id":886,"type":"single","cat":"基础概念","stem":"无人机磁罗盘（指南针）受干扰后，可能导致（）。","A":"航向数据异常，无人机无法准确按预定航向飞行","B":"电池电量消耗变慢","C":"图传信号增强","D":"桨叶转速提高","answer":"A"},{"id":887,"type":"single","cat":"设备与维护","stem":"电动无人机动力电池常用类型是（）。","A":"锂聚合物电池","B":"铅酸蓄电池","C":"镍镉电池","D":"锌锰干电池","answer":"A"},{"id":888,"type":"single","cat":"设备与维护","stem":"锂聚合物电池的充电安全要求中，下列说法正确的是（）。","A":"必须使用专用平衡充电器，充电时人员在场看护","B":"可随意使用大功率充电器快充","C":"电池鼓包后仍可继续使用","D":"可在无人看管时通宵充电","answer":"A"},{"id":889,"type":"single","cat":"设备与维护","stem":"一块5000mAh、20C的锂电池，其理论最大持续放电电流为（）。","A":"100A","B":"50A","C":"200A","D":"25A","answer":"A"},{"id":890,"type":"single","cat":"操纵与飞行技术","stem":"无人机螺旋桨安装错误（如正反桨装反），起飞时会（）。","A":"拉力方向异常，机身剧烈抖动甚至无法稳定起飞","B":"飞行速度大幅提升","C":"对飞行无影响","D":"电池发热但飞行正常","answer":"A"},{"id":891,"type":"single","cat":"设备与维护","stem":"多旋翼无人机起飞前校准IMU和磁罗盘的主要目的是（）。","A":"保证飞控姿态解算和航向数据准确","B":"提高图传清晰度","C":"延长电池续航","D":"增大遥控距离","answer":"A"},{"id":892,"type":"single","cat":"基础概念","stem":"在标准大气条件下，海平面气温为（）。","A":"15℃","B":"20℃","C":"25℃","D":"0℃","answer":"A"},{"id":893,"type":"single","cat":"航空气象","stem":"对流层中，气温随高度增加而（）。","A":"降低","B":"升高","C":"不变","D":"先升高后降低","answer":"A"},{"id":894,"type":"single","cat":"基础概念","stem":"气温升高时，无人机的飞行性能将（）。","A":"下降，空气密度减小使升力降低、发动机功率降低","B":"提升，空气变稀薄阻力变小","C":"不受影响","D":"只影响航程不影响升力","answer":"A"},{"id":895,"type":"single","cat":"操纵与飞行技术","stem":"某多旋翼无人机从真高120米处以5米/秒的速度匀速下降至20米处，所需时间约为（）。","A":"20秒","B":"24秒","C":"15秒","D":"30秒","answer":"A"},{"id":896,"type":"single","cat":"基础概念","stem":"无人机在大风天气飞行时，下列做法正确的是（）。","A":"顺风航行时注意地速增大导致返航电量不足","B":"逆风更适合长航时飞行","C":"大风对多旋翼没有影响","D":"风越大越省电","answer":"A"},{"id":897,"type":"single","cat":"航空气象","stem":"遇有低能见度天气，下列哪种操作符合安全要求？（）","A":"取消飞行任务，待能见度改善后再执行","B":"降低高度强行目视飞行","C":"依赖图传信号冒险飞行","D":"申请更高高度飞行","answer":"A"},{"id":898,"type":"single","cat":"飞行原理","stem":"无人机机翼产生升力的根本原因是（）。","A":"气流流过机翼上下表面产生压力差","B":"发动机推力直接托举","C":"螺旋桨滑流吹起机翼","D":"机身浮力作用","answer":"A"},{"id":899,"type":"single","cat":"飞行原理","stem":"当机翼迎角超过临界迎角时，飞机将出现（）。","A":"失速，升力急剧下降","B":"升力线性增大","C":"阻力迅速减小","D":"速度自动增加","answer":"A"},{"id":900,"type":"single","cat":"飞行原理","stem":"固定翼无人机在平飞时，升力与重力、推力与阻力的关系是（）。","A":"升力等于重力，推力等于阻力","B":"升力大于重力，推力大于阻力","C":"升力等于重力，推力大于阻力","D":"升力小于重力，推力等于阻力","answer":"A"},{"id":901,"type":"single","cat":"设备与维护","stem":"飞机重心位置过于靠前会导致（）。","A":"飞机配平阻力增大，操纵性变差","B":"飞机更容易抬头","C":"飞机航向不稳定","D":"飞机失速速度降低","answer":"A"},{"id":902,"type":"single","cat":"基础概念","stem":"地面效应会使固定翼无人机在低空飞行时（）。","A":"诱导阻力减小，升力增大，感觉漂浮","B":"升力减小，产生下沉","C":"阻力急剧增大","D":"发动机功率自动升高","answer":"A"},{"id":903,"type":"single","cat":"设备与维护","stem":"无人机飞行时发生机翼结冰，主要危害是（）。","A":"翼型改变、升力下降、阻力增大，严重时失速","B":"机体重量减轻","C":"燃油消耗减少","D":"对飞行安全无影响","answer":"A"},{"id":904,"type":"single","cat":"基础概念","stem":"任务载荷为可见光相机时，影响航拍照片清晰度的主要因素是（）。","A":"拍摄时的快门速度是否足以凝固飞机振动与运动","B":"遥控器天线朝向","C":"起落架形式","D":"桨叶颜色","answer":"A"},{"id":905,"type":"single","cat":"航空气象","stem":"无人机云台的主要功能是（）。","A":"隔离机体振动与姿态变化，保持相机稳定","B":"增大无人机推力","C":"修改飞行控制参数","D":"增加续航时间","answer":"A"},{"id":906,"type":"single","cat":"基础概念","stem":"植保无人机作业中，造成药液漂移的因素不包括（）。","A":"药箱容量","B":"风力大小","C":"飞行高度","D":"雾滴粒径","answer":"A"},{"id":907,"type":"single","cat":"领航与任务规划","stem":"无人机测绘作业中，航线设计应重点考虑（）。","A":"航向与旁向重叠率、地面分辨率及地形起伏","B":"遥控器握持姿势","C":"桨叶数量","D":"电池品牌","answer":"A"},{"id":908,"type":"single","cat":"电力巡检","stem":"无人机在电力巡检中贴近铁塔飞行时，应特别注意（）。","A":"强电磁环境可能导致磁罗盘和飞控异常，保持安全距离","B":"图传信号会增强","C":"机翼产生额外升力","D":"没有任何风险","answer":"A"},{"id":909,"type":"single","cat":"领航与任务规划","stem":"无人机紧急返航前，应当重点确认（）。","A":"返航点已刷新且卫星定位正常，飞行高度高于航线障碍物","B":"遥控器电池满电即可","C":"相机电量","D":"云台角度","answer":"A"},{"id":910,"type":"single","cat":"基础概念","stem":"无人机在人群上方飞行时，下列做法正确的是（）。","A":"禁止在人群上方飞行，防止失控坠落伤人","B":"可以飞行，只要高度超过50米","C":"可以飞行，只要速度快","D":"可以飞行，只要操作者技术熟练","answer":"A"},{"id":911,"type":"single","cat":"基础概念","stem":"无人机降落后，正确的断电顺序是（）。","A":"先关闭遥控器电源，再断开飞行器电源","B":"先断开飞行器电源，再关闭遥控器电源","C":"两者不分先后","D":"长按遥控器油门即可","answer":"B"},{"id":912,"type":"single","cat":"设备与维护","stem":"无人机机臂折叠机构的主要作用是（）。","A":"便于运输携带并减小收纳体积","B":"延长飞行时间","C":"增大摄像头视角","D":"提高飞行速度","answer":"A"},{"id":913,"type":"single","cat":"设备与维护","stem":"无刷电机相比有刷电机的优点是（）。","A":"效率高、寿命长、维护少","B":"启动扭矩更小","C":"需要定期更换碳刷","D":"只能用于固定翼","answer":"A"},{"id":914,"type":"single","cat":"基础概念","stem":"无人机电子调速器（ESC）的作用是（）。","A":"将飞控信号转换为电机转速控制","B":"为遥控器充电","C":"存储拍摄照片","D":"放大GPS信号","answer":"A"},{"id":915,"type":"single","cat":"设备与维护","stem":"无人机图传系统的作用是（）。","A":"将机载相机画面实时传输回地面端","B":"传输遥控指令","C":"传输电池电量","D":"控制螺旋桨转速","answer":"A"},{"id":916,"type":"single","cat":"操纵与飞行技术","stem":"无人机遥控器摇杆默认模式中，美国手（Mode2）的油门摇杆位于（）。","A":"左侧摇杆上下","B":"右侧摇杆上下","C":"左侧摇杆左右","D":"右侧摇杆左右","answer":"A"},{"id":917,"type":"single","cat":"领航与任务规划","stem":"无人机上的GPS模块主要提供（）。","A":"经纬度与高度位置信息","B":"姿态角信息","C":"电机转速","D":"云台角度","answer":"A"},{"id":918,"type":"single","cat":"基础概念","stem":"关于无人机飞行前检查，下列说法错误的是（）。","A":"可不检查螺旋桨是否裂纹","B":"应检查电池电量与电压","C":"应检查固定螺丝与机臂","D":"应确认遥控器电量","answer":"A"},{"id":919,"type":"single","cat":"基础概念","stem":"无人机在夜间飞行时，除需遵守一般规定外，还应（）。","A":"开启导航灯并确保夜航能力，必要时报备","B":"关闭所有灯光以免暴露","C":"必须摘除云台","D":"禁止使用任何传感器","answer":"A"},{"id":920,"type":"single","cat":"基础概念","stem":"无人机失控保护（Failsafe）设置中，当遥控信号丢失时最安全的默认动作是（）。","A":"自动返航或悬停，并按设定策略处理","B":"继续直线高速飞行","C":"立即解锁电机","D":"随机转向","answer":"A"},{"id":921,"type":"single","cat":"设备与维护","stem":"多旋翼无人机飞行中若一个电机停转，通常会造成（）。","A":"机身剧烈偏航翻转，难以继续安全飞行","B":"剩余电机功率自动增大一倍，飞行不受影响","C":"无人机自动降落","D":"只影响续航不影响姿态","answer":"A"},{"id":922,"type":"single","cat":"设备与维护","stem":"选购无人机桨叶时，同一架多旋翼应使用（）。","A":"同一规格、动平衡良好的配套桨叶","B":"任意品牌任意尺寸桨叶","C":"新旧桨叶混合使用","D":"尽可能大的桨叶","answer":"A"},{"id":923,"type":"single","cat":"航空气象","stem":"无人机固定翼起飞时，逆风起飞的主要目的是（）。","A":"增大初始空速，缩短滑跑距离并提高升力","B":"缩短着陆滑跑距离","C":"减小发动机功率","D":"降低失速速度","answer":"A"},{"id":924,"type":"single","cat":"设备与维护","stem":"无人机降落后发现电池鼓包，正确的处理是（）。","A":"停止使用并妥善回收，不可继续充放电","B":"继续用完剩余电量","C":"用针扎破放气后继续使用","D":"冷藏后继续使用","answer":"A"},{"id":925,"type":"single","cat":"设备与维护","stem":"无人机飞控中的加速度计用于测量（）。","A":"三轴线加速度，辅助姿态解算","B":"磁场方向","C":"大气压力","D":"卫星信号强度","answer":"A"},{"id":926,"type":"single","cat":"设备与维护","stem":"无人机飞行时电机堵转的直接后果是（）。","A":"电流急剧增大，可能烧毁电调与电机","B":"电池电压升高","C":"图传信号增强","D":"无人机速度加快","answer":"A"},{"id":927,"type":"single","cat":"操纵与飞行技术","stem":"无人机起飞前进行试悬停（悬停检查）的主要目的是（）。","A":"确认姿态、动力和遥控响应正常","B":"延长电池寿命","C":"增加航拍照片数量","D":"检查云台防水性能","answer":"A"},{"id":928,"type":"single","cat":"法规与空域","stem":"无人机在机场净空保护区飞行属于（）。","A":"违法违规行为，可能危及民航飞行安全","B":"正常飞行动作","C":"只要不拍摄客机即可","D":"超视距飞手的合法练习项目","answer":"A"},{"id":929,"type":"single","cat":"设备与维护","stem":"无人机使用完毕后，对电池的正确保养方式是（）。","A":"若长期存放，将电池放电至存储电压（约3.8V/芯）并存放于阴凉处","B":"充满电长期存放","C":"放空电量长期存放","D":"随意放置于高温车内","answer":"A"},{"id":930,"type":"multi","cat":"基础概念","stem":"无人机起飞前必须完成的检查包括（）。","A":"检查桨叶、机臂、螺丝是否完好紧固","B":"检查电池电压、电量和充电状态","C":"检查遥控器、图传、飞控参数与返航点设置","D":"检查空域申请、天气和周边环境","answer":"ABCD"},{"id":931,"type":"multi","cat":"飞行原理","stem":"下列哪些因素会影响多旋翼无人机产生的升力？（）","A":"空气密度","B":"桨叶直径与螺距","C":"旋翼转速","D":"云台相机重量","answer":"ABC"},{"id":932,"type":"multi","cat":"基础概念","stem":"无人机系统通常由哪些部分组成？（）","A":"飞行器平台与动力系统","B":"飞控系统与导航系统","C":"链路系统（遥控、图传）","D":"地面站与任务载荷","answer":"ABCD"},{"id":933,"type":"multi","cat":"设备与维护","stem":"关于锂聚合物电池的使用，下列说法正确的有（）。","A":"不得过充、过放","B":"不得挤压、刺破或投入火中","C":"应使用专用平衡充电器充电","D":"充电时不得无人看管","answer":"ABCD"},{"id":934,"type":"multi","cat":"基础概念","stem":"无人机在以下哪些区域飞行属于高风险甚至违法违规行为？（）","A":"机场净空保护区","B":"军事管理区周边","C":"政府机关、核电站等敏感目标上空","D":"城市广场空旷区域","answer":"ABC"},{"id":935,"type":"multi","cat":"基础概念","stem":"无人机执行航拍任务时，下列做法正确的有（）。","A":"提前规划航线并设置返航点","B":"根据光照与风速调整拍摄参数","C":"注意避开障碍物、高压线和人群","D":"全程保持视距内或按超视距规定执飞","answer":"ABCD"},{"id":936,"type":"multi","cat":"基础概念","stem":"无人机在空中出现漂移现象，可能的原因有（）。","A":"GPS信号差或丢失","B":"磁罗盘受到干扰","C":"飞控未校准或振动过大","D":"风力过大","answer":"ABCD"},{"id":937,"type":"multi","cat":"操纵与飞行技术","stem":"固定翼无人机着陆时，影响着陆距离的因素有（）。","A":"着陆重量","B":"逆风/顺风分量","C":"跑道或场地表面状况","D":"襟翼使用情况","answer":"ABCD"},{"id":938,"type":"multi","cat":"航空气象","stem":"关于无人机云台与相机的使用，正确的有（）。","A":"起飞前应取下镜头保护罩","B":"应根据任务需要设置云台跟随或锁定模式","C":"航拍时应根据光线调整ISO、快门与光圈","D":"云台在飞行中可随意用手掰正","answer":"ABC"},{"id":939,"type":"multi","cat":"领航与任务规划","stem":"无人机发生紧急状况必须立即降落或返航的情形包括（）。","A":"电量不足且距返航点距离较远","B":"电机或电调温度异常、桨叶受损","C":"图传中断或无法判断飞行状态","D":"遭遇强降雨、大风或能见度骤降","answer":"ABCD"},{"id":940,"type":"single","cat":"法规与空域","stem":"根据2024年修订的《无人驾驶航空器飞行管理暂行条例》，微型无人机在适飞空域内飞行时，下列哪项操作符合规定？","A":"夜间飞行时未开启位置灯","B":"在机场净空保护区域上空100米飞行","C":"携带总重量0.3kg的摄影设备","D":"在城市人口密集区上空真高60米飞行","answer":"C"},{"id":941,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机在稳定悬停时，若出现顺时针旋转（俯视），最可能的原因是？","A":"1号电机（假设顺时针桨）转速偏高","B":"2号电机（逆时针桨）转速偏低","C":"3号电机（顺时针桨）转速偏低","D":"4号电机（逆时针桨）转速偏高","answer":"B"},{"id":942,"type":"single","cat":"航空气象","stem":"下列哪类气象条件最可能导致无人机GPS信号异常？","A":"雷暴云团中的强电场","B":"低云（云底高200米）","C":"相对湿度90%的潮湿空气","D":"风速12m/s的侧风","answer":"A"},{"id":943,"type":"single","cat":"法规与空域","stem":"视距内驾驶员执照（AOPA）持有人操作最大起飞重量12kg的无人机时，飞行高度限制为？","A":"真高100米","B":"真高120米","C":"真高500米","D":"真高不限（符合适飞空域）","answer":"B"},{"id":944,"type":"single","cat":"基础概念","stem":"无人机在600米高度飞行时，若遭遇突然断电，正确的应急措施是？","A":"立即切换手动模式进行迫降","B":"启用降落伞系统（若配备）","C":"尝试重启动力系统","D":"保持GPS模式等待重启","answer":"B"},{"id":945,"type":"multi","cat":"法规与空域","stem":"下列属于无人机适飞空域禁止行为的有？","A":"在军事管理区上空50米飞行","B":"携带易燃物品进行航空拍摄","C":"飞行中抛洒宣传物料","D":"夜间飞行时开启频闪灯","answer":"ABC"},{"id":946,"type":"multi","cat":"设备与维护","stem":"影响无人机电池续航的主要因素包括？","A":"环境温度（-10℃）","B":"飞行速度（15m/svs5m/s）","C":"起飞重量（10kgvs8kg）","D":"飞行高度（100米vs500米）","answer":"ABCD"},{"id":947,"type":"multi","cat":"基础概念","stem":"无人机起飞前检查应包括？","A":"螺旋桨安装方向（正/反桨匹配）","B":"飞控校准（磁罗盘、加速度计）","C":"电池剩余电量（≥80%）","D":"周边50米内无人员聚集","answer":"ABCD"},{"id":948,"type":"single","cat":"飞行原理","stem":"无人机飞行时放下襟翼，会使飞机（）。","A":"飞行速度增大","B":"飞行速度无明显变化","C":"飞行速度减小","D":"以上均不正确","answer":"C"},{"id":949,"type":"single","cat":"操纵与飞行技术","stem":"飞机的起飞和着陆，通常要求在（）条件下进行。","A":"逆风","B":"顺风","C":"上升气流","D":"下降气流","answer":"A"},{"id":950,"type":"single","cat":"设备与维护","stem":"为了解决大速度下空气压缩性的影响和噪音问题，可以对桨叶进行何种操作（）。","A":"把桨叶尖部作成后掠行","B":"采用矩形桨叶","C":"采用尖削桨叶","D":"以上均不正确","answer":"A"},{"id":951,"type":"single","cat":"航空气象","stem":"遥控无人机着陆时，关于顺风着陆描述正确的是（）。","A":"地速较大，平飘距离较长","B":"地速较小，平飘距离较短","C":"地速正常，平飘距离正常","D":"以上均不正确","answer":"A"},{"id":952,"type":"single","cat":"设备与维护","stem":"多旋翼无人机动力系统主要调试（）、动力电源、螺旋桨和调速系统等。","A":"机架","B":"动力电机","C":"定位系统","D":"避障系统","answer":"B"},{"id":953,"type":"single","cat":"基础概念","stem":"无人机驾驶员操作副翼时，飞行器将（）。","A":"横轴运动","B":"纵轴运动","C":"立轴运动","D":"以上均不正确","answer":"B"},{"id":954,"type":"single","cat":"操纵与飞行技术","stem":"无人机驾驶员操纵无人机着陆滑跑时，油门状态描述正确的是（）。","A":"飞机接地后，为保证安全一般将油门收为零","B":"飞机接地后，着陆滑跑一段距离再收油门","C":"飞机接地后，将油门保持大车状态，准备随时复飞","D":"以上均不正确","answer":"A"},{"id":955,"type":"single","cat":"基础概念","stem":"当多旋翼无人机无法保持当前高度飞行时，应该检查（）。","A":"空速计","B":"陀螺仪","C":"气压计","D":"加速度计","answer":"C"},{"id":956,"type":"single","cat":"设备与维护","stem":"执行测量任务的传感器部件，如高度差传感器，送出姿态信号的惯性陀螺平台，实际上也都是一些（）系统。","A":"开放","B":"闭合","C":"闭环","D":"环路","answer":"C"},{"id":957,"type":"single","cat":"飞行原理","stem":"直升机在前飞时桨叶在什么方位迎角最大？（）","A":"180°方位","B":"90°方位","C":"270°方位","D":"以上均不正确","answer":"C"},{"id":958,"type":"single","cat":"基础概念","stem":"（）是无人驾驶航空器地面站的主要功能。","A":"数据采集处理","B":"飞行控制","C":"导航","D":"监控与任务规划","answer":"D"},{"id":959,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机下滑中，估计到第四转弯时的高度将高于预定的高度（）。","A":"应及时地收小油门，必要时可收至20%，增大下滑角","B":"应适当地加大油门，减小下滑角","C":"转为平飞进行修正","D":"以上均不正确","answer":"A"},{"id":960,"type":"single","cat":"设备与维护","stem":"为无人机选取机架时，如飞行器起飞重量大于4kg，建议电机臂碳管不小于（）mm或以上，机架碳板厚度达到5mm或以上。","A":"6","B":"16","C":"60","D":"160","answer":"B"},{"id":961,"type":"single","cat":"飞行原理","stem":"民用无人机运行多处于低空低速环境下，主要受到的阻力有①摩擦阻力；②循环阻力；③干扰阻力；④激波阻力；⑤诱导阻力；⑥压差阻力。","A":"①②③④","B":"①③⑤⑥","C":"①②⑤⑥","D":"以上均不正确","answer":"B"},{"id":962,"type":"single","cat":"电力巡检","stem":"巡检作业时，若固定翼无人机出现失去动力等机械故障，应控制无人机（）。","A":"立即拉升爬高","B":"原地降落","C":"在安全区域紧急降落","D":"立即飞回","answer":"C"},{"id":963,"type":"multi","cat":"基础概念","stem":"常见小型多旋翼无人机常使用的动力装置不包括（）。","A":"燃气涡轮发动机","B":"四冲程活塞发动机","C":"电动机","D":"涡轮轴发动机","answer":"ABD"},{"id":964,"type":"multi","cat":"基础概念","stem":"起飞前应检查无人直升机动力系统的（）或（），确认满足飞行巡检航程要求。","A":"油量","B":"燃油","C":"电能储备","D":"电量储备","answer":"BC"},{"id":965,"type":"multi","cat":"基础概念","stem":"多轴飞行器在没有发生机械结构改变的前提下，如发生漂移，不能直线飞行时，需关注的是","A":"GPS定位","B":"指南针校准","C":"调整重心位置","D":"遥控天线","answer":"AB"},{"id":966,"type":"multi","cat":"基础概念","stem":"垂直起降固定翼无人机，又分为（）和（），指一种结合了多旋翼无人机和固定翼无人机优势的新型垂直起降飞行器。","A":"倾转旋翼无人机","B":"叠转旋翼无人机","C":"固定旋翼无人机","D":"复合翼无人机","answer":"AD"},{"id":967,"type":"multi","cat":"电力巡检","stem":"当无人机巡检系统主要组成部件进行了更换或升级后，运维单位应（）。","A":"立即使用","B":"组织试验检测","C":"组织评估","D":"确保无人机巡检系统满足相关标准要求","answer":"BD"},{"id":968,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，无人机巡检作业应严格按国家相关（）、等要求规范化使用空域。","A":"政策","B":"法规","C":"当地民航军管","D":"规程","answer":"ABC"},{"id":969,"type":"multi","cat":"电力巡检","stem":"无人直升机巡检系统应具备（）功能","A":"一键返航功能","B":"链路中断返航功能","C":"飞行区域限制功能","D":"低电压报警功能","answer":"ABC"},{"id":970,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机自动驾驶状态下，安全下降速率应该是哪一个？（）","A":"2米/秒","B":"8米/秒","C":"5米/秒","D":"以上均不正确","answer":"A"},{"id":971,"type":"single","cat":"设备与维护","stem":"多旋翼电调与电机如何匹配？（）","A":"电调的额定电压要比电机的最大电流高","B":"电调的额定电流要比电机的最大电流底","C":"电调的额定电流要比电机的最大电流高","D":"以上均不正确","answer":"C"},{"id":972,"type":"single","cat":"操纵与飞行技术","stem":"无人机在室外作业时，没有按照指定位置悬停，而是不受控制自己飘走，应维修（）可以恢复其正常功能。","A":"陀螺仪","B":"飞控","C":"水平仪","D":"GPS模块","answer":"D"},{"id":973,"type":"single","cat":"设备与维护","stem":"多旋翼飞行器如果重新组装后，必须校准哪些传感器？（）","A":"磁罗盘，陀螺仪","B":"电调，GPS","C":"接收机，IMU","D":"以上均不正确","answer":"A"},{"id":974,"type":"single","cat":"设备与维护","stem":"无人机飞行时收起起落架，会使飞机（）。","A":"全机阻力无明显变化","B":"全机阻力减小","C":"全机阻力增大","D":"以上均不正确","answer":"B"},{"id":975,"type":"single","cat":"基础概念","stem":"（）是无人机完成起飞、空中飞行、执行任务、返场回收等整个飞行过程的核心系统，对无人机实现全权控制与管理。","A":"飞控计算机","B":"飞控子系统","C":"导航子系统","D":"以上均不正确","answer":"B"},{"id":976,"type":"single","cat":"基础概念","stem":"多轴飞行器（）。","A":"无自转下滑能力","B":"有部分自传下滑能力","C":"有自转下滑能力","D":"以上均不正确","answer":"A"},{"id":977,"type":"single","cat":"设备与维护","stem":"外转子无刷电机相对于内转子无刷的优势是（）。","A":"扭矩更高","B":"寿命更长","C":"功率更大","D":"转速更高","answer":"A"},{"id":978,"type":"single","cat":"基础概念","stem":"以下是共轴双旋翼直升机的优点的是（）。","A":"操作结构简单","B":"自转下滑性能优异","C":"纵向尺寸小","D":"以上均不正确","answer":"C"},{"id":979,"type":"single","cat":"操纵与飞行技术","stem":"属于减升装置的辅助操纵面是（）。","A":"扰流扳","B":"副冀","C":"前缘缝翼","D":"以上均不正确","answer":"A"},{"id":980,"type":"single","cat":"基础概念","stem":"可进行夜间监视的无人机，作业时突然失去该夜视功能，此时可判断该现象产生的主要原因是（）出现故障。","A":"全球定位系统（GPS）模块","B":"前视红外仪","C":"摄像头","D":"电子调速器（电调）","answer":"B"},{"id":981,"type":"multi","cat":"基础概念","stem":"安全保护功能应具备安全控制策略，包括（）和（）。","A":"返航策略","B":"自动躲避策略","C":"应急降落策略","D":"应急提升策略","answer":"AC"},{"id":982,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，无人机巡检区域处于（）等特殊区域时，巡检人员应根据无人机的性能及气象情况判断是否继续飞行。","A":"狭长地带","B":"大档距","C":"大落差","D":"微气象","answer":"ABCD"},{"id":983,"type":"multi","cat":"设备与维护","stem":"固定翼无人机的舵角一般是一个三角形的固定件，安装在无人机副翼、尾翼的活动面上，通过连杆与舵机摇臂连接，其安装过程中的注意事项包括（）。","A":"同一舵面的各个铰链的中心线应该在一条直线上，并且位于舵面的中心","B":"舵脚的转动点应该与铰链的中心线在同一个垂直面上","C":"舵机摇臂应该与连杆垂直，调整摇臂使得键槽与键齿相配合，尽量不要使用遥控器的中立位置调整功能来调整舵机的中心位置","D":"使用高级的带轴承的连接附件和精密加工的铝制舵机摇臂，可以更好的完成设置","answer":"ABCD"},{"id":984,"type":"multi","cat":"基础概念","stem":"设备运维单位应提前掌握线路周边重要建筑和设施、人员活动密集区、（）、森林防火区和无人区等的分布情况。","A":"空中管制区","B":"无线电干扰区","C":"通讯阻隔区","D":"大风或切变风多发区","answer":"ABCD"},{"id":985,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，军用无人机可以分为（）。","A":"校靶机","B":"攻击机","C":"电子战无人机","D":"巡查/监视无人机","answer":"ABC"},{"id":986,"type":"multi","cat":"操纵与飞行技术","stem":"直升机的空间有六个自由度，但实际上只需要四个操纵，这四个操纵分别是（）。","A":"总距操纵","B":"纵向操纵","C":"横向操纵","D":"航向操纵","answer":"ABCD"},{"id":987,"type":"single","cat":"法规与空域","stem":"根据2025年修订的《无人驾驶航空器飞行管理暂行条例》实施细则，微型无人机（空机重量≤0.25kg）在适飞空域内飞行时，下列哪项操作符合规定？","A":"夜间飞行时未开启示位灯","B":"超视距飞行但保持与管制单位通信","C":"在机场净空保护区外100米高度飞行","D":"搭载总重量0.3kg的测绘设备","answer":"C","exp":"微型无人机在适飞空域内可超视距飞行，但需满足高度限制；夜间需示位灯，搭载重量不得超过空机重量，机场净空保护区外允许120米以下飞行"},{"id":988,"type":"single","cat":"航空气象","stem":"某多旋翼无人机在6m/s稳定风速中悬停，其电机输出功率与无风悬停相比：","A":"增加，因需抵消风阻","B":"减少，因风速提供部分升力","C":"不变，悬停功率仅与重力有关","D":"先增后减，取决于风向","answer":"A","exp":"稳定风场中，无人机需通过姿态调整产生水平推力抵消风阻，导致电机功率增加"},{"id":989,"type":"single","cat":"航空气象","stem":"以下哪种气象条件最可能引发无人机动力系统结冰？","A":"温度-5℃，相对湿度60%的晴天","B":"温度0℃，过冷水滴含量0.5g/m³的层云","C":"温度10℃，雷暴云砧下方","D":"温度-15℃，干燥的高空气流","answer":"B","exp":"结冰需满足过冷水滴存在、温度0℃至-10℃、水滴含量≥0.3g/m³，层云符合条件"},{"id":990,"type":"single","cat":"领航与任务规划","stem":"采用GPS+惯性导航（INS）组合导航的无人机，当GPS信号丢失时，导航误差主要来源于：","A":"气压高度计的温度漂移","B":"加速度计的零偏误差","C":"磁罗盘的磁干扰","D":"视觉定位的延迟","answer":"B","exp":"INS通过加速度计积分计算位移，其零偏误差会随时间累积，导致定位误差增大"},{"id":991,"type":"single","cat":"飞行原理","stem":"某4轴无人机（轴距450mm）使用1045桨（直径10英寸，螺距4.5英寸），若更换为1240桨，其他参数不变，最可能出现的现象是：","A":"悬停电流降低，最大升力增加","B":"悬停电流增加，最大升力降低","C":"悬停电流降低，最大升力降低","D":"悬停电流增加，最大升力增加","answer":"D","exp":"大直径桨叶在低转速下可产生更大升力，但需更大扭矩，导致悬停电流增加；螺距减小补偿转速需求，整体最大升力提升"},{"id":992,"type":"single","cat":"法规与空域","stem":"依据《民用无人驾驶航空器驾驶员执照管理规定》，申请视距内驾驶员执照（超视距等级）的申请人，需具备至少（）小时的超视距飞行训练经历？","A":"10","B":"15","C":"20","D":"25","answer":"B","exp":"2026年新规要求超视距等级需15小时专项训练，含5小时模拟机训练"},{"id":993,"type":"single","cat":"航空气象","stem":"无人机在500米高度飞行时，遇到中度颠簸，正确的应对措施是：","A":"立即降低高度至100米以下","B":"保持当前空速，调整俯仰角","C":"增大油门至最大，快速爬升","D":"切换至手动模式，稳定姿态","answer":"D","exp":"颠簸时需稳定姿态，手动模式可更精准控制；盲目增减油门或高度可能加剧不稳定"},{"id":994,"type":"single","cat":"设备与维护","stem":"以下哪种电池存储方式符合安全规范？","A":"锂电池充满电后，在25℃环境中密封保存","B":"镍氢电池放电至20%电量，在15℃干燥环境存放","C":"铅酸电池完全放电后，在0℃环境长期存储","D":"聚合物电池放电至50%电量，在35℃通风处堆叠存放","answer":"B","exp":"锂电池应存储在30%-50%电量，20-25℃；铅酸电池需保持部分电量防止硫化；聚合物电池需单颗隔离存放，避免堆叠"},{"id":995,"type":"single","cat":"设备与维护","stem":"某无人机飞控系统显示磁罗盘校准失败，可能的原因不包括：","A":"附近存在强电磁干扰（如高压电线）","B":"校准过程中无人机姿态变化过快","C":"飞控固件版本与磁罗盘型号不匹配","D":"螺旋桨旋转产生的振动导致传感器误差","answer":"D","exp":"磁罗盘校准失败主要因环境干扰、操作不当或软硬件不兼容；螺旋桨振动影响加速度计，不直接导致磁罗盘校准问题"},{"id":996,"type":"single","cat":"基础概念","stem":"关于无人机起降场地选择，错误的做法是：","A":"选择逆风方向起降，缩短滑跑距离","B":"多旋翼无人机在坡度15°的斜坡上垂直起降","C":"固定翼无人机在长度80米的草地跑道起飞","D":"避开通信基站、雷达站等电磁敏感区域","answer":"B","exp":"多旋翼垂直起降需场地水平，坡度超过10°可能导致起飞时姿态失控"},{"id":997,"type":"single","cat":"基础概念","stem":"下列哪项不属于无人机系统的感知与规避（SAA）功能？","A":"毫米波雷达探测前方障碍物","B":"视觉识别系统跟踪附近有人机","C":"自动调整航线避让禁飞区","D":"ADS-B接收机接收其他飞机位置信息","answer":"C","exp":"SAA特指对动态障碍物的实时感知与避让，禁飞区避让属于路径规划，非实时感知"},{"id":998,"type":"single","cat":"设备与维护","stem":"某六轴无人机（桨序1-6顺时针排列），若第2号电机（前右）停转，飞机会出现：","A":"机头向右偏转，右侧下沉","B":"机头向左偏转，左侧下沉","C":"机头向右偏转，左侧下沉","D":"机头向左偏转，右侧下沉","answer":"A","exp":"前右电机停转，该桨升力消失，右侧力矩不平衡导致右侧下沉；顺时针桨停转，反扭矩减少，机头向右转"},{"id":999,"type":"single","cat":"基础概念","stem":"气压高度表在高原地区（海拔3000米）使用时，若未修正基准气压，测得的高度会：","A":"高于实际高度（相对海平面）","B":"低于实际高度（相对海平面）","C":"准确反映相对地面高度","D":"误差随温度变化无规律","answer":"B","exp":"高原地区气压低于标准大气压，未修正时气压高度表会将低气压误判为更高高度，导致显示高度高于实际海拔，但相对地面高度需结合实时气压"},{"id":1000,"type":"single","cat":"领航与任务规划","stem":"无人机在执行测绘任务时，若需要地面分辨率达到5cm，飞行高度100米，应选择的相机焦距为（像元尺寸3.75μm）：","A":"15mm","B":"20mm","C":"25mm","D":"30mm","answer":"B","exp":"地面分辨率GSD=（像元尺寸×飞行高度"},{"id":1001,"type":"single","cat":"基础概念","stem":"依据《无人驾驶航空器运行风险等级划分》，以下哪类运行属于高风险？","A":"视距内农林喷洒（起飞重量25kg）","B":"超视距物流配送（起飞重量50kg，高度150米）","C":"视距内航空摄影（起飞重量1.5kg，人群上空50米）","D":"超视距电力巡检（起飞重量12kg，远离人群）","answer":"B","exp":"高风险运行包括超视距、起飞重量＞25kg、人口密集区上空等多重风险叠加"},{"id":1002,"type":"single","cat":"基础概念","stem":"无人机在飞行中出现动力不足报警，可能的原因不包括：","A":"电池内阻增大，放电能力下降","B":"电机KV值与桨叶匹配不当（KV值过高）","C":"飞控PID参数设置过软，响应延迟","D":"螺旋桨安装反角错误，产生负拉力","answer":"C","exp":"PID参数影响稳定性，不直接导致动力不足；动力问题多与动力系统效率相关"},{"id":1003,"type":"single","cat":"飞行原理","stem":"以下哪种飞行状态最容易诱发失速？","A":"固定翼无人机以1.2倍失速速度平飞","B":"多旋翼无人机以最大俯仰角（30°）俯冲","C":"固定翼无人机带20°坡度转弯，空速降低至失速速度","D":"多旋翼无人机在6级侧风中悬停","answer":"C","exp":"转弯时升力需分解为向心力，有效升力降低，空速接近失速速度时易失速"},{"id":1004,"type":"single","cat":"设备与维护","stem":"无人机数据链中断（信号丢失）时，优先执行的动作是：","A":"切换至手动模式，人工接管","B":"按预设航线继续飞行","C":"原地盘旋等待信号恢复","D":"自动返航至起飞点","answer":"D","exp":"多数飞控设计为信号丢失时优先返航，避免失控漂移；需根据飞控设置，但标准流程以返航为第一选择"},{"id":1005,"type":"single","cat":"设备与维护","stem":"关于无人机电池循环寿命，正确的描述是：","A":"循环次数指完全充放电（0-100%）的次数","B":"聚合物锂电池循环寿命通常＞1000次","C":"浅充浅放（20%-80%）会降低循环寿命","D":"镍镉电池无记忆效应，可任意充放电","answer":"A","exp":"循环寿命定义为完全充放电次数；聚合物锂电池循环约300-500次；浅充浅放可延长寿命；镍镉电池有记忆效应"},{"id":1006,"type":"single","cat":"设备与维护","stem":"某无人机飞控记录显示IMU校准失败，最可能的故障部件是：","A":"惯性测量单元（加速度计+陀螺仪）","B":"全球导航卫星系统（GNSS）模块","C":"气压高度传感器","D":"磁罗盘","answer":"A","exp":"IMU校准直接关联加速度计和陀螺仪，校准失败通常因传感器故障或环境振动过大"},{"id":1007,"type":"multi","cat":"法规与空域","stem":"以下哪些属于无人机适飞空域的管制空域？","A":"真高120米以上区域","B":"机场跑道中心线两侧各10公里、跑道端外20公里范围","C":"军事管理区上空","D":"人口密集区真高50米以下","answer":"ABC","exp":"管制空域包括高高度层、机场净空区、军事区等；人口密集区50米以下属加强管控区，非管制空域"},{"id":1008,"type":"multi","cat":"操纵与飞行技术","stem":"多旋翼无人机悬停时，影响其稳定性的主要因素有：","A":"电机响应速度","B":"桨叶动平衡","C":"飞控PID参数","D":"电池放电倍率","answer":"ABCD","exp":"电机响应影响姿态调整速度；桨叶不平衡导致振动；PID参数决定控制精度；电池放电不足会导致动力中断"},{"id":1009,"type":"multi","cat":"航空气象","stem":"无人机在雷暴天气中飞行可能面临的风险包括：","A":"强电场引发电子设备故障","B":"上升/下沉气流导致失控","C":"冰雹撞击损坏机体","D":"湿度大导致电池短路","answer":"ABC","exp":"雷暴云内强电场、剧烈气流、冰雹是主要风险；密封良好的电池不易因湿度短路"},{"id":1010,"type":"multi","cat":"基础概念","stem":"固定翼无人机起飞滑跑距离过长，可能的原因有：","A":"起飞重量过大","B":"跑道表面摩擦系数过高","C":"迎角设置过小","D":"发动机推力不足","answer":"ACD","exp":"重量大、推力小、迎角小（升力不足"},{"id":1011,"type":"multi","cat":"基础概念","stem":"无人机维护时，需要检查的项目包括：","A":"螺旋桨是否有裂纹或变形","B":"飞控天线是否松动","C":"电池接口是否氧化","D":"电机轴是否有径向晃动","answer":"ABCD","exp":"螺旋桨结构、天线连接、电池接触、电机间隙均为关键检查项"},{"id":1012,"type":"single","cat":"法规与空域","stem":"根据《无人驾驶航空器飞行管理暂行条例》，我国对无人驾驶航空器实行（）制度。","A":"实名登记","B":"备案管理","C":"适航认证","D":"运营许可","answer":"A"},{"id":1013,"type":"single","cat":"法规与空域","stem":"轻型无人驾驶航空器在适飞空域内飞行的最大真高不得超过（）。","A":"50米","B":"120米","C":"500米","D":"1000米","answer":"B"},{"id":1014,"type":"single","cat":"法规与空域","stem":"下列空域中，属于我国民用无人机适飞空域的是（）。","A":"机场净空保护区","B":"军事禁区上空","C":"真高120米以下的非管控空域","D":"政府机关驻地上空","answer":"C"},{"id":1015,"type":"single","cat":"法规与空域","stem":"CAAC颁发的民用无人机超视距驾驶员执照的理论考试合格分数线为（）。","A":"60分","B":"70分","C":"80分","D":"90分","answer":"C"},{"id":1016,"type":"single","cat":"操纵与飞行技术","stem":"视距内（VLOS）飞行是指驾驶员在目视范围内操纵无人机，其水平距离通常不超过（），相对高度不超过120米。","A":"200米","B":"500米","C":"1000米","D":"2000米","answer":"B"},{"id":1017,"type":"single","cat":"基础概念","stem":"无人机飞行中，应当避让的第一优先级目标是（）。","A":"其他无人机","B":"有人驾驶航空器","C":"地面建筑物","D":"地面人员","answer":"B"},{"id":1018,"type":"single","cat":"法规与空域","stem":"从事经营性无人机飞行活动，应当取得（）颁发的经营许可证。","A":"民用航空管理部门","B":"公安机关","C":"交通运输部门","D":"应急管理部门","answer":"A"},{"id":1019,"type":"single","cat":"基础概念","stem":"下列哪种类型的无人机飞行，无需提前申请飞行计划（）。","A":"轻型无人机在适飞空域内飞行","B":"中型无人机在农村地区飞行","C":"植保无人机在管控空域内飞行","D":"测绘无人机在城市上空飞行","answer":"A"},{"id":1020,"type":"single","cat":"法规与空域","stem":"无人机实名登记的信息不包括下列哪项（）。","A":"所有者姓名/单位名称","B":"无人机型号、序列号","C":"无人机购买价格","D":"联系方式","answer":"C"},{"id":1021,"type":"single","cat":"法规与空域","stem":"机场净空保护区通常是指机场跑道中心线两侧各（）、跑道端外各20公里的范围。","A":"5公里","B":"10公里","C":"20公里","D":"50公里","answer":"B"},{"id":1022,"type":"single","cat":"法规与空域","stem":"根据《民用无人机驾驶员管理规定》，无人机驾驶员执照的有效期为（）。","A":"2年","B":"3年","C":"6年","D":"长期有效","answer":"C"},{"id":1023,"type":"single","cat":"基础概念","stem":"超视距飞行任务中，对飞行安全负全面责任的是（）。","A":"无人机驾驶员","B":"任务载荷操作员","C":"无人机机长","D":"地面站观察员","answer":"C"},{"id":1024,"type":"single","cat":"法规与空域","stem":"下列区域中，属于无人机管控空域的是（）。","A":"真高100米的乡村农田上空","B":"真高80米的城市公园上空","C":"民用机场障碍物限制面以内的空域","D":"真高120米以下的无人区上空","answer":"C"},{"id":1025,"type":"single","cat":"基础概念","stem":"无人机飞行活动的统一监督管理部门是（）。","A":"中国民用航空局","B":"国家发展和改革委员会","C":"工业和信息化部","D":"公安部","answer":"A"},{"id":1026,"type":"single","cat":"基础概念","stem":"多旋翼无人机的核心飞行控制部件是（）。","A":"电调","B":"飞控","C":"GPS模块","D":"接收机","answer":"B"},{"id":1027,"type":"single","cat":"设备与维护","stem":"多旋翼无人机中，用于调节电机转速的部件是（）。","A":"飞控","B":"电调","C":"电池","D":"接收机","answer":"B"},{"id":1028,"type":"single","cat":"设备与维护","stem":"民用无人机常用的锂聚合物电池（LiPo）的单体额定电压是（）。","A":"1.2V","B":"3.7V","C":"4.2V","D":"5.0V","answer":"B"},{"id":1029,"type":"single","cat":"操纵与飞行技术","stem":"下列传感器中，用于测量无人机姿态角速度的是（）。","A":"加速度计","B":"陀螺仪","C":"磁力计","D":"气压计","answer":"B"},{"id":1030,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机实现悬停的基本原理是（）。","A":"升力大于重力","B":"升力等于重力","C":"升力小于重力","D":"推力等于阻力","answer":"B"},{"id":1031,"type":"single","cat":"飞行原理","stem":"固定翼无人机产生升力的主要部件是（）。","A":"机身","B":"机翼","C":"尾翼","D":"螺旋桨","answer":"B"},{"id":1032,"type":"single","cat":"领航与任务规划","stem":"无人机GPS模块的主要作用是（）。","A":"测量飞行高度","B":"获取位置与速度信息","C":"测量飞行姿态","D":"接收地面控制信号","answer":"B"},{"id":1033,"type":"single","cat":"设备与维护","stem":"多旋翼无人机的螺旋桨通常分为正桨和反桨，其主要作用是（）。","A":"提高飞行速度","B":"抵消反扭力","C":"增加升力","D":"降低阻力","answer":"B"},{"id":1034,"type":"single","cat":"设备与维护","stem":"下列不属于无人机飞控系统组成部分的是（）。","A":"惯性测量单元（IMU）","B":"GPS接收机","C":"任务载荷相机","D":"气压计","answer":"C"},{"id":1035,"type":"single","cat":"设备与维护","stem":"锂聚合物电池的安全储存电压通常为单体（）左右。","A":"3.7V","B":"3.85V","C":"4.2V","D":"3.2V","answer":"B"},{"id":1036,"type":"single","cat":"基础概念","stem":"垂直起降固定翼无人机的优势是（）。","A":"续航时间比多旋翼短","B":"不需要跑道即可起降，且巡航速度快","C":"结构比多旋翼简单","D":"载重量比同级别多旋翼小","answer":"B"},{"id":1037,"type":"single","cat":"设备与维护","stem":"无人机接收机的主要作用是（）。","A":"发送飞行状态数据到地面站","B":"接收遥控器的控制信号","C":"接收卫星定位信号","D":"处理飞行姿态数据","answer":"B"},{"id":1038,"type":"single","cat":"设备与维护","stem":"下列哪种电池类型的能量密度最高（）。","A":"铅酸电池","B":"镍氢电池","C":"锂聚合物电池","D":"磷酸铁锂电池","answer":"C"},{"id":1039,"type":"single","cat":"基础概念","stem":"多旋翼无人机的三轴姿态指的是（）。","A":"滚转轴、俯仰轴、偏航轴","B":"X轴、Y轴、Z轴","C":"横轴、纵轴、竖轴","D":"速度轴、加速度轴、姿态轴","answer":"A"},{"id":1040,"type":"single","cat":"飞行原理","stem":"根据伯努利原理，流体流速越快，压强（）。","A":"越高","B":"越低","C":"不变","D":"不确定","answer":"B"},{"id":1041,"type":"single","cat":"飞行原理","stem":"固定翼无人机的失速是指（）。","A":"飞行速度过低导致升力不足","B":"迎角超过临界迎角，升力急剧下降","C":"发动机失去动力","D":"舵面失效无法操纵","answer":"B"},{"id":1042,"type":"single","cat":"飞行原理","stem":"下列哪种阻力属于诱导阻力（）。","A":"机身摩擦阻力","B":"螺旋桨阻力","C":"机翼升力产生的附加阻力","D":"起落架阻力","answer":"C"},{"id":1043,"type":"single","cat":"基础概念","stem":"多旋翼无人机向左偏航（机头左转）时，通常的操作逻辑是（）。","A":"左侧电机加速，右侧电机减速","B":"右侧电机加速，左侧电机减速","C":"顺时针旋转的桨加速，逆时针旋转的桨减速","D":"逆时针旋转的桨加速，顺时针旋转的桨减速","answer":"C"},{"id":1044,"type":"single","cat":"飞行原理","stem":"固定翼无人机的升阻比是指（）。","A":"升力与阻力的比值","B":"阻力与升力的比值","C":"升力与重力的比值","D":"推力与阻力的比值","answer":"A"},{"id":1045,"type":"single","cat":"设备与维护","stem":"下列关于重心位置的说法，正确的是（）。","A":"重心越靠前，无人机静稳定性越强","B":"重心越靠后，无人机静稳定性越强","C":"重心位置与稳定性无关","D":"重心在焦点之前，无人机是静不稳定的","answer":"A"},{"id":1046,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机在爬升过程中，需要（）。","A":"所有电机同步加速","B":"所有电机同步减速","C":"前侧电机加速，后侧电机减速","D":"左侧电机加速，右侧电机减速","answer":"A"},{"id":1047,"type":"single","cat":"飞行原理","stem":"临界迎角是指（）。","A":"产生最大升力的迎角","B":"产生最小阻力的迎角","C":"产生最大升阻比的迎角","D":"失速后的迎角","answer":"A"},{"id":1048,"type":"single","cat":"飞行原理","stem":"下列哪种飞行状态下，固定翼无人机的诱导阻力最大（）。","A":"高速巡航","B":"低速大迎角飞行","C":"下降阶段","D":"平飞加速","answer":"B"},{"id":1049,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机实现机头低头的俯仰动作，需要（）。","A":"前侧电机加速，后侧电机减速","B":"前侧电机减速，后侧电机加速","C":"左侧电机加速，右侧电机减速","D":"左侧电机减速，右侧电机加速","answer":"B"},{"id":1050,"type":"single","cat":"飞行原理","stem":"空气密度对无人机升力的影响是（）。","A":"空气密度越大，升力越大","B":"空气密度越大，升力越小","C":"空气密度与升力无关","D":"仅影响固定翼，不影响多旋翼","answer":"A"},{"id":1051,"type":"single","cat":"基础概念","stem":"对无人机飞行影响最大的大气层是（）。","A":"对流层","B":"平流层","C":"中间层","D":"散逸层","answer":"A"},{"id":1052,"type":"single","cat":"航空气象","stem":"下列哪种云对飞行安全危害最大（）。","A":"卷云","B":"积雨云","C":"层云","D":"高积云","answer":"B"},{"id":1053,"type":"single","cat":"航空气象","stem":"风切变是指（）。","A":"风速的突然变化","B":"风向的突然变化","C":"风速或风向在短距离内的显著变化","D":"风力等级的变化","answer":"C"},{"id":1054,"type":"single","cat":"航空气象","stem":"能见度是指（）。","A":"正常视力的人能看清最远目标的水平距离","B":"正常视力的人在当时天气条件下，能够从天空背景中看到和辨认出目标物的最大水平距离","C":"无人机摄像头能看清的最远距离","D":"雷达能探测的最远距离","answer":"B"},{"id":1055,"type":"single","cat":"航空气象","stem":"低空风切变通常是指发生在（）以下的风切变，对无人机起降阶段威胁极大。","A":"100米","B":"500米","C":"1000米","D":"2000米","answer":"B"},{"id":1056,"type":"single","cat":"操纵与飞行技术","stem":"下列哪种天气现象会导致无人机锂电池性能急剧下降（）。","A":"大风","B":"低温","C":"多云","D":"阴天","answer":"B"},{"id":1057,"type":"single","cat":"航空气象","stem":"雷暴天气对无人机飞行的危害不包括（）。","A":"雷电损坏电子设备","B":"强阵风导致失控","C":"冰雹损坏机身结构","D":"能见度升高","answer":"D"},{"id":1058,"type":"single","cat":"基础概念","stem":"大气中水汽凝结的条件不包括（）。","A":"水汽达到饱和","B":"有凝结核","C":"气温升高","D":"气温降低","answer":"C"},{"id":1059,"type":"single","cat":"航空气象","stem":"逆风飞行对多旋翼无人机的影响是（）。","A":"续航时间增加","B":"续航时间减少","C":"悬停稳定性提升","D":"相同油门下地速增大","answer":"B"},{"id":1060,"type":"single","cat":"航空气象","stem":"积冰对无人机飞行的影响是（）。","A":"增加重量，破坏气动外形","B":"仅影响固定翼，不影响多旋翼","C":"提高升力","D":"降低阻力","answer":"A"},{"id":1061,"type":"single","cat":"基础概念","stem":"下列关于气温垂直递减率的说法，正确的是（）。","A":"对流层内气温随高度升高而降低，平均每升高100米下降0.65​","B":"对流层内气温随高度升高而升高","C":"平流层内气温随高度升高而降低","D":"中间层内气温随高度升高而升高","answer":"A"},{"id":1062,"type":"single","cat":"基础概念","stem":"无人机起飞前的检查项目不包括（）。","A":"电池电量","B":"螺旋桨安装是否牢固","C":"飞控校准状态","D":"无人机机身颜色","answer":"D"},{"id":1063,"type":"single","cat":"领航与任务规划","stem":"无人机航线规划时，返航高度应设置为（）。","A":"与飞行任务高度一致","B":"低于航线周边最高障碍物的高度","C":"高于航线周边最高障碍物至少30米","D":"越高越好","answer":"C"},{"id":1064,"type":"single","cat":"设备与维护","stem":"无人机飞行日志应当记录的内容不包括（）。","A":"飞行时间、地点","B":"飞行任务内容","C":"故障与异常情况","D":"驾驶员的饮食情况","answer":"D"},{"id":1065,"type":"single","cat":"领航与任务规划","stem":"下列关于无人机返航的说法，错误的是（）。","A":"低电量时应及时触发返航","B":"失联后无人机应自动返航","C":"返航时无需考虑周边障碍物","D":"返航前应确认返航点已正确记录","answer":"C"},{"id":1066,"type":"single","cat":"基础概念","stem":"超视距飞行时，地面站的主要作用不包括（）。","A":"实时监控飞行状态","B":"发送控制指令","C":"操纵遥控器目视飞行","D":"规划与调整航线","answer":"C"},{"id":1067,"type":"single","cat":"基础概念","stem":"无人机在人口稠密区上空飞行时，下列做法正确的是（）。","A":"尽量降低高度，拍摄更清晰的画面","B":"保持足够高度，确保故障时可滑翔至无人区","C":"飞越高楼顶部以获得更好的视野","D":"在人群正上方悬停","answer":"B"},{"id":1068,"type":"single","cat":"设备与维护","stem":"起飞前指南针（磁力计）校准的目的是（）。","A":"提高定位精度","B":"消除周围磁场干扰，保证航向准确","C":"测量飞行高度","D":"校准姿态","answer":"B"},{"id":1069,"type":"single","cat":"基础概念","stem":"下列哪种情况可以进行无人机飞行（）。","A":"能见度不足100米的大雾天气","B":"风力6级的晴天（超出无人机抗风等级）","C":"夜间在开阔无人区进行视距内飞行（符合当地规定）","D":"雷雨天气","answer":"C"},{"id":1070,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机悬停时出现漂移，最不可能的原因是（）。","A":"GPS信号不良","B":"风速过大","C":"电池电量不足","D":"飞控未校准","answer":"C"},{"id":1071,"type":"single","cat":"领航与任务规划","stem":"任务规划时，下列哪项不是需要重点考虑的因素（）。","A":"空域限制","B":"地形与障碍物","C":"气象条件","D":"无人机的生产厂家","answer":"D"},{"id":1072,"type":"single","cat":"操纵与飞行技术","stem":"无人机着陆时，下列做法正确的是（）。","A":"快速下降以节省时间","B":"选择平坦、开阔、无障碍物的场地","C":"在人员密集的地方降落","D":"无需检查降落场地，直接降落","answer":"B"},{"id":1073,"type":"single","cat":"领航与任务规划","stem":"无人机飞行中失去GPS信号后，首先应（）。","A":"立即推杆降落","B":"切换至姿态模式，尝试目视飞回","C":"等待GPS信号恢复","D":"直接触发返航","answer":"B"},{"id":1074,"type":"single","cat":"基础概念","stem":"无人机飞行中遇到有人驾驶航空器时，正确的处置方式是（）。","A":"保持原高度和航线飞行","B":"主动避让，下降高度或偏离航线","C":"拉升高度躲避","D":"原地悬停等待","answer":"B"},{"id":1075,"type":"single","cat":"设备与维护","stem":"锂聚合物电池发生明火时，下列哪种处置方式是错误的（）。","A":"使用干粉灭火器扑灭明火","B":"用沙土覆盖隔绝氧气","C":"用水浇淋降温防止复燃","D":"直接用手拿起电池扔到室外","answer":"D"},{"id":1076,"type":"single","cat":"基础概念","stem":"无人机飞行中动力突然完全失效，正确的处置是（）。","A":"立即拉杆拉升","B":"选择合适的迫降场地，尽量减少人员与财产损失","C":"直接弃机逃跑","D":"继续飞行尝试恢复动力","answer":"B"},{"id":1077,"type":"single","cat":"基础概念","stem":"无人机失联后，下列哪种做法是错误的（）。","A":"记录最后失联的位置与高度","B":"立即到失联区域正下方寻找","C":"在安全区域等待无人机自动返航","D":"必要时向空管部门报备","answer":"B"},{"id":1078,"type":"single","cat":"设备与维护","stem":"飞行中发现无人机机身异常震动，首先应（）。","A":"继续飞行完成任务","B":"尽快降落检查","C":"拉升高度","D":"加速飞行","answer":"B"},{"id":1079,"type":"single","cat":"基础概念","stem":"无人机在人口稠密区发生故障即将坠机时，首要任务是（）。","A":"保护无人机设备","B":"保护地面人员安全","C":"保护任务载荷","D":"保护地面财产","answer":"B"},{"id":1080,"type":"single","cat":"基础概念","stem":"下列哪种行为属于无人机飞行安全违规行为（）。","A":"起飞前进行安全检查","B":"在适飞空域内按规定飞行","C":"酒后操纵无人机","D":"飞行前查看气象预报","answer":"C"},{"id":1081,"type":"single","cat":"基础概念","stem":"无人机发生飞行安全事故造成人员伤亡或重大财产损失的，应当第一时间向（）报告。","A":"当地民用航空管理部门与公安机关","B":"无人机销售商","C":"无人机生产厂家","D":"当地街道办事处","answer":"A"},{"id":1082,"type":"multi","cat":"法规与空域","stem":"根据《无人驾驶航空器飞行管理暂行条例》，下列属于管控空域的有（）。","A":"民用机场障碍物限制面范围以内的空域","B":"真高120米以上的空域（除经批准的适飞空域外）","C":"军事禁区、军事管理区上空","D":"真高100米以下的乡村农田上空","answer":"ABC"},{"id":1083,"type":"multi","cat":"法规与空域","stem":"下列关于无人机驾驶员执照的说法，正确的有（）。","A":"视距内驾驶员执照理论考试合格线为70分","B":"超视距驾驶员执照理论考试合格线为80分","C":"执照有效期为6年","D":"执照到期后无需审验，自动延续","answer":"ABC"},{"id":1084,"type":"multi","cat":"基础概念","stem":"无人机飞行前，应当完成的准备工作包括（）。","A":"查看飞行空域的限制要求","B":"查询飞行时段的气象条件","C":"检查无人机设备状态","D":"确认飞行计划已获批（如需）","answer":"ABCD"},{"id":1085,"type":"multi","cat":"设备与维护","stem":"下列属于多旋翼无人机飞控系统核心传感器的有（）。","A":"陀螺仪","B":"加速度计","C":"磁力计","D":"气压计","answer":"ABCD"},{"id":1086,"type":"multi","cat":"设备与维护","stem":"锂聚合物电池的正确使用方法包括（）。","A":"避免过充过放","B":"低温环境下适当降低飞行强度","C":"满电状态长期储存","D":"发现鼓包后继续使用","answer":"AB"},{"id":1087,"type":"multi","cat":"基础概念","stem":"固定翼无人机的组成部分包括（）。","A":"机翼","B":"机身","C":"尾翼","D":"动力系统","answer":"ABCD"},{"id":1088,"type":"multi","cat":"飞行原理","stem":"下列关于失速的说法，正确的有（）。","A":"失速是由于迎角超过临界迎角导致的","B":"失速仅发生在低速飞行时","C":"失速时升力会急剧下降","D":"高速飞行时不会发生失速","answer":"AC"},{"id":1089,"type":"multi","cat":"基础概念","stem":"多旋翼无人机的三轴姿态控制包括（）。","A":"滚转控制","B":"俯仰控制","C":"偏航控制","D":"高度控制","answer":"ABC"},{"id":1090,"type":"single","cat":"基础概念","stem":"固定翼无人机摩擦阻力产生的原因主要是（）。","A":"空气的粘性","B":"飞机表面与空气的接触面积","C":"飞机的总量","D":"飞机的型号","answer":"A"},{"id":1091,"type":"single","cat":"基础概念","stem":"无人机地面调试不包括（）。","A":"重心稳定度调试","B":"气动舵面调试","C":"动力系统调试","D":"抗风性测试","answer":"D"},{"id":1092,"type":"single","cat":"飞行原理","stem":"相同迎角，飞行速度增大一倍，阻力增加为原来的（）。","A":"一倍","B":"二倍","C":"四倍","D":"以上均不正确","answer":"C"},{"id":1093,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，拉平低的修正方法是（）。","A":"发现有拉低的趋势，应适当地增大拉杆量","B":"发现有拉低的趋势，应停止拉杆或减小拉杆量","C":"发现有拉低的趋势，应推杆","D":"以上均不正确","answer":"A"},{"id":1094,"type":"single","cat":"设备与维护","stem":"飞机场当地气温的变化，主要会影响以下哪种无人机的传感器。","A":"气压高度计","B":"磁罗盘","C":"速率陀螺","D":"以上均不正确","answer":"A"},{"id":1095,"type":"single","cat":"领航与任务规划","stem":"地面站地图航迹显示系统可为无人机驾驶员提供飞行器（）等信息。","A":"飞行姿态","B":"位置","C":"飞控状态","D":"以上均不正确","answer":"B"},{"id":1097,"type":"single","cat":"设备与维护","stem":"四旋翼无人机，当逆时针的螺旋桨加速旋转，顺时针的螺旋桨减速旋转（）。","A":"飞机向左偏航","B":"飞机向右偏航","C":"飞机向右滚转","D":"飞机向上爬升","answer":"B"},{"id":1098,"type":"single","cat":"航空气象","stem":"遥控无人机着陆时，如果飞机处于逆侧风时（）。","A":"地速增大，收油门下滑和四转弯时机均应适当提前","B":"地速减小，收油门下滑和四转弯时机均应适当延后","C":"地速增大，收油门下滑和四转弯时机均应适当延后","D":"以上均不正确","answer":"B"},{"id":1100,"type":"single","cat":"设备与维护","stem":"多旋翼无人机动平衡调试电机正反转平均值及（）。","A":"正反差值","B":"正差值","C":"反差值","D":"转速比","answer":"A"},{"id":1101,"type":"single","cat":"设备与维护","stem":"电子调速器（电调）调参的方法有多种，使用遥控器的操作进行简单的设置、使用（）调参、使用电调调参软件调参等。","A":"飞行控制系统（自驾仪）","B":"编程卡","C":"电子调速器（电调）","D":"电机与飞行控制系统（自驾仪）","answer":"B"},{"id":1102,"type":"single","cat":"基础概念","stem":"飞机的压力中心是（）。","A":"压力最低的点","B":"压力最高的点","C":"升力的着力点","D":"以上均不正确","answer":"C"},{"id":1103,"type":"single","cat":"操纵与飞行技术","stem":"自主飞行时，油门应该处于什么位置？（）","A":"中立位偏上","B":"中立位偏下","C":"中立位","D":"以上均不正确","answer":"C"},{"id":1104,"type":"single","cat":"设备与维护","stem":"航测固定翼无人机在不同的大气环境下飞行测试必须校准（）传感器。","A":"气压计","B":"全球定位系统（GPS）","C":"磁罗盘","D":"角速度计","answer":"A"},{"id":1106,"type":"single","cat":"基础概念","stem":"下面关于助手与飞手之间协作描述错误的是（）。","A":"助手可对B点一侧进行观察，保障无人机能够准确的完成航线","B":"助手可对速度进行观察，提醒飞手降速或增速","C":"助手可对横移宽度进行观察，提醒横移宽度是否合适","D":"助手可对无人机进行实时操控，纠正飞手的操控动作","answer":"D"},{"id":1107,"type":"single","cat":"基础概念","stem":"遥控模型飞机具有一定的（），不要把它当做玩具。","A":"观赏性","B":"娱乐性","C":"危险性","D":"以上均不正确","answer":"C"},{"id":1108,"type":"multi","cat":"基础概念","stem":"电子地图插件应具备以下基本功能（）","A":"地面站所需要的永久图层和临时图层的创建","B":"地图属性设置，如图层设置、样式选择等","C":"对地图的一些基本操作，如拖动、放大、缩小等","D":"对地图图元的添加、删除、选定、移动等操作","answer":"ABCD"},{"id":1109,"type":"multi","cat":"设备与维护","stem":"下面哪一项属于无刷电机的组成部分（）。","A":"电刷","B":"转轴","C":"漆包线","D":"轴承","answer":"BCD"},{"id":1110,"type":"multi","cat":"操纵与飞行技术","stem":"无人机着陆后应检查哪些方面？（）","A":"飞行器外观检查","B":"燃油动力飞行器需要称重检查","C":"各系统电量检查","D":"下载飞行参数并检查","answer":"ABCD"},{"id":1111,"type":"multi","cat":"电力巡检","stem":"在（）和其他特殊情况时，应及时对线路进行特殊巡视，以发现线路通道的异常现象及设备部件的缺陷及异常情况。","A":"气候剧烈变化","B":"自然灾害","C":"外力影响","D":"异常运行","answer":"ABCD"},{"id":1112,"type":"multi","cat":"基础概念","stem":"无人直升机出厂文件资料应至少包含：（）","A":"技术规格书","B":"操作手册","C":"出厂检验报告","D":"维护保养手册","answer":"ABCD"},{"id":1114,"type":"single","cat":"基础概念","stem":"以下无冫机中，需要跑道起降的是（）？","A":"固定翼无冫机","B":"无冫直升机","C":"多旋翼无冫机","D":"六轴飞行器","answer":"A"},{"id":1115,"type":"single","cat":"基础概念","stem":"小型无人机，是指空机重量不超过（）千克或者最大起飞重量不超过（）千克的无人机，但不包括微型、轻型无人机。","A":"25，35","B":"15，35","C":"25，45","D":"15，25","answer":"D"},{"id":1116,"type":"single","cat":"领航与任务规划","stem":"（）是指从航线上的任意点转入安全返航通道或从安全返航通道转向应急迫降点或机场。","A":"安全着陆策略","B":"航线转移策略","C":"安全返航策略","D":"以上均不正确","answer":"B"},{"id":1117,"type":"single","cat":"领航与任务规划","stem":"电台、接收机、调速器、电池、GPS、电机（多旋翼无人机以下哪个组设备连接是正确的）？","A":"调速-电机-GPS-接收机","B":"接收机-调速器-电池-电台","C":"电池-调速器-电机","D":"以上均不正确","answer":"C"},{"id":1118,"type":"single","cat":"基础概念","stem":"地面控制站飞行参数综合显示的内容包括（）。","A":"飞行与导航信息、数据链状态信息、设备状态信息、指令信息","B":"导航信息显示、航迹绘制显示以及地理信息的显示","C":"告警信息、地图航迹显示信息","D":"以上均不正确","answer":"A"},{"id":1119,"type":"single","cat":"操纵与飞行技术","stem":"（）主要包括起飞场地标注、着陆场地标注、应急场地标注，为操作员提供发射与回收以及应急迫降区域参考。","A":"场地标注","B":"任务区域标注","C":"警示标注","D":"以上均不正确","answer":"A"},{"id":1120,"type":"single","cat":"设备与维护","stem":"多轴飞行器飞控软件使用中要特别注意的事项，不包括（）。","A":"文件大小","B":"各通道正反逻辑设置","C":"版本","D":"以上均不正确","answer":"A"},{"id":1121,"type":"single","cat":"操纵与飞行技术","stem":"无人机在遥控下降时，驾驶员应注意（）。","A":"飞机下降时，油门收小，螺旋桨扭转气流减弱，飞机有右偏趋势，须抵住左舵","B":"飞机状态不会发生变化，不需做任何准备","C":"飞机下降时，油门收小，螺旋桨扭转气流减弱，飞机有左偏趋势，须抵住右舵","D":"以上均不正确","answer":"A"},{"id":1122,"type":"multi","cat":"领航与任务规划","stem":"航线规划应远离（）、大风或切变风多发区，尽量避免跨越高速公路和铁路飞行。","A":"人口稠密区","B":"重要建筑和设施","C":"通讯阻隔区","D":"无线电干扰区","answer":"ABCD"},{"id":1123,"type":"multi","cat":"基础概念","stem":"以下关于宽容度的描述，正确的是（）。","A":"宽容度高，能更完好地保留画面细节","B":"不同数码相机的宽容度是相同的","C":"宽容度有限，可能导致照片暗部细节无法展示","D":"宽容度有限，可能导致照片亮部细节无法展示","answer":"ACD"},{"id":1124,"type":"multi","cat":"电力巡检","stem":"无人直升机进行输电线路巡检的主要巡检内容中对导地线可见光检测内容为（）。","A":"导地线断股","B":"锈蚀","C":"异物","D":"覆冰","answer":"ABCD"},{"id":1125,"type":"multi","cat":"设备与维护","stem":"多旋翼无人机的动力电机调速可以采用（）的方法调速。","A":"电枢供电电压","B":"改变电机主磁通","C":"改变电枢回路总电阻","D":"改变外接电阻","answer":"ABC"},{"id":1126,"type":"multi","cat":"电力巡检","stem":"无人直升机巡检系统的地面站系统包括（）、（）和（）等。","A":"硬件设备","B":"飞行控制软件","C":"检测软件","D":"通讯软件","answer":"ABC"},{"id":1127,"type":"single","cat":"基础概念","stem":"固定翼无人机电子调速器额定电流应与电动机的工作电流的关系是（）。","A":"大于","B":"小于","C":"等于","D":"不确定","answer":"C"},{"id":1128,"type":"single","cat":"设备与维护","stem":"某螺旋桨是正桨，是指（）。","A":"从多轴飞行器上方观察，该螺旋桨逆时针旋转","B":"从多轴飞行器上方观察，该螺旋桨顺时针旋转","C":"从多轴飞行器下方观察，该螺旋桨逆时针旋转","D":"以上均不正确","answer":"A"},{"id":1129,"type":"single","cat":"基础概念","stem":"可能需要处置的紧急情况不包括（）。","A":"控制站显示系统故障","B":"上行通讯链路故障","C":"飞控系统故障","D":"以上均不正确","answer":"C"},{"id":1130,"type":"single","cat":"设备与维护","stem":"调飞机遥控器的前四步是（）。","A":"新建模型、模型重命名、选择发射制式、失控保护","B":"新建模型、选择发射制式、定义开关、失控保护","C":"新建模型、选择发射制式、中立微调、行程量设置","D":"以上均不正确","answer":"B"},{"id":1131,"type":"single","cat":"设备与维护","stem":"一款无刷电机通电后电机卡顿，无法连续旋转，排查的项目不包括的是（）。","A":"检查电调信号线是否插紧","B":"电机引出线是否断线","C":"电调线与电调本体焊接是否松脱","D":"电机与电调线连接是否牢靠","answer":"A"},{"id":1132,"type":"single","cat":"基础概念","stem":"一般不在（）的天气使用无人机，若无法避免，尽快使用完毕，断电擦干，风干或者放到防潮箱吸潮，确定湿气除净后再次使用。","A":"雨雪","B":"阴天","C":"晴朗","D":"多云","answer":"A"},{"id":1133,"type":"single","cat":"基础概念","stem":"真空速明显小于地速是什么原因？（）","A":"逆风","B":"顺风","C":"无风","D":"以上均不正确","answer":"B"},{"id":1134,"type":"single","cat":"领航与任务规划","stem":"规划的航线遇有线路交叉跨越、临近边坡等情况，应保持足够的（）。","A":"净空距离","B":"安全距离","C":"飞行距离","D":"海拔高度","answer":"B"},{"id":1136,"type":"single","cat":"设备与维护","stem":"（）通常有刷电机的连续工作寿命在几百到1千多个小时，到达使用极限就需要更换碳刷，不然很容易造成轴承的磨损。","A":"无刷电机","B":"碳刷电机","C":"直流电机","D":"交流电机","answer":"B"},{"id":1138,"type":"single","cat":"基础概念","stem":"无人机（）配平主要考虑是沿纵轴的前后位置。","A":"气动焦点","B":"发动机","C":"重心","D":"机翼","answer":"C"},{"id":1139,"type":"multi","cat":"操纵与飞行技术","stem":"无人机着陆时，飞机（）都在随时发生变化。","A":"高度","B":"速度","C":"状态","D":"下降率","answer":"ABCD"},{"id":1140,"type":"multi","cat":"设备与维护","stem":"动力电池性能类检测包括（），具体检测方法参照QB/T2502相关规定。","A":"外观检测","B":"绝缘检测","C":"放电容量检测方法（蓄电池充电、20℃放电容量、-20℃放电容量、55℃放电容量）","D":"安全性能试验（过充电、短路、加热、挤压、针刺、振动）","answer":"ABCD"},{"id":1141,"type":"multi","cat":"基础概念","stem":"巡检飞行结束后，应及时做好（）等资料的归档。","A":"空域审批文件","B":"工作票（单）","C":"视频、影像资料","D":"航线信息库","answer":"ABD"},{"id":1142,"type":"multi","cat":"领航与任务规划","stem":"航点类型指的是到达该航点时的动作类型，分为（）。","A":"起飞模式","B":"途径模式","C":"巡航模式","D":"着陆模式","answer":"BCD"},{"id":1143,"type":"multi","cat":"基础概念","stem":"无人机飞行前需要检查的项目有（）","A":"电池电量","B":"螺旋桨安装","C":"飞控系统","D":"遥控器信号","answer":"ABCD"},{"id":1144,"type":"multi","cat":"航空气象","stem":"影响无人机飞行安全的气象因素有（）","A":"风速","B":"温度","C":"湿度","D":"能见度","answer":"ABCD"},{"id":1145,"type":"multi","cat":"基础概念","stem":"多轴飞行器的优点包括（）","A":"垂直起降","B":"操作简单","C":"续航时间长","D":"可悬停","answer":"ABD"},{"id":1146,"type":"multi","cat":"基础概念","stem":"无人机在飞行中遇到的常见故障有（）","A":"电机故障","B":"电池故障","C":"信号丢失","D":"螺旋桨损坏","answer":"ABCD"},{"id":1147,"type":"multi","cat":"基础概念","stem":"无人机的应用领域包括（）","A":"物流配送","B":"测绘地理信息","C":"环境监测","D":"应急救援","answer":"ABCD"},{"id":1148,"type":"multi","cat":"设备与维护","stem":"无人机的电池使用注意事项有（）","A":"避免过度放电","B":"避免高温存放","C":"定期充电保养","D":"不同容量电池混用","answer":"ABC"},{"id":1149,"type":"multi","cat":"基础概念","stem":"以下哪些情况会导致无人机信号干扰（）","A":"附近有高压电线","B":"周围有大量金属物体","C":"有其他无线设备工作","D":"飞行高度过高","answer":"ABC"},{"id":1150,"type":"multi","cat":"基础概念","stem":"多轴飞行器的飞行模式有（）","A":"手动模式","B":"自动模式","C":"跟随模式","D":"返航模式","answer":"ABCD"},{"id":1151,"type":"multi","cat":"基础概念","stem":"无人机飞行过程中，出现以下哪些情况需要立即降落（）","A":"电机冒烟","B":"电池过热","C":"信号持续丢失","D":"飞行姿态异常","answer":"ABCD"},{"id":1152,"type":"multi","cat":"设备与维护","stem":"无人机的飞控系统包含的主要部件有（）","A":"主控板","B":"传感器","C":"陀螺仪","D":"加速度计","answer":"ABCD"},{"id":1153,"type":"multi","cat":"操纵与飞行技术","stem":"无人机第四转弯后，有些情况下收油门的时机应当延迟，收油门的动作应适当减慢。它们是（）","A":"下滑点在预定下滑点的后面","B":"当时的高度低于预定高度","C":"速度小、下沉快","D":"逆风较大","answer":"ABCD"},{"id":1154,"type":"multi","cat":"基础概念","stem":"安装固定翼无人机时，以下（）说法是正确的。","A":"左右机翼安装角要一致","B":"水平尾翼和机翼的安装角要一致","C":"单垂尾飞机的垂直尾翼和水平尾翼夹角成90度","D":"左右垂起臂中心线应保证对称平行","answer":"ABCD"},{"id":1155,"type":"multi","cat":"基础概念","stem":"无人机资质培训模拟器训练时，主要采取以下训练方法（）","A":"示范演练","B":"辅导训练","C":"小组训练","D":"个人训练","answer":"ABCD"},{"id":1156,"type":"single","cat":"设备与维护","stem":"无人机飞行控制系统（飞控系统）的核心作用是？","A":"稳定无人机飞行姿态并控制飞行轨迹","B":"提供动力输出以驱动无人机前进","C":"接收并执行地面站的所有指令","D":"存储飞行过程中的所有传感器数据","answer":"A","exp":"本题考察无人机系统组成知识点，正确答案为A。飞控系统通过传感器（如陀螺仪、加速度计）实时感知无人机姿态，通过控制算法调整电机转速或舵面（如多旋翼调整各电机功率），实现姿态稳定（如悬停、俯仰、偏航）并执行预设飞行轨迹。选项B是动力系统（电机、电调）的功能；选项C是遥控器/地面站的功能；选项D是数据记录模块的功能，非飞控核心作用。"},{"id":1157,"type":"single","cat":"法规与空域","stem":"根据《民用无人驾驶航空器实名制登记管理规定》，无人机在以下哪个区域飞行时，无需向空管部门申请空域许可？","A":"机场净空区外围5公里范围内","B":"城市人口密集区域上空","C":"国家重点文物保护单位上空","D":"海拔1000米以下的偏远山区（非军事、非管制区域）","answer":"D","exp":"根据民航法规，在非管制空域（如偏远山区、无人区等）飞行，若满足重量、高度等限制，无需申请空域许可。A、B、C选项均属于管制或限制飞行区域（机场净空区、人口密集区、重点文物区），需提前申请空域许可。D选项偏远山区（非军事、非管制区域）属于典型的低风险、非管制空域，符合条件。"},{"id":1158,"type":"single","cat":"基础概念","stem":"起飞前对无人机进行检查时，以下哪项是必须重点确认的？","A":"电池电压是否在安全范围内","B":"地面是否有无关人员停留","C":"遥控器天线是否完全展开","D":"无人机是否已完成实名登记注册","answer":"A","exp":"本题考察无人机飞行前检查的关键项目。起飞前必须确认电池电量充足（电压在安全范围），否则可能因电量不足导致飞行中失控。B选项属于环境安全检查（需确保周围无人员），但非设备本身检查项；C选项遥控器天线展开与否不影响核心功能；D选项实名登记为法规要求，与起飞前设备检查无关，因此A为正确答案。"},{"id":1159,"type":"single","cat":"设备与维护","stem":"起飞前对无人机电池进行检查时，以下哪项是必须重点关注的？","A":"电池外观是否有鼓包或漏液","B":"遥控器信号强度","C":"任务载荷是否安装牢固","D":"图传设备是否正常","answer":"A","exp":"本题考察无人机飞行前检查要点知识点。正确答案为A。分析：A选项电池外观是否有鼓包或漏液是电池检查的核心，鼓包或漏液可能导致电池短路、起火或爆炸，属于严重安全隐患；B选项遥控器信号强度属于飞行控制系统检查，与电池无关；C选项任务载荷是否安装牢固属于任务系统检查；D选项图传设备是否正常属于通信系统检查，均非电池检查重点。"},{"id":1160,"type":"single","cat":"飞行原理","stem":"无人机飞行时，旋翼产生升力的主要物理原理是基于哪个定律？","A":"伯努利原理","B":"牛顿第三定律","C":"万有引力定律","D":"楞次定律","answer":"A","exp":"本题考察旋翼升力产生的物理原理，正确答案为A。伯努利原理指出流体（空气）流速越快，压强越小。无人机旋翼高速旋转时，叶片上方空气流速快、压强低，下方流速慢、压强大，形成向上的压力差（升力）。选项B牛顿第三定律解释了旋翼对空气的作用力与反作用力，是升力的间接来源但非主要原理；选项C万有引力是重力来源，与升力无关；选项D楞次定律是电磁感应现象，与升力无关。"},{"id":1161,"type":"single","cat":"法规与空域","stem":"无人机驾驶员执照的有效期及签注要求是？","A":"6年，每2年进行签注","B":"5年，每年进行签注","C":"8年，每3年进行签注","D":"10年，无需签注","answer":"A","exp":"本题考察无人机驾驶员执照管理知识点。根据民航局规定，无人机驾驶员执照有效期为6年，需每2年进行签注（复训）以保持资质有效。选项B错误在于有效期5年及每年签注周期不符合规定；选项C错误为8年有效期及3年签注周期；选项D错误为10年有效期且无需签注，均不符合法规要求。"},{"id":1162,"type":"single","cat":"设备与维护","stem":"当无人机动力系统突发故障（如电机停止运转）时，正确的处置措施是？","A":"立即操控无人机迫降在人员密集区域以减少损失","B":"持续尝试反复开关遥控器重启动力系统","C":"保持飞行姿态，优先选择无障碍物的空旷区域迫降","D":"继续尝试通过地面站指令强制无人机升空脱离危险","answer":"C","exp":"本题考察应急处置原则知识点。动力故障时，首要原则是安全优先：A错误（人员密集区迫降易造成伤亡）；B错误（反复重启可能导致电池耗尽或二次故障）；D错误（动力失效无法强制升空）；C正确（利用剩余动能寻找安全区平稳迫降，避免失控风险）。"},{"id":1163,"type":"single","cat":"法规与空域","stem":"在以下哪种情况下，无人机驾驶员必须向空管部门申请飞行空域许可？","A":"在机场净空区5公里范围内飞行","B":"在人口密集的城市中心区飞行","C":"在自然保护区核心区上空飞行","D":"以上均不需要申请","answer":"A","exp":"本题考察无人机飞行空域申请要求。根据《民用无人驾驶航空器实名制登记管理规定》，机场净空区（通常机场周边5公里范围内）属于敏感空域，飞行前必须向空管部门申请许可。B选项城市中心区人口密集区域为禁飞区（除非特殊申请）；C选项自然保护区核心区禁止任何飞行活动；D选项与法规要求矛盾。因此正确答案为A。"},{"id":1164,"type":"single","cat":"领航与任务规划","stem":"当无人机GPS信号突然失灵时，以下哪种操作是正确的应急措施？","A":"立即执行返航操作","B":"切换至姿态模式并保持手动控制","C":"关闭无人机电源并迫降","D":"继续使用自动避障功能飞行","answer":"B","exp":"本题考察无人机GPS失灵时的应急处置知识点。GPS失灵后，无人机失去卫星定位，需切换至姿态模式（手动模式），依靠飞控系统的姿态传感器（陀螺仪、加速度计）保持稳定飞行，避免因失控导致坠机。A选项中GPS失灵时无法准确执行返航；C选项关闭电源会直接导致无人机坠落；D选项自动避障功能依赖GPS定位数据，失灵后无法正常工作。因此正确答案为B。"},{"id":1165,"type":"single","cat":"操纵与飞行技术","stem":"无人机飞行时，负责稳定飞行姿态、执行飞控指令（如悬停、转向）的核心系统是？","A":"飞控系统","B":"动力系统","C":"图传系统","D":"遥控系统","answer":"A","exp":"本题考察无人机系统组成知识点。飞控系统（飞行控制系统）是无人机的核心控制系统，通过传感器实时监测姿态参数（如俯仰角、滚转角），并通过控制算法稳定飞行姿态、执行预设或遥控指令。选项B（动力系统）负责提供飞行动力，C（图传系统）用于传输航拍画面，D（遥控系统）仅负责地面指令传输，均不具备稳定飞行姿态的功能。"},{"id":1166,"type":"single","cat":"法规与空域","stem":"根据中国民航局规定，以下哪种无人机驾驶员必须持相应执照？","A":"最大起飞重量＞7千克","B":"最大起飞重量＞15千克","C":"最大起飞重量＞25千克","D":"最大起飞重量＞5千克","answer":"B","exp":"本题考察无人机驾驶员执照适用条件。根据民航局规定，最大起飞重量＞15千克的民用无人机（轻型或微型）需驾驶员持照；A选项7千克以下属于轻型无人机，通常无需执照；C、D选项数值不符合民航局明确规定的执照适用阈值，因此正确答案为B。"},{"id":1167,"type":"single","cat":"基础概念","stem":"无人机起飞前，以下哪项检查是确保飞行安全的首要步骤？","A":"检查螺旋桨是否安装牢固且无损坏","B":"检查无人机电池电量是否充足","C":"检查飞行场地是否有无关人员和障碍物","D":"检查遥控器与无人机的连接是否正常","answer":"B","exp":"本题考察无人机起飞前检查流程。电池电量不足（B）直接导致飞行中失电坠机，是最致命风险；A（螺旋桨）、C（场地）、D（连接）均为重要检查项，但电池电量是飞行动力的基础，无电则无法飞行。因此首要步骤为B。"},{"id":1168,"type":"single","cat":"领航与任务规划","stem":"当无人机在飞行中突然发生GPS信号丢失时，应优先采取的处置措施是？","A":"立即关闭电源迫降","B":"尝试切换至手动模式并执行返航操作","C":"继续保持自动模式并尝试悬停","D":"加大油门爬升以摆脱信号干扰","answer":"B","exp":"本题考察无人机应急处置知识点。GPS信号丢失后，飞控系统可能因定位失效导致失控风险。此时优先操作：①切换至手动模式（选项B，手动模式下可通过遥控器直接控制无人机姿态，避免自动模式的不可控性）；②执行返航操作（利用返航点记忆功能返回起飞点，确保安全）。选项A（关闭电源）会导致无人机无动力坠落，损坏设备；选项C（继续自动模式）可能因GPS失效引发剧烈晃动或直接坠机；选项D（加大油门爬升）会增加失控概率且无法解决信号问题。因此正确选项为B。"},{"id":1169,"type":"single","cat":"法规与空域","stem":"根据民航局规定，重量大于多少克的民用无人机需在实名登记系统中进行登记备案？","A":"250克","B":"200克","C":"500克","D":"1000克","answer":"A","exp":"本题考察无人机实名登记法规知识点。根据《民用无人驾驶航空器实名制登记管理规定》，重量大于0.25千克（即250克）的民用无人机需在民航局无人机实名登记系统中进行实名登记，未登记不得飞行。选项B（200克）低于规定阈值，选项C（500克）和D（1000克）属于更大重量级别，均非法规规定的最低登记标准，故正确答案为A。"},{"id":1170,"type":"single","cat":"基础概念","stem":"在视距内飞行时，微型无人机的最大允许飞行高度通常不超过以下哪个数值？","A":"50米","B":"100米","C":"120米","D":"150米","answer":"C","exp":"本题考察无人机飞行高度限制知识点。根据《民用无人驾驶航空器实名制登记管理规定》及飞行安全标准，微型无人机在视距内飞行时，为避免与其他飞行器冲突，最大高度限制为120米。选项A（50米）和B（100米）过低，不符合实际操作标准；选项D（150米）超过视距内安全高度范围，可能导致空域冲突风险。"},{"id":1171,"type":"single","cat":"设备与维护","stem":"在无人机飞行过程中，若突然发生图传信号中断，应优先采取以下哪种措施？","A":"立即尝试手动操作无人机继续飞行","B":"执行紧急返航程序并远离人群","C":"增大油门使无人机快速爬升以恢复信号","D":"关闭遥控器电源后重新开机","answer":"B","exp":"本题考察飞行中突发故障的应急处置。图传信号中断可能意味着无人机失去控制或失联，此时优先执行紧急返航程序并远离人群，避免坠落在人员密集区域。A选项手动操作可能因失去信号无法控制；C选项加大油门可能加剧失控风险；D选项重启遥控器无法解决信号中断问题，因此B为正确答案。"},{"id":1172,"type":"single","cat":"基础概念","stem":"当无人机在飞行过程中突然与地面站失去通信连接时，驾驶员应优先采取的措施是？","A":"立即操作无人机执行返航指令","B":"尝试手动重新连接地面站","C":"启动紧急迫降程序（如迫降在安全区域）","D":"保持当前高度等待通信自动恢复","answer":"C","exp":"本题考察无人机失联应急处理。正确答案为C，失联时无人机可能因姿态失控或位置未知，无法执行返航指令（选项A）；手动重新连接需地面站支持，无法立即完成（选项B）；等待恢复可能导致无人机持续失控或坠机（选项D）。启动紧急迫降（如选择空旷安全区域迫降）是确保人员和设备安全的优先措施。"},{"id":1173,"type":"single","cat":"设备与维护","stem":"无人机飞行控制系统（飞控系统）的核心功能是？","A":"接收并执行遥控器指令","B":"稳定无人机姿态与飞行参数","C":"为动力系统提供电力","D":"记录飞行轨迹数据","answer":"B","exp":"正确答案为B，飞控系统通过传感器感知无人机姿态，通过PID算法稳定姿态、保持航向与高度；A选项是遥控器的功能；C选项为动力系统供电是电池模块的功能；D选项记录飞行数据通常由飞行数据记录器或地面站软件完成，非飞控核心功能。"},{"id":1174,"type":"single","cat":"航空气象","stem":"以下哪种气象条件下，无人机起飞前应暂停飞行计划？","A":"能见度300米","B":"风速10米/秒","C":"中度雾霾（能见度100-200米）","D":"温度15℃","answer":"C","exp":"本题考察无人机飞行环境知识点。A选项能见度300米在开放空域可满足目视飞行基本要求；B选项风速10米/秒（约5级风），多数消费级无人机抗风等级可达8-10米/秒，可尝试起飞；C选项中度雾霾（能见度100-200米）会严重降低无人机视觉避障系统的可靠性，增加碰撞风险，禁止起飞；D选项温度15℃属于常规环境，不影响飞行安全。正确答案为C。"},{"id":1175,"type":"single","cat":"基础概念","stem":"当无人机突然失控并可能坠向人群时，应优先采取的措施是？","A":"立即启动返航程序","B":"手动切断动力开关","C":"快速远离并远离人群","D":"尝试手动遥控修正姿态","answer":"C","exp":"本题考察无人机应急处置原则。安全优先原则下，失控无人机威胁人群安全时，首要任务是避免人员伤亡，应迅速远离危险区域。选项A（返航）可能因失控无法执行，B（切断动力）若直接坠落仍伤人，D（手动遥控）在失控状态下难以操作。因此正确答案为C。"},{"id":1176,"type":"single","cat":"基础概念","stem":"在下列哪种天气条件下，无人机应禁止起飞？","A":"风速达到6级（10.8-13.8m/s）","B":"能见度低于1000米","C":"有持续雷雨活动","D":"以上所有情况","answer":"D","exp":"本题考察无人机飞行的气象安全要求。A选项中，多数消费级无人机安全风速上限为5级（8.3-10.7m/s），6级风易导致无人机姿态失控；B选项能见度低于1000米时，目视避障和空域识别能力下降，存在碰撞风险；C选项雷雨天气伴随雷击、强气流和电磁干扰，会直接威胁设备安全和飞行稳定性。因此D选项以上所有情况均为禁止起飞的条件。"},{"id":1177,"type":"single","cat":"法规与空域","stem":"在机场净空保护区域内进行无人机飞行时，必须遵守的规定是？","A":"提前向当地空管部门申请并获得空域使用许可","B":"可在白天无需报备直接起飞","C":"仅需在夜间飞行前向机场塔台报备","D":"允许在无人看管的情况下进行飞行","answer":"A","exp":"本题考察无人机空域使用法规知识点。机场净空区属于受管制的空域，任何单位和个人进入该区域飞行均需提前向当地空管部门申请并获得空域使用许可（如飞行计划审批），因此A正确。B选项错误，因净空区禁止未经许可飞行；C选项错误，夜间飞行同样需要提前申请，且仅报备不足以获得合法飞行权限；D选项错误，无人看管飞行不符合安全操作规范，存在碰撞风险。"},{"id":1178,"type":"single","cat":"基础概念","stem":"以下哪项属于无人机明确禁止飞行的区域？","A":"军事管理区上空","B":"民用机场净空保护区域","C":"人口密集的城市中心区域","D":"以上均属于禁飞区","answer":"D","exp":"本题考察无人机禁飞区法规知识点。根据中国民航局及空域管理规定，军事管理区（A）、机场净空区（B）、人口密集区（C）均属于禁飞区或限制飞行区域，未经审批不得进入。因此A、B、C均为禁飞区，正确选项为D。"},{"id":1179,"type":"single","cat":"基础概念","stem":"起飞前检查中，必须重点确认的项目是？","A":"无人机电池剩余电量（≥80%）","B":"地面是否有无关人员停留","C":"起飞场地是否为硬质地面","D":"无人机GPS信号是否显示为红色","answer":"A","exp":"本题考察无人机飞行前检查要点。电池电量是飞行安全的基础，起飞前必须确保电池剩余电量≥80%（微型机可适当放宽至70%），否则可能因电量不足导致中途失压坠机。B选项地面无关人员属于场地安全检查，需在起飞前完成但非必须重点确认的核心项目；C选项硬质地面仅针对部分固定翼机型，且非普适性要求；D选项GPS信号红色通常表示信号弱或无定位，属于检查内容但优先级低于电池电量，故正确答案为A。"},{"id":1180,"type":"single","cat":"领航与任务规划","stem":"无人机飞行中突发GPS信号丢失时，正确的处置措施是？","A":"立即切换至手动模式并快速拉升高度","B":"切换至姿态模式，保持悬停并寻找开阔区域","C":"继续使用GPS模式尝试返航","D":"直接关闭电源迫降","answer":"B","exp":"GPS丢失后，飞控系统会自动切换至姿态模式（依赖惯性测量单元IMU），此时应保持悬停并寻找开阔区域恢复信号或手动操作降落。A选项手动拉升高度可能因失去定位导致失控；C选项GPS模式已失效无法使用；D选项直接关闭电源易因惯性导致坠机，非安全处置。"},{"id":1181,"type":"single","cat":"基础概念","stem":"无人机飞行控制系统的核心组成部分是？","A":"飞控系统","B":"导航模块","C":"动力系统","D":"遥控系统","answer":"A","exp":"本题考察无人机系统结构。飞控系统（FlightControlSystem）是无人机飞行控制的核心，通过传感器采集数据、处理器计算姿态并输出指令，直接控制无人机飞行姿态和轨迹。B选项导航模块、C选项动力系统、D选项遥控系统均为无人机系统的子模块，非核心控制单元，因此正确答案为A。"},{"id":1182,"type":"single","cat":"设备与维护","stem":"无人机飞行中遭遇动力系统突发故障（如电机停转），以下哪种处置方式最安全？","A":"立即尝试重启发动机（螺旋桨）","B":"保持当前高度继续飞行至目的地","C":"迅速选择空旷无人员区域迫降","D":"立即切换至备用电池并返航","answer":"C","exp":"本题考察动力故障处置原则。A选项：若为螺旋桨断裂或电机卡死，重启无法实现，且盲目重启可能导致二次事故；B选项：持续飞行会因无动力急速坠落，增加风险；D选项：返航需动力维持，无动力时无法操作；C选项：优先确保安全，选择空旷区域迫降可避免人员和财产损失，符合安全第一原则。"},{"id":1183,"type":"single","cat":"设备与维护","stem":"多旋翼无人机飞行中突然出现单个电机停转，以下处置方式最合理的是？","A":"立即尝试切换至备用电池并迫降","B":"保持操控尝试手动降落至安全区域","C":"继续飞行至开阔地后紧急迫降","D":"重启飞控系统并继续执行任务","answer":"B","exp":"本题考察多旋翼无人机单电机故障应急处置。正确答案为B，多旋翼无人机单个电机停转后，机身会因力矩失衡倾斜，此时应立即手动操控剩余电机产生反扭矩，逐步降低高度并降落至安全区域。A选项切换备用电池适用于电池故障，与电机故障无关；C选项继续飞行会加剧失衡风险；D选项飞控系统重启无法解决电机硬件故障，且可能导致二次失控。"},{"id":1184,"type":"single","cat":"基础概念","stem":"无人机实现自主稳定飞行、姿态控制的核心系统是？","A":"飞控系统","B":"动力系统","C":"图传系统","D":"悬停系统","answer":"A","exp":"飞控系统（飞行控制系统）是无人机的大脑，通过传感器实时监测姿态、高度、速度等数据，自动调节电机输出实现稳定飞行和航线规划。B选项动力系统仅负责提供飞行动力；C选项图传系统用于传输航拍画面，不涉及飞行控制；D选项悬停是飞控系统实现的功能之一，非独立系统。"},{"id":1185,"type":"single","cat":"基础概念","stem":"起飞前无人机检查中，以下哪项属于必须确认的关键系统状态？","A":"电池剩余电量及电压","B":"飞控系统传感器校准状态","C":"遥控器与无人机的通讯信号强度","D":"以上均为必须确认项","answer":"D","exp":"本题考察无人机起飞前的系统检查要点。A选项电池状态直接决定飞行续航和稳定性，电量不足会导致突然失电；B选项飞控传感器（如GPS、IMU）校准失效会引发飞行姿态失控；C选项通讯信号弱或丢失会导致失联。三者均为起飞前必须确认的核心系统状态，缺一不可，故D正确。"},{"id":1186,"type":"single","cat":"法规与空域","stem":"以下哪种场景属于无人机法定禁飞区域？","A":"城市中心广场（非特殊活动时段）","B":"距离民用机场跑道入口5公里的空域","C":"国家测绘地理信息局划定的测绘作业区","D":"军事管理区外围1公里范围","answer":"B","exp":"本题考察无人机禁飞区法规知识点。根据《民用无人驾驶航空器实名制登记管理规定》及《无人驾驶航空器经营性飞行活动管理办法》，民用机场净空区（通常为机场跑道两端及周边3-10公里范围内）属于法定禁飞区，选项B中距离跑道入口5公里符合净空区范围。选项A错误，城市中心广场可能受临时管制但非法定禁飞；选项C错误，测绘作业区通常需提前申请空域；选项D错误，军事管理区外围1公里无明确禁飞规定，因此正确答案为B。"},{"id":1187,"type":"single","cat":"航空气象","stem":"在视距内飞行时，小型多旋翼无人机起飞阶段的最大允许风速通常为？","A":"2级（≤1.6m/s）","B":"3级（3.4-5.4m/s）","C":"4级（5.5-7.9m/s）","D":"5级（8.0-10.7m/s）","answer":"B","exp":"本题考察无人机起飞风速限制知识点。小型多旋翼无人机起飞需避免强风干扰，3级风（风速3.4-5.4m/s）为安全范围。选项A（2级）过于保守；选项C（4级）和D（5级）风速过大，易导致无人机偏航、失控甚至坠毁，不符合安全规范。"},{"id":1188,"type":"single","cat":"基础概念","stem":"无人机起飞前，确保飞行安全的最重要基础检查环节是？","A":"检查遥控器与无人机的通讯连接是否正常","B":"检查无人机机身是否有明显损伤","C":"检查螺旋桨安装是否牢固且无变形","D":"检查地面是否有障碍物","answer":"C","exp":"本题考察无人机起飞前检查知识点。螺旋桨作为直接产生升力的部件，安装不牢固或变形会导致飞行中脱落、失衡甚至失控，是最基础且关键的安全隐患点；A（通讯检查）、B（机身损伤检查）、D（地面障碍物检查）均为重要检查项目，但螺旋桨安装质量直接决定飞行稳定性和安全性，是所有检查中最优先的基础环节，故正确答案为C。"},{"id":1189,"type":"single","cat":"基础概念","stem":"起飞前无人机检查中，以下哪项是必须检查的？","A":"螺旋桨叶片是否有裂纹或变形","B":"无人机内所有电子元件是否防水","C":"遥控器电池剩余电量是否充足","D":"飞行空域的实时天气情况","answer":"A","exp":"本题考察起飞前无人机检查要点。起飞前必须检查无人机硬件状态，螺旋桨作为动力传输关键部件，裂纹或变形会导致飞行失衡甚至坠机，属于必查项。选项B（防水检查非起飞前必查）、C（遥控器电量属于飞行准备阶段）、D（天气状况需提前查询而非起飞前检查无人机）均不符合检查要求。"},{"id":1190,"type":"single","cat":"航空气象","stem":"以下哪种气象条件下，无人机驾驶员应禁止起飞？","A":"能见度5公里（视距内标准）","B":"风速8m/s（多旋翼安全阈值内）","C":"轻度霾（能见度≥3公里）","D":"雷暴天气（伴随闪电、强风）","answer":"D","exp":"本题考察飞行气象条件知识点。雷暴天气伴随强对流、雷击及乱流，易导致无人机失控或坠机，属于绝对禁止起飞的气象条件。A/B/C项均为允许飞行的气象条件（能见度≥5公里满足视距标准，风速≤10m/s、轻度霾对飞行影响小）。因此正确答案为D。"},{"id":1191,"type":"single","cat":"基础概念","stem":"在进行无人机起飞和降落时，为确保安全，应与人群保持至少多少米的水平距离？","A":"5米","B":"10米","C":"15米","D":"20米","answer":"B","exp":"本题考察飞行安全操作规范。根据《民用无人驾驶航空器实名制登记管理规定》及飞行安全准则，起飞和降落阶段无人机操控难度较高，与人群需保持至少10米水平距离，以避免螺旋桨伤人或坠机风险。选项A距离过近，安全系数不足；C、D虽安全冗余更高，但法规标准中明确的基础安全距离为10米。故正确答案为B。"},{"id":1192,"type":"single","cat":"设备与维护","stem":"无人机飞行控制系统（飞控系统）的核心功能不包括以下哪项？","A":"稳定飞行姿态","B":"自主起飞与降落","C":"实时图像传输","D":"调整飞行参数","answer":"C","exp":"本题考察无人机系统组成知识点。飞控系统核心功能包括稳定飞行姿态（通过PID算法控制）、自主起飞/降落（预设控制逻辑）、调整飞行参数（如高度、速度）；而实时图像传输（FPV图传）属于独立的图传系统功能，由图传模块实现，非飞控系统范畴。因此正确答案为C。"},{"id":1193,"type":"single","cat":"领航与任务规划","stem":"当无人机在视距内飞行时突然发生GPS信号丢失且无法手动控制，最可能触发的安全机制是？","A":"无人机自动迫降在最近障碍物上","B":"无人机自动触发失控返航功能并悬停","C":"无人机立即切换至手动油门模式","D":"无人机持续向地面发送紧急求救信号","answer":"B","exp":"本题考察无人机失控处理机制。GPS丢失后，多数无人机默认触发失控返航（B），返回起飞点上空悬停等待指令，避免因失去定位导致坠机。A选项迫降非安全机制；C选项手动模式在GPS丢失后无法稳定控制；D选项无人机通常无独立求救信号发送功能，依赖地面站指令。"},{"id":1194,"type":"single","cat":"基础概念","stem":"根据中国民航局规定，最大起飞重量在7千克至116千克之间的民用无人机属于哪一类？","A":"微型","B":"轻型","C":"小型","D":"大型","answer":"B","exp":"本题考察无人机分类知识点。中国民航局对民用无人机的分类标准为：微型无人机（最大起飞重量≤7千克）、轻型无人机（7千克＜最大起飞重量≤116千克）、小型无人机（116千克＜最大起飞重量≤5700千克）、大型无人机（最大起飞重量＞5700千克）。选项A（微型）重量范围错误；选项C（小型）重量下限错误；选项D（大型）重量范围远超题干描述。故正确答案为B。"},{"id":1195,"type":"single","cat":"法规与空域","stem":"在我国，以下哪种空域类型的无人机飞行通常需要提前向空管部门申请飞行计划？","A":"开放空域","B":"限制空域","C":"隔离空域","D":"通用空域","answer":"B","exp":"开放空域（如低空空域试点区域）无需申请飞行计划；限制空域（如机场净空区周边）需提前申请；隔离空域（军事禁区、禁飞区）严禁飞行。因此本题正确答案为B选项。"},{"id":1196,"type":"single","cat":"基础概念","stem":"起飞前对无人机进行检查时，以下哪项属于必须确认的关键内容？","A":"电池剩余电量及电压","B":"地面是否有无关人员","C":"无人机是否已完成注册登记","D":"图传设备是否连接正常","answer":"A","exp":"本题考察无人机起飞前的关键检查项目。电池是无人机动力来源，起飞前必须确认电池电压正常（如锂电池需达到额定电压，避免电量不足导致飞行中失控），故A为正确答案。B选项属于飞行空域安全确认，非无人机本身检查；C选项登记信息为静态备案，无需起飞前实时检查；D选项图传设备故障通常不影响起飞，仅影响作业时的图像传输。"},{"id":1197,"type":"single","cat":"基础概念","stem":"以下哪个区域属于无人机严格禁止飞行的区域？","A":"民用机场净空保护区域","B":"城市中心广场","C":"偏远山区无人区","D":"乡村农田上空","answer":"A","exp":"本题考察禁飞区法规。民用机场净空区（A）是民航安全的核心保障区域，根据《中华人民共和国民用航空法》，严禁任何无人机进入。城市中心广场（B）通常有临时禁飞规定，但优先级低于机场净空区；偏远山区（C）和乡村农田（D）在符合法规条件下可合法飞行。"},{"id":1198,"type":"single","cat":"基础概念","stem":"在城市人口密集区域飞行无人机时，应特别注意避开以下哪个区域？","A":"城市公园","B":"机场净空区","C":"军事管理区","D":"城市绿地","answer":"B","exp":"本题考察飞行空域安全知识点。机场净空区是为保障机场起降安全划定的严格禁飞区域，根据《民用机场管理条例》，任何单位或个人不得在机场净空区从事影响飞行安全的活动，因此必须避开。选项A城市公园、D城市绿地在符合条件下可飞行；选项C军事管理区属于禁飞区，但题目强调城市人口密集区域，军事管理区多位于非城市核心区，而机场净空区常分布于城市周边或内部，更需特别注意。故正确答案为B。"},{"id":1199,"type":"single","cat":"法规与空域","stem":"根据《民用无人驾驶航空器实名制登记管理规定》，重量大于（）千克的民用无人机需要进行实名登记。","A":"0.25","B":"0.5","C":"1.0","D":"2.5","answer":"A","exp":"本题考察无人机实名登记的法规知识点，正确答案为A。根据规定，重量≥0.25千克（250克）的民用无人机必须进行实名登记，这是保障飞行安全和追溯管理的基础。选项B（0.5千克）通常是超视距飞行的重量限制标准，选项C（1.0千克）和D（2.5千克）均高于实名登记的法定阈值，因此错误。"},{"id":1200,"type":"single","cat":"基础概念","stem":"在以下哪种区域飞行时，无人机驾驶员必须提前向空管部门申请并获得飞行许可？","A":"城市中心广场","B":"机场净空区","C":"农村田野","D":"偏远山区","answer":"B","exp":"本题考察无人机禁飞区管理知识点。机场净空区属于受严格管制的空域，任何未经批准的无人机飞行都可能干扰机场正常运行，必须提前向空管部门申请并获得许可。选项A（城市中心广场）通常属于城市禁飞区，以限高/禁飞为主，无需单独申请；选项C（农村田野）和D（偏远山区）一般无需特殊申请，符合法规即可飞行。"},{"id":1201,"type":"single","cat":"设备与维护","stem":"起飞前检查无人机电池时，以下哪项是最关键的安全检查内容？","A":"检查电池外观是否有鼓包或破损","B":"确认电池电压在标称电压±5%范围内","C":"仅需检查电池电量指示灯显示为绿色","D":"确保电池固定卡扣无松动","answer":"B","exp":"本题考察飞行前电池检查知识点。电池电压直接决定动力输出和续航能力，电压不足会导致飞行失控，是最核心的安全参数；外观检查（A）可辅助判断电池状态但非核心；电量指示灯可能受虚电影响，电压测量更准确；固定卡扣（D）属于机身结构检查，非电池安全检查的核心内容。"},{"id":1202,"type":"single","cat":"领航与任务规划","stem":"无人机飞行中突然丢失GPS信号时，最安全的应急操作是？","A":"利用返航点记忆功能执行一键返航","B":"手动加大油门保持悬停","C":"尝试切换至‘姿态模式’手动控制","D":"立即关闭无人机电源迫降","answer":"A","exp":"本题考察无人机应急处置知识点。GPS丢失后，无人机可能进入失控或自稳模式，此时最安全的操作是利用预设的返航点（如起飞点）执行一键返航（通常由飞控系统自动完成，避免手动操作失误）。B选项手动加大油门可能因失去定位导致无人机失控；C选项姿态模式下无GPS辅助，手动控制难度极高，易碰撞；D选项立即迫降会造成设备损坏或人员风险。因此正确答案为A。"},{"id":1203,"type":"single","cat":"设备与维护","stem":"当无人机突然失控（如飞控系统故障）时，以下哪项操作是正确的应急处置措施？","A":"立即拉满油门使无人机快速爬升","B":"尝试通过遥控器执行手动返航程序","C":"切断无人机遥控器信号以停止飞行","D":"立即弃机远离人群，放弃无人机","answer":"B","exp":"本题考察无人机应急处置知识点。手动返航是失控时最直接的安全措施，可快速恢复无人机控制并返回安全区域；拉满油门（A）可能加剧失控或导致动力过载；切断遥控器信号（C）无效，无人机可能因惯性继续飞行；弃机（D）会造成设备损失，且未优先保障安全距离。"},{"id":1204,"type":"single","cat":"法规与空域","stem":"视距内驾驶员执照（驾驶员执照）的适用空域范围是？","A":"半径500米、高度120米以下的目视范围内空域","B":"任何空域（无需额外审批）","C":"仅允许在夜间飞行（需额外夜间资质）","D":"必须在有管制员指挥的空域飞行","answer":"A","exp":"本题考察无人机驾驶员执照分类知识点。视距内驾驶员执照（驾驶员执照）的核心要求是驾驶员需目视范围内（通常半径≤500米、高度≤120米）飞行，A选项描述符合规定。B选项错误，任何空域飞行需超视距执照或特殊审批；C选项错误，夜间飞行需额外夜间资质，与视距内执照无关；D选项错误，视距内飞行无需管制员指挥。"},{"id":1205,"type":"single","cat":"操纵与飞行技术","stem":"无人机在稳定悬停状态时，其主要受力平衡关系是？","A":"升力>重力，推力>阻力","B":"升力=重力，推力=阻力","C":"升力<重力，推力<阻力","D":"升力=重力，推力=0","answer":"B","exp":"悬停时无人机处于相对静止的平衡状态，竖直方向上升力与重力大小相等（F升=G），水平方向上（若考虑前进/后退）推力与阻力大小相等（F推=F阻）。A选项升力大于重力会导致上升，推力大于阻力会导致前进，不符合悬停；C选项升力小于重力会下降，推力小于阻力会减速，错误；D选项推力=0仅适用于完全无风的理想状态，实际微型无人机仍需微小推力平衡气流阻力，且推力为零无法维持悬停。"},{"id":1206,"type":"single","cat":"法规与空域","stem":"根据《民用无人驾驶航空器实名制登记管理规定》，微型民用无人机的最大起飞重量限制为多少？","A":"7千克","B":"15千克","C":"116千克","D":"250千克","answer":"A","exp":"本题考察无人机重量分类知识点，正确答案为A。根据中国民航局相关规定，微型民用无人机（microUAV）定义为最大起飞重量≤7千克，轻型无人机（lightUAV）为＞7千克且≤116千克，小型无人机（smallUAV）通常指＞116千克且≤5700千克。选项B无明确对应标准；选项C是轻型无人机的上限；选项D超出了小型无人机的一般范围。"},{"id":1207,"type":"single","cat":"法规与空域","stem":"根据中国民航局相关规定，最大起飞重量超过以下哪个数值的民用无人机需要进行实名登记？","A":"250克","B":"2500克","C":"7000克","D":"15000克","answer":"B","exp":"本题考察无人机实名登记管理知识点。根据规定，最大起飞重量250克以下的民用无人机无需实名登记，250克至2500克的无人机需进行备案，超过2500克（即2.5千克）的无人机必须进行实名登记。选项A（250克）为无需登记的标准，选项C（7000克）和D（15000克）属于需实名登记的更大重量范围，但题目问的是超过多少需要登记，2500克是明确的登记门槛，故正确答案为B。"},{"id":1208,"type":"single","cat":"基础概念","stem":"根据中国民航局对民用无人驾驶航空器的分类标准，最大起飞重量≥25千克的民用无人机属于以下哪一类？","A":"微型无人机","B":"轻型无人机","C":"小型无人机","D":"中型无人机","answer":"C","exp":"本题考察无人机分类知识点。根据民航局规定，微型无人机最大起飞重量＜7千克，轻型无人机7千克≤最大起飞重量＜116千克，小型无人机116千克≤最大起飞重量＜5700千克，中型无人机≥5700千克。25千克属于轻型与小型的重叠区间，但题目中≥25千克更接近小型无人机范畴，故正确答案为C。A、B选项重量范围不符合，D选项重量超限。"},{"id":1209,"type":"single","cat":"基础概念","stem":"根据中国民航局规定，在以下哪种区域飞行时，无人机驾驶员必须提前向当地空管部门申请并获得批准？","A":"城市中心公园","B":"民用机场净空区","C":"偏远山区","D":"军事管理区","answer":"B","exp":"本题考察无人机飞行空域管理知识点。A选项城市中心公园属于限制飞行区（需提前报备但非严格申请）；B选项民用机场净空区是严格管制区域，无人机飞行必须提前向空管部门申请并获批；C选项偏远山区通常属于低空空域开放区域，无需申请；D选项军事管理区属于禁飞区，禁止飞行而非申请。因此正确答案为B。"},{"id":1210,"type":"single","cat":"基础概念","stem":"根据中国民航局对民用无人机的分类标准，最大起飞重量大于7千克但不超过116千克的民用无人机属于以下哪一类？","A":"微型无人机","B":"轻型无人机","C":"小型无人机","D":"中型无人机","answer":"B","exp":"中国民航局对民用无人机的分类标准为：微型无人机（最大起飞重量≤7千克）、轻型无人机（7千克＜最大起飞重量≤116千克）、小型无人机（116千克＜最大起飞重量≤5700千克）、中型无人机（5700千克＜最大起飞重量≤57000千克）、大型无人机（＞57000千克）。因此，A选项（微型）因最大起飞重量≤7千克不符合，C选项（小型）因最大起飞重量＞116千克不符合，D选项（中型）因最大起飞重量＞5700千克不符合，正确答案为B。"},{"id":1211,"type":"single","cat":"基础概念","stem":"当无人机在飞行中出现动力系统故障且无法恢复控制时，应优先采取的措施是？","A":"立即切换至备用电池并尝试手动操控返航","B":"启动紧急迫降程序，选择远离人群、无障碍物的区域","C":"向地面指挥中心发送紧急失联信号后等待指令","D":"持续尝试增大油门使无人机重新升空","answer":"B","exp":"本题考察无人机应急动力故障处置知识点。动力系统故障时，无人机通常会失去升力或姿态控制，选项A切换备用电池可能因故障未排除导致二次失控；选项C等待指令会延误最佳处置时机，增加坠机风险；选项D增大油门可能因动力系统已失效而无效。正确原则是安全第一，立即启动迫降程序，选择开阔无人区域避免伤及他人或设备损坏。"},{"id":1212,"type":"single","cat":"飞行原理","stem":"无人机在静风中保持悬停状态时，其升力与重力的关系是？","A":"升力大于重力","B":"升力等于重力","C":"升力小于重力","D":"无法确定","answer":"B","exp":"本题考察无人机飞行原理。无人机悬停时处于垂直方向平衡状态，根据牛顿第一定律，合力为零。升力作为垂直向上的力，需与垂直向下的重力大小相等、方向相反，才能保持静止。选项A会导致无人机上升，C会导致下降，D不符合物理平衡原理，故正确答案为B。"},{"id":1213,"type":"single","cat":"设备与维护","stem":"当无人机飞行中突然信号丢失（图传中断）且处于失控状态时，最安全的处置措施是？","A":"立即启动返航程序","B":"尝试手动遥控器恢复控制","C":"继续尝试调整飞行参数","D":"保持当前高度等待信号恢复","answer":"A","exp":"本题考察应急处置措施。信号丢失且失控时，无人机无法自主稳定飞行，立即启动返航程序可引导无人机返回预设起飞点附近，避免迷失或坠落。B选项手动控制在失控状态下难度极大；C、D选项无法解决失控问题，可能导致无人机碰撞或坠机。故正确答案为A。"},{"id":1214,"type":"single","cat":"基础概念","stem":"在无人机飞行前，检查‘动力系统’时，需重点关注的是？","A":"电池电量及电机转速","B":"螺旋桨安装牢固性及电池电压","C":"飞控系统传感器校准状态","D":"地面站图传信号强度","answer":"B","exp":"本题考察无人机动力系统检查要点知识点。动力系统核心由电池、电机、螺旋桨组成，检查时需确认螺旋桨无变形/松动（避免飞行中脱落）、电池电压在安全范围（防止供电不足）。选项A（电机转速）需在飞行中监测，非起飞前重点；选项C（飞控传感器校准）属于飞控系统检查内容；选项D（图传信号）属于通信系统检查。因此正确答案为B。"},{"id":1215,"type":"single","cat":"设备与维护","stem":"起飞前检查无人机电池时，不需要重点关注的是？","A":"电池接口是否有松动","B":"电池生产日期","C":"电池外观有无鼓包变形","D":"电池电压是否在正常范围内","answer":"B","exp":"本题考察飞行前电池检查要点。起飞前检查电池需重点关注：A选项电池接口松动可能导致接触不良引发断电；C选项电池鼓包变形存在短路或起火风险；D选项电压异常会导致动力不足或无法启动。而电池生产日期仅反映生产时间，不影响当前飞行安全，无需重点检查。因此正确答案为B。"},{"id":1216,"type":"single","cat":"飞行原理","stem":"在其他条件不变的情况下，无人机平飞时，若空速增大，其升力将如何变化？","A":"增大","B":"减小","C":"不变","D":"不确定","answer":"A","exp":"本题考察无人机升力产生原理。根据升力公式L=1/2ρv²SCL（ρ为空气密度，v为空速，S为机翼面积，CL为升力系数），在ρ、S、CL不变时，升力L与空速v的平方成正比。因此空速增大时，升力必然增大，A选项正确。B选项认为升力减小，违背公式关系；C选项认为不变，忽略了空速对升力的直接影响；D选项错误，因条件不变时空速与升力的关系明确。"},{"id":1217,"type":"single","cat":"基础概念","stem":"当无人机在飞行过程中失去控制信号或出现故障时，自动返回至起飞点附近并降落的功能称为？","A":"自主飞行模式","B":"自动返航功能","C":"失控保护模式","D":"失速恢复模式","answer":"B","exp":"本题考察无人机功能术语。自动返航功能（B）特指无人机在失控、低电量等情况下，按预设逻辑返回起飞点的功能；自主飞行（A）是指按预设航线自主完成任务的通用模式；失控保护（C）是更宽泛的故障应对机制，范围不限于返航；失速恢复（D）针对飞行速度过低的恢复措施，与题意无关。"},{"id":1218,"type":"single","cat":"基础概念","stem":"当无人机在飞行中突然与地面站失去通信连接（失联）时，正确的紧急处置方法是？","A":"立即上升高度至云层以上，扩大通信范围","B":"保持当前飞行姿态，等待无人机自动执行返航程序","C":"持续手动操控无人机，尝试重新锁定信号","D":"直接关闭遥控器电源，确保无人机平稳坠落","answer":"B","exp":"本题考察无人机应急处置流程知识点。根据《民用无人驾驶航空器飞行操作规范》，失联后无人机通常预设失联返航或自动降落程序，保持当前姿态等待指令是最安全的操作。选项A错误，上升高度可能进一步增加通信距离，导致信号更难恢复；选项C错误，手动操控在远距离失联时无法生效；选项D错误，直接关闭电源会导致无人机因惯性失控坠落，且不符合应急处置规范，因此正确答案为B。"},{"id":1219,"type":"single","cat":"领航与任务规划","stem":"当无人机GPS信号突然丢失时，以下哪项操作是最安全合理的？","A":"立即关闭无人机发动机并任其自由坠落","B":"切换至惯性导航模式并优先选择无人群区域安全降落","C":"持续尝试遥控器摇杆校准以恢复GPS信号","D":"继续保持当前航向飞行至预定降落点","answer":"B","exp":"本题考察无人机GPS失灵时的应急操作知识点。无人机通常配置多源导航系统（如GPS、北斗、惯性导航、气压计），当GPS信号丢失时，惯性导航（IMU）可短时维持定位和姿态控制，气压计辅助高度保持。选项A自由坠落可能造成设备损坏或人员伤害；选项C持续校准遥控器无法解决GPS硬件故障；选项D继续飞行至预定点可能因惯性导航误差导致撞障或失联。正确做法是切换至备用导航并优先降落。"},{"id":1220,"type":"single","cat":"基础概念","stem":"无人机起飞前，不需要重点检查的项目是？","A":"电池剩余电量","B":"GPS卫星信号强度","C":"螺旋桨安装是否牢固","D":"地面环境温度","answer":"D","exp":"本题考察起飞前检查要点。电池剩余电量（A）、GPS卫星信号强度（B）、螺旋桨安装牢固性（C）均为影响飞行安全的核心项目，必须严格检查。地面环境温度（D）一般不直接影响无人机起飞性能，属于非必要检查项。"},{"id":1221,"type":"single","cat":"法规与空域","stem":"无人机驾驶员执照的有效期一般为多少年？","A":"2年","B":"3年","C":"4年","D":"5年","answer":"B","exp":"本题考察无人机驾驶员执照有效期知识点。根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》及相关法规，无人机驾驶员执照（合格证）有效期通常为3年，到期前需完成签注或重新考核。选项A（2年）不符合常规有效期设定；选项C（4年）和D（5年）超出法规规定的常见有效期范围，因此正确答案为B。"},{"id":1222,"type":"single","cat":"基础概念","stem":"起飞前检查无人机时，以下哪项属于必须确认的项目？","A":"电池剩余电量是否满足飞行需求","B":"GPS卫星信号是否正常","C":"螺旋桨安装是否牢固无松动","D":"以上都是","answer":"D","exp":"本题考察无人机飞行前检查流程。正确答案为D，起飞前需全面检查：电池电量不足会导致飞行中断；GPS信号异常会引发定位漂移或失控；螺旋桨松动可能在飞行中脱落，造成安全隐患。选项A、B、C均为起飞前关键检查项，缺一不可。"},{"id":1223,"type":"single","cat":"基础概念","stem":"根据中国民航局对民用无人机的分类标准，最大起飞重量大于7千克且小于等于116千克的无人机属于以下哪一类？","A":"微型","B":"轻型","C":"小型","D":"大型","answer":"B","exp":"根据中国民航局分类标准：微型无人机最大起飞重量≤7千克，轻型无人机为7千克以上且≤116千克（不含），小型无人机为116千克以上且≤5700千克，大型无人机重量更大。因此本题正确答案为B选项。"},{"id":1224,"type":"single","cat":"法规与空域","stem":"在我国，以下哪种情况的无人机飞行需要提前向空管部门申请飞行空域许可？","A":"视距内目视飞行","B":"超视距飞行","C":"起飞重量小于7千克","D":"白天在城市上空飞行","answer":"B","exp":"本题考察无人机空域申请法规知识点。超视距飞行（超出驾驶员目视范围）需向空管部门申请空域许可，因无法直接观察无人机状态，需空管协调保障安全；视距内飞行通常在开放空域内无需额外申请；起飞重量小于7千克的微型无人机一般无需空域申请；白天在城市上空飞行若未超视距且符合禁飞区规定，也无需专门申请空域许可。"},{"id":1225,"type":"single","cat":"法规与空域","stem":"在我国，无人机驾驶员在视距内飞行时，以下哪类空域无需向空管部门申请空域使用许可？","A":"开放类空域","B":"限制类空域","C":"管控类空域","D":"隔离类空域","answer":"A","exp":"本题考察无人机空域使用相关法规知识点。开放类空域（如低空空域开放区域）允许视距内飞行且无需申请空域使用许可；限制类空域（如部分机场周边）需提前申请并获得批准；管控类空域（如军事管制区）需严格审批；隔离类空域（如军事禁区）禁止民用无人机进入。因此正确答案为A。"},{"id":1226,"type":"single","cat":"基础概念","stem":"无人机起飞前，必须检查的项目是？","A":"遥控器摇杆是否居中","B":"螺旋桨是否安装牢固","C":"天气是否为晴天","D":"飞行器GPS是否有信号","answer":"B","exp":"本题考察起飞前设备检查知识点。正确答案为B，螺旋桨安装牢固是起飞前必须检查的核心项目，若安装不牢，起飞时可能因螺旋桨脱落导致无人机失控。A选项遥控器摇杆居中属于开机后操作检查，非起飞前必须项；C选项天气晴朗是理想飞行条件，非起飞前检查内容；D选项GPS信号需在飞行前开机自检时确认，非必须检查的基础物理状态项。"},{"id":1227,"type":"single","cat":"飞行原理","stem":"无人机飞行时，升力的主要产生原理是以下哪项？","A":"螺旋桨旋转产生的直接推力","B":"空气动力学中机翼上下表面的压力差（伯努利原理）","C":"发动机燃烧产生的热能转化","D":"机身与空气摩擦产生的反作用力","answer":"B","exp":"本题考察无人机升力的空气动力学原理。升力本质是机翼上下表面因气流速度差异产生的压力差（伯努利原理），即上表面气流速度快、压力低，下表面气流速度慢、压力高，形成向上的压力差。A选项螺旋桨推力是提供前进动力，而非升力；C选项热能转化是能量来源，不直接产生升力；D选项摩擦反作用力无法形成稳定升力，故B为正确答案。"},{"id":1228,"type":"single","cat":"法规与空域","stem":"根据民航及空域管理规定，以下哪些区域属于无人机禁飞区？","A":"机场净空保护区域","B":"军事管理区","C":"人口密集区域（如城市中心）","D":"A、B、C均属于","answer":"D","exp":"正确答案为D，机场净空区（A）禁止无人机飞行以保障航空器起降安全；军事管理区（B）属于敏感空域，禁止民用无人机进入；人口密集区域（C）因安全隐患（如坠机伤人）通常禁止飞行；因此A、B、C均为禁飞区，选D。"},{"id":1229,"type":"single","cat":"设备与维护","stem":"无人机飞行中突然出现电机停转故障，首要应急措施是？","A":"立即开启备用电源","B":"尝试重启故障电机","C":"迅速切换至手动降落模式","D":"保持悬停等待地面救援","answer":"C","exp":"本题考察无人机电机故障应急处理知识点。C选项迅速切换至手动降落模式是首要措施，可避免因失去动力导致无人机失控坠落。A选项备用电源通常未配置或容量有限；B选项重启电机需时间且成功率低；D选项无动力时无法悬停，必须立即迫降以保障安全。"},{"id":1230,"type":"single","cat":"法规与空域","stem":"无人机驾驶员执照的有效期是多久？","A":"1年","B":"2年","C":"3年","D":"5年","answer":"C","exp":"本题考察无人机法规知识点。根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》，无人机驾驶员执照有效期为3年，持照人需在有效期内完成每年签注培训（含理论和实践考核），否则执照自动失效。选项A（1年）、B（2年）为错误有效期；选项D（5年）不符合民航局规定。故正确答案为C。"},{"id":1231,"type":"single","cat":"设备与维护","stem":"当无人机在飞行中突然出现失控（如遥控器信号丢失）时，应优先采取的措施是？","A":"立即手动关闭无人机电源开关","B":"尝试通过地面站执行紧急返航","C":"持续尝试遥控器操作使无人机撞向障碍物","D":"等待无人机自动降落至最近区域","answer":"B","exp":"本题考察无人机失控的应急处置。当无人机失控时，手动关闭电源（A）会导致无人机无动力坠落；持续操作撞向障碍物（C）会造成危险；等待自动降落（D）可能因电量耗尽或姿态失控导致坠机。正确做法是通过地面站或遥控器尝试执行紧急返航程序（B），利用GPS或预设航线返回安全区域，避免危险。"},{"id":1232,"type":"single","cat":"法规与空域","stem":"根据《民用无人驾驶航空器实名制登记管理规定》，以下哪种飞行场景需要向空管部门报备飞行计划？","A":"起飞重量≤7kg的微型无人机在视距内飞行","B":"起飞重量＞7kg的轻型无人机在视距内飞行","C":"起飞重量＞7kg的轻型无人机在超视距飞行","D":"起飞重量＜25kg的轻型无人机在城市上空飞行","answer":"C","exp":"本题考察无人机法规与飞行管理知识点。民航局规定：①微型无人机（≤7kg）视距内飞行无需报备；②轻型无人机（7-116kg）超视距飞行需执照并报备；③轻型无人机视距内飞行仅需实名登记。A选项无需报备；B选项视距内无需报备；D选项城市上空飞行属于空域限制，与报备要求无关。正确答案为C。"},{"id":1233,"type":"single","cat":"基础概念","stem":"根据中国民航局规定，以下哪类无人机属于轻型无人机？","A":"最大起飞重量5千克","B":"最大起飞重量100千克","C":"最大起飞重量7千克","D":"最大起飞重量150千克","answer":"B","exp":"本题考察无人机重量分类知识点。正确答案为B。分析：中国民航局规定，轻型无人机的最大起飞重量范围为7千克至116千克。A选项（5千克）和C选项（7千克）属于微型无人机（<7千克）；D选项（150千克）超过116千克，属于中型无人机；B选项（100千克）在7-116千克范围内，符合轻型无人机定义。"},{"id":1234,"type":"single","cat":"飞行原理","stem":"无人机飞行时，其升力主要由以下哪个因素产生？","A":"发动机推力","B":"螺旋桨旋转产生的下洗气流","C":"空气浮力","D":"机身结构产生的浮力","answer":"B","exp":"本题考察无人机升力原理。正确答案为B，无人机（多旋翼）的升力来源于螺旋桨高速旋转时，桨叶对空气施加向下的作用力（下洗气流），根据牛顿第三定律，空气对桨叶施加向上的反作用力，即升力。选项A发动机推力是提供无人机前进动力，而非升力；选项C空气浮力（如热气球原理）仅适用于密度远小于空气的飞行器，无人机因密度大于空气，升力远大于空气浮力；选项D机身浮力无此概念，故错误。"},{"id":1235,"type":"single","cat":"基础概念","stem":"根据中国民航局相关规定，轻型民用无人机的最大起飞重量通常不超过以下哪个数值？","A":"7千克","B":"116千克","C":"100千克","D":"200千克","answer":"B","exp":"本题考察轻型无人机的重量分类知识点。根据《民用无人驾驶航空器实名制登记管理规定》及飞行标准，轻型民用无人机指最大起飞重量大于7千克且不超过116千克的民用无人机，因此最大起飞重量上限为116千克。A选项7千克是微型无人机的典型最大起飞重量；C、D选项均超出轻型无人机的重量范围。"},{"id":1236,"type":"single","cat":"设备与维护","stem":"在无人机飞行前，检查电池状态时，以下哪项是最重要的？","A":"电池外观无鼓包变形","B":"电池电量是否充足","C":"电池接口是否清洁","D":"电池生产日期是否在保质期内","answer":"B","exp":"本题考察飞行前电池检查知识点。电池电量直接决定无人机能否完成飞行任务，电量不足会导致飞行中断或坠机风险。选项A（外观检查）可排除电池物理损坏风险，但非飞行前提；选项C（接口清洁）影响连接稳定性，但电量不足时仍无法起飞；选项D（保质期检查）属于长期存储要求，飞行前优先保障电量。"},{"id":1237,"type":"single","cat":"领航与任务规划","stem":"当无人机在飞行中突然失去GPS信号并出现姿态失控时，应优先采取的操作是？","A":"立即尝试手动返航（若有返航指令）","B":"继续保持当前航向飞行至安全区域","C":"快速拉升高度至云层以上脱离当前空域","D":"立即操控无人机迫降在最近平坦地面","answer":"A","exp":"本题考察无人机应急处置规范。失去GPS信号后，优先尝试手动返航（若飞控支持返航功能）是最安全的操作，可避免无人机因失控偏离航线或坠入危险区域，因此A正确。B选项继续飞行会加剧失控风险；C选项拉升高度可能进入更高风险空域（如高空风区）；D选项迫降需地面条件允许，且手动迫降易导致无人机损坏或造成人员/财产损失，故B、C、D错误。"},{"id":1238,"type":"single","cat":"领航与任务规划","stem":"无人机在自主飞行模式下，若GPS信号突然丢失，优先操作应为？","A":"立即触发‘失控返航’程序","B":"继续保持当前飞行姿态","C":"手动切换至手动模式并尝试迫降","D":"关闭遥控器电源后离开","answer":"A","exp":"本题考察无人机GPS信号丢失的应急处置知识点。当无人机自主飞行时，GPS信号丢失会导致定位失效，此时无人机通常会触发预设的‘失控返航’程序（基于最后已知位置和返航高度），确保安全返回起飞点。选项B（继续保持姿态）会导致无人机因无法定位而随机漂移，增加碰撞风险；选项C（手动迫降）需驾驶员具备极高操控能力，非优先操作；选项D（关闭电源）会导致无人机直接坠落，完全不可控。因此正确答案为A。"},{"id":1239,"type":"single","cat":"领航与任务规划","stem":"无人机飞行中，负责稳定飞行姿态、实现悬停及航线规划的核心系统是？","A":"动力系统（提供升力）","B":"飞控系统（飞行控制系统）","C":"图传系统（传输视频数据）","D":"遥控系统（接收操控指令）","answer":"B","exp":"本题考察无人机核心系统功能。飞控系统（飞行控制系统）是无人机的大脑，负责稳定姿态、悬停、航线规划、故障预警等，B选项正确。A动力系统仅提供动力；C图传系统仅传输视频；D遥控系统仅接收指令，均非核心飞行控制功能。"},{"id":1240,"type":"single","cat":"基础概念","stem":"起飞前检查无人机时，以下哪项属于必须检查的关键项目？","A":"遥控器电池电量","B":"螺旋桨是否有裂纹或变形","C":"地面是否有障碍物","D":"天气是否晴朗","answer":"B","exp":"本题考察无人机起飞前检查重点。螺旋桨作为动力传输核心部件，若有裂纹或变形会导致旋转不平衡，引发剧烈震动、动力失衡甚至空中解体，是起飞前必须检查的关键项目，故B正确。A选项遥控器电池属于地面设备，无人机自身起飞前检查重点是自身系统（如电池电量、螺旋桨、GPS等），遥控器电量通常由操作员自行负责；C、D选项属于飞行环境检查（障碍物、天气），并非无人机自身必须检查的关键项目。"},{"id":1241,"type":"single","cat":"基础概念","stem":"无人机的动力系统主要不包括以下哪个部件？","A":"电机","B":"螺旋桨","C":"电池","D":"GPS模块","answer":"D","exp":"本题考察无人机系统组成知识点。动力系统负责驱动无人机飞行，主要包括提供动力的电机、传递动力的螺旋桨、储存能量的电池。而GPS模块属于导航与定位系统，用于实现无人机位置感知、自主飞行控制，不属于动力系统范畴。故正确答案为D。"},{"id":1242,"type":"single","cat":"基础概念","stem":"起飞前对无人机进行检查时，以下哪项是最关键的检查项目？","A":"遥控器剩余电量","B":"无人机机身外观及螺旋桨安装情况","C":"地面站软件版本是否最新","D":"起飞区域的实时风速数据","answer":"B","exp":"本题考察无人机起飞前的安全检查重点。正确答案为B，起飞前必须检查无人机机身是否有结构损坏（如机架变形）、螺旋桨是否安装牢固且无裂纹/磨损，这些直接影响飞行安全；A选项遥控器电量是飞行前需确认的，但属于辅助检查；C选项地面站版本与飞行安全无直接关联；D选项风速是环境参数，需提前查询，不属于对无人机本身的检查项目。"},{"id":1243,"type":"single","cat":"法规与空域","stem":"根据民航局规定，以下哪类无人机飞行活动需驾驶员取得相应执照？","A":"起飞重量250克以下的微型无人机","B":"起飞重量大于7千克的轻型无人机","C":"起飞重量大于15千克的小型无人机","D":"起飞重量大于100千克的大型无人机","answer":"B","exp":"本题考察无人机执照适用范围。根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》，起飞重量＞7千克的轻型无人机（含轻型以上）在经营性飞行活动中需取得驾驶员执照；选项A（250克以下）属于微型无人机，法规规定无需执照；选项C（15千克以上）已超出轻型范畴，属于小型，需执照但选项B描述更精准；选项D（100千克以上）属于大型，需执照但题目选项中B更符合需执照的典型场景。故正确答案为B。"},{"id":1244,"type":"single","cat":"基础概念","stem":"当无人机突然失控并可能撞向人群时，最优先采取的应急措施是？","A":"立即切断动力并迫降（远离人群区域）","B":"尝试远程操控使其反向远离人群","C":"紧急返航至起飞点并途经人群上空","D":"继续观察等待无人机自动恢复稳定","answer":"A","exp":"本题考察无人机失控应急处置原则。失控撞向人群时，首要目标是避免人员伤亡，最优先措施是立即切断动力（如关闭电机或熄火），并选择无人区域迫降，防止进一步碰撞危险，故A正确。B选项远程操控可能因信号延迟或无人机完全失控无法实现；C选项紧急返航若途经人群上空，仍可能造成二次伤害；D选项等待自动恢复会错失最佳避险时机，加剧危险。"},{"id":1245,"type":"single","cat":"基础概念","stem":"起飞前检查无人机的关键步骤是？","A":"检查遥控器与无人机之间的信号强度","B":"检查GPS卫星数量是否≥4颗","C":"检查螺旋桨是否有明显磨损","D":"检查地面是否有人员围观","answer":"B","exp":"本题考察起飞前检查要点。选项A（信号强度）虽重要，但GPS定位是悬停和飞行稳定的核心前提；选项B（GPS卫星数量）直接关系到无人机定位精度和稳定性，起飞前必须确保GPS信号良好（通常需≥4颗卫星可见），否则易导致悬停漂移或失控；选项C（螺旋桨磨损）影响飞行安全性，但非起飞前关键检查的唯一核心项；选项D（地面人员）属于飞行安全距离要求，非检查内容。故正确答案为B。"},{"id":1246,"type":"single","cat":"基础概念","stem":"起飞前检查无人机时，以下哪项不属于必须检查的项目？","A":"电池剩余电量","B":"GPS信号强度","C":"螺旋桨安装是否牢固","D":"地面障碍物分布","answer":"D","exp":"本题考察起飞前检查要点。起飞前需检查无人机自身状态：A（电池电量）、B（GPS信号确保定位）、C（螺旋桨安装影响飞行安全）均为必查项目。D选项地面障碍物分布属于飞行前环境规划内容，非无人机自身检查项目，故正确答案为D。"},{"id":1247,"type":"single","cat":"法规与空域","stem":"根据中国民航局《轻小无人机运行规定》，轻型民用无人机（起飞重量≥7千克）在开放空域视距内飞行时，最大允许飞行高度为？","A":"120米","B":"150米","C":"500米","D":"1000米","answer":"A","exp":"本题考察无人机飞行高度限制。轻型无人机（起飞重量≥7千克）在开放空域视距内飞行高度限制为120米（A正确），超视距飞行高度≤50米；500米、1000米属于超视距或特定空域（如限高区），不符合轻小无人机常规规定。"},{"id":1248,"type":"single","cat":"飞行原理","stem":"无人机在空中悬停时，其动力系统产生的升力主要平衡的力是？","A":"无人机自身重力","B":"空气流动产生的阻力","C":"螺旋桨旋转产生的离心力","D":"地面效应产生的托举力","answer":"A","exp":"本题考察无人机飞行力学基础知识点。悬停状态下，无人机处于受力平衡状态，动力系统产生的升力与无人机自身重力（包括载荷）完全相等，因此升力主要平衡重力。选项B错误，空气阻力在悬停时极小，不构成主要平衡对象；选项C错误，离心力是螺旋桨旋转的惯性力，升力与离心力方向相反但作用不同；选项D错误，地面效应仅在低空（距地面高度＜旋翼直径）时产生，非悬停升力的核心平衡对象，因此正确答案为A。"},{"id":1249,"type":"single","cat":"法规与空域","stem":"根据中国空域管理规定，以下哪类区域属于无人机禁飞区？","A":"机场净空区（半径10公里内）","B":"军事管理区","C":"人口密集区（如城市核心区）","D":"以上都是","answer":"D","exp":"本题考察无人机空域管理法规。正确答案为D，根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》，机场净空区（防止干扰航班起降）、军事管理区（国家安全）、人口密集区（避免坠机风险）均属于禁飞区或限制飞行区域，未经批准不得飞入。选项A、B、C均符合禁飞区定义。"},{"id":1250,"type":"single","cat":"设备与维护","stem":"当无人机飞行中电池剩余电量显示为15%时，正确的操作是？","A":"继续飞行直到返回起飞点","B":"立即返航并优先保证安全降落","C":"继续拍摄直到电量耗尽","D":"切换至节能模式并快速爬升","answer":"B","exp":"本题考察低电量应急处置，正确答案为B。15%剩余电量已处于低电量警告状态，继续飞行（A）或拍摄（C）可能导致无人机在降落前完全断电，引发失控坠机；快速爬升（D）会增加动力负荷，加速电量消耗，加剧风险。立即返航并优先降落（B）是最安全的选择，确保无人机在可控状态下着陆，避免意外发生。"},{"id":1251,"type":"single","cat":"法规与空域","stem":"根据无人机飞行法规，起飞前必须完成的核心操作是？","A":"申请空域并获得批准","B":"调试地面站参数","C":"充电电池至100%","D":"检查螺旋桨安装牢固","answer":"A","exp":"本题考察无人机飞行前法规要求。正确答案为A，根据民航局及国际无人机法规，起飞前必须提前申请并获得空域使用许可（如视距内飞行需申请开放空域，超视距飞行需额外审批）。B选项调试地面站参数属于飞行前准备工作，但非法规强制前提；C选项充电电池至100%是设备维护要求，非法规强制的必须完成步骤；D选项检查螺旋桨安装属于飞行前机械检查，但属于操作前准备而非法规要求的核心操作。"},{"id":1252,"type":"single","cat":"飞行原理","stem":"无人机飞行时，产生升力的主要物理原理是？","A":"伯努利原理（机翼上下表面压力差）","B":"牛顿第三定律（作用力与反作用力）","C":"阿基米德原理（流体浮力）","D":"万有引力定律","answer":"A","exp":"本题考察无人机升力原理。无人机机翼设计基于伯努利原理：机翼上表面弧度大于下表面，气流流经时上表面流速更快，压强更低，下表面流速慢、压强大，形成上下表面压力差，从而产生向上的升力，故A正确。B选项牛顿第三定律主要解释螺旋桨推力（作用力与反作用力），但升力本质是压力差；C选项阿基米德原理适用于浮力（如船在水中），与无人机靠压力差产生升力无关；D选项万有引力是重力来源，与升力产生无直接关联。"},{"id":1253,"type":"single","cat":"基础概念","stem":"无人机飞行中突然失去动力，应优先采取以下哪种措施？","A":"立即返航","B":"尝试重启动力系统","C":"寻找最佳安全迫降区域","D":"继续保持高度盘旋等待救援","answer":"C","exp":"本题考察应急处置流程。失去动力后，无人机无法自主控制飞行，应优先选择空旷、无人员/障碍物的区域迫降（如农田、空地），避免坠机风险。A选项立即返航和D选项盘旋等待会因失去动力导致失控；B选项重启动力系统在动力完全失效时无法实现，因此正确答案为C。"},{"id":1254,"type":"single","cat":"法规与空域","stem":"根据《民用无人驾驶航空器实名制登记管理规定》，以下哪种场景飞行前需向空管部门申请飞行计划？","A":"在城市居民区上空进行航拍作业","B":"在机场净空区边缘1公里外进行测绘飞行","C":"在国家测绘地理信息局划定的开放空域进行训练飞行","D":"在农村无人区域进行农业植保飞行","answer":"B","exp":"本题考察无人机飞行空域申请规范知识点。根据《民用无人驾驶航空器经营性飞行活动管理办法》，机场净空区（含跑道端外3公里、侧方1公里）属于限制飞行区，需提前向当地空管部门（如民航局空管局）申请飞行计划；选项A居民区属于一般限制区，视距内飞行通常无需额外申请（但需遵守高度限制）；选项C开放空域按规定可直接飞行；选项D农村无人区属于开放空域，无需申请。因此答案为B。"},{"id":1255,"type":"single","cat":"设备与维护","stem":"无人机飞行控制系统中，负责稳定无人机姿态、执行飞控算法并确保飞行安全的核心组件是？","A":"飞控系统","B":"图传系统","C":"动力系统","D":"导航系统","answer":"A","exp":"本题考察无人机系统组成知识点。飞控系统（飞行控制系统）是无人机的大脑，通过传感器感知姿态并执行飞控指令，稳定飞行姿态；B选项图传系统主要负责传输无人机实时影像，不参与姿态控制；C选项动力系统提供飞行动力，与姿态稳定无关；D选项导航系统负责定位和路径规划，不直接执行姿态稳定指令。因此正确答案为A。"},{"id":1256,"type":"single","cat":"基础概念","stem":"当无人机在飞行中突然失控并开始俯冲时，驾驶员应优先采取以下哪项措施？","A":"立即拉满油门使无人机快速爬升","B":"快速关闭遥控器油门通道（切断动力）","C":"迅速远离人群密集区域并尝试手动迫降","D":"立即切换至备用遥控器频率尝试控制","answer":"C","exp":"本题考察应急处置知识点。无人机俯冲失控时，首要原则是避免伤害他人，应优先远离人群（C项）。A项拉满油门可能加剧俯冲；B项切断动力可能导致突然坠落；D项切换频率需额外时间且成功率低。因此正确答案为C。"},{"id":1257,"type":"single","cat":"航空气象","stem":"在以下哪种气象条件下，根据中国民航相关规定，应当禁止无人机起飞？","A":"雷雨天气","B":"能见度良好（≥300米）","C":"风速≤5级（地面）","D":"无人机系统状态正常","answer":"A","exp":"本题考察无人机起飞的气象条件限制知识点。雷雨天气属于强对流气象条件，可能导致无人机雷击、失控或坠机风险，根据民航规定禁止起飞。B选项能见度良好是允许起飞的前提条件，C选项风速≤5级（地面）属于安全风速范围，D选项是无人机系统正常的基本要求，均非禁止起飞条件。因此正确答案为A。"},{"id":1258,"type":"single","cat":"飞行原理","stem":"多旋翼无人机升力产生的主要物理原理是基于以下哪项？","A":"伯努利原理","B":"牛顿第三定律（反作用力）","C":"阿基米德原理","D":"帕斯卡定律","answer":"B","exp":"本题考察无人机升力原理知识点。多旋翼无人机通过高速旋转的旋翼向下推动空气（作用力），根据牛顿第三定律，空气对旋翼产生向上的反作用力（反作用力），从而形成升力。选项A（伯努利原理）主要用于解释固定翼飞机机翼升力（上下表面流速差）；选项C（阿基米德原理）是浮力原理，适用于气球/飞艇；选项D（帕斯卡定律）是液体压强传递规律，与无人机升力无关。"},{"id":1259,"type":"single","cat":"基础概念","stem":"根据中国民航局规定，以下哪种区域属于无人机驾驶员必须严格禁止飞行的区域？","A":"城市中心广场","B":"机场跑道外5公里净空区","C":"军事管理区边界线内","D":"自然保护区核心区","answer":"C","exp":"本题考察无人机禁飞区法规，正确答案为C。军事管理区（或军事禁区）属于国家重点安全管控区域，根据《无人驾驶航空器飞行管理暂行条例》，严禁任何未经批准的无人机进入。选项A城市中心广场需遵守限高但非绝对禁飞；选项B机场净空区通常指跑道两端及附近一定范围内（如10公里），但题目表述跑道外5公里不准确；选项D自然保护区核心区需谨慎飞行但非法定禁飞区。"},{"id":1260,"type":"single","cat":"操纵与飞行技术","stem":"无人机能够稳定悬停在空中的主要原理是？","A":"伯努利原理","B":"牛顿第三定律","C":"帕斯卡定律","D":"阿基米德原理","answer":"A","exp":"旋翼旋转使上下表面空气流速差形成压力差（伯努利原理），产生升力平衡重力；牛顿第三定律是辅助解释（反作用力），帕斯卡定律（液体压强）和阿基米德原理（浮力）与悬停无关。因此本题正确答案为A选项。"},{"id":1261,"type":"single","cat":"基础概念","stem":"在我国，轻型民用无人机在人口稠密区域上空飞行时，其最大允许飞行高度通常为？","A":"50米","B":"100米","C":"120米","D":"200米","answer":"C","exp":"本题考察轻型无人机飞行高度限制。根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》，轻型无人机在人口稠密区上空飞行高度不得超过120米。A选项50米可能适用于微型无人机或特定限制区域；B选项1"},{"id":1262,"type":"single","cat":"基础概念","stem":"以下哪项不属于无人机系统的组成部分？","A":"飞行器平台","B":"地面控制站","C":"卫星定位模块","D":"地面电源","answer":"D","exp":"本题考察无人机系统组成的知识点。无人机系统通常由飞行器平台（含动力、飞控等）、地面控制站（遥控站）、任务设备、数据链路等核心部分组成。C选项卫星定位模块（如GPS）是飞控系统的关键组成部分，用于定位和导航；A、B均为系统核心组成。而D选项地面电源仅用于地面设备（如地面站供电），并非无人机系统运行时的必要组成部分（无人机飞行依赖自身电池），因此正确答案为D。"},{"id":1263,"type":"single","cat":"领航与任务规划","stem":"当无人机飞行中突然出现GPS信号丢失（无GPS数据）时，最安全的应急操作是？","A":"立即切换至手动模式并尝试继续飞行","B":"保持当前航向，缓慢爬升以重新获取信号","C":"优先执行返航程序（若返航点有效且信号未丢失）","D":"继续操作无人机悬停，等待信号恢复","answer":"C","exp":"本题考察无人机GPS故障应急处理知识点。GPS丢失时，无人机通常触发失控保护或返航逻辑（若返航点有效），此时优先返航可避免因信号丢失导致的失控；A手动模式易因失去GPS辅助导致碰撞；B爬升可能加剧信号干扰；D悬停等待会因无人机惯性漂移或动力耗尽坠落。正确答案为C。"},{"id":1264,"type":"single","cat":"飞行原理","stem":"当无人机在地面悬停时，升力与重力的关系是？","A":"升力大于重力","B":"升力小于重力","C":"升力等于重力","D":"不确定，取决于风速","answer":"C","exp":"本题考察无人机飞行原理中升力与重力的平衡关系。悬停状态下，无人机相对地面静止（匀速直线运动的特殊形式），根据牛顿第一定律，合力为零，因此升力与重力大小相等、方向相反。A选项错误（升力过大将导致无人机上升），B选项错误（升力不足将导致无人机下降），D选项错误（风速不影响悬停时的升力-重力平衡）。"},{"id":1265,"type":"single","cat":"法规与空域","stem":"关于民用无人驾驶航空器驾驶员执照，以下说法正确的是？","A":"视距内驾驶员执照允许在目视气象条件下，高度≤120米、半径≤500米的空域飞行","B":"超视距驾驶员执照仅适用于夜间飞行场景","C":"轻型驾驶员执照允许起飞重量超过150千克的无人机飞行","D":"小型驾驶员执照无需通过理论考试即可申请 answer:","answer":"A","exp":"本题考察民用无人机驾驶员执照分类及适用范围。正确答案为A：视距内驾驶员执照（视距内驾驶员）的空域限制明确为目视气象条件下，高度≤120米、半径≤500米，符合中国民航局《民用无人驾驶航空器驾驶员管理暂行规定》。B错误：超视距驾驶员执照需通过额外考核（如超视距空域知识），且需遵守能见度、气象等条件，并非仅适用于夜间。C错误：轻型驾驶员执照对应的无人机最大起飞重量为7-116千克，而非超过150千克（后者属于小型或大型）。D错误：无论何种执照，均需通过理论考试（含法规、系统原理等）及实践考核，无豁免考试情况。"},{"id":1266,"type":"single","cat":"领航与任务规划","stem":"当无人机在飞行中突然失控（如GPS信号丢失），应首先采取以下哪项措施？","A":"立即拉回油门","B":"尝试手动紧急降落","C":"关闭遥控器电源","D":"启动返航程序","answer":"D","exp":"本题考察无人机安全操作知识点。A拉回油门可能因动力控制失效导致坠机；B手动紧急降落需精准操作，易因操作失误引发碰撞；C关闭遥控器电源会直接切断控制，导致无人机失控坠地。D启动返航程序（若飞控支持）可让无人机自动返回预设返航点，是最安全的应急措施，故正确答案为D。"},{"id":1267,"type":"single","cat":"领航与任务规划","stem":"当无人机飞行中突然出现GPS信号丢失（进入姿态模式），此时应优先采取以下哪项措施？","A":"立即关闭电源","B":"尝试手动返航（利用视觉定位和遥控器控制）","C":"继续保持原航向飞行","D":"尝试切换至备用电池","answer":"B","exp":"本题考察无人机应急处置流程。GPS丢失后，无人机进入姿态模式，需手动操作维持安全。B选项通过视觉定位（如地面标记）和遥控器手动控制，可优先确保无人机不坠机；A选项关闭电源会丢失飞行数据且无法应急；C选项无GPS时无法自动导航，继续飞行易失控；D选项备用电池与GPS丢失无关。因此正确答案为B。"},{"id":1268,"type":"single","cat":"基础概念","stem":"无人机起飞前，以下哪项检查是确保飞行安全的关键步骤？","A":"检查螺旋桨是否安装牢固","B":"检查地面是否有人员","C":"检查天气是否晴朗","D":"检查无人机外观是否有划痕","answer":"A","exp":"本题考察无人机起飞前安全检查知识点。A正确，螺旋桨安装不牢固会导致飞行中脱落，引发失控或碰撞风险，是核心安全检查项。B错误，地面人员需提前撤离至安全区，但属于飞行前观察而非关键检查；C错误，天气晴朗是飞行条件，非检查步骤；D错误，外观划痕不影响飞行性能，不属于安全检查范畴。"},{"id":1269,"type":"single","cat":"领航与任务规划","stem":"无人机在飞行中突然出现GPS信号丢失，此时应优先采取的措施是？","A":"继续手动操作无人机返回起飞点","B":"切换至姿态模式并执行自动返航（RTH）","C":"立即关闭电源迫降","D":"继续爬升以寻找卫星信号","answer":"B","exp":"本题考察无人机故障处理知识点。GPS信号丢失后，无人机主要依靠IMU（惯性测量单元）维持姿态，但无法定位。此时切换至姿态模式并执行RTH（自动返航）是最安全的措施，可利用预设返航点自动返回。选项A手动操作因无定位易失控，选项C强行关闭电源可能导致坠机，选项D爬升不一定恢复卫星信号。"},{"id":1270,"type":"single","cat":"飞行原理","stem":"多旋翼无人机产生升力的主要原理是？","A":"伯努利原理（旋翼上下表面压力差）","B":"牛顿第三定律（作用力与反作用力）","C":"阿基米德原理（浮力）","D":"万有引力","answer":"A","exp":"本题考察无人机升力产生原理知识点。A正确，多旋翼通过旋翼高速旋转使上下表面形成压力差（上表面流速快压力低，下表面流速慢压力高），根据伯努利原理产生升力。B错误，牛顿第三定律是螺旋桨反推原理（空气被下压产生反作用力），但非升力的核心原理；C错误，无人机升力与空气浮力无关（浮力针对密度差，升力针对相对运动）；D错误，万有引力是重力来源，与升力产生无关。"},{"id":1271,"type":"single","cat":"设备与维护","stem":"无人机飞控系统（FlightControlSystem）的核心功能是？","A":"接收并解析卫星定位信号，提供精确位置信息","B":"稳定无人机飞行姿态，实现自主控制与航线规划","C":"驱动电机旋转，提供无人机飞行所需的动力","D":"传输无人机实时状态数据至地面站","answer":"B","exp":"本题考察无人机飞控系统功能知识点。飞控系统的核心职责是通过传感器（如IMU惯性测量单元、GPS等）感知无人机姿态和位置，结合预设参数或地面指令，计算并输出控制指令，稳定飞行姿态（如悬停、转向）并实现自主控制（如航线规划）。选项A卫星定位信号解析是导航系统的功能，非飞控核心；选项C驱动电机旋转属于动力系统（电机、电调等）的职责；选项D数据传输由图传系统或数传模块完成，飞控系统不直接负责数据传输。因此正确答案为B。"},{"id":1272,"type":"single","cat":"基础概念","stem":"多旋翼无人机起飞前，以下哪项属于必须检查的关键项目？","A":"飞行空域是否已向空管部门申请","B":"电池电压是否在安全工作范围内","C":"地面站软件版本是否为最新","D":"无人机机身厂商售后服务电话","answer":"B","exp":"本题考察无人机起飞前检查要点知识点。起飞前必须检查的关键项目包括电池状态（电压、电量）、桨叶安装、GPS信号、遥控器连接等，其中电池电压是确保无人机动力系统正常运行的核心指标，因此正确答案为B。A选项空域申请属于飞行前准备阶段的行政流程，非起飞前直接检查项目；C选项地面站软件版本属于调试阶段，非起飞前关键检查项；D选项厂商售后电话与飞行安全无关。"},{"id":1273,"type":"single","cat":"基础概念","stem":"根据中国民航局规定，视距内飞行的无人机最大飞行高度通常不超过多少米？","A":"50米","B":"120米","C":"200米","D":"500米","answer":"B","exp":"中国民航局明确视距内飞行标准：水平距离≤500米，高度≤120米（含120米）。A选项50米过低，C选项200米、D选项500米均超出规定高度限制。因此正确答案为B。"},{"id":1274,"type":"single","cat":"操纵与飞行技术","stem":"无人机飞行过程中，负责实时监测并自动修正无人机姿态（如倾斜、俯仰），确保飞行稳定性的核心系统是？","A":"飞控系统（飞行控制系统）","B":"遥控系统（地面站）","C":"动力系统（电机、电池）","D":"导航系统（GPS）","answer":"A","exp":"本题考察无人机系统组成及功能。飞控系统通过陀螺仪、加速度计等传感器实时感知无人机姿态，结合预设算法自动调节电机转速以修正姿态偏差，保障飞行稳定性。B遥控系统仅负责接收地面指令；C动力系统提供飞行动力但不控制姿态；D导航系统（GPS）提供位置信息和路径规划，不直接参与姿态稳定。"},{"id":1275,"type":"single","cat":"法规与空域","stem":"在未取得空域使用许可的情况下，微型无人机在视距内飞行的最大高度一般不超过多少米？","A":"80米","B":"100米","C":"120米","D":"150米","answer":"C","exp":"本题考察无人机飞行高度限制的法规知识点。根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》及空域管理规定，微型无人机在视距内飞行（无审批空域）的最大高度限制为120米。选项A（80米）和B（100米）低于常规视距内飞行高度上限，选项D（150米）通常适用于特定空域审批后的轻型无人机，未取得许可时不适用。因此正确答案为C。"},{"id":1276,"type":"single","cat":"基础概念","stem":"无人机的动力系统主要负责以下哪项核心功能？","A":"提供飞行动力","B":"处理飞行数据","C":"导航定位","D":"图像传输","answer":"A","exp":"本题考察无人机系统组成的动力系统功能知识点。动力系统（含电机、电池、螺旋桨等）的核心作用是通过电能转化为机械能，产生升力和推力以维持无人机飞行。选项B（处理飞行数据）属于飞控系统功能，选项C（导航定位）由GPS/IMU等导航模块实现，选项D（图像传输）属于图传系统功能。因此正确答案为A。19.无人机在飞行中突然与地面站失联，最不可能的原因是："},{"id":1277,"type":"single","cat":"基础概念","stem":"无人机在飞行中突然与地面站失联，最不可能的原因是：","A":"无人机飞控系统故障","B":"遥控器电池电量耗尽","C":"图传信号受到强电磁干扰","D":"无人机GPS卫星信号丢失","answer":"B","exp":"本题考察失联故障原因，正确答案为B。遥控器电池耗尽仅影响对无人机的控制操作，不会导致无人机与地面站失联；A（飞控故障）、C（信号干扰）、D（GPS丢失）均可能直接导致数据连接中断。"},{"id":1278,"type":"single","cat":"基础概念","stem":"当多旋翼无人机在飞行中突然失去动力时，以下哪项操作是正确的应急处置措施？","A":"立即关闭无人机电源并等待坠落","B":"尝试通过调整飞行摇杆控制无人机平稳迫降","C":"迅速拉升无人机高度并继续尝试操控","D":"立即切换至备用电池并继续飞行","answer":"B","exp":"失去动力时，立即关闭电源会导致完全失控坠落；拉升高度因无动力会迅速下降；备用电池切换无法解决动力缺失问题；正确做法是通过手动调整摇杆控制姿态，平稳迫降以减少损坏。因此正确答案为B。"},{"id":1279,"type":"single","cat":"操纵与飞行技术","stem":"四旋翼无人机悬停时，主要通过调节以下哪个参数平衡自身重力？","A":"电机转速","B":"扭矩","C":"升力大小","D":"推力方向","answer":"A","exp":"本题考察无人机飞行原理。四旋翼无人机通过改变每个电机的转速（A）来调整桨叶产生的升力，悬停时升力需与重力平衡。选项B（扭矩）是电机转动的力矩，不直接决定升力；选项C（升力大小）是结果而非调节参数；选项D（推力方向）为固定方向，无法平衡重力。因此正确答案为A。"},{"id":1280,"type":"single","cat":"领航与任务规划","stem":"当无人机飞行中突然失去GPS信号时，以下哪种操作是正确的应急措施？","A":"立即拉升至云层以上寻找信号","B":"切换至姿态模式保持基本控制","C":"强行执行返航程序","D":"关闭无人机电源避免失控","answer":"B","exp":"本题考察无人机故障应急处理知识点。GPS丢失后，无人机进入GPS模式失效状态，此时切换至姿态模式（B正确）可仅依赖惯性测量单元（IMU）维持基础飞行姿态，避免因失控坠落；A选项拉升至云层可能进入无信号区域加剧危险；C选项强行返航需GPS定位，无法执行；D选项关闭电源会导致无人机立即失控坠落，均错误。正确答案为B。"},{"id":1281,"type":"single","cat":"基础概念","stem":"无人机飞行前检查的核心项目不包括以下哪项？","A":"电池电压检查","B":"螺旋桨安装牢固性","C":"遥控器电量检查","D":"地面站软件版本检查","answer":"D","exp":"本题考察无人机飞行前检查的关键内容。飞行前需重点确认无人机硬件状态（如电池电压是否充足、螺旋桨安装是否牢固）及操控设备状态（遥控器电量是否满足飞行需求）。地面站软件版本属于任务规划阶段的配置，与实时飞行安全无关，因此无需在飞行前检查。"},{"id":1282,"type":"single","cat":"基础概念","stem":"根据中国民航局相关规定，视距内飞行的微型无人机，其最大飞行高度通常不超过多少米？","A":"50米","B":"120米","C":"500米","D":"1000米","answer":"B","exp":"本题考察无人机飞行高度法规知识点。根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》，视距内飞行的微型无人机最大飞行高度限制为120米；轻型无人机视距内飞行高度不超过500米（超视距飞行需额外审批）。A选项50米为超小型无人机的低空限制，C选项500米为轻型无人机视距内高度上限，D选项1000米为超视距飞行高度上限（非视距内），故正确答案为B。"},{"id":1283,"type":"single","cat":"设备与维护","stem":"飞行中突然电机停转，正确的应急处置步骤是？","A":"立即切换至备用电池","B":"尝试手动操控无人机滑翔降落","C":"保持原飞行高度，等待地面指令","D":"快速拉升至安全高度后关闭电源","answer":"B","exp":"本题考察无人机动力失效应急处置知识点。正确答案为B。电机停转后无人机失去动力，应利用滑翔状态手动控制方向，尽快寻找安全区域迫降；A选项错误，切换电池需时间，可能已无法安全操作；C选项等待指令会加剧坠落风险；D选项拉升后关闭电源会直接导致无人机坠落，更危险。"},{"id":1284,"type":"single","cat":"飞行原理","stem":"当无人机飞行速度低于临界值，导致升力无法维持飞行高度时，这种现象称为？","A":"失速","B":"螺旋","C":"尾旋","D":"失控","answer":"A","exp":"本题考察无人机飞行术语中的失速概念知识点。失速的定义是飞行速度过低，机翼迎角超过临界值，导致升力急剧下降，无法维持高度或速度。选项B（螺旋）是无人机绕纵轴和横轴同时旋转的失控状态，选项C（尾旋）是螺旋的极端形式（绕垂直轴旋转），选项D（失控）是更宽泛的故障统称。三者均与速度过低导致升力不足的核心定义不符。因此正确答案为A。"},{"id":1285,"type":"single","cat":"基础概念","stem":"起飞前检查中，以下哪项属于必须确认的关键项目？","A":"螺旋桨安装是否牢固","B":"地面是否有手机信号","C":"天气是否为阴天","D":"无人机外观是否有划痕","answer":"A","exp":"本题考察起飞前检查要点。螺旋桨安装牢固是飞行安全的核心，若安装不牢，飞行中可能脱落导致事故，属于关键项目。选项B（手机信号）与飞行安全无关；选项C（天气）影响飞行但非必须检查的关键项目；选项D（外观划痕）不影响性能，无需检查。"},{"id":1286,"type":"single","cat":"法规与空域","stem":"申请民航局核发的民用无人驾驶航空器驾驶员执照，申请人的年龄应满足以下哪个条件？","A":"年满16周岁","B":"年满18周岁","C":"年满20周岁","D":"年满14周岁","answer":"A","exp":"本题考察无人机驾驶员执照申请的年龄要求知识点。根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》及民航局相关规定，申请驾驶员执照的申请人需年满16周岁，这是基础考证的法定年龄起点。选项B年满18周岁通常是经营性飞行人员或特定职业岗位的额外要求，非普遍基础条件；选项C年满20周岁不符合常规要求；选项D年满14周岁未达到法定最低年龄标准，因此正确答案为A。"},{"id":1287,"type":"single","cat":"设备与维护","stem":"无人机飞行中出现图传信号中断（画面/数据丢失），以下哪项不是可能的原因？","A":"遥控器与无人机间存在强电磁干扰","B":"无人机端图传模块硬件损坏","C":"无人机GPS信号丢失导致自动返航","D":"无人机电池电量耗尽","answer":"D","exp":"本题考察无人机图传中断故障原因。图传中断通常由信号链路问题或设备故障导致：A强电磁干扰会阻断无线信号传输，B图传模块损坏直接导致信号中断，CGPS丢失后无人机可能自动返航，但返航过程中仍可能因信号中断显示失联；D电池电量耗尽会导致无人机自动迫降，而非图传中断（电量耗尽前图传已中断）。故正确答案为D。"},{"id":1288,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机能够悬停的核心原理是？","A":"固定翼机翼上下表面压力差产生升力","B":"旋翼高速旋转产生的反作用力与重力平衡","C":"螺旋桨推力直接克服重力","D":"发动机动力通过传动系统转化为升力","answer":"B","exp":"本题考察多旋翼无人机悬停原理知识点。多旋翼无人机通过多个旋翼高速旋转，使旋翼下方空气流速加快、压力降低，上方空气流速慢、压力高，形成向上的反作用力（升力），当升力与无人机重力平衡时即可悬停，因此正确答案为B。A选项是固定翼无人机升力原理，与多旋翼无关；C选项错误，螺旋桨推力本质是反作用力，表述不准确；D选项错误，多旋翼无人机由电机驱动而非发动机，且推力表述混淆了升力与推力的概念。"},{"id":1289,"type":"single","cat":"基础概念","stem":"起飞前检查无人机时，以下哪项是必须执行的关键步骤？","A":"检查电池电量≥80%","B":"确认螺旋桨安装牢固且无损伤","C":"测试遥控器摇杆行程是否正常","D":"以上都是","answer":"D","exp":"本题考察无人机起飞前安全检查知识点。起飞前需执行多维度检查：电池电量需充足（≥80%）以避免空中断电；螺旋桨需安装牢固且无裂纹/变形（防止旋转时脱落或失衡）；遥控器摇杆行程需正常（确保控制指令有效）。错误选项A、B、C均为起飞前检查的必要环节，单独任何一项缺失都可能导致飞行风险，因此正确答案为D。"},{"id":1290,"type":"single","cat":"基础概念","stem":"无人机起飞前，以下哪项属于必须检查的关键项目？","A":"螺旋桨安装是否牢固且方向正确","B":"无人机机身外观是否有明显变形","C":"地面是否有无关人员停留","D":"飞行空域是否已申请飞行计划","answer":"A","exp":"本题考察无人机起飞前检查要点。螺旋桨安装牢固和方向正确直接影响飞行平衡与动力输出，是飞行安全的核心保障。B选项外观变形若不影响结构安全则非必须检查；C、D属于场地和空域管理，非设备检查项目。故正确答案为A。"},{"id":1291,"type":"single","cat":"基础概念","stem":"无人机飞行前检查中，以下哪项属于必须确认的机械安全检查内容？","A":"遥控器电池剩余电量","B":"图传信号是否稳定","C":"螺旋桨是否安装牢固","D":"GPS卫星数量是否充足","answer":"C","exp":"本题考察飞行前检查要点。C选项螺旋桨安装牢固是机械连接安全的核心，若安装不牢，飞行中可能脱落导致失控或损坏，属于必须检查内容。A选项电池电量是能源检查，非机械安全检查。B选项图传信号稳定性需飞行中观察，非检查项目。D选项GPS卫星数量属于导航系统检查，与机械安全无关。"},{"id":1292,"type":"single","cat":"设备与维护","stem":"无人机遥控器校准过程中，必须执行的关键步骤是？","A":"校准指南针","B":"调整螺旋桨角度","C":"更换锂电池","D":"格式化SD卡","answer":"A","exp":"本题考察无人机设备操作的校准知识点。遥控器校准的核心是确保无人机与遥控器的信号匹配及姿态控制准确，其中校准指南针是关键步骤，可消除磁干扰对无人机方向的影响。选项B（调整螺旋桨角度）属于出厂设置或维护操作，非校准步骤；选项C（更换电池）仅为供电操作，与校准无关；选项D（格式化SD卡）用于数据存储管理，与校准无关。"},{"id":1293,"type":"single","cat":"领航与任务规划","stem":"无人机的核心控制系统，负责稳定飞行姿态、执行导航指令和故障处理的是？","A":"飞控系统","B":"动力系统","C":"遥控系统","D":"图传系统","answer":"A","exp":"本题考察无人机系统组成知识点。飞控系统（FlightControlSystem）是无人机的核心，通过传感器实时监测姿态并执行控制算法，确保飞行稳定；B选项动力系统负责提供飞行动力；C选项遥控系统仅负责地面指令传输；D选项图传系统用于传输图像视频，不参与飞行控制。因此正确答案为A。"},{"id":1294,"type":"single","cat":"法规与空域","stem":"根据中国民航局规定，重量大于多少克的民用无人机需要进行实名登记？","A":"200克","B":"250克","C":"150克","D":"300克","answer":"B","exp":"本题考察无人机实名登记法规知识点。根据民航局《民用无人驾驶航空器实名制登记管理规定》，重量大于等于250克（含250克）的民用无人机需向民航局指定平台实名登记。A选项200克未达到规定阈值，C选项150克低于标准，D选项300克虽需登记但非规定的最低阈值，因此正确答案为B。37.无人机起飞前，地面检查的首要关键系统是____。"},{"id":1295,"type":"single","cat":"基础概念","stem":"无人机起飞前，地面检查的首要关键系统是____。","A":"图传系统信号强度","B":"动力系统（螺旋桨、电机、电池）安装牢固性","C":"飞控系统参数设置","D":"遥控器摇杆行程校准","answer":"B","exp":"本题考察无人机起飞前检查重点。动力系统（螺旋桨、电机、电池）是飞行安全的核心，起飞前必须确保螺旋桨安装牢固（防止脱落）、电机无异常、电池电量充足，否则可能引发空中失控或机械故障。A选项图传系统为辅助设备，C选项参数设置需在起飞前检查但非首要，D选项摇杆校准属于调试环节，因此正确答案为B。"},{"id":1296,"type":"single","cat":"基础概念","stem":"无人机飞行模式中，位置模式与高度模式的主要区别在于？","A":"位置模式可保持当前位置，高度模式仅控制高度","B":"位置模式需手动调整航向，高度模式自动调整","C":"位置模式依赖GPS，高度模式仅依赖气压计","D":"位置模式支持悬停，高度模式不支持悬停","answer":"A","exp":"本题考察无人机飞行模式参数控制知识点。位置模式（如GPS模式）下，无人机可保持当前经纬度位置（悬停时维持坐标不变），同时通过遥控器调整航向和高度；高度模式（如高度/姿态模式）下，无人机仅通过油门控制高度，位置需手动调整（如手动飞直线）。错误选项B描述反了两种模式的航向控制逻辑；C中两种模式均可能同时依赖GPS和气压计；D中高度模式也支持悬停（如保持固定高度），故排除。"},{"id":1297,"type":"single","cat":"航空气象","stem":"无人机起飞时，为获得最佳起飞性能，应尽量选择哪种风向？","A":"逆风","B":"顺风","C":"侧风","D":"无风","answer":"A","exp":"本题考察无人机起飞时的风向选择知识点。逆风起飞时，无人机相对空气的速度更快，机翼上下表面的气压差增大，升力显著提升，可缩短起飞滑跑距离、降低对发动机推力的依赖。顺风会降低相对空气速度，导致升力不足，需更长滑跑距离甚至可能因推力不足无法离地；侧风会增加起飞操控难度，无风则无额外升力增益。因此A选项正确。"},{"id":1298,"type":"single","cat":"基础概念","stem":"在进行视距内（VLOS）飞行时，根据中国民航局相关规定，民用无人机的最大飞行高度通常为？","A":"50米","B":"120米","C":"200米","D":"500米","answer":"B","exp":"本题考察视距内飞行高度限制知识点。中国民航局规定视距内飞行高度一般不超过120米，超视距飞行高度通常不超过500米。A选项50米过低，不符合实际操作；C选项200米超过视距内标准；D选项500米为超视距飞行高度上限，故正确答案为B。"},{"id":1299,"type":"single","cat":"领航与任务规划","stem":"飞行中GPS信号突然丢失时，应优先采取的操作是？","A":"立即切换至手动模式","B":"尝试重新搜索卫星信号","C":"启用返航功能（如有返航点）","D":"继续维持当前航向飞行","answer":"C","exp":"GPS丢失后无人机定位失效，继续飞行（D）易因失控坠毁；切换手动模式（A）需熟练操作且存在坠机风险；重新搜索卫星（B）无明确时间保障；启用返航功能（基于预设返航点）是最安全的应急措施，可快速返回安全区域，故正确答案为C。"},{"id":1300,"type":"single","cat":"法规与空域","stem":"未经批准在机场净空区进行无人机飞行，可能面临的法律后果不包括以下哪项？","A":"行政处罚（罚款）","B":"民事赔偿责任（如造成他人损失）","C":"刑事责任（如危害公共安全）","D":"仅需口头警告","answer":"D","exp":"本题考察禁飞区飞行法律后果。根据《无人驾驶航空器飞行管理暂行条例》，非法在机场净空区飞行属于违法行为，将面临罚款（A）、民事赔偿（B）甚至刑事处罚（C），仅口头警告（D）不符合法律规定。故正确答案为D。"},{"id":1301,"type":"single","cat":"领航与任务规划","stem":"无人机在飞行中突然失去GPS信号（无GPS模式），应优先采取以下哪种操作？","A":"立即执行返航操作（RTH）","B":"继续保持当前飞行姿态","C":"尝试手动调整油门和摇杆","D":"立即切换至紧急迫降模式","answer":"A","exp":"本题考察无人机故障应急处理流程。失去GPS信号后，无人机易因位置丢失失控，优先执行返航（RTH）可自动返回起飞点附近，避免盲目飞行导致坠机；B项继续飞行加剧危险；C项手动控制难度大且易误操作；D项紧急迫降需在安全环境下，非优先措施。因此正确答案为A。"},{"id":1302,"type":"single","cat":"设备与维护","stem":"起飞前检查无人机电池时，以下哪项不属于必要检查内容？","A":"电池外观是否有鼓包、漏液","B":"电芯电压是否在正常范围内","C":"电池接口是否有松动或氧化","D":"电池生产日期及保质期","answer":"D","exp":"本题考察起飞前电池检查要点。起飞前需重点检查电池安全性（外观鼓包/漏液）、供电稳定性（电芯电压）、连接可靠性（接口状态）；电池生产日期及保质期仅影响长期存储寿命，与当前飞行安全无关。因此正确答案为D。"},{"id":1303,"type":"single","cat":"飞行原理","stem":"多旋翼无人机主要依靠什么原理产生升力？","A":"螺旋桨旋转产生的反作用力（升力）","B":"空气动力学伯努利效应（机翼上下表面压力差）","C":"发动机喷气推力","D":"机身与空气的相对运动产生的动压","answer":"A","exp":"本题考察无人机升力原理。多旋翼无人机通过多个螺旋桨高速旋转，对空气施加向下的作用力，根据牛顿第三定律，空气对螺旋桨产生向上的反作用力（即升力），因此A正确。B选项是固定翼无人机的升力原理；C选项是直升机或固定翼飞机发动机的推力来源，与多旋翼无关；D选项属于空气动力学基础概念，但多旋翼升力核心是螺旋桨反作用力，非单纯相对运动。"},{"id":1304,"type":"single","cat":"设备与维护","stem":"无人机飞控系统的核心功能是？","A":"稳定飞行姿态","B":"实时传输任务载荷数据","C":"控制动力系统输出","D":"显示地面站信息","answer":"A","exp":"飞控系统（FlightControlSystem）的核心职责是通过传感器采集姿态数据，计算并输出控制指令，实现无人机的稳定飞行（如保持高度、俯仰角、横滚角等）。选项B为任务载荷子系统功能，C为动力系统控制模块职责，D属于地面站数据显示范畴，均非飞控核心功能，故正确答案为A。"},{"id":1305,"type":"single","cat":"法规与空域","stem":"无人机驾驶员执照按运行环境（是否超出视线范围）分为以下哪两类？","A":"AOPA执照和民航局执照","B":"视距内驾驶员执照和超视距驾驶员执照","C":"固定翼执照和多旋翼执照","D":"民用执照和军用执照","answer":"B","exp":"本题考察无人机驾驶员执照分类知识点。无人机驾驶员执照根据运行环境分为视距内驾驶员执照（VLOS）和超视距驾驶员执照（BVLOS），前者适用于视线范围内飞行，后者需额外培训和资质。A选项是执照颁发机构，C选项是按无人机类型分类，D选项为执照用途分类，均不符合题意。"},{"id":1306,"type":"single","cat":"领航与任务规划","stem":"无人机在GPS模式飞行中突然失控，最可能的直接原因是？","A":"GPS卫星信号丢失","B":"螺旋桨被异物缠绕","C":"遥控器天线接触不良","D":"地面站软件故障","answer":"A","exp":"本题考察GPS模式飞行安全知识点。GPS模式依赖卫星定位数据，信号丢失会导致无人机失去自主悬停和位置控制能力，直接引发失控。B选项螺旋桨缠绕会导致动力失衡，通常表现为缓慢失控而非突然；C选项遥控器接触不良会导致控制信号中断，但不会直接引发失控状态；D选项地面站故障不影响飞行中无人机的实时控制。因此正确答案为A。"},{"id":1307,"type":"single","cat":"法规与空域","stem":"根据中国民航局规定，无人机驾驶员执照的有效期一般为多少年？","A":"1年","B":"3年","C":"5年","D":"7年","answer":"C","exp":"本题考察无人机驾驶员执照管理知识点。根据民航局规定，视距内驾驶员执照有效期为5年，故正确答案为C。A选项1年不符合实际，执照有效期不会如此短暂；B选项3年通常为其他短期证件的有效期，非执照有效期；D选项7年过长，超出常规执照管理周期。"},{"id":1308,"type":"single","cat":"法规与空域","stem":"以下哪个区域属于无人机飞行的严格禁飞区？","A":"城市公园","B":"机场净空区","C":"偏远山区","D":"乡村田野","answer":"B","exp":"本题考察无人机禁飞区安全规范。机场净空区是为保障机场运行安全划定的严格禁飞区域，根据《民用机场管理条例》，无人机在机场跑道端外3公里、跑道中心线两侧各10公里范围内禁止飞行。A、C、D选项均不属于禁飞区，城市公园、乡村田野等开放区域在遵守法规前提下可飞行，偏远山区虽无明确禁飞规定但需注意地形风险。因此正确答案为B。"},{"id":1309,"type":"single","cat":"基础概念","stem":"当无人机在空中突然与地面站失去连接（失联）时，最优先采取的应急措施是？","A":"立即关闭无人机电源","B":"尝试重新连接遥控器","C":"启动无人机的失控保护/返航程序","D":"手动操作无人机迫降","answer":"C","exp":"本题考察无人机故障应急处理知识点。无人机飞控系统通常预设失联保护或失控保护程序，当与地面站/遥控器失去连接时，系统会自动执行预设的安全动作（如返航、降落或悬停），优先保障飞行安全。选项A（关闭电源）会导致无人机突然坠落，可能引发安全事故；选项B（重新连接）成功率低且耗时，可能错过最佳处理时机；选项D（手动迫降）需依赖操作员手动控制，而失联后操作员无法实时接收无人机状态，易导致失控。因此正确答案为C。"},{"id":1310,"type":"single","cat":"操纵与飞行技术","stem":"无人机悬停时，主要依靠哪个部件产生的力平衡自身重力？","A":"推力","B":"升力","C":"阻力","D":"重力","answer":"B","exp":"本题考察无人机飞行原理。无人机悬停时，螺旋桨高速旋转推动空气向下，根据牛顿第三定律，空气对螺旋桨产生向上的反作用力即升力，升力与重力平衡使无人机保持悬停。选项A推力是螺旋桨提供的动力来源，非直接平衡重力的力；选项C阻力为空气阻碍运动的力，与悬停无关；选项D重力是被平衡的力而非平衡力，故正确答案为B。"},{"id":1311,"type":"single","cat":"基础概念","stem":"无人机飞行中突发低电量警告时，最优先的安全操作是？","A":"立即迫降","B":"执行返航程序","C":"继续飞行至目的地","D":"联系地面站","answer":"B","exp":"本题考察无人机应急处置规范。飞行中低电量时，无人机飞控系统会自动触发低电量返航程序（若未设置，驾驶员应手动执行），优先返回起飞点，避免因电量耗尽导致失控坠机。A选项迫降易造成设备损坏或人员伤害；C选项继续飞行会导致动力中断风险；D选项联系地面站无法解决电量不足问题，且可能延误操作时机。因此正确答案为B。"},{"id":1312,"type":"single","cat":"法规与空域","stem":"下列哪类无人机驾驶员执照适用于最大起飞重量25千克以上的民用无人机在视距内飞行？","A":"视距内驾驶员执照（25kg以下）","B":"超视距驾驶员执照（25kg以下）","C":"视距内驾驶员执照（25kg以上）","D":"超视距驾驶员执照（25kg以上）","answer":"C","exp":"本题考察无人机驾驶员执照分类知识点。中国民航局对无人机驾驶员执照分为视距内驾驶员执照（VTC）和超视距驾驶员执照（BVC），其中视距内驾驶员执照又根据最大起飞重量分为25千克以下和25千克以上两个等级。选项A适用于25kg以下无人机，选项B和D不符合超视距执照的重量限制，选项C正确描述了25kg以上视距内驾驶员执照的适用范围。"},{"id":1313,"type":"single","cat":"基础概念","stem":"根据中国民航局相关规定，微型民用无人机在视距内飞行时，最大允许飞行高度为？","A":"100米","B":"120米","C":"150米","D":"200米","answer":"B","exp":"本题考察无人机飞行空域高度限制知识点。根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》，微型无人机在视距内飞行高度不得超过120米。A选项100米为早期非视距场景参考值，C（150米）和D（200米）均超出法规限制。"},{"id":1314,"type":"single","cat":"设备与维护","stem":"无人机飞控系统的核心功能不包括以下哪项？","A":"稳定飞行姿态","B":"自动避障决策","C":"控制电机转速","D":"调节飞行高度","answer":"B","exp":"本题考察无人机系统组成。飞控系统（FlightControlSystem）主要负责稳定无人机姿态（如横滚、俯仰、偏航）、控制电机转速以调节动力输出，以及通过PID算法自动调节飞行高度和速度。选项B自动避障决策属于无人机感知系统（如视觉避障、激光雷达）的功能，由外部传感器和独立算法完成，不属于飞控系统核心功能，故正确答案为B。"},{"id":1315,"type":"single","cat":"基础概念","stem":"根据《民用无人驾驶航空器经营性飞行活动管理办法》，无人机在人口密集区域上空飞行时，最低安全高度应为多少米？","A":"5米","B":"10米","C":"15米","D":"20米","answer":"B","exp":"本题考察空域安全操作规范。根据民航局规定，无人机在人口密集区域（如城市、广场、居民区）上空飞行时，需保持至少10米的安全高度，以避免碰撞风险；选项A（5米）过低、C（15米）和D（20米）过高，均不符合标准，故正确答案为B。"},{"id":1316,"type":"single","cat":"领航与任务规划","stem":"当无人机飞行中突然丢失GPS信号时，以下哪项是正确的应急操作？","A":"立即切换至手动模式并尝试返航","B":"继续操控无人机上升至云层上方","C":"关闭无人机电源以避免失控","D":"保持原航向继续飞行以节省电量","answer":"A","exp":"本题考察应急处理流程。GPS丢失时，手动模式可通过姿态控制实现返航/迫降，避免失控风险。上升至云层上方（B）无法解决信号问题且增加碰撞风险，关闭电源（C）会丢失飞行数据，保持原航向（D）易导致坠机或碰撞。"},{"id":1317,"type":"single","cat":"法规与空域","stem":"根据中国民航局相关规定，最大起飞重量在多少克以上的民用无人机需要进行实名登记？","A":"150克","B":"200克","C":"250克","D":"300克","answer":"C","exp":"本题考察无人机实名登记的重量标准知识点。根据《民用无人驾驶航空器实名制登记管理规定》，最大起飞重量≥250克的民用无人机（除微型航拍器等豁免情况外）需进行实名登记。选项A（150克）和B（200克）均低于规定阈值，选项D（300克）属于超轻型或轻型无人机的更高重量分类，并非登记的最低标准。因此正确答案为C。"},{"id":1318,"type":"single","cat":"设备与维护","stem":"当无人机飞行中发生单个电机突然停止工作时，正确的应急处置措施是？","A":"立即切换至备用电池并继续飞行","B":"尝试手动操作控制无人机平稳迫降","C":"保持当前飞行姿态直至电量耗尽","D":"强行拉升无人机高度以脱离故障区域","answer":"B","exp":"本题考察无人机故障应急处理。单电机故障会导致无人机失去平衡，此时强行拉升（D）或继续飞行（C）可能加剧失控；若无人机无备用电池（A），切换电池不现实。正确做法是手动操作无人机，利用剩余电机和舵面控制，选择无人区域平稳迫降，减少损失。"},{"id":1319,"type":"single","cat":"基础概念","stem":"根据中国民航局对轻型民用无人机（空机重量＜7千克）视距内飞行的规定，最大飞行高度限制为多少？","A":"50米","B":"120米","C":"500米","D":"1000米","answer":"B","exp":"本题考察无人机飞行高度法规。中国民航局规定，轻型民用无人机在视距内飞行时，最大高度限制为120米（含120米），以保障空域安全与避免空中冲突。A选项50米为低空飞行常见限制；C、D选项高度过高，超出轻型视距内飞行的安全范围（超视距飞行需额外资质且高度限制不同）。"},{"id":1320,"type":"single","cat":"基础概念","stem":"无人机系统（UAS）的核心组成部分不包括以下哪项？","A":"飞行器平台","B":"地面指挥控制站","C":"卫星定位系统","D":"任务载荷设备","answer":"C","exp":"本题考察无人机系统组成知识点。无人机系统核心由四部分构成：①飞行器平台（机体），②任务载荷设备（如相机、传感器），③地面指挥控制站（含地面站软件、遥控器），④遥控链路（含图传、数据链）。卫星定位系统（GPS/北斗）属于飞行器平台的子部件（飞控系统组成部分），并非独立核心组成，故C选项错误。A、B、D均为系统核心组成部分，正确答案为C。"},{"id":1321,"type":"single","cat":"法规与空域","stem":"根据中国民航局规定，无人机驾驶员执照主要依据以下哪项标准进行分类？","A":"按起飞重量分为15kg和25kg级","B":"按是否具备视距内飞行能力分为视距内驾驶员和超视距驾驶员","C":"按使用空域类型分为开放空域和限制空域驾驶员","D":"按电池容量分为高容量和低容量驾驶员","answer":"B","exp":"本题考察无人机驾驶员执照的分类标准知识点。中国民航局对无人机驾驶员执照的分类核心依据是飞行能力范围，即是否具备视距内（VLOS）飞行能力和超视距（BVLOS）飞行能力，因此正确答案为B。A选项错误，起飞重量是无人机类型划分（如微型、轻型、小型、大型）的标准，而非执照分类；C选项错误，空域类型是飞行任务的申请依据，并非执照分类标准；D选项错误，电池容量与执照分类无关。"},{"id":1322,"type":"single","cat":"领航与任务规划","stem":"当多旋翼无人机GPS信号突然丢失时，最安全的操作是？","A":"立即拉升高度至云层以上，重新搜索卫星信号","B":"保持当前高度和航向，等待GPS信号恢复","C":"切换至手动模式，尝试返航至起飞点","D":"立即关闭发动机，选择开阔地带紧急迫降","answer":"C","exp":"本题考察无人机GPS丢失后的应急处理。GPS丢失时，无人机可能因失去定位而进入失控状态（如漂移、坠落）。选项A盲目拉升可能因高度过高导致飞控无法恢复；选项B等待无法解决信号丢失问题；选项D紧急迫降易因失去定位导致撞击风险；选项C通过手动模式返航至起飞点，可避免失控风险，是最安全的操作。"},{"id":1323,"type":"single","cat":"设备与维护","stem":"多旋翼无人机遥控器中，通常用于控制飞行器升降（高度）的摇杆是？","A":"左摇杆","B":"右摇杆","C":"中摇杆","D":"无升降控制摇杆","answer":"A","exp":"本题考察无人机遥控器操作逻辑。主流多旋翼无人机遥控器布局中，左摇杆通常负责控制高度（油门）和偏航（旋转）：上下推动左摇杆可改变螺旋桨总升力大小，实现飞行器升降；左右推动左摇杆控制无人机绕竖轴旋转（偏航）。右摇杆一般控制俯仰（前后倾斜）和横滚（左右倾斜）。C、D选项不符合主流遥控器设计，因此正确答案为A。"},{"id":1324,"type":"single","cat":"设备与维护","stem":"无人机起飞后电机突然停转且无明显故障，最可能的原因是？","A":"螺旋桨卡滞","B":"电池电压过低","C":"飞控系统故障","D":"GPS信号丢失","answer":"B","exp":"本题考察无人机故障排除。电池电压过低会导致电机无法获得足够电能驱动，表现为突然停转且无机械卡滞（无异响）。选项A螺旋桨卡滞会伴随电机异响或剧烈震动；选项C飞控系统故障通常伴随飞行姿态异常（如倾斜、抖动）；选项DGPS信号丢失会导致失控但不会直接导致电机停转。因此，电池电压过低是最可能原因，正确答案为B。"},{"id":1325,"type":"single","cat":"设备与维护","stem":"在无人机飞行中，若发现电池电量不足，应如何操作？","A":"立即切换至低电量保护模式","B":"继续飞行至目的地后降落","C":"强行降落","D":"继续飞行至电量耗尽","answer":"A","exp":"本题考察无人机电池安全操作知识点。无人机低电量保护模式会自动启动，优先保障安全返航或迫降。选项B、C、D均因电量不足导致无人机失控坠落，存在设备损坏或安全隐患，而低电量保护模式是唯一安全操作方式。"},{"id":1326,"type":"single","cat":"领航与任务规划","stem":"当多旋翼无人机飞行过程中突然失去GPS信号时，最安全的应急处置措施是？","A":"继续手动操作无人机至安全地点","B":"立即启动自动返航程序","C":"强行继续飞行并尝试手动修正姿态","D":"直接关闭无人机电源并迫降","answer":"B","exp":"本题考察无人机应急处置知识点。GPS信号丢失后，无人机通常进入姿态模式，此时自动返航（RTF）是最安全的措施，可自动返回起飞点悬停，避免因手动操作失误导致坠机。错误选项中，A项手动操作难度高（无GPS定位易迷失方向）；C项强行飞行易因姿态失控坠落；D项直接断电会导致无人机失控坠落，无法保障安全。"},{"id":1327,"type":"single","cat":"法规与空域","stem":"根据中国民航局《民用无人驾驶航空器实名制登记管理规定》，以下哪种无人机需要进行实名登记？","A":"起飞重量≥250克的微型无人机","B":"起飞重量≥2000克的轻型无人机","C":"起飞重量≥1500克的小型无人机","D":"起飞重量≥1000克的轻型无人机","answer":"A","exp":"本题考察无人机实名登记法规知识点。根据民航局规定，起飞重量≥250克的微型无人机（属于民航局定义的‘轻型’以下类别）需进行实名登记，以加强监管。选项B、C、D的重量标准均不符合实名登记的具体阈值，因此正确答案为A。"},{"id":1328,"type":"single","cat":"航空气象","stem":"飞行中遭遇突发强风（风速超过安全阈值）时，最安全的处置措施是？","A":"立即关闭无人机电源","B":"果断返航降落","C":"继续保持原航向飞行","D":"增大油门提升高度","answer":"B","exp":"本题考察强风天气下的应急操作。强风可能导致无人机失控（如偏航、失速或坠机），此时应立即终止飞行并返航降落，避免因强风持续作用造成不可挽回的损失。A选项关闭电源会直接导致坠机；C选项强风下保持航向会加剧失控风险；D选项增大油门可能导致动力过载或姿态失衡。"},{"id":1329,"type":"single","cat":"基础概念","stem":"起飞前检查无人机时，以下哪项属于必须执行的安全检查项目？","A":"检查螺旋桨是否安装牢固","B":"确认遥控器电量充足","C":"检查GPS卫星信号强度是否正常","D":"以上都是","answer":"D","exp":"本题考察无人机起飞前的基础检查流程。起飞前需全面检查：A选项螺旋桨安装牢固可避免飞行中脱落导致事故；B选项遥控器电量不足会导致失控风险；C选项GPS信号弱或丢失会影响悬停稳定性与返航安全。因此A、B、C均为必须检查项目，正确答案为D。"},{"id":1330,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机悬停时，其能够保持在空中不坠落的主要原因是？","A":"螺旋桨产生的推力大于重力","B":"螺旋桨产生的升力等于重力","C":"空气对无人机的浮力平衡重力","D":"电池提供的电能维持高度","answer":"B","exp":"多旋翼无人机通过螺旋桨高速旋转产生向上的升力，悬停时升力与重力大小相等、方向相反，形成平衡。推力是螺旋桨反作用力的分量，并非直接平衡重力；浮力对悬停影响极小；电池仅提供动力，不直接平衡重力。因此正确答案为B。"},{"id":1331,"type":"single","cat":"飞行原理","stem":"无人机飞行时，机翼产生升力的主要物理原理是？","A":"伯努利原理（机翼上下表面流速差导致压力差）","B":"牛顿第三定律（螺旋桨反作用力）","C":"万有引力（地球引力提供升力）","D":"阿基米德原理（空气浮力）","answer":"A","exp":"本题考察无人机空气动力学基础。升力产生的核心是机翼上下表面的压力差：机翼上表面弯曲，气流流速快（根据伯努利原理，流速大则压力小），下表面相对平直，流速慢压力大，上下表面压力差形成升力。选项B中牛顿第三定律是螺旋桨推力的原理（作用力与反作用力）；选项C万有引力是重力来源，与升力无关；选项D阿基米德原理适用于液体浮力，空气浮力对升力贡献可忽略不计。"},{"id":1332,"type":"single","cat":"法规与空域","stem":"以下哪种场景属于中国民航局明确规定的无人机‘禁飞区’？","A":"城市居民区广场","B":"民用机场跑道外5公里","C":"军事管理区周边10公里","D":"偏远山区无人区","answer":"C","exp":"本题考察无人机禁飞区法规。正确答案为C，军事管理区属于国家安全管控区域，10公里内为严格禁飞区。A选项居民区广场若未明确禁飞（如公园广场）不属于禁飞区；B选项民用机场净空区通常为跑道外8-15公里，具体范围需精确划定；D选项偏远山区无人区为允许飞行区域。"},{"id":1333,"type":"single","cat":"基础概念","stem":"无人机起飞前，确保飞行安全的首要检查项目是？","A":"飞行器GPS卫星信号数量（≥8颗）","B":"遥控器电池剩余电量","C":"地面是否有无关人员","D":"天气是否为晴朗无云","answer":"A","exp":"本题考察飞行前关键检查。GPS信号是定位与稳定悬停的核心前提，卫星数量不足会导致失控。选项B（遥控器电量）影响操控但非首要；选项C（地面人员）为环境排查，非核心；选项D（天气）为宏观条件，非飞行安全直接前提。正确答案为A。"},{"id":1334,"type":"single","cat":"领航与任务规划","stem":"当无人机飞行中突然发生GPS信号丢失且无法手动遥控时，应优先采取的安全措施是？","A":"立即执行一键返航功能（若具备）","B":"快速关闭无人机电源以防止失控","C":"尝试手动切换至备用GPS卫星信号","D":"继续观察无人机姿态等待恢复信号 answer","answer":"A","exp":"本题考察失控应急处置流程。正确答案为A：若无人机具备一键返航功能，优先触发该功能，利用其内置的气压计、高度计及预存航线参数，在GPS丢失时尝试返回起飞点或安全迫降点。B错误：关闭电源会导致无人机立即坠落，无法执行任何安全操作。C错误：GPS信号丢失时，备用卫星信号切换无意义，且此时无人机可能因失去定位而进入随机漂移。D错误：等待信号恢复会导致无人机因动力耗尽或姿态失控坠毁，风险极高。"},{"id":1335,"type":"single","cat":"基础概念","stem":"当无人机在飞行中突然发生动力系统故障，最优先的处置措施是？","A":"立即切换至备用电池","B":"尝试手动迫降至空旷区域","C":"保持当前航向并继续飞行","D":"启动紧急返航程序","answer":"B","exp":"本题考察故障应急处置原则。动力系统故障时，无人机可能失去控制或急速坠落，首要任务是选择安全区域手动迫降（避免砸落伤人）。选项A（切换电池）需时间且未必能解决根本故障；C（继续飞行）会加剧风险；D（紧急返航）可能因动力不足无法执行。正确做法是优先确保地面人员安全，选择无人群区域迫降，故正确答案为B。"},{"id":1336,"type":"single","cat":"操纵与飞行技术","stem":"无人机悬停时，主要依靠哪个力与重力平衡？","A":"升力","B":"推力","C":"阻力","D":"重力","answer":"A","exp":"本题考察无人机飞行基本原理。悬停状态下，无人机的升力（由旋翼旋转产生的向上气流压力差）与重力大小相等、方向相反，实现平衡。选项B推力用于前进/加速，C阻力为空气阻碍运动的力，D重力是无人机自身重量，均无法直接平衡悬停时的重力，故正确答案为A。"},{"id":1337,"type":"single","cat":"基础概念","stem":"无人机的核心控制系统，负责稳定飞行姿态、执行飞行控制指令的是以下哪个系统？","A":"飞控系统（飞行控制系统）","B":"GPS定位系统","C":"图传系统","D":"动力系统","answer":"A","exp":"本题考察无人机系统组成知识点。飞控系统是无人机的大脑，通过传感器（如IMU惯性测量单元）实时感知飞行姿态，执行控制算法（如PID调节），确保无人机稳定悬停、巡航、转向等。选项B（GPS）仅负责定位，不直接控制飞行；选项C（图传）用于传输视频数据，不参与飞行控制；选项D（动力系统）负责提供动力，而非控制指令。因此正确答案为A。"},{"id":1338,"type":"single","cat":"法规与空域","stem":"申请民用无人驾驶航空器系统驾驶员执照的最低年龄要求是多少？","A":"16周岁","B":"17周岁","C":"18周岁","D":"20周岁","answer":"A","exp":"本题考察无人机驾驶员执照申请的法规知识点。根据中国民航局规定，申请驾驶员执照的最低年龄为16周岁。选项B（17周岁）、C（18周岁）、D（20周岁）均高于最低年龄要求，不符合最低条件，因此错误。"},{"id":1339,"type":"single","cat":"设备与维护","stem":"无人机飞控系统（FlightController）的核心功能是？","A":"直接控制电机转速","B":"处理传感器数据并自动控制无人机姿态和位置","C":"存储飞行日志数据","D":"实时传输航拍视频","answer":"B","exp":"本题考察无人机系统组成知识点。飞控系统的核心功能是通过处理陀螺仪、加速度计、GPS等传感器数据，计算并输出控制指令，实现无人机姿态稳定（如悬停、转向）和位置控制（如航线飞行）。选项A错误，飞控不直接控制电机，而是通过电调（ESC）控制；选项C是数据记录模块的功能；选项D是图传系统的功能，故正确答案为B。"},{"id":1340,"type":"single","cat":"基础概念","stem":"根据中国民航局规定，视距内运行的民用无人驾驶航空器最大飞行高度为多少米？","A":"100","B":"120","C":"150","D":"200","answer":"B","exp":"本题考察无人机飞行高度限制知识点。根据《民用无人驾驶航空器实名制登记管理规定》及民航局相关细则，视距内运行（VLOS）的民用无人驾驶航空器最大飞行高度为120米，此高度限制旨在保障空域安全。错误选项中，100米为常见混淆值（非标准限制），150米和200米通常为超视距飞行或特定场景（如需审批的空域），不符合视距内的基本要求。"},{"id":1341,"type":"single","cat":"基础概念","stem":"根据中国民航局规定，轻型无人机的起飞重量范围通常是？","A":"<0.25kg","B":"0.25kg-7kg","C":"7kg-116kg","D":">116kg","answer":"C","exp":"中国民航局对无人机的分类标准为：微型无人机（<7kg）、轻型无人机（7kg-116kg）、小型无人机（116kg-570kg）、大型无人机（>570kg）。选项A为微型无人机范围，B为过渡性分类，D为大型无人机范围，均不符合题意，故正确答案为C。"},{"id":1342,"type":"single","cat":"基础概念","stem":"无人机的核心控制系统，负责稳定飞行姿态、执行控制指令并实现自主飞行的是？","A":"飞控系统","B":"图传系统","C":"动力系统","D":"遥控系统","answer":"A","exp":"本题考察无人机系统组成知识点。飞控系统（飞行控制系统）是无人机的核心控制单元，通过传感器数据（如陀螺仪、加速度计）和GPS定位，执行姿态稳定算法（如PID控制），确保无人机按指令飞行（如悬停、航线规划）。B选项图传系统仅负责传输无人机实时视频信号；C选项动力系统提供飞行动力（如电机、电池）；D选项遥控系统是地面端向无人机发送操控指令的设备，而非核心控制组件。因此正确答案为A。"},{"id":1343,"type":"single","cat":"基础概念","stem":"轻型民用无人机的最大起飞重量范围通常是？","A":"≤7千克","B":"＞7千克且≤116千克","C":"＞116千克且≤5700千克","D":"＞5700千克","answer":"B","exp":"本题考察无人机分类知识点。正确答案为B，根据中国民航局分类标准，轻型无人机指最大起飞重量＞7千克且≤116千克的无人机。A选项为微型无人机（≤7千克），C选项为小型无人机（＞116千克且≤5700千克），D选项为大型无人机（＞5700千克）。"},{"id":1344,"type":"single","cat":"基础概念","stem":"在无人机飞行前，必须优先确认的关键信息是？","A":"飞行空域是否在禁飞区范围内","B":"无人机电池剩余电量是否充足","C":"遥控器与无人机的信号连接强度","D":"天气状况是否为晴朗无雨","answer":"A","exp":"本题考察无人机安全飞行操作规范。禁飞区（如机场净空区、军事管理区、政府机关等）是法律禁止飞行的区域，未经审批进入可能面临行政处罚甚至刑事责任，是飞行前必须首要确认的安全前提。选项B、C、D均为飞行前需检查的细节，但属于操作前准备而非必须确认的核心关键信息。"},{"id":1345,"type":"single","cat":"法规与空域","stem":"根据《民用无人驾驶航空器实名制登记管理规定》，以下哪类无人机需要进行实名登记？","A":"所有起飞重量＞250克的无人机","B":"所有起飞重量＞150克的无人机","C":"所有空机重量＞250克的无人机","D":"所有起飞重量＞1000克的无人机","answer":"C","exp":"本题考察无人机实名登记规范知识点。民航局明确规定：空机重量＞250克的民用无人机（不含微型遥控模型飞机）需进行实名登记，以实现飞行数据可追溯。选项A混淆起飞重量与空机重量，选项B（150克）和D（1000克）均不符合规定标准。"},{"id":1346,"type":"single","cat":"基础概念","stem":"无人机飞行中突然失去动力，可能的直接原因是？","A":"电池电压过低","B":"电机控制器故障","C":"螺旋桨卡滞","D":"以上都是","answer":"D","exp":"本题考察无人机故障排除中动力系统失效原因知识点。A选项电池电压过低会导致电机无法获得足够功率（电压是电机输出功率的核心参数）；B选项电机控制器（ESC）故障会直接切断电机供电或驱动信号；C选项螺旋桨卡滞（如缠绕异物、电机卡死）会导致动力无法有效输出（旋翼无法转动产生升力）。三者均为动力中断的典型直接原因。因此正确答案为D。"},{"id":1347,"type":"single","cat":"基础概念","stem":"在视距内运行轻型民用无人机时，其最大飞行高度不得超过（）米。","A":"100","B":"120","C":"150","D":"200","answer":"B","exp":"本题考察无人机飞行高度的法规限制知识点。根据中国民航局相关规定，轻型民用无人机在视距内飞行时，最大飞行高度限制为120米；超视距飞行时，高度限制为500米。A选项100米低于规定下限，C选项150米和D选项200米均超过视距内轻型无人机的高度限制，因此正确答案为B。"},{"id":1348,"type":"single","cat":"法规与空域","stem":"根据中国民用无人驾驶航空器实名登记管理规定，起飞重量在250克至7千克之间的民用无人机，应当进行以下哪项操作？","A":"无需登记","B":"必须进行实名登记","C":"需向军方申请飞行许可","D":"仅需驾驶员执照即可飞行","answer":"B","exp":"中国民航局规定，250克（0.25千克）以下的民用无人机无需实名登记，250克以上、7千克以下的无人机必须进行实名登记，7千克以上的无人机也需登记。因此250克至7千克之间的无人机必须实名登记，正确答案为B。"},{"id":1349,"type":"single","cat":"基础概念","stem":"无人机起飞前，以下哪项属于必须完成的关键检查项目？","A":"遥控器电量与通道校准","B":"螺旋桨是否安装正确且无裂纹","C":"飞行器固件版本是否为最新","D":"以上所有均为关键检查项","answer":"D","exp":"本题考察无人机起飞前检查要点。A选项遥控器电量不足会导致失控，通道校准错误易引发操作失效；B选项螺旋桨安装错误（如反桨）或裂纹会导致失衡、动力中断甚至空中解体；C选项固件版本影响系统稳定性（如避障、传感器校准）。三者均为起飞前必须检查的关键环节，因此正确答案为D。"},{"id":1350,"type":"single","cat":"法规与空域","stem":"根据《民用无人驾驶航空器实名制登记管理规定》，以下哪种类型的无人机需要向民航局指定平台进行实名登记？","A":"最大起飞重量≥250克的民用无人机","B":"最大起飞重量≥7千克的民用无人机","C":"所有民用无人机均需登记","D":"仅植保类无人机需登记","answer":"A","exp":"本题考察无人机实名登记管理知识点。正确答案为A。根据规定，最大起飞重量≥250克的民用无人机（包括微型、轻型等类型）需实名登记；B选项错误，7千克是轻型与小型无人机的分界标准，并非登记标准；C选项错误，并非所有无人机都需登记（如微型无人机≥250克才需登记）；D选项错误，非植保类无人机（如消费级、测绘类）也需按重量登记。"},{"id":1351,"type":"single","cat":"基础概念","stem":"根据中国民航局标准，以下哪种分类符合轻型民用无人驾驶航空器的定义？","A":"最大起飞重量≤7千克","B":"最大起飞重量7-116千克","C":"最大起飞重量116-5700千克","D":"最大起飞重量5700千克以上 answer","answer":"B","exp":"本题考察无人机重量分类标准。正确答案为B：根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》，轻型无人机的最大起飞重量为7-116千克（含7千克，不含116千克）。A错误：≤7千克属于微型无人机。C错误：116-5700千克为小型无人机。D错误：＞5700千克为大型无人机。"},{"id":1352,"type":"single","cat":"法规与空域","stem":"以下哪项属于法定禁飞区？","A":"城市中心广场","B":"机场净空区","C":"偏远山区","D":"无人区","answer":"B","exp":"本题考察无人机空域管理知识点。正确答案为B（机场净空区），根据《民用机场管理条例》，机场净空区是法定禁飞区，任何无人机未经审批不得进入，否则将面临行政处罚。A选项城市中心广场多为限飞区（需提前申请）；C、D选项偏远山区和无人区通常允许合法飞行（需遵守空域申请规定），非法定禁飞区。"},{"id":1353,"type":"single","cat":"基础概念","stem":"根据中国民航局规定，微型无人机的最大起飞重量通常是？","A":"≤7千克","B":"7-116千克","C":"116-5700千克","D":"＞5700千克","answer":"A","exp":"本题考察无人机分类标准知识点。根据中国民航局规定，微型无人机的最大起飞重量通常≤7千克；7-116千克为轻型无人机（B选项），116-5700千克为小型无人机（C选项），＞5700千克为大型无人机（D选项）。因此正确答案为A。"},{"id":1354,"type":"single","cat":"基础概念","stem":"起飞前，对无人机进行检查时，以下哪项是必须确认的关键安全检查项？","A":"电池电量是否充足","B":"GPS卫星信号是否正常","C":"图传设备是否连接正常","D":"遥控器摇杆是否居中","answer":"B","exp":"本题考察无人机起飞前安全检查知识点。起飞前关键安全检查项包括：①GPS卫星信号是否正常（定位是飞行控制的基础，信号丢失会导致无人机失控）；②电池电量是否充足（防止空中断电）；③传感器校准状态（如IMU、磁罗盘）；④周围环境是否有障碍物。选项BGPS卫星信号是否正常是飞行控制的核心前提，直接决定无人机能否稳定悬停和自主导航；选项A（电池电量）是重要检查项，但题目问必须确认的关键安全项，GPS信号异常比电量不足更直接导致飞行失控；选项C（图传）不影响飞行控制；选项D（摇杆居中）属于调试环节，非起飞前核心安全检查。因此正确答案为B。"},{"id":1355,"type":"single","cat":"设备与维护","stem":"起飞前检查无人机电池时，首要关注的参数是？","A":"电池剩余容量（电压）","B":"电池生产厂商品牌","C":"电池单体温度","D":"电池总重量","answer":"A","exp":"本题考察飞行前检查要点。电池电压是起飞前最关键的检查参数，电压过低会导致动力不足、飞行失控甚至炸机，故A正确。选项B品牌不影响电池安全性；选项C温度需关注但非首要（极端高温/低温才需特别注意）；选项D总重量是起飞前整体检查内容，非电池单独检查重点。"},{"id":1356,"type":"single","cat":"法规与空域","stem":"根据中国民航局《民用无人驾驶航空器实名制登记管理规定》，重量超过多少克的微型无人机需要进行实名登记？","A":"150克","B":"250克","C":"300克","D":"500克","answer":"B","exp":"本题考察无人机法规知识点。根据民航局规定，重量超过250克的微型和轻型民用无人机需按要求实名登记，便于管理和事故追溯。选项A（150克）为未达阈值，无需登记；C（300克）和D（500克）为超轻型及以上级别，虽需登记但非微型范畴，故正确答案为B。"},{"id":1357,"type":"single","cat":"法规与空域","stem":"根据中国民航局规定，视距内运行的微型无人机在开放空域的最大飞行高度是多少？","A":"50米","B":"120米","C":"150米","D":"200米","answer":"B","exp":"本题考察无人机视距内运行的空域法规知识点。根据《民用无人驾驶航空器实名制登记管理规定》及民航局相关细则，视距内运行的微型无人机在开放空域的最大飞行高度为120米。A选项50米低于法规最低标准；C、D选项150米和200米超出了视距内飞行的高度限制，可能引发空域冲突或违反法规。"},{"id":1358,"type":"single","cat":"基础概念","stem":"无人机起飞前，以下哪项不属于必须检查的核心内容？","A":"电池电量、GPS信号强度、桨叶安装牢固性","B":"手机APP版本、地面障碍物分布、电机品牌型号","C":"遥控器摇杆行程、图传信号稳定性、螺旋桨平衡度","D":"无人机固件版本、起飞场地风速、云台角度是否正确","answer":"B","exp":"本题考察无人机安全操作检查要点。起飞前检查需围绕飞行安全、设备功能展开，核心包括电池（电量）、传感器（GPS）、机械结构（桨叶安装）、控制链路（遥控器）等。选项B中手机APP版本（非硬件功能）和电机品牌型号（与安全无关）不属于核心检查项；地面障碍物分布虽重要但不属于选项A的错误描述，故错误选项为B。"},{"id":1359,"type":"single","cat":"法规与空域","stem":"根据《民用无人驾驶航空器实名制登记管理规定》，需要进行实名登记的无人机是？","A":"最大起飞重量≥1.0千克的无人机","B":"空机重量≥2.0千克的无人机","C":"起飞重量≥3.0千克的无人机","D":"所有类型的无人机","answer":"A","exp":"本题考察无人机实名登记法规知识点。正确答案为A，根据规定，最大起飞重量≥1.0千克的民用无人机需进行实名登记，小于1.0千克的无需登记。B选项重量标准错误（应为1.0千克而非2.0千克），C选项标准错误（应为最大起飞重量而非起飞重量），D选项所有类型错误（部分小型无人机无需登记）。"},{"id":1360,"type":"single","cat":"法规与空域","stem":"以下哪种区域属于法律明确规定的‘禁飞区’？","A":"民用机场净空区","B":"城市公园广场","C":"偏远山区","D":"无人海岛","answer":"A","exp":"本题考察无人机禁飞区的法规边界。正确答案为A，民用机场净空区是为保障民航飞机起降安全划定的严格禁飞区域，根据《中华人民共和国民用航空法》，未经批准严禁无人机进入。选项B城市广场属于限制飞行区域（人流密集区），但非法定禁飞区；C、D无特殊限制可依法飞行。"},{"id":1361,"type":"single","cat":"法规与空域","stem":"根据中国民航局相关规定，最大起飞重量250克以下的民用无人机在开放空域飞行时，通常是否需要驾驶员执照？","A":"需要","B":"不需要","C":"需要备案登记","D":"需要参加理论培训","answer":"B","exp":"本题考察无人机驾驶员执照法规要求。根据民航局规定，最大起飞重量小于7千克的轻型民用无人机，在开放空域个人使用时通常无需驾驶员执照（需符合其他安全规定）；250克以下属于超轻型范畴，飞行限制更宽松，因此无需执照。选项A错误，因法规豁免此类飞行执照要求；C备案登记针对250克以上，D培训非执照强制要求，故正确答案为B。"},{"id":1362,"type":"single","cat":"基础概念","stem":"飞行中发现无人机失控并急速下坠，正确的处置方式是？","A":"立即尝试手动拉回控制，强行保持高度","B":"立即关闭遥控器电源，任由无人机自由坠落","C":"迅速远离无人机可能坠落的区域，避免人员伤亡","D":"继续操作无人机，尝试返航迫降","answer":"C","exp":"本题考察无人机失控应急处置知识点。正确答案为C。首要原则是确保地面人员安全，应迅速撤离危险区域；A选项错误，强行拉回控制可能导致二次失控或损坏；B选项错误，关闭电源会加剧坠落风险；D选项错误，失控状态下无法继续操作，强行返航易引发事故。"},{"id":1363,"type":"single","cat":"法规与空域","stem":"根据中国民用航空安全管理规定，以下哪些区域属于无人机绝对禁飞或严格限制飞行的区域？","A":"机场跑道及净空保护区域","B":"军事管理区及周边空域","C":"人口密集的城市核心区（如CBD）","D":"以上所有区域均属于禁飞/限飞区","answer":"D","exp":"本题考察无人机禁飞区法规。根据《民用无人驾驶航空器实名制登记管理规定》及《民用航空法》，机场净空区（A）为绝对禁飞区，军事管理区（B）为严格管控区，城市核心区（C）因安全与空域使用冲突通常限制飞行。因此三者均属于禁飞/限飞范畴，正确答案为D。"},{"id":1364,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机起飞时，地面操作员应站立在无人机的哪个位置以避免螺旋桨伤害？","A":"正前方（10米内）","B":"侧后方（安全距离外）","C":"正下方（5米内）","D":"任意远离机身的位置","answer":"B","exp":"本题考察无人机起飞安全规范知识点。多旋翼螺旋桨高速旋转时，前方气流最强且存在反推效应，正前方（A）和正下方（C）易被螺旋桨气流/叶片击中；B侧后方是安全区域（气流分散且远离旋转平面）；D任意位置未明确安全距离，可能因距离过近仍有风险，因此正确答案为B。"},{"id":1365,"type":"single","cat":"基础概念","stem":"起飞前检查中，下列哪项是确保飞行安全的关键步骤？","A":"检查遥控器电量","B":"确认螺旋桨安装牢固","C":"验证地面站连接状态","D":"测试图传信号强度","answer":"B","exp":"本题考察无人机起飞前安全操作规范。螺旋桨安装牢固是基础安全检查项，若螺旋桨松动或安装错误，起飞时可能脱落导致失控或损坏。选项A（遥控器电量）、C（地面站连接）、D（图传信号）是飞行过程中的辅助检查，非起飞前必须的关键检查。正确答案为B。"},{"id":1366,"type":"single","cat":"法规与空域","stem":"根据中国民航局规定，起飞重量在多少千克以下的微型民用无人机飞行时无需驾驶员执照？","A":"7千克","B":"25千克","C":"116千克","D":"150千克","answer":"A","exp":"本题考察无人机驾驶员执照法规知识点。根据《民用无人驾驶航空器实名制登记管理规定》及《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》，中国民航局将无人机分为微型（起飞重量＜7千克）、轻型（7-116千克）等类别，其中微型无人机飞行时无需驾驶员执照。选项B（25千克）、C（116千克）是轻型无人机的重量上限，D（150千克）为超轻型或其他分类，均需相应执照或审批。"},{"id":1367,"type":"single","cat":"领航与任务规划","stem":"当无人机GPS信号突然丢失且未开启‘失控返航’功能时，应优先采取的操作是？","A":"立即手动拉回无人机至手中","B":"尝试快速切换至‘返航模式’并锁定高度","C":"继续手动操作，观察无人机姿态变化","D":"重新启动无人机并搜索卫星信号","answer":"B","exp":"本题考察无人机失控应急操作。正确答案为B，GPS丢失后无人机进入姿态模式，无法自主定位，应优先锁定高度并返航至安全区域（如起飞点）。A选项手动拉回易导致无人机失控坠机；C选项继续操作缺乏定位，姿态模式下易因操控偏差失控；D选项重启耗时且无法解决当前信号丢失问题。"},{"id":1368,"type":"single","cat":"法规与空域","stem":"无人机驾驶员执照中，视距内驾驶员执照（VLOS）的适用范围是指无人机处于驾驶员目视范围内的水平距离和垂直高度限制，通常VLOS的水平距离和垂直高度限制分别是？","A":"500米，120米","B":"1000米，150米","C":"500米，150米","D":"1000米，120米","answer":"A","exp":"本题考察无人机法规中视距内驾驶员（VLOS）的飞行范围知识点。根据中国民航局相关规定，视距内驾驶员执照的VLOS标准为水平距离不超过500米，垂直高度不超过120米。B选项1000米和150米为超视距飞行（BVLOS）或特定场景下的放宽标准；C选项500米（水平）与150米（垂直）不符合VLOS定义；D选项1000米水平距离远超常规VLOS限制。因此正确答案为A。"},{"id":1369,"type":"single","cat":"法规与空域","stem":"根据《民用无人驾驶航空器系统驾驶员管理暂行规定》，在视距内运行的空机重量大于7千克且在25千克以下的无人机驾驶员，应当取得哪种资质？","A":"无需资质","B":"驾驶员合格证","C":"机长合格证","D":"教员合格证","answer":"B"},{"id":1370,"type":"single","cat":"基础概念","stem":"无人机在飞行中，与地面指挥中心通信中断时，正确的处置方法是？","A":"继续按原航线飞行","B":"立即下降高度","C":"按预案自动返航或就近降落","D":"保持高度盘旋等待","answer":"C"},{"id":1371,"type":"single","cat":"法规与空域","stem":"民用无人机驾驶员执照理论考试的最低合格分数线是？","A":"60分","B":"70分","C":"80分","D":"90分","answer":"C"},{"id":1372,"type":"single","cat":"法规与空域","stem":"无人机飞行前进行空域申请时，下列哪项不是必须提供的信息？","A":"飞行任务性质","B":"无人机驾驶员健康证明","C":"飞行空域范围","D":"飞行起止时间","answer":"B"},{"id":1373,"type":"single","cat":"法规与空域","stem":"无人机在机场净空保护区内飞行，应当？","A":"经机场管理机构批准","B":"只要不在航线上即可","C":"提前向空管部门报备即可","D":"禁止飞行","answer":"A"},{"id":1374,"type":"single","cat":"航空气象","stem":"大气中导致无人机产生积冰的主要气象条件是？","A":"在含过冷水滴的云中飞行","B":"在干燥空气中飞行","C":"在高温高湿环境飞行","D":"在强对流天气下飞行","answer":"A"},{"id":1375,"type":"single","cat":"设备与维护","stem":"无人机常用锂电池的正常工作电压范围一般为？","A":"每节2.0~3.0V","B":"每节3.0~4.2V","C":"每节4.2~5.0V","D":"每节5.0~6.0V","answer":"B"},{"id":1376,"type":"single","cat":"航空气象","stem":"无人机逆风起降时，通常应当选择哪种方式？","A":"逆风起飞，逆风降落","B":"逆风起飞，顺风降落","C":"顺风起飞，逆风降落","D":"顺风起飞，顺风降落","answer":"A"},{"id":1377,"type":"single","cat":"飞行原理","stem":"无人机在水平飞行中，升力等于？","A":"重力与阻力之和","B":"重力","C":"重力沿垂直方向的分量","D":"重力沿飞行方向的分量","answer":"B"},{"id":1378,"type":"single","cat":"飞行原理","stem":"多旋翼无人机在空中悬停时，旋翼产生的升力大小？","A":"大于无人机重力","B":"等于无人机重力","C":"小于无人机重力","D":"与重力无关","answer":"B"},{"id":1379,"type":"single","cat":"操纵与飞行技术","stem":"无人机最大平飞速度是指？","A":"一定高度上发动机最大推力下的平飞速度","B":"海平面上的平飞速度","C":"巡航状态下的平飞速度","D":"安全飞行允许的最大速度","answer":"A"},{"id":1380,"type":"single","cat":"操纵与飞行技术","stem":"无人机自动驾驶仪中，负责感知姿态角速率并参与姿态稳定控制的传感器是？","A":"GPS接收机","B":"气压高度计","C":"角速率陀螺仪","D":"磁罗盘","answer":"C"},{"id":1381,"type":"single","cat":"基础概念","stem":"无人机地面站的主要功能不包括？","A":"飞行数据实时显示","B":"飞行航线规划与上传","C":"无人机机体制造","D":"遥控指令发送","answer":"C"},{"id":1382,"type":"single","cat":"设备与维护","stem":"当无人机出现单侧电机失效时，正确的应急处置原则是？","A":"立即加大油门，保持原姿态","B":"尽快降低高度，控制姿态并迫降","C":"立即切断所有动力","D":"立即满油门爬升","answer":"B"},{"id":1383,"type":"single","cat":"基础概念","stem":"无人机在夜间飞行时，应当开启？","A":"搜索灯","B":"导航灯和防撞灯","C":"着陆灯","D":"闪光灯","answer":"B"},{"id":1384,"type":"single","cat":"操纵与飞行技术","stem":"在标准大气条件下，海拔每升高1000米，气温大约下降？","A":"1.5℃","B":"6.5℃","C":"9.8℃","D":"12℃","answer":"B"},{"id":1385,"type":"single","cat":"操纵与飞行技术","stem":"无人机水平转弯时，倾斜角越大，则？","A":"转弯半径越大","B":"转弯半径越小","C":"转弯速度越快","D":"转弯速度越慢","answer":"B"},{"id":1386,"type":"single","cat":"领航与任务规划","stem":"无人机使用GPS导航时，至少需要接收多少颗卫星才能实现三维定位？","A":"3颗","B":"4颗","C":"5颗","D":"6颗","answer":"B"},{"id":1387,"type":"single","cat":"基础概念","stem":"无人机机体上的空速管主要用于测量？","A":"气压高度","B":"升降速度","C":"空速","D":"地速","answer":"C"},{"id":1388,"type":"single","cat":"领航与任务规划","stem":"无人机在遥控链路丢失后，若未能收到返航指令，飞控系统通常默认执行？","A":"原地坠毁","B":"立即降落","C":"自动返航至起飞点","D":"按原航线继续飞行","answer":"C"},{"id":1389,"type":"single","cat":"法规与空域","stem":"根据现行法规，从事无人机经营性飞行活动应当取得？","A":"通用航空经营许可","B":"民用机场使用许可证","C":"营业执照即可","D":"无需许可","answer":"A"},{"id":1390,"type":"single","cat":"设备与维护","stem":"无人机发动机空中停车后，活塞式无人机应首先采取的处置措施是？","A":"立即重新启动发动机","B":"操纵飞机进入最佳滑翔状态","C":"弃机跳伞","D":"加大油门","answer":"B"},{"id":1391,"type":"single","cat":"基础概念","stem":"无人机飞行时，空气密度减小会导致？","A":"升力增大，阻力减小","B":"升力减小，阻力减小","C":"升力增大，阻力增大","D":"升力减小，阻力增大","answer":"B"},{"id":1392,"type":"single","cat":"航空气象","stem":"无人机云台的主要作用是？","A":"增加飞行稳定性","B":"稳定相机姿态，隔离机体振动","C":"提高飞行速度","D":"扩展通信距离","answer":"B"},{"id":1393,"type":"single","cat":"设备与维护","stem":"无人机在寒冷环境下飞行，电池性能会？","A":"放电能力增强","B":"放电能力下降","C":"容量增加","D":"内阻减小","answer":"B"},{"id":1394,"type":"single","cat":"基础概念","stem":"多旋翼无人机改变飞行方向是通过？","A":"改变旋翼总距","B":"差动改变各旋翼转速","C":"改变机体俯仰角","D":"改变旋翼倾转角度","answer":"B"},{"id":1395,"type":"single","cat":"基础概念","stem":"无人机在超过视距运行（BVLOS）时，应满足的条件是？","A":"驾驶员必须目视观察","B":"必须使用电子围栏和感知避让系统","C":"只需保持通信链路","D":"必须在隔离空域内飞行","answer":"D"},{"id":1396,"type":"single","cat":"基础概念","stem":"无人机飞行记录中，通常要求保存至少？","A":"1个月","B":"3个月","C":"6个月","D":"12个月","answer":"D"},{"id":1397,"type":"single","cat":"设备与维护","stem":"无人机起飞前检查螺旋桨时，应重点确认？","A":"螺旋桨颜色","B":"螺旋桨安装方向正确且无裂纹","C":"螺旋桨数量","D":"螺旋桨材质","answer":"B"},{"id":1398,"type":"single","cat":"设备与维护","stem":"无人机使用遥控器时，应先开启哪个设备？","A":"先开无人机电源","B":"先开遥控器电源","C":"同时开启","D":"顺序无所谓","answer":"B"},{"id":1399,"type":"single","cat":"航空气象","stem":"无人机在风切变环境中飞行，最危险的情况是？","A":"顺风切变","B":"逆风切变","C":"侧风切变","D":"下击暴流","answer":"D"},{"id":1400,"type":"single","cat":"设备与维护","stem":"无人机电池充电时，正确的做法是？","A":"使用原装充电器并有人看守","B":"在密闭高温环境充电","C":"将电池充满后长时间不拔","D":"使用充电器时叠加充电","answer":"A"},{"id":1401,"type":"single","cat":"基础概念","stem":"无人机在雨中飞行可能导致？","A":"电子设备短路失效","B":"电机散热更好","C":"飞行速度增加","D":"电池续航增加","answer":"A"},{"id":1402,"type":"single","cat":"基础概念","stem":"无人机在飞行中，机头朝北，正西风（风从西吹向东），无人机应向哪个方向偏航补偿？","A":"左偏","B":"右偏","C":"上偏","D":"下偏","answer":"A"},{"id":1403,"type":"single","cat":"领航与任务规划","stem":"无人机执行测绘任务时，航线规划应优先考虑？","A":"风速与重叠率","B":"飞行高度固定","C":"地面控制点数量","D":"飞机颜色","answer":"A"},{"id":1404,"type":"single","cat":"基础概念","stem":"无人机超视距飞行时，驾驶员应随时掌握？","A":"飞机位置和飞行状态","B":"飞机外观","C":"发动机温度","D":"机翼结冰情况","answer":"A"},{"id":1405,"type":"single","cat":"基础概念","stem":"无人机在机场附近飞行，飞行高度不得超过？","A":"相对机场跑道高度的120米","B":"相对机场跑道高度的200米","C":"相对机场跑道高度的300米","D":"机场净空规定的限制高度","answer":"D"},{"id":1406,"type":"single","cat":"设备与维护","stem":"无人机动力电池常见标示45C中的C表示？","A":"电池容量","B":"放电倍率","C":"充电倍率","D":"电池节数","answer":"B"},{"id":1407,"type":"single","cat":"基础概念","stem":"无人机在高温高原地区飞行时，主要影响是？","A":"空气密度减小，升力下降","B":"空气密度增大，升力增加","C":"发动机功率增大","D":"电池放电能力增强","answer":"A"},{"id":1408,"type":"single","cat":"领航与任务规划","stem":"无人机飞行中，如果GPS信号丢失，正确的做法是？","A":"立即降落","B":"切换为姿态模式并人工操控","C":"继续等待GPS恢复","D":"关闭电源重启","answer":"B"},{"id":1409,"type":"single","cat":"基础概念","stem":"无人机起飞前进行磁罗盘校准的目的是？","A":"校准空速管","B":"消除周围磁场干扰，保证航向准确","C":"校准电池电量","D":"校准遥控器","answer":"B"},{"id":1410,"type":"single","cat":"法规与空域","stem":"无人机在真高120米以下、隔离空域内飞行，需遵守？","A":"无需任何审批","B":"需向空管部门报备飞行计划","C":"必须获得飞行执照","D":"必须投保责任险","answer":"B"},{"id":1411,"type":"single","cat":"飞行原理","stem":"无人机螺旋桨的螺距是指？","A":"螺旋桨直径","B":"螺旋桨旋转一周前进的理论距离","C":"螺旋桨叶片宽度","D":"螺旋桨安装角度","answer":"B"},{"id":1412,"type":"single","cat":"领航与任务规划","stem":"无人机在地面站设置返航高度时，应高于返航路径上最高障碍物的？","A":"10米","B":"20米","C":"50米","D":"100米","answer":"C"},{"id":1413,"type":"single","cat":"航空气象","stem":"无人机起降时遭遇低空风切变，应当？","A":"加大油门强行起降","B":"立即中止起降，改到安全区域","C":"减小油门缓慢起降","D":"保持原操作不变","answer":"B"},{"id":1414,"type":"single","cat":"基础概念","stem":"无人机每次飞行结束后，应当？","A":"立即拆除所有部件","B":"检查机身、螺旋桨、电池等状态","C":"只保存飞行数据","D":"关闭遥控器电源即可","answer":"B"},{"id":1415,"type":"single","cat":"设备与维护","stem":"无人机机载飞控系统的主要功能不包括？","A":"姿态稳定与控制","B":"导航与制导","C":"任务载荷投放","D":"应急保护与失效处理","answer":"C"},{"id":1416,"type":"single","cat":"法规与空域","stem":"无人机在禁飞区内飞行，可能导致？","A":"行政拘留","B":"罚款","C":"追究刑事责任","D":"以上均可能","answer":"D"},{"id":1417,"type":"single","cat":"基础概念","stem":"无人机在夜间飞行时，地面人员辨别无人机方向的依据是？","A":"机头灯颜色","B":"导航灯位置与颜色","C":"机身反光","D":"遥控器信号强度","answer":"B"},{"id":1418,"type":"single","cat":"基础概念","stem":"无人机飞行前查看天气，重点关注？","A":"风速、风向、能见度、云底高","B":"气温、气压、湿度","C":"降水、雷电","D":"以上全部","answer":"D"},{"id":1419,"type":"multi","cat":"法规与空域","stem":"无人机驾驶员执照理论考试内容包括？","A":"航空法规","B":"气象学","C":"飞行原理","D":"无人机系统组成与操作","answer":"ABCD"},{"id":1420,"type":"multi","cat":"基础概念","stem":"无人机在飞行前必须进行的检查项目包括？","A":"螺旋桨安装牢固无裂纹","B":"电池电量充足","C":"遥控器与无人机通信正常","D":"GPS卫星颗数满足要求","answer":"ABCD"},{"id":1421,"type":"multi","cat":"基础概念","stem":"下列哪些属于无人机常见故障类型？","A":"电机停转","B":"飞控传感器漂移","C":"GPS丢失","D":"遥控链路中断","answer":"ABCD"},{"id":1422,"type":"multi","cat":"基础概念","stem":"无人机在山区飞行时，可能遇到的危险有？","A":"地形障碍碰撞","B":"山谷风切变","C":"上升气流影响高度","D":"磁罗盘受磁场干扰","answer":"ABC"},{"id":1423,"type":"multi","cat":"设备与维护","stem":"无人机电池安全使用要求包括？","A":"使用专用充电器","B":"充电时远离易燃物","C":"电池鼓包后继续使用","D":"运输时保持短路保护","answer":"ABD"},{"id":1424,"type":"multi","cat":"领航与任务规划","stem":"无人机执行应急测绘任务时，航线规划应考虑？","A":"禁飞区避让","B":"地形起伏与安全高度","C":"地面分辨率与重叠率","D":"飞机涂装颜色","answer":"ABC"},{"id":1425,"type":"multi","cat":"基础概念","stem":"无人机在雨中飞行可能造成的后果有？","A":"电子设备短路","B":"镜头起雾影响成像","C":"机翼表面污染增加阻力","D":"电池续航增加","answer":"ABC"},{"id":1426,"type":"multi","cat":"法规与空域","stem":"无人机在机场净空区域内飞行，应当避免？","A":"进入跑道中心线延长线","B":"在进近航线下方飞行","C":"在起飞爬升航迹下方飞行","D":"在停机坪上方低空飞行","answer":"ABC"},{"id":1427,"type":"multi","cat":"基础概念","stem":"无人机地面站软件应具备的基本功能包括？","A":"航线规划","B":"实时飞行数据显示","C":"飞行参数设置","D":"故障诊断与报警","answer":"ABCD"},{"id":1428,"type":"multi","cat":"基础概念","stem":"无人机驾驶员在飞行中应当遵守的原则有？","A":"保持视距内飞行","B":"避让有人驾驶航空器","C":"严禁酒后飞行","D":"任意跨越禁飞区","answer":"ABC"}];
